INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('3/4 Abdominal','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en el suelo y asegura tus pies. Tus piernas deben estar dobladas a la altura de las rodillas.\", \"Coloca tus manos detras o a los lados de tu cabeza. Comenzaras con tu espalda en el suelo. Esta sera tu posicion inicial.\", \"Flexiona tus caderas y columna para levantar tu torso hacia tus rodillas.\", \"En la parte superior de la contraccion tu torso debe estar perpendicular al suelo. Invierte el movimiento, yendo solo ¾ del camino hacia abajo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"3_4_Sit-Up/0.jpg\", \"3_4_Sit-Up/1.jpg\"]','3_4_Sit-Up',0) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('90/90 Isquiotibiales','empuje','principiante','Ninguno','solo_cuerpo','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"Acuestate boca arriba, con una pierna extendida recta hacia fuera.\", \"Con la otra pierna, flexiona la cadera y la rodilla a 90 grados. Puedes sujetar la pierna con las manos si es necesario. Esta sera tu posicion inicial.\", \"Extiende la pierna recta hacia arriba, haciendo una breve pausa en la parte superior. Vuelve la pierna a la posicion inicial.\", \"Repite durante 10-20 repeticiones, y luego cambia a la otra pierna.\"]','estiramiento','[\"90_90_Hamstring/0.jpg\", \"90_90_Hamstring/1.jpg\"]','90_90_Isquiotibiales',1) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ab Roller','traccion','intermedio','compuesto','otro','[\"abdominales\"]','[\"hombros\"]','[\"Sosten el rodillo abdominal con ambas manos y arrodillate en el suelo.\", \"Ahora coloca el rodillo abdominal en el suelo frente a ti, de modo que estes apoyado en las manos y las rodillas (como en una posicion de flexion arrodillada). Esta sera tu posicion inicial.\", \"Desliza lentamente el rodillo abdominal hacia delante, estirando el cuerpo hasta quedar en posicion recta. Consejo: Baja todo lo que puedas sin tocar el suelo con el cuerpo. Inhala durante esta parte del movimiento.\", \"Despues de una pausa en la posicion estirada, empieza a tirar de ti mismo hacia atras hasta la posicion inicial mientras exhalas. Consejo: Ve despacio y manten los abdominales tensos en todo momento.\"]','fuerza','[\"Ab_Roller/0.jpg\", \"Ab_Roller/1.jpg\"]','Ab_Roller',3) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Adductor','estatico','intermedio','aislamiento','rodillo_espuma','[\"aductores\"]','[]','[\"Acuestate boca abajo con una pierna sobre un rodillo de espuma.\", \"Gira la pierna de modo que el rodillo de espuma entre en contacto con la parte interna del muslo. Desplaza todo el peso que puedas soportar sobre el rodillo de espuma.\", \"Mientras intentas relajar los musculos de la parte interna del muslo, rueda sobre la espuma entre la cadera y la rodilla, manteniendo los puntos de tension durante 10-30 segundos. Repite con la otra pierna.\"]','estiramiento','[\"Adductor/0.jpg\", \"Adductor/1.jpg\"]','Aductor',4) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Aductor/Ingle','estatico','intermedio','Ninguno','Ninguno','[\"aductores\"]','[]','[\"Acuestate boca arriba con tus pies levantados hacia el techo.\", \"Pide a tu compañero que te sujete los pies o los tobillos. Abduce tus piernas tan lejos como puedas. Esta sera tu posicion inicial.\", \"Intenta apretar tus piernas durante 10 o mas segundos, mientras tu compañero te impide hacerlo.\", \"Ahora, relaja los musculos de tus piernas mientras tu compañero separa tus pies, estirandolos tanto como te resulte comodo. Asegurate de avisar a tu compañero cuando el estiramiento sea adecuado para evitar un estiramiento excesivo o una lesion.\"]','estiramiento','[\"Adductor_Groin/0.jpg\", \"Adductor_Groin/1.jpg\"]','Adductor_Ingle',5) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Avanzado con pesas rusas Molino','empuje','intermedio','aislamiento','pesas rusas','[\"abdominales\"]','[\"gluteos\", \"isquiotibiales\", \"hombros\"]','[\"Limpia y presiona una pesa rusa sobre la cabeza con un brazo.\", \"Manteniendo la pesa rusa bloqueada en todo momento, empuja el trasero en la direccion de la pesa rusa bloqueada. Manten el brazo que no esta trabajando detras de tu espalda y gira tus pies en un angulo de cuarenta y cinco grados con respecto al brazo con la pesa rusa.\", \"Baja lo mas lejos posible.\", \"Haz una pausa por un segundo y revierte el movimiento de espalda a la posicion inicial.\"]','fuerza','[\"Advanced_Kettlebell_Windmill/0.jpg\", \"Advanced_Kettlebell_Windmill/1.jpg\"]','Molino avanzado con pesas rusas',6) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bicicleta aerea','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate boca arriba en el suelo con la parte inferior de la espalda pegada al suelo. Para este ejercicio, tendras que colocar las manos junto a la cabeza. Sin embargo, ten cuidado de no forzar el cuello mientras lo realizas. Ahora levanta los hombros hasta la posicion de abdominales.\", \"Lleva las rodillas hacia arriba hasta que queden perpendiculares al suelo, con las piernas paralelas al suelo. Esta sera tu posicion inicial.\", \"Ahora, simultaneamente, realiza lentamente un movimiento de pedaleo, pateando hacia adelante con la pierna derecha y llevando la rodilla de la pierna izquierda hacia dentro. Acerca el codo derecho a la rodilla izquierda doblandote hacia ese lado, mientras exhalas.\", \"Vuelve a la posicion inicial mientras inhalas.\", \"Doblate hacia el lado opuesto mientras pedaleas con las piernas y acerca el codo izquierdo a la rodilla derecha y exhala.\", \"Continua alternando de esta forma hasta completar todas las repeticiones recomendadas para cada lado.\"]','fuerza','[\"Air_Bike/0.jpg\", \"Air_Bike/1.jpg\"]','Bicicleta de aire',7) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de cuadriceps a cuatro patas','estatico','intermedio','Ninguno','solo_cuerpo','[\"cuadriceps\"]','[\"cuadriceps\"]','[\"Comienza en tus manos y rodillas, luego levanta la pierna del suelo y manten el pie con tu mano.\", \"Usa tu mano para mantener el pie o tobillo, manteniendo la rodilla completamente flexionada, estirando los cuadriceps y flexores de la cadera.\", \"Concentrate en extender tus caderas, empujandolas hacia el suelo. Manten durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"All_Fours_Quad_Stretch/0.jpg\", \"All_Fours_Quad_Stretch/1.jpg\"]','Estiramiento de cuadriceps a cuatro patas',8) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl martillo alternativo','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie con el torso erguido y una mancuerna en cada mano, sosteniendolas a la longitud de los brazos. Los codos deben estar cerca del torso.\", \"Las palmas de las manos deben estar orientadas hacia el torso. Esta sera tu posicion inicial.\", \"Mientras mantienes el brazo superior inmovil, flexiona el peso derecho hacia adelante mientras contraes el biceps y exhalas. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Sosten la posicion contraida durante un segundo mientras aprietas el biceps. Consejo: Solo deben moverse los antebrazos.\", \"Comienza lentamente a llevar las mancuernas hacia atras a la posicion inicial mientras inspiras.\", \"Repite el movimiento con la mano izquierda. Esto equivale a una repeticion.\", \"Continua alternando de esta forma durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Alternate_Hammer_Curl/0.jpg\", \"Alternate_Hammer_Curl/1.jpg\"]','Alternancia de flexiones con mancuernas',9) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Alternate Heel Touchers','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en el suelo con las rodillas dobladas y los pies en el suelo a unos 45-60 cm de distancia. Tus brazos deben estar extendidos a los lados. Esta sera tu posicion inicial.\", \"Haz crunch con tu torso hacia adelante y arriba aproximadamente 7-10 cm hacia el lado derecho y toca tu talon derecho mientras mantienes la contraccion por un segundo. Exhala mientras realizas este movimiento.\", \"Ahora regresa lentamente a la posicion inicial mientras inhalas.\", \"Ahora haz abdominales con el torso hacia adelante y arriba aproximadamente 3-4 pulgadas hacia el lado izquierdo y toca tu talon izquierdo mientras mantienes la contraccion por un segundo. Exhala mientras realizas este movimiento y luego vuelve a la posicion inicial mientras inhalas. Ahora que has tocado ambos talones, eso se considera 1 repeticion.\", \"Continua alternando lados de esta forma hasta completar todas las repeticiones prescritas.\"]','fuerza','[\"Alternate_Heel_Touchers/0.jpg\", \"Alternate_Heel_Touchers/1.jpg\"]','Alternate_Heel_Touchers',10) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Alternate Inclinado con Mancuerna Curl','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Sientate en un banco inclinado con una mancuerna en cada mano, sosteniendolas a la longitud de los brazos. Consejo: Manten los codos cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes la parte superior del brazo inmovil, flexiona el peso derecho hacia adelante mientras contraes el biceps al exhalar. Al hacerlo, gira la mano de modo que la palma quede hacia arriba. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Sosten la posicion contraida durante un segundo mientras aprietas el biceps. Consejo: Solo deben moverse los antebrazos.\", \"Comienza lentamente a llevar la mancuerna hacia atras a la posicion inicial mientras inhalas.\", \"Repite el movimiento con la mano izquierda. Esto equivale a una repeticion.\", \"Continua alternando de esta forma durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Alternate_Incline_Dumbbell_Curl/0.jpg\", \"Alternate_Incline_Dumbbell_Curl/1.jpg\"]','Curl inclinado alternativo con mancuernas',11) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Alternate Pierna Diagonal Bound','empuje','principiante','compuesto','Ninguno','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Adopta una postura comoda con un pie ligeramente delante del otro.\", \"Comienza empujando con la pierna delantera, llevando la rodilla opuesta hacia delante y lo mas alto posible antes de aterrizar. Intenta cubrir la mayor distancia posible a cada lado con cada salto.\", \"Puede ser util utilizar una linea en el suelo para medir la distancia de lado a lado.\", \"Repite la secuencia con la otra pierna.\"]','pliometria','[\"Alternate_Leg_Diagonal_Bound/0.jpg\", \"Alternate_Leg_Diagonal_Bound/1.jpg\"]','Salto diagonal alternando piernas',12) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Alternando en Polea Hombro Press','empuje','principiante','compuesto','polea','[\"hombros\"]','[\"triceps\"]','[\"Mueve las poleas a la parte inferior de la torre y selecciona un peso adecuado.\", \"Agarra los cables y mantenlos a la altura de los hombros, con las palmas hacia delante. Esta sera tu posicion inicial.\", \"Manteniendo la cabeza y el pecho erguidos, extiende el codo para presionar un lado directamente sobre la cabeza.\", \"Despues de hacer una pausa en la parte superior, vuelve a la posicion inicial y repite en el lado opuesto.\"]','fuerza','[\"Alternating_Cable_Shoulder_Press/0.jpg\", \"Alternating_Cable_Shoulder_Press/1.jpg\"]','Press de hombros alternado con cable',13) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion deltoidea alterna','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"En posicion de pie, manten un par de mancuernas a los lados.\", \"Manten los codos ligeramente flexionados y levanta las pesas directamente frente a ti hasta la altura de los hombros, evitando cualquier balanceo o trampa.\", \"Vuelve a colocar las pesas a los lados.\", \"En la siguiente repeticion, levanta las pesas lateralmente, llevandolas hacia tu lado hasta aproximadamente la altura de los hombros.\", \"Vuelve a colocar las pesas en la posicion inicial y continua alternando hacia delante y hacia los lados.\"]','fuerza','[\"Alternating_Deltoid_Raise/0.jpg\", \"Alternating_Deltoid_Raise/1.jpg\"]','Elevacion_alternada_del_deltoides',14) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press alternado en el suelo','empuje','principiante','compuesto','pesas rusas','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Acuestate en el suelo con dos pesas rusas junto a tus hombros.\", \"Coloca una en tu pecho y luego la otra, agarrando las pesas rusas por el mango con las palmas hacia adelante.\", \"Extiende ambos brazos, de modo que las pesas rusas queden por encima de tu pecho. Baja una pesa rusa, llevandola a tu pecho y gira la muñeca en la direccion de la pesa rusa bloqueada.\", \"Levanta la pesa rusa y repite en el lado opuesto.\"]','fuerza','[\"Alternating_Floor_Press/0.jpg\", \"Alternating_Floor_Press/1.jpg\"]','Press de suelo alternado',15) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hang Clean alternado','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"biceps\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"trapecios\"]','[\"Coloca dos pesas rusas entre tus pies. Para colocarte en la posicion inicial, empuja el trasero hacia atras y mira recto al frente.\", \"Lleva una pesa rusa al hombro y manten la otra pesa rusa en posicion colgante. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia los hombros. Gira la muñeca mientras lo haces.\", \"Baja la pesa rusa limpia a una posicion colgante y limpia la pesa rusa alternativa. Repite.\"]','fuerza','[\"Alternating_Hang_Clean/0.jpg\", \"Alternating_Hang_Clean/1.jpg\"]','Alternancia de levantamiento de peso muerto',16) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo alternado con pesa rusa','traccion','intermedio','aislamiento','pesas rusas','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca dos pesas rusas frente a tus pies. Dobla ligeramente las rodillas y empuja el trasero hacia atras tanto como sea posible. Mientras te inclinas para ponerte en la posicion inicial, agarra ambas pesas rusas por las asas.\", \"Levanta una pesa rusa del suelo mientras sostienes la otra pesa rusa. Retrae el omoplato del lado con el que estas trabajando, mientras flexionas el codo, llevando la pesa rusa hacia tu estomago o caja toracica.\", \"Baja la pesa rusa del brazo con el que estas trabajando y repite con el otro brazo.\"]','fuerza','[\"Alternating_Kettlebell_Row/0.jpg\", \"Alternating_Kettlebell_Row/1.jpg\"]','Remo alternativo con pesas rusas',18) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo renegado alternativo','traccion','experto','compuesto','pesas rusas','[\"espalda_media\"]','[\"abdominales\", \"biceps\", \"pecho\", \"dorsales\", \"triceps\"]','[\"Coloca dos pesas rusas en el suelo aproximadamente a la anchura de los hombros. Colocate en puntas de pie y con las manos como si fueras a hacer una flexion, con el cuerpo recto y extendido. Utiliza los mangos de las pesas rusas para apoyar la parte superior del cuerpo. Puedes necesitar posicionar tus pies mas separados durante el apoyo.\", \"Empuja una pesa rusa hacia el suelo y rema con la otra pesa rusa, retraiendo el omoplato del lado de trabajo mientras flexionas el codo, tirando hacia tu costado.\", \"Luego baja la pesa rusa al suelo y comienza con la pesa rusa en la mano opuesta. Repite durante varias repeticiones.\"]','fuerza','[\"Alternating_Renegade_Row/0.jpg\", \"Alternating_Renegade_Row/1.jpg\"]','Remo renegado alternativo',19) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos con el tobillo','traccion','principiante','aislamiento','Ninguno','[\"pantorrillas\"]','[]','[\"Utiliza un objeto resistente, como una jaula de sentadillas, para mantenerte estable.\", \"Eleva la pierna derecha en el aire (a unos 5 cm del suelo) y realiza un movimiento circular con el dedo gordo del pie. Imagina que estas dibujando un gran circulo con el. Consejo: un circulo equivale a una repeticion. Respira con normalidad mientras realizas el movimiento.\", \"Cuando hayas terminado con la pierna derecha, repite con la izquierda.\"]','estiramiento','[\"Ankle_Circles/0.jpg\", \"Ankle_Circles/1.jpg\"]','Circulos de tobillo',20) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tobillo sobre la rodilla','estatico','principiante','Ninguno','Ninguno','[\"gluteos\"]','[]','[\"Desde una posicion acostada, dobla tus rodillas y manten tus pies en el suelo.\", \"Coloca el tobillo de un pie en la rodilla opuesta.\", \"Agarra el muslo o la rodilla de la pierna inferior y lleva ambas piernas hacia el pecho. Relaja tu cuello y hombros. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Tobillo_sobre_la_rodilla/0.jpg\", \"Tobillo_sobre_la_rodilla/1.jpg\"]','Tobillo sobre la rodilla',21) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tibial anterior-SMR','estatico','intermedio','Ninguno','otro','[\"pantorrillas\"]','[]','[\"Comienza sentado en el suelo con las piernas dobladas y los pies en el suelo.\", \"Con un rodillo muscular o un rodillo de amasar, aplica presion sobre los musculos de la parte exterior de las espinillas. Trabaja desde justo debajo de la rodilla hasta por encima del tobillo, haciendo pausas en los puntos de tension durante 10-30 segundos. Repite en la otra pierna.\"]','estiramiento','[\"Anterior_Tibialis-SMR/0.jpg\", \"Anterior_Tibialis-SMR/1.jpg\"]','Tibial anterior-SMR',22) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Prensa antigravedad','empuje','principiante','compuesto','barra','[\"hombros\"]','[\"espalda_media\", \"trapecios\", \"triceps\"]','[\"Coloca una barra en el suelo detras de la cabeza de un banco inclinado.\", \"Tumbate en el banco boca abajo. Con un agarre pronado, levanta la barra del suelo. Flexiona los codos, realizando un curl inverso para llevar la barra cerca de tu pecho. Esta sera tu posicion inicial.\", \"Para comenzar, presiona la barra frente a tu cabeza extendiendo los codos. Manten los brazos paralelos al suelo durante todo el movimiento.\", \"Regresa a la posicion inicial y repite para completar la serie.\"]','fuerza','[\"Anti-Gravity_Press/0.jpg\", \"Anti-Gravity_Press/1.jpg\"]','Press antigravedad',23) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos con los brazos','empuje','principiante','aislamiento','Ninguno','[\"hombros\"]','[\"trapecios\"]','[\"Ponte de pie y extiende los brazos rectos hacia los lados. Los brazos deben estar paralelos al suelo y perpendiculares (angulo de 90 grados) a tu torso. Esta sera tu posicion inicial.\", \"Empieza lentamente a hacer circulos de aproximadamente 30 cm de diametro con cada brazo extendido. Respira con normalidad mientras realizas el movimiento.\", \"Continua con el movimiento circular de los brazos extendidos durante aproximadamente diez segundos. A continuacion, invierte el movimiento, yendo en la direccion opuesta.\"]','estiramiento','[\"Arm_Circles/0.jpg\", \"Arm_Circles/1.jpg\"]','Circulos de brazos',24) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arnold con Mancuerna Press','empuje','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Sientate en un banco de ejercicios con respaldo y manten dos mancuernas frente a ti a la altura aproximada de la parte superior del pecho, con las palmas de las manos mirando hacia tu cuerpo y los codos flexionados. Consejo: Tus brazos deben estar pegados al torso. La posicion inicial debe parecerse a la parte contraida de una flexion con mancuernas.\", \"Ahora, para realizar el movimiento, levanta las mancuernas mientras giras las palmas de tus manos hasta que queden mirando hacia delante.\", \"Continua levantando las mancuernas hasta que tus brazos esten extendidos por encima de ti en posicion recta. Exhala mientras realizas esta parte del movimiento.\", \"Despues de una pausa de un segundo en la parte superior, comienza a bajar las mancuernas a la posicion original girando las palmas de tus manos hacia ti. Consejo: El brazo izquierdo se girara en sentido contrario a las agujas del reloj, mientras que el derecho se girara en el sentido de las agujas del reloj. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Arnold_Dumbbell_Press/0.jpg\", \"Arnold_Dumbbell_Press/1.jpg\"]','Arnold_Press_con_mancuernas',25) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Alrededor del mundo','empuje','intermedio','compuesto','mancuerna','[\"pecho\"]','[\"hombros\"]','[\"Tumbate en un banco plano sosteniendo una mancuerna en cada mano con las palmas de las manos mirando hacia el techo. Consejo: Tus brazos deben estar paralelos al suelo y junto a tus muslos. Para evitar lesiones, asegurate de mantener los codos ligeramente flexionados. Esta sera tu posicion inicial.\", \"Ahora mueve las mancuernas creando un semicirculo mientras las desplazas desde la posicion inicial hasta por encima de la cabeza. Todo el movimiento debe realizarse con los brazos paralelos al suelo en todo momento. Inhala mientras realizas esta parte del movimiento.\", \"Invierte el movimiento para devolver el peso a la posicion inicial mientras exhalas.\"]','fuerza','[\"Around_The_Worlds/0.jpg\", \"Around_The_Worlds/1.jpg\"]','Alrededor_del_mundo',26) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Back Flyes - Con bandas','traccion','principiante','compuesto','bandas','[\"hombros\"]','[\"espalda_media\", \"triceps\"]','[\"Coloca una banda alrededor de un poste fijo, como el de una jaula de sentadillas.\", \"Agarra la banda por las asas y ponte de espaldas para que la tension de la banda aumente.\", \"Extiende y levanta los brazos rectos frente a ti. Consejo: Tus brazos deben estar rectos y paralelos al suelo, perpendiculares a tu torso. Tus pies deben estar firmemente plantados en el suelo, separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Mientras exhalas, mueve tus brazos hacia los lados y hacia atras. Manten tus brazos extendidos y paralelos al suelo. Continua el movimiento hasta que los brazos esten extendidos a los lados.\", \"Despues de una pausa, vuelve a la posicion original mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Back_Flyes_-_With_Bands/0.jpg\", \"Back_Flyes_-_With_Bands/1.jpg\"]','Back_Flyes_-_Con_bandas',30) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Backward Drag','traccion','principiante','compuesto','otro','[\"cuadriceps\"]','[\"Pantorrillas\", \"Antebrazos\", \"Gluteos\", \"Isquiotibiales\", \"Espalda_baja\"]','[\"Carga un trineo con el peso deseado, colocando una cuerda o correas al trineo para que puedas sujetarte.\"]','hombre_fuerte','[\"Backward_Drag/0.jpg\", \"Backward_Drag/1.jpg\"]','Arrastre hacia atras',31) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento de balon medicinal hacia atras','empuje','principiante','compuesto','balon_medicinal','[\"hombros\"]','[]','[\"Este ejercicio se realiza mejor con un compañero. Si no tienes compañero, puedes lanzar y recuperar el balon contra una pared.\", \"Comienza de pie a unos metros delante de tu compañero, ambos mirando en la misma direccion. Comienza sosteniendo el balon entre tus piernas.\", \"Haz una sentadilla y luego cambia bruscamente de direccion, extendiendote completamente y lanzando el balon por encima de tu cabeza a tu compañero.\", \"Tu compañero puede luego hacer rodar el balon hacia ti. Repite durante el numero deseado de repeticiones.\"]','pliometria','[\"Backward_Medicine_Ball_Throw/0.jpg\", \"Backward_Medicine_Ball_Throw/1.jpg\"]','Lanzamiento hacia atras con balon medicinal',32) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tabla de equilibrio','Ninguno','principiante','compuesto','otro','[\"pantorrillas\"]','[\"isquiotibiales\", \"cuadriceps\"]','[\"Coloca una tabla de equilibrio frente a ti.\", \"Ponte de pie en ella e intenta mantener el equilibrio.\", \"Manten el equilibrio durante el tiempo que desees.\"]','fuerza','[\"Tabla_de_equilibrio/0.jpg\", \"Tabla_de_equilibrio/1.jpg\"]','Tabla de equilibrio',33) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de piernas con pelota','traccion','principiante','aislamiento','fitball','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Comienza en el suelo tumbado en tu espalda con tus pies en la parte superior de la pelota.\", \"Coloca la pelota de manera que cuando tus piernas esten extendidas tus tobillos esten en la parte superior de la pelota. Esta sera tu posicion inicial.\", \"Levanta las caderas del suelo, manteniendo tu peso en los omoplatos y tus pies.\", \"Flexiona las rodillas, tirando de la pelota lo mas cerca posible de ti, contrayendo los isquiotibiales.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"Ball_Leg_Curl/0.jpg\", \"Ball_Leg_Curl/1.jpg\"]','Flexion de piernas con balon',34) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominada asistida con banda','Ninguno','principiante','compuesto','otro','[\"dorsales\"]','[\"abdominales\", \"antebrazos\", \"espalda_media\"]','[\"Aprieta la banda alrededor del centro de la barra de dominadas. Puedes usar diferentes bandas para proporcionar distintos niveles de asistencia.\", \"Tira del extremo de la banda hacia abajo y coloca una rodilla doblada en el lazo, asegurandote de que no se salga. Toma un agarre medio a amplio en la barra. Esta sera tu posicion inicial.\", \"Subete hacia arriba contrayendo los dorsales mientras flexionas el codo. El codo debe quedar pegado al costado. Tira hacia adelante, intentando llevar la barbilla por encima de la barra. Evita los movimientos bruscos o sacudidas.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"Band_Assisted_Pull-Up/0.jpg\", \"Band_Assisted_Pull-Up/1.jpg\"]','Bandas_asistidas_para_dominadas',35) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Band Good Morning','traccion','principiante','compuesto','bandas','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\"]','[\"Con una banda de 41 pulgadas, ponte de pie en un extremo, separando ligeramente los pies. Dobla las caderas para pasar el extremo de la banda por detras del cuello. Esta sera tu posicion inicial.\", \"Manteniendo las piernas rectas, extiende las caderas hasta llegar a una posicion casi vertical.\", \"Asegurate de no arquear la espalda al bajar a la posicion inicial.\"]','levantamiento de pesas','[\"Band_Good_Morning/0.jpg\", \"Band_Good_Morning/1.jpg\"]','Buenos dias con banda',36) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Band Good Morning (Pull Through)','traccion','principiante','compuesto','bandas','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\"]','[\"Enrolla la banda alrededor de un poste. Colocate a cierta distancia y enrolla el extremo opuesto alrededor del cuello. Tus manos pueden ayudarte a mantener la banda en su posicion.\", \"Comienza flexionando las caderas y alejando el trasero lo maximo posible. Manten la espalda recta e inclinate hacia delante aproximadamente 90 grados. Las rodillas deben estar solo ligeramente flexionadas.\", \"Vuelve a la posicion inicial empujando con las caderas para volver a la posicion de pie.\"]','levantamiento de pesas','[\"Band_Good_Morning_Pull_Through/0.jpg\", \"Band_Good_Morning_Pull_Through/1.jpg\"]','Band_Buenos_dias_tirada_hacia_adelante',37) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Aducciones de cadera con banda','traccion','principiante','aislamiento','bandas','[\"aductores\"]','[]','[\"Ancla una banda alrededor de un poste solido u otro objeto.\", \"Ponte de pie con tu lado izquierdo hacia el poste y pasa tu pie derecho por la banda, colocandola alrededor del tobillo.\", \"Ponte de pie recto y mantente agarrado al poste si es necesario. Esta sera tu posicion inicial.\", \"Manteniendo la rodilla recta, levanta la pierna derecha hacia el lado tanto como puedas.\", \"Vuelve a la posicion inicial y repite durante el numero de repeticiones deseado.\", \"Cambia de lado.\"]','fuerza','[\"Band_Hip_Adductions/0.jpg\", \"Band_Hip_Adductions/1.jpg\"]','Aduccion de cadera con banda',38) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Separacion con banda','traccion','principiante','aislamiento','bandas','[\"hombros\"]','[\"espalda_media\", \"trapecios\"]','[\"Comienza con los brazos extendidos rectos frente a ti, sosteniendo la banda con ambas manos.\", \"Inicia el movimiento realizando un movimiento de vuelo inverso, moviendo las manos lateralmente hacia los costados.\", \"Manten los codos extendidos mientras realizas el movimiento, llevando la banda hacia el pecho. Asegurate de mantener los hombros hacia atras durante el ejercicio.\", \"Haz una pausa al completar el movimiento y vuelve a la posicion inicial de forma controlada.\"]','fuerza','[\"Band_Pull_Apart/0.jpg\", \"Band_Pull_Apart/1.jpg\"]','Separacion con banda',39) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Band Skull Crusher','empuje','principiante','aislamiento','bandas','[\"triceps\"]','[]','[\"Fija una banda a la base de una rejilla o al banco. Tumbate en el banco de forma que la banda quede alineada por encima de tu cabeza.\", \"Sujeta la banda, levantando los codos de forma que la parte superior del brazo quede perpendicular al suelo. Con el codo flexionado, la banda debe quedar por encima de tu cabeza. Esta sera tu posicion inicial.\", \"Extiende el codo para estirar el brazo, manteniendo la parte superior del brazo en su sitio. Haz una pausa arriba del movimiento y vuelve a la posicion inicial.\"]','fuerza','[\"Band_Skull_Crusher/0.jpg\", \"Band_Skull_Crusher/1.jpg\"]','Band_Skull_Crusher',40) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Barbell Ab Rollout','traccion','intermedio','compuesto','barra','[\"abdominales\"]','[\"espalda_baja\", \"hombros\"]','[\"Para este ejercicio, tendras que ponerte en posicion de flexion, pero en lugar de apoyar las manos en el suelo, agarraras una barra olimpica (cargada con 5-10 libras en cada lado). Esta sera tu posicion inicial.\", \"Mientras mantienes un ligero arco en la espalda, levanta las caderas y rueda la barra hacia los pies mientras exhalas. Consejo: Mientras realizas el movimiento, tus gluteos deben levantarse, debes mantener los abdominales tensos y debes mantener la postura de la espalda en todo momento. Ademas, tus brazos deben permanecer perpendiculares al suelo durante todo el movimiento. Si no lo haces, trabajaras mas los hombros y la espalda que los abdominales.\", \"Despues de una segunda contraccion en la parte superior, comienza a rodar la barra hacia adelante lentamente mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Ab_Rollout/0.jpg\", \"Barbell_Ab_Rollout/1.jpg\"]','Barra_Abdominales_Rollout',41) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Barbell Ab Rollout - De rodillas','traccion','experto','compuesto','barra','[\"abdominales\"]','[\"espalda_baja\", \"hombros\"]','[\"Sujeta una barra olimpica cargada con 5-10 libras en cada lado y arrodillate en el suelo.\", \"Ahora coloca la barra en el suelo frente a ti, de modo que estes apoyado en las manos y las rodillas (como en una posicion de flexion arrodillada). Esta sera tu posicion inicial.\", \"Desliza lentamente la barra hacia delante, estirando el cuerpo hasta una posicion recta. Consejo: Baja todo lo que puedas sin tocar el suelo con tu cuerpo. Inhala durante esta parte del movimiento.\", \"Despues de una pausa de un segundo en la posicion estirada, empieza a tirar de ti mismo hacia atras a la posicion inicial mientras exhalas. Consejo: Ve despacio y manten los abdominales tensos en todo momento.\"]','fuerza','[\"Barbell_Ab_Rollout_-_On_Knees/0.jpg\", \"Barbell_Ab_Rollout_-_On_Knees/1.jpg\"]','Barra_Abdominales_Rollout_-_De_rodillas',42) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con barra - Agarre medio','empuje','principiante','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco plano. Con un agarre de anchura media (un agarre que crea un angulo de 90 grados en el centro del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Desde la posicion inicial, respira y comienza a bajar lentamente hasta que la barra toque la parte media del pecho.\", \"Despues de una breve pausa, empuja la barra hacia atras a la posicion inicial mientras exhalas. Concentrate en empujar la barra utilizando los musculos del pecho. Bloquea los brazos y contrae el pecho en la posicion superior del movimiento, manten durante un segundo y luego comienza a bajar lentamente de nuevo. Consejo: Lo ideal es que bajar el peso te lleve aproximadamente el doble de tiempo que levantarlo.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra de nuevo en el soporte.\"]','fuerza','[\"Barbell_Bench_Press_-_Medium_Grip/0.jpg\", \"Barbell_Bench_Press_-_Medium_Grip/1.jpg\"]','Press de banca con barra - Agarre medio',43) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con barra','traccion','principiante','aislamiento','barra','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie con el torso erguido mientras sostienes una barra con un agarre a la anchura de los hombros. Las palmas de las manos deben estar mirando hacia delante y los codos deben estar cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores inmoviles, flexiona los pesos hacia delante mientras contraes los biceps y exhalas. Consejo: Solo deben moverse los antebrazos.\", \"Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo y aprieta los biceps con fuerza.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Curl/0.jpg\", \"Barbell_Curl/1.jpg\"]','Curl con barra',44) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curls con barra tumbado en un banco inclinado','traccion','principiante','aislamiento','barra','[\"biceps\"]','[]','[\"Acuestate en un banco inclinado, con los brazos sosteniendo una barra y colgando hacia abajo en linea horizontal. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, levanta el peso lo mas alto que puedas mientras aprietas los biceps. Exhala mientras realizas esta parte del movimiento. Consejo: Solo deben moverse los antebrazos. No balancees los brazos.\", \"Despues de una segunda contraccion, vuelve lentamente a la posicion inicial mientras inhalas. Consejo: Asegurate de bajar completamente.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Curls_Lying_Against_An_Incline/0.jpg\", \"Barbell_Curls_Lying_Against_An_Incline/1.jpg\"]','Curl con barra tumbado en inclinacion',45) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Puente gluteo con barra','empuje','intermedio','compuesto','barra','[\"gluteos\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Comienza sentado en el suelo con una barra cargada sobre tus piernas. Usar una barra gruesa o colocar una almohadilla en la barra puede reducir en gran medida la incomodidad causada por este ejercicio. Haz rodar la barra para que quede directamente sobre tus caderas y tumbate boca arriba en el suelo.\", \"Comienza el movimiento empujando con los talones, extendiendo tus caderas verticalmente a traves de la barra. Tu peso debe estar apoyado en la parte superior de la espalda y los talones de los pies.\", \"Extiende lo mas lejos posible, luego invierte el movimiento para volver a la posicion inicial.\"]','levantamiento de pesas','[\"Barbell_Glute_Bridge/0.jpg\", \"Barbell_Glute_Bridge/1.jpg\"]','Puente gluteo con barra',48) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con barra','empuje','intermedio','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Con un agarre de anchura media (un agarre que crea un angulo de 90 grados en el centro del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y mantenla recta sobre tu cuello con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Mientras inhalas, baja la barra lentamente hasta que este aproximadamente a 1 pulgada de tu cuello.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra usando los musculos del pecho. Bloquea los brazos y aprieta el pecho en la posicion contraida, manten durante un segundo y luego comienza a bajar lentamente de nuevo. Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra de nuevo en el soporte.\"]','fuerza','[\"Barbell_Guillotine_Bench_Press/0.jpg\", \"Barbell_Guillotine_Bench_Press/1.jpg\"]','Press de banca con barra guillotina',49) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado con barra - Agarre medio','empuje','principiante','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco inclinado. Con un agarre de anchura media (un agarre que crea un angulo de 90 grados en el centro del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Mientras inspiras, baja lentamente hasta que sientas la barra en la parte superior del pecho.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos del pecho. Bloquea los brazos en la posicion contraida, aprieta el pecho, manten la posicion durante un segundo y luego vuelve a bajar lentamente. Consejo: debe tardar al menos el doble de tiempo en bajar que en subir.\", \"Repita el movimiento durante el numero de repeticiones prescrito.\", \"Cuando haya terminado, coloque la barra de nuevo en el soporte.\"]','fuerza','[\"Barbell_Incline_Bench_Press_-_Medium_Grip/0.jpg\", \"Barbell_Incline_Bench_Press_-_Medium_Grip/1.jpg\"]','Press de banca inclinado con barra - Agarre medio',52) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado con barra','empuje','principiante','compuesto','barra','[\"hombros\"]','[\"pecho\"]','[\"Acuestese boca arriba en un banco inclinado. Con un agarre de anchura media (un poco mas ancho que el ancho de los hombros), levante la barra del soporte y mantengala recta sobre usted con los brazos estirados. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos rectos, levanta la barra protrayendo los omoplatos, levantando los hombros del banco mientras exhalas.\", \"Lleva la barra a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Incline_Shoulder_Raise/0.jpg\", \"Barbell_Incline_Shoulder_Raise/1.jpg\"]','Levantamiento de hombros inclinado con barra',53) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension con barra desde el banco','traccion','intermedio','compuesto','barra','[\"abdominales\"]','[\"gluteos\", \"isquiotibiales\", \"dorsales\", \"hombros\"]','[\"Coloca una barra cargada en el suelo, cerca del extremo de un banco. Arrodillate con ambas piernas en el banco y agarra la barra con un agarre medio-estrecho. Esta sera tu posicion inicial.\", \"Para empezar, extiende las caderas para rodar lentamente la barra hacia delante. A medida que la desplazas, flexiona los hombros para llevar la barra por encima de la cabeza. Asegurate de que los brazos permanezcan extendidos durante todo el movimiento.\", \"Cuando la barra haya sido desplazada lo mas adelante posible, vuelve a la posicion inicial.\"]','fuerza','[\"Barbell_Rollout_from_Bench/0.jpg\", \"Barbell_Rollout_from_Bench/1.jpg\"]','Barra_Rollout_desde_banco',56) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de pantorrillas con barra sentado','empuje','principiante','aislamiento','barra','[\"pantorrillas\"]','[]','[\"Coloca un bloque aproximadamente a 30 cm delante de un banco plano.\", \"Sientate en el banco y coloca la parte anterior de los pies sobre el bloque.\", \"Pide a alguien que coloque una barra sobre la parte superior de tus muslos, aproximadamente 7,5 cm por encima de tus rodillas, y mantenla ahi. Esta sera tu posicion inicial.\", \"Levantate sobre los dedos de los pies lo mas alto posible mientras aprietas las pantorrillas y exhalas.\", \"Despues de una segunda contraccion, vuelve lentamente a la posicion inicial. Consejo: Para obtener el maximo beneficio, estira las pantorrillas lo mas lejos que puedas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Seated_Calf_Raise/0.jpg\", \"Barbell_Seated_Calf_Raise/1.jpg\"]','Elevacion de pantorrillas sentado con barra',57) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de hombros con barra','empuje','intermedio','compuesto','barra','[\"hombros\"]','[\"pecho\", \"triceps\"]','[\"Sientate en un banco con la espalda apoyada en un soporte para sentadillas. Coloca una barra a una altura que este justo por encima de tu cabeza. Agarra la barra con un agarre pronado (las palmas mirando hacia delante).\", \"Una vez que hayas cogido la barra con el ancho de agarre correcto, levanta la barra por encima de tu cabeza bloqueando los brazos. Mantenla aproximadamente a la altura de los hombros y ligeramente por delante de tu cabeza. Esta es tu posicion inicial.\", \"Baja la barra lentamente hasta los hombros mientras inhalas.\", \"Eleva la barra por encima de la espalda hasta la posicion inicial mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Barbell_Shoulder_Press/0.jpg\", \"Barbell_Shoulder_Press/1.jpg\"]','Press de hombros con barra',58) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros con barra','traccion','principiante','aislamiento','barra','[\"trapecios\"]','[]','[\"Ponte de pie recto con tus pies al ancho de los hombros mientras mantienes una barra con ambas manos frente a ti usando un agarre pronado (las palmas mirando hacia los muslos). Consejo: Tus manos deben estar un poco mas separadas que el ancho de los hombros. Puedes usar muñequeras durante este ejercicio para tener un mejor agarre. Esta sera tu posicion inicial.\", \"Levanta los hombros hacia arriba tanto como puedas mientras exhalas y manten la contraccion durante un segundo. Consejo: Evita levantar la barra usando los biceps.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Shrug/0.jpg\", \"Barbell_Shrug/1.jpg\"]','Encogimiento de hombros con barra',59) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros con barra detras de la espalda','traccion','principiante','aislamiento','barra','[\"trapecios\"]','[\"antebrazos\", \"espalda_media\"]','[\"Ponte de pie recto con tus pies at shoulder width as you manten una barra con ambos manos behind tu espalda using a pronated grip (palms facing back). Consejo: Your manos should be a little wider than shoulder width apart. You can use wrist wraps durante este exercise during better grip. Esta sera tu posicion inicial.\", \"Levanta tu hombros arriba tan lejos como puedas ve mientras exhalas y manten la contraccion durante un segundo. Consejo: Evita levantar la barra utilizando los biceps. Los brazos deben permanecer estirados en todo momento.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Barbell_Shrug_Behind_The_Back/0.jpg\", \"Barbell_Shrug_Behind_The_Back/1.jpg\"]','Encogimiento de hombros con barra detras de la espalda',60) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion lateral con barra','traccion','principiante','aislamiento','barra','[\"abdominales\"]','[\"espalda_baja\"]','[\"Ponte de pie recto mientras sostienes una barra colocada en la espalda de tus hombros (ligeramente por debajo del cuello). Tus pies deben estar separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Mientras mantienes la espalda recta y la cabeza erguida, inclinate solo por la cintura hacia la derecha tanto como te sea posible. Inhala mientras te inclinas hacia un lado. A continuacion, manten la posicion durante un segundo y vuelve a la posicion inicial mientras exhalas. Consejo: manten el resto del cuerpo inmovil.\", \"Ahora repite el movimiento, pero inclinandote hacia la izquierda. Manten la posicion durante un segundo y vuelve a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Barbell_Side_Bend/0.jpg\", \"Barbell_Side_Bend/1.jpg\"]','Flexion lateral con barra',61) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla lateral con barra','empuje','principiante','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"isquiotibiales\", \"espalda_baja\"]','[\"Ponte de pie recto mientras sostienes una barra colocada en la espalda de tus hombros (ligeramente por debajo del cuello). Tus pies deben estar separados con el pie de la pierna delantera en angulo hacia el lado. Esta sera tu posicion inicial.\", \"Baja tu cuerpo hacia el lado de tu pie en angulo doblando la rodilla y la cadera de tu pierna delantera y manteniendo la pierna opuesta solo ligeramente doblada. Inhala mientras bajas tu cuerpo.\", \"Regresa a la posicion inicial extendiendo la cadera y la rodilla de la pierna delantera. Exhala mientras realizas este movimiento.\", \"Despues de realizar la cantidad recomendada de repeticiones, repite el movimiento con la pierna opuesta.\"]','fuerza','[\"Barbell_Side_Split_Squat/0.jpg\", \"Barbell_Side_Split_Squat/1.jpg\"]','Sentadilla lateral con barra',62) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con barra','empuje','principiante','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Este ejercicio se realiza mejor dentro de una jaula de sentadillas por motivos de seguridad. Para comenzar, primero coloca la barra en una jaula justo por debajo del nivel de los hombros. Una vez elegida la altura correcta y cargada la barra, colocate debajo de la barra y coloca la espalda de tus hombros (ligeramente por debajo del cuello) sobre ella.\", \"Sujeta la barra con ambos brazos a cada lado y levantala del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso.\", \"Alejate del soporte y coloca las piernas a la anchura de los hombros con los dedos de los pies ligeramente apuntando hacia fuera. Manten la cabeza arriba en todo momento y tambien manten la espalda recta. Esta sera tu posicion inicial. (Nota: A efectos de esta discusion, utilizaremos la postura media descrita anteriormente, que se centra en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas descritas en la seccion de posturas de los pies).\", \"Comienza a bajar lentamente la barra doblando las rodillas y las caderas mientras mantienes una postura recta con la cabeza arriba. Continua bajando hasta que el angulo entre la parte superior de la pierna y las pantorrillas sea ligeramente inferior a 90 grados. Inhala mientras realizas esta parte del movimiento. Consejo: Si has realizado el ejercicio correctamente, la parte delantera de las rodillas debe formar una linea recta imaginaria con los dedos de los pies, que es perpendicular a la parte delantera. Si tus rodillas estan mas alla de esa linea imaginaria (si estan mas alla de los dedos de los pies), entonces estas ejerciendo una tension excesiva sobre las rodillas y el ejercicio se ha realizado incorrectamente.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo con el talon del pie mientras enderezas las piernas de nuevo y vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Barbell_Squat/0.jpg\", \"Barbell_Squat/1.jpg\"]','Barbell_Squat',63) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Step ups con barra','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Ponte de pie recto mientras sostienes una barra colocada en la espalda de tus hombros (ligeramente por debajo del cuello) y ponte erguido detras de una plataforma elevada (como la que se utiliza durante el spotting detras de un banco plano). Esta es tu posicion inicial.\", \"Coloca el pie derecho en la plataforma elevada. Sube a la plataforma extendiendo la cadera y la rodilla de la pierna derecha. Utiliza principalmente el talon para levantar el resto del cuerpo y coloca tambien el pie de la pierna izquierda en la plataforma. Exhala mientras ejecutas la fuerza necesaria para subir.\", \"Da un paso hacia abajo con la pierna izquierda flexionando la cadera y la rodilla de la pierna derecha mientras inhalas. Vuelve a la posicion inicial colocando el pie derecho junto al pie izquierdo en la posicion inicial.\", \"Repite con la pierna derecha durante el numero recomendado de repeticiones y luego hazlo con la pierna izquierda.\"]','fuerza','[\"Barbell_Step_Ups/0.jpg\", \"Barbell_Step_Ups/1.jpg\"]','Subidas con barra',65) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancada con barra','empuje','principiante','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza de pie con los pies separados a la anchura de los hombros y una barra sobre la parte superior de la espalda.\", \"Da un paso adelante con una pierna, flexionando las rodillas para bajar las caderas. Desciende hasta que la rodilla trasera casi toque el suelo. Tu postura debe permanecer erguida y tu rodilla delantera debe permanecer por encima del pie delantero.\", \"Empuja con el talon del pie delantero y extiende ambas rodillas para levantarte.\", \"Da un paso adelante con el pie trasero, repitiendo la zancada con la pierna opuesta.\"]','fuerza','[\"Barbell_Walking_Lunge/0.jpg\", \"Barbell_Walking_Lunge/1.jpg\"]','Zancada caminando con barra',66) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cuerdas de entrenamiento','empuje','principiante','compuesto','otro','[\"hombros\"]','[\"pecho\", \"antebrazos\"]','[\"Para este ejercicio necesitaras una cuerda pesada anclada en su centro a una distancia de entre 4,5 y 6 metros. De pie frente a la cuerda, toma un extremo en cada mano con los brazos extendidos a los lados. Esta sera tu posicion inicial.\", \"Inicia el movimiento levantando rapidamente un brazo hasta la altura del hombro tan rapido como puedas.\", \"A medida que dejas caer el brazo a la posicion inicial, levanta el lado opuesto.\", \"Continua alternando los brazos izquierdo y derecho, azotando las cuerdas arriba y abajo tan rapido como puedas.\"]','fuerza','[\"Battling_Ropes/0.jpg\", \"Battling_Ropes/1.jpg\"]','Cuerdas de entrenamiento',67) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pecho detras de la cabeza','estatico','experto','aislamiento','otro','[\"pecho\"]','[\"hombros\"]','[\"Sientate erguido en el suelo con tu compañero detras de ti.\", \"Coloca tus manos detras de tu cabeza y empuja tus codos hacia atras tan lejos como puedas. Tu compañero debe sujetar tus codos. Esta sera tu posicion inicial.\", \"Intenta tirar suavemente de tus codos hacia delante con las manos todavia detras de la cabeza durante 10 o mas segundos. Tu compañero debe evitar que tus codos se muevan.\", \"Ahora, relaja tus musculos y deja que tu compañero tire suavemente de tus codos hacia atras tanto como te resulte comodo. Asegurate de avisar a tu compañero cuando el estiramiento sea adecuado para evitar un estiramiento excesivo o una lesion.\"]','estiramiento','[\"Behind_Head_Chest_Stretch/0.jpg\", \"Behind_Head_Chest_Stretch/1.jpg\"]','Estiramiento detras de la cabeza y el pecho',69) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Fondos en banco','empuje','principiante','compuesto','solo_cuerpo','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Para este ejercicio, necesitaras colocar un banco detras de tu espalda. Con el banco perpendicular a tu cuerpo, y mientras miras alejandote de el, manten en el banco en su borde con las manos completamente extendidas, separadas a la altura de los hombros. Las piernas estaran extendidas hacia delante, dobladas por la cintura y perpendiculares a tu torso. Esta sera tu posicion inicial.\", \"Baja lentamente tu cuerpo mientras inhalas doblando los codos hasta bajar lo suficiente como para que haya un angulo ligeramente inferior a 90 grados entre la parte superior del brazo y el antebrazo. Consejo: Manten los codos lo mas cerca posible durante todo el movimiento. Los antebrazos deben apuntar siempre hacia abajo.\", \"Utiliza los triceps para volver a subir el torso y levantate hasta la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Bench_Dips/0.jpg\", \"Bench_Dips/1.jpg\"]','Fondos en banco',70) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto en banco','empuje','intermedio','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza con una caja o un banco a 1-2 pies frente a ti. Ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Realiza una sentadilla corta como preparacion para el salto; balancea los brazos hacia atras.\", \"Rebota desde esta posicion, extendiendo las caderas, las rodillas y los tobillos para saltar lo mas alto posible. Balancea los brazos hacia delante y hacia arriba.\", \"Salta por encima del banco, aterrizando con las rodillas flexionadas, absorbiendo el impacto con las piernas.\", \"Gira y mira en la direccion opuesta, luego salta de espaldas por encima del banco.\"]','pliometria','[\"Bench_Jump/0.jpg\", \"Bench_Jump/1.jpg\"]','Salto sobre banco',71) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca - Powerlifting','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"antebrazos\", \"dorsales\", \"hombros\"]','[\"Comienza tumbado en el banco, colocando la cabeza mas alla de la barra si es posible. Mete los pies debajo de ti y arquea la espalda. Utilizando la barra para ayudarte a soportar tu peso, levanta los hombros del banco y retractalos, apretando los omoplatos. Utiliza los pies para empujar los trapecios contra el banco. Manten esta posicion corporal firme durante todo el movimiento.\", \"Independientemente de la anchura de tu agarre, este debe cubrir el anillo de la barra. Tira de la barra fuera del soporte sin protraer los hombros. Concentrate en apretar la barra e intentar separarla.\", \"Baja la barra hasta la parte inferior del pecho o la parte superior del estomago. La barra, la muñeca y el codo deben permanecer alineados en todo momento.\", \"Haz una pausa cuando la barra toque tu torso y luego empuja la barra hacia arriba con tanta fuerza como sea posible. Los codos deben estar pegados al cuerpo hasta el bloqueo.\"]','levantamiento de pesas','[\"Bench_Press_-_Powerlifting/0.jpg\", \"Bench_Press_-_Powerlifting/1.jpg\"]','Press de banca - Powerlifting',72) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca - Con bandas','empuje','principiante','compuesto','bandas','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Usando un banco plano, asegura una banda debajo de la pata del banco que esta mas cerca de tu cabeza.\", \"Una vez que la banda este asegurada, agarrala por ambas asas y tumbate en el banco.\", \"Extiende tus brazos de modo que sostengas las asas de la banda frente a ti a la altura de los hombros.\", \"Una vez a la altura de los hombros, gira tus muñecas hacia delante de modo que las palmas de tus manos queden mirando hacia fuera. Esta sera tu posicion inicial.\", \"Baja las asas lentamente hasta que tus codos formen un angulo de 90 grados. Manten el control total en todo momento.\", \"Mientras exhalas, lleva las asas hacia arriba utilizando los musculos pectorales. Bloquea los brazos en la posicion contraida, aprieta el pecho, manten la posicion durante un segundo y luego empieza a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito en tu programa de entrenamiento.\"]','fuerza','[\"Bench_Press_-_With_Bands/0.jpg\", \"Bench_Press_-_With_Bands/1.jpg\"]','Press de banca con bandas',73) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con cadenas','empuje','experto','compuesto','barra','[\"triceps\"]','[\"pecho\", \"dorsales\", \"hombros\"]','[\"Ajusta la cadena principal, acortandola hasta la longitud deseada. Coloca las cadenas en las mangas de la barra.\", \"Tumbado en el banco, coloca la cabeza mas alla de la barra si es posible. Mete los pies debajo de ti y arquea la espalda. Usando la barra para ayudarte a soportar tu peso, levanta los hombros del banco y retractalos, apretando los omoplatos. Usa tus pies para empujar tus trapecios contra el banco. Manten esta posicion corporal firme durante todo el movimiento. Sea cual sea la anchura de tu agarre, debe cubrir el anillo de la barra.\", \"Tira de la barra fuera del soporte sin protraer los hombros. Concentrate en apretar la barra e intenta separarla. Baja la barra hasta la parte inferior del pecho o la parte superior del estomago. La barra, la muñeca y el codo deben permanecer alineados en todo momento.\", \"Haz una pausa cuando la barra toque tu torso y luego empuja la barra hacia arriba con tanta fuerza como sea posible. Los codos deben estar pegados al cuerpo hasta el bloqueo.\"]','levantamiento de pesas','[\"Bench_Press_with_Chains/0.jpg\", \"Bench_Press_with_Chains/1.jpg\"]','Press de banca con cadenas',74) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sprint en banco','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie en el suelo con un pie apoyado en un banco o caja con el talon cerca del borde.\", \"Empuja con el pie en la parte superior del banco, extendiendo la cadera y la rodilla.\", \"Aterriza con el pie opuesto en la parte superior de la caja, volviendo el otro pie a la posicion inicial.\", \"Continua alternando de un pie a otro para completar la serie.\"]','pliometria','[\"Bench_Sprint/0.jpg\", \"Bench_Sprint/1.jpg\"]','Sprint en banco',75) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Inclinacion con mancuernas Elevacion deltoides posterior con la cabeza en el banco','traccion','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Ponte de pie recto mientras sostienes una mancuerna en cada mano y con un banco inclinado frente a ti.\", \"Mientras mantienes la espalda recta y conservas el arco natural de tu espalda, inclinate hacia adelante hasta que tu frente toque el banco frente a ti. Deja que los brazos cuelguen frente a ti perpendiculares al suelo. Las palmas de tus manos deben estar enfrentadas entre si y tu torso debe estar paralelo al suelo. Esta sera tu posicion inicial.\", \"Manteniendo tu torso hacia adelante y fijo, y los brazos rectos con una ligera flexion en los codos, levanta las mancuernas rectas hacia los lados hasta que ambos brazos esten paralelos al suelo. Exhala mientras levantas las pesas. Precaucion: evita balancear el torso o llevar los brazos hacia atras en lugar de hacia los lados.\", \"Despues de una contraccion de un segundo en la parte superior, baja lentamente las mancuernas hacia atras hasta la posicion inicial.\", \"Repite el numero recomendado de repeticiones.\"]','fuerza','[\"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/0.jpg\", \"Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench/1.jpg\"]','Levantamiento inclinado con mancuernas para deltoides posterior con la cabeza en el banco',77) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo inclinado con dos mancuernas','traccion','principiante','compuesto','mancuerna','[\"espalda_media\"]','[\"biceps\", \"dorsales\", \"hombros\"]','[\"Con una mancuerna en cada mano (las palmas mirando hacia tu torso), flexiona ligeramente las rodillas y lleva el torso hacia adelante doblando la cintura; mientras te inclinas, asegurate de mantener la espalda recta hasta que este casi paralela al suelo. Consejo: Asegurate de mantener la cabeza erguida. Las pesas deben colgar directamente frente a ti, con los brazos perpendiculares al suelo y el torso. Esta es tu posicion inicial.\", \"Mientras mantienes el torso inmovil, levanta las mancuernas hacia los lados (mientras exhalas), manteniendo los codos cerca del cuerpo (no ejerzas ninguna fuerza con los antebrazos que no sea la de sostener las pesas). En la posicion superior contraida, aprieta los musculos de la espalda y manten durante un segundo.\", \"Baja lentamente el peso de nuevo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Bent_Over_Two-Dumbbell_Row/0.jpg\", \"Bent_Over_Two-Dumbbell_Row/1.jpg\"]','Remo inclinado con dos mancuernas',81) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo inclinado con dos mancuernas y las palmas hacia dentro','traccion','principiante','compuesto','mancuerna','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Con una mancuerna en cada mano (las palmas enfrentadas), flexiona ligeramente las rodillas e inclina el torso hacia delante, doblando la cintura, mientras mantienes la espalda recta hasta que quede casi paralela al suelo. Consejo: Asegurate de mantener la cabeza erguida. Las pesas deben colgar directamente frente a ti, con los brazos perpendiculares al suelo y el torso. Esta es tu posicion inicial.\", \"Mientras mantienes el torso inmovil, levanta las mancuernas hacia tu lado mientras exhalas, apretando los omoplatos. En la posicion superior contraida, aprieta los musculos de la espalda y manten durante un segundo.\", \"Baja lentamente el peso de nuevo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Bent_Over_Two-Dumbbell_Row_With_Palms_In/0.jpg\", \"Bent_Over_Two-Dumbbell_Row_With_Palms_In/1.jpg\"]','Remo inclinado con dos mancuernas y palmas hacia dentro',82) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado','traccion','experto','compuesto','pesas rusas','[\"abdominales\"]','[\"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"triceps\"]','[\"Limpia una pesa rusa hasta tu hombro. Limpia la pesa rusa hasta tus hombros extendiendo las piernas y las caderas mientras levantas la pesa rusa hacia tu hombro. La muñeca debe girar mientras lo haces. Esta sera tu posicion inicial.\", \"Comienza inclinandote hacia el lado opuesto a la pesa rusa, continuando hasta que puedas tocar el suelo con tu mano libre, manteniendo la vista en la pesa rusa. Mientras lo haces, presiona el peso verticalmente extendiendo el codo, manteniendo el brazo perpendicular al suelo.\", \"Regresa a una posicion erguida, con la pesa rusa por encima de tu cabeza. Vuelve a colocar la pesa rusa en el hombro y repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Bent_Press/0.jpg\", \"Bent_Press/1.jpg\"]','Press inclinado',83) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de cadera con rodillas flexionadas','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Tumbate en el suelo con los brazos junto a los costados.\", \"Ahora flexiona las rodillas en un angulo de aproximadamente 75 grados y levanta los pies del suelo unos 5 cm.\", \"Utilizando los abdominales inferiores, lleva las rodillas hacia ti mientras mantienes el angulo de 75 grados en las piernas. Continua este movimiento hasta que levantes las caderas del suelo haciendo rodar la pelvis hacia atras. Exhala mientras realizas esta parte del movimiento. Consejo: Al final del movimiento, tus rodillas estaran sobre tu pecho.\", \"Aprieta tus abdominales en la parte superior del movimiento durante un segundo y luego vuelve a la posicion inicial lentamente mientras inhalas. Consejo: Manten un movimiento controlado en todo momento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Bent-Knee_Hip_Raise/0.jpg\", \"Bent-Knee_Hip_Raise/1.jpg\"]','Elevacion de cadera con rodillas flexionadas',86) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bicicleta','Ninguno','principiante','Ninguno','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, sientate en la bicicleta y ajusta el sillin a tu altura.\"]','cardio','[\"Ciclismo/0.jpg\", \"Ciclismo/1.jpg\"]','Bicicleta',87) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ciclismo, estatico','Ninguno','principiante','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, sientese en la bicicleta y ajuste el sillin a su altura.\", \"Seleccione la opcion deseada en el menu. Puede empezar a pedalear para encenderla. Puedes utilizar el ajuste manual o seleccionar un programa. Normalmente, puedes introducir tu edad y peso para calcular la cantidad de calorias quemadas durante el ejercicio. El nivel de resistencia se puede cambiar durante el entrenamiento. Las asas se pueden utilizar para controlar tu frecuencia cardiaca y ayudarte a mantener una intensidad adecuada.\"]','cardio','[\"Bicycling_Stationary/0.jpg\", \"Bicycling_Stationary/1.jpg\"]','Bicicleta estatica',88) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"antebrazos\", \"dorsales\", \"hombros\"]','[\"Comience tumbado en el banco, colocando la cabeza mas alla de la barra si es posible. Se pueden atornillar entre una y cinco tablas, fabricadas con listones de 2x6, y sujetarlas con la ayuda de un compañero de entrenamiento, bandas elasticas o simplemente metiendolas debajo de la camiseta.\", \"Mete los pies debajo de ti y arquea la espalda. Utilizando la barra para ayudar a soportar tu peso, levanta los hombros del banco y retractalos, apretando los omoplatos. Usa los pies para empujar los trapecios contra el banco. Manten esta posicion corporal firme durante todo el movimiento.\", \"Puedes hacer un agarre estandar en el banco o a la anchura de los hombros para centrarte en los triceps. Tira de la barra fuera del soporte sin protraer los hombros. La barra, la muñeca y el codo deben permanecer alineados en todo momento. Concentrate en apretar la barra e intentar separarla.\", \"Baja la barra hasta las tablas y luego empujala hacia arriba con tanta fuerza como sea posible. Los codos deben estar pegados al cuerpo hasta el bloqueo.\"]','levantamiento de pesas','[\"Board_Press/0.jpg\", \"Board_Press/1.jpg\"]','Press de banca',89) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de triceps con el cuerpo','empuje','principiante','aislamiento','solo_cuerpo','[\"triceps\"]','[]','[\"Coloca una barra en un soporte a la altura del pecho.\", \"De pie, agarra la barra con las manos separadas a la anchura de los hombros y da un paso o dos hacia atras, con los pies juntos y los brazos extendidos, de modo que te inclines sobre la barra. Esta sera tu posicion inicial.\", \"Comienza flexionando los codos, bajando hacia la barra.\", \"Haz una pausa y luego invierte el movimiento extendiendo los codos.\", \"Aumenta la dificultad añadiendo cadenas sobre tus hombros.\"]','fuerza','[\"Body_Tricep_Press/0.jpg\", \"Body_Tricep_Press/1.jpg\"]','Press de triceps con barra',90) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Body-Up','empuje','intermedio','aislamiento','solo_cuerpo','[\"triceps\"]','[\"abdominales\", \"antebrazos\"]','[\"Adopta una posicion de plancha en el suelo. Debes apoyar el peso de tu cuerpo en los dedos de los pies y los antebrazos, manteniendo el torso recto. Los antebrazos deben estar separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Presionando las palmas de las manos firmemente contra el suelo, extiende los codos para levantar el cuerpo del suelo. Manten el torso rigido mientras realizas el movimiento.\", \"Baja lentamente los antebrazos hacia la espalda permitiendo que los codos se flexionen.\", \"Repite.\"]','fuerza','[\"Body-Up/0.jpg\", \"Body-Up/1.jpg\"]','Body-Up',91) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bodyweight Flyes','empuje','intermedio','aislamiento','barra_ez','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Coloca dos barras EZ con el mismo peso en el suelo, una al lado de la otra. Asegurate de que puedan rodar.\", \"Adopta una posicion de flexion sobre las barras, apoyando tu peso en los dedos de los pies y las manos, con los brazos extendidos y el cuerpo recto.\", \"Coloca tus manos en las barras. Esta sera tu posicion inicial.\", \"Con un movimiento lento y controlado, aleja tus manos de la linea media de tu cuerpo, separando las barras. Inhala durante esta parte del movimiento.\", \"Despues de separar las barras lo maximo posible, vuelve a la posicion inicial tirando de ellas hacia atras. Exhala mientras realizas este movimiento.\"]','fuerza','[\"Bodyweight_Flyes/0.jpg\", \"Bodyweight_Flyes/1.jpg\"]','Bodyweight_Flyes',92) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bodyweight Sentadilla','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie con los pies separados a la anchura de los hombros. Puedes colocar las manos detras de la cabeza. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando las rodillas y las caderas, sentando la espalda con las caderas.\", \"Continua bajando hasta la profundidad maxima si puedes y revierte rapidamente el movimiento hasta volver a la posicion inicial. Mientras te pones en cuclillas, manten la cabeza y el pecho arriba y empuja las rodillas hacia fuera.\"]','fuerza','[\"Bodyweight_Squat/0.jpg\", \"Bodyweight_Squat/1.jpg\"]','Sentadilla con peso corporal',94) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancada con peso corporal','empuje','principiante','compuesto','Ninguno','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza de pie con los pies separados a la anchura de los hombros y las manos en las caderas.\", \"Da un paso adelante con una pierna, flexionando las rodillas para bajar las caderas. Desciende hasta que la rodilla trasera casi toque el suelo. Tu postura debe permanecer erguida y tu rodilla delantera debe permanecer por encima del pie delantero.\", \"Empuja con el talon del pie delantero y extiende ambas rodillas para levantarte.\", \"Da un paso adelante con el pie trasero, repitiendo la zancada con la pierna opuesta.\"]','fuerza','[\"Bodyweight_Walking_Lunge/0.jpg\", \"Bodyweight_Walking_Lunge/1.jpg\"]','Zancada caminando con peso corporal',95) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bosu Ball en Polea Crunch con flexiones laterales','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[]','[\"Conecta un mango estandar a cada brazo de una maquina de cable y colocalos en la posicion mas baja.\", \"Coge una pelota Bosu y colocala delante y en el centro de la maquina de polea.\", \"Tumbate boca abajo sobre la pelota Bosu con la parte baja de la espalda arqueada alrededor de la pelota. Tu trasero debe estar cerca del suelo sin tocarlo.\", \"Con ambas manos, alcanza la espalda y agarra el mango de cada cable.\", \"Con tus pies en posicion amplia, extiende tus brazos rectos frente a ti y entre tus rodillas. Tus manos deben estar a la altura de las rodillas.\", \"Manten tus brazos rectos y alineados con el angulo superior de la polea. Eleva tu torso con un movimiento de abdominales sin bajar ni doblar los brazos.\", \"Manten la posicion rigida con tus brazos. Desciende lentamente la espalda a la posicion inicial con la espalda arqueada alrededor de la pelota Bosu y los abdominales estirados.\", \"Repite la misma serie de movimientos hasta el fallo.\", \"Una vez que llegues al fallo, manten los abdominales tensos y levanta el torso hasta la posicion de plancha, de modo que la espalda quede elevada sobre la pelota Bosu.\", \"Baja los brazos a los lados; mantenlos rectos. Empieza a hacer flexiones laterales alternas; ¡alcanza tus talones! Este movimiento final se centrara en tus oblicuos.\"]','fuerza','[\"Bosu_Ball_Cable_Crunch_With_Side_Bends/0.jpg\", \"Bosu_Ball_Cable_Crunch_With_Side_Bends/1.jpg\"]','Abdominales con cable y Bosu Ball con flexiones laterales',96) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bottoms Up','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Comienza por recostarte boca arriba en el suelo. Las piernas deben estar rectas y los brazos a los lados. Esta sera tu posicion inicial.\", \"Para realizar el movimiento, lleva las rodillas hacia el pecho flexionando las caderas y las rodillas. A continuacion, extiende las piernas directamente por encima de ti, de modo que queden perpendiculares al suelo. Gira y eleva la pelvis para levantar los gluteos del suelo.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"Bottoms_Up/0.jpg\", \"Bottoms_Up/1.jpg\"]','Bottoms_Up',97) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bottoms-Up Clean desde la posicion de suspension','traccion','intermedio','compuesto','pesas rusas','[\"antebrazos\"]','[\"biceps\", \"hombros\"]','[\"Inicia el ejercicio de pie erguido con una pesa rusa en una mano.\", \"Balancea la pesa rusa hacia atras con fuerza y luego invierte el movimiento con fuerza. Aprieta el mango de la pesa rusa con toda la fuerza posible y levanta la pesa rusa hasta el hombro.\"]','fuerza','[\"Bottoms-Up_Clean_From_The_Hang_Position/0.jpg\", \"Bottoms-Up_Clean_From_The_Hang_Position/1.jpg\"]','Levantamiento desde la posicion de suspension',98) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto sobre caja (respuesta multiple)','empuje','principiante','compuesto','otro','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"cuadriceps\"]','[\"Adopta una postura relajada frente a la caja o plataforma, a aproximadamente un brazo de distancia. Los brazos deben estar abajo a los lados y las piernas ligeramente flexionadas.\", \"Utilizando los brazos para ayudar en el impulso inicial, salta hacia arriba y hacia adelante, aterrizando con los pies simultaneamente en la parte superior de la caja o plataforma.\", \"Inmediatamente baja o salta espalda abajo al lugar inicial original; luego repite la secuencia.\"]','pliometria','[\"Box_Jump_Multiple_Response/0.jpg\", \"Box_Jump_Multiple_Response/1.jpg\"]','Salto sobre caja con respuesta multiple',99) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Box Skip','empuje','principiante','compuesto','otro','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"cuadriceps\"]','[\"Necesitaras varias cajas alineadas a aproximadamente 8 pies de distancia entre si.\", \"Comienza de frente a la primera caja con una pierna ligeramente detras de la otra.\", \"Impulsate con la pierna trasera, intentando ganar tanta altura con las caderas como sea posible.\", \"Inmediatamente despues de aterrizar en la caja, impulsa la otra pierna hacia adelante y arriba para ganar altura y distancia, saltando desde la caja. Aterriza entre las dos primeras cajas con la misma pierna con la que aterrizaste en la primera caja.\", \"A continuacion, pasa a la siguiente caja y repite.\"]','pliometria','[\"Box_Skip/0.jpg\", \"Box_Skip/1.jpg\"]','Salto sobre caja',100) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Brachialis-SMR','estatico','intermedio','Ninguno','rodillo_espuma','[\"biceps\"]','[]','[\"Acuestate de lado, con la parte superior del brazo contra el rodillo de espuma. La parte superior del brazo debe estar mas o menos alineada con tu cuerpo, con la parte exterior del biceps presionada contra el rodillo de espuma.\", \"Levanta las caderas del suelo, apoyando tu peso en el brazo y en los pies. Manten la posicion durante 10-30 segundos y luego cambia de lado.\"]','estiramiento','[\"Brachialis-SMR/0.jpg\", \"Brachialis-SMR/1.jpg\"]','Brachialis-SMR',104) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bradford/Rocky Presses','empuje','principiante','compuesto','barra','[\"hombros\"]','[\"triceps\"]','[\"Sientate en un banco de press militar con una barra a la altura de los hombros con un agarre pronado (las palmas mirando hacia delante). Consejo: Tu agarre debe ser mas ancho que el ancho de los hombros y debe crear un angulo de 90 grados entre el antebrazo y el brazo cuando la barra baja. Esta es su posicion inicial.\", \"Una vez que levante la barra con el agarre correcto, levante la barra por encima de su cabeza bloqueando los brazos.\", \"Ahora baje la barra lentamente hacia la espalda de la cabeza mientras inhala.\", \"Eleve la barra hacia atras hasta la posicion inicial mientras exhala.\", \"Baje la barra lentamente hasta la posicion inicial mientras inhala. Esto es una repeticion.\", \"Alterna de esta forma hasta completar la cantidad recomendada de repeticiones.\"]','fuerza','[\"Bradford_Rocky_Presses/0.jpg\", \"Bradford_Rocky_Presses/1.jpg\"]','Bradford_Rocky_Presses',105) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de gluteos (puente)','empuje','principiante','aislamiento','solo_cuerpo','[\"gluteos\"]','[\"isquiotibiales\"]','[\"Acuestate boca arriba en el suelo con las manos a los lados y las rodillas flexionadas. Los pies deben estar separados a la altura de los hombros. Esta sera tu posicion inicial.\", \"Empujando principalmente con los talones, levanta las caderas del suelo mientras mantienes la espalda recta. Exhala mientras realizas esta parte del movimiento y manten en la parte superior durante un segundo.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\"]','fuerza','[\"Butt_Lift_Bridge/0.jpg\", \"Butt_Lift_Bridge/1.jpg\"]','Puente de levantamiento de gluteos',106) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones de gluteos','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Comienza en posicion de flexion, pero con los codos en el suelo y apoyandote en los antebrazos. Los brazos deben estar doblados en un angulo de 90 grados.\", \"Arquea ligeramente la espalda en lugar de mantenerla completamente recta.\", \"Levanta los gluteos hacia el techo, apretando los abdominales con fuerza para acortar la distancia entre la caja toracica y las caderas. El resultado final sera que terminaras arriba en una posicion de puente alto. Exhala mientras realizas esta parte del movimiento.\", \"Baja la espalda lentamente hasta tu posicion inicial mientras inhalas. Consejo: No dejes que tu espalda se hunda hacia abajo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Butt-Ups/0.jpg\", \"Butt-Ups/1.jpg\"]','Elevaciones de gluteos',107) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de pecho con cable','empuje','principiante','compuesto','polea','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Ajusta el peso a una cantidad adecuada y sientate, agarrando las manijas. Tus brazos superiores deben estar aproximadamente a 45 grados del cuerpo, con la cabeza y el pecho hacia arriba. Los codos deben estar doblados a aproximadamente 90 grados. Esta sera tu posicion inicial.\", \"Comienza extendiendo el codo, presionando las manijas juntas recto frente a ti. Manten los omoplatos retraidos mientras ejecutas el movimiento.\", \"Despues de hacer una pausa en la extension completa, vuelve a la posicion inicial, manteniendo la tension en las poleas.\", \"Tambien puedes ejecutar este movimiento con la espalda fuera de la almohadilla, en inclinacion o declive, o alternando las manos.\"]','fuerza','[\"Cable_Chest_Press/0.jpg\", \"Cable_Chest_Press/1.jpg\"]','Press de pecho con cable',109) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Crossover con cable','empuje','principiante','aislamiento','polea','[\"pecho\"]','[\"hombros\"]','[\"Para colocarte en la posicion inicial, coloca las poleas en una posicion alta (por encima de tu cabeza), selecciona la resistencia que vas a utilizar y manten las poleas en cada mano.\", \"Da un paso adelante frente a una linea recta imaginaria entre ambas poleas mientras juntas los brazos frente a ti. Tu torso debe tener una pequeña inclinacion hacia adelante desde la cintura. Esta sera tu posicion inicial.\", \"Con una ligera flexion en tus codos para evitar tension en el tendon del biceps, extiende tus brazos a los lados (rectos hacia ambos lados) en un amplio arco hasta que sientas un estiramiento en tu pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento, los brazos y el torso deben permanecer inmoviles; el movimiento solo debe producirse en la articulacion del hombro.\", \"Vuelve los brazos a la posicion inicial mientras exhalas. Asegurate de utilizar el mismo arco de movimiento que has utilizado para bajar las pesas.\", \"Manten durante un segundo la posicion inicial y repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Cable_Crossover/0.jpg\", \"Cable_Crossover/1.jpg\"]','Crossover con cable',110) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cable Crunch','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[]','[\"Arrodillate debajo de una polea alta que contenga un accesorio de cuerda.\", \"Agarra el accesorio de cuerda del cable y baja la cuerda hasta que tus manos esten colocadas junto a tu cara.\", \"Flexiona ligeramente las caderas y deja que el peso hiperextienda la zona lumbar. Esta sera tu posicion inicial.\", \"Con las caderas fijas, flexiona la cintura mientras contraes los abdominales para que los codos se desplacen hacia el centro de los muslos. Exhala mientras realizas esta parte del movimiento y manten la contraccion durante un segundo.\", \"Vuelve lentamente a la posicion inicial mientras inhalas. Consejo: Asegurate de mantener una tension constante en los abdominales durante todo el movimiento. Ademas, no elijas un peso tan pesado que la parte baja de la espalda tenga que soportar la mayor parte del esfuerzo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Crunch/0.jpg\", \"Cable_Crunch/1.jpg\"]','Abdominales con cable',111) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cable Peso Muertos','traccion','principiante','compuesto','polea','[\"cuadriceps\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Mueve las poleas hasta la parte inferior de las torres y selecciona un peso adecuado. Colocate directamente entre los montantes.\", \"Para empezar, haz una sentadilla flexionando las caderas y las rodillas hasta que puedas alcanzar las asas.\", \"Despues de agarrarlas, comienza el ascenso. Empuja con los talones, extiende las caderas y las rodillas, manteniendo las manos colgando a los lados. Manten la cabeza y el pecho arriba durante todo el movimiento.\", \"Despues de alcanzar una posicion completamente erguida, regresa a la posicion inicial y repite.\"]','fuerza','[\"Cable_Deadlifts/0.jpg\", \"Cable_Deadlifts/1.jpg\"]','Cable_Deadlifts',112) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curls con cable martillo - Accesorio de cuerda','traccion','principiante','aislamiento','polea','[\"biceps\"]','[]','[\"Conecta un accesorio de cuerda a una polea baja y colocate frente a la maquina a aproximadamente 12 pulgadas de distancia de ella.\", \"Agarra la cuerda con un agarre neutro (palmas hacia dentro) y mantente erguido manteniendo el arco natural de la espalda y el torso inmovil.\", \"Coloca los codos a los lados y mantenlos inmoviles durante todo el movimiento. Consejo: Solo deben moverse los antebrazos, no los brazos. Esta sera tu posicion inicial.\", \"Usando los biceps, levanta los brazos mientras exhalas hasta que los biceps toquen los antebrazos. Consejo: Recuerda mantener los codos hacia dentro y la parte superior de los brazos inmoviles.\", \"Despues de una contraccion de 1 segundo en la que aprietas los biceps, empieza lentamente a llevar el peso hacia atras a la posicion original.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Hammer_Curls_-_Rope_Attachment/0.jpg\", \"Cable_Hammer_Curls_-_Rope_Attachment/1.jpg\"]','Curls con mancuernas con cable - Accesorio de cuerda',113) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje inclinado con cable','traccion','principiante','aislamiento','polea','[\"dorsales\"]','[]','[\"Acuestate en un banco inclinado mirando hacia una maquina de polea alta que tiene un accesorio de barra recta en ella.\", \"Agarra el accesorio de barra recta sobre la cabeza con un agarre pronado (con las palmas hacia abajo) a la altura de los hombros y extiende los brazos frente a ti. La barra debe estar a unas 2 pulgadas de distancia de la parte superior de los muslos. Esta sera tu posicion inicial.\", \"Manteniendo los brazos superiores fijos, levanta los brazos hacia atras en un semicirculo hasta que la barra quede recta sobre tu cabeza. Inhala durante esta parte del movimiento.\", \"Vuelve lentamente a la posicion inicial utilizando los dorsales y manten la contraccion una vez que alcances la posicion inicial. Exhala durante la ejecucion de este movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Incline_Pushdown/0.jpg\", \"Cable_Incline_Pushdown/1.jpg\"]','Extension inclinada con cable',115) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con cable inclinado','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Acuestate en un banco inclinado mirando hacia una maquina de polea alta que tenga un accesorio de barra recta en ella.\", \"Agarra el accesorio de barra recta sobre la cabeza con un agarre pronado (palmas hacia abajo) y estrecho (menos que el ancho de los hombros) y manten los codos pegados a los costados. Tus brazos superiores deben formar un angulo de unos 25 grados con respecto al suelo.\", \"Manten los brazos superiores fijos y extiende los brazos mientras flexionas los triceps. Exhala durante esta parte del movimiento y manten la contraccion durante un segundo.\", \"Vuelve lentamente a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Cable_Incline_Triceps_Extension/0.jpg\", \"Cable_Incline_Triceps_Extension/1.jpg\"]','Extension de triceps con cable inclinado',116) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Voltereta de judo con cable','traccion','principiante','compuesto','polea','[\"abdominales\"]','[]','[\"Conecta un accesorio de cuerda a una torre y mueve la polea a la posicion mas baja. Ponte de pie de lado a la polea con una postura amplia y agarra la cuerda con ambas manos.\", \"Gira el cuerpo alejandote de la polea mientras llevas la cuerda por encima del hombro como si estuvieras realizando un lanzamiento de judo.\", \"Desplaza el peso entre los pies mientras giras y te inclinas hacia delante, tirando de la polea hacia abajo.\", \"Vuelve a la posicion inicial y repite hasta el fallo.\", \"A continuacion, cambia de posicion y repite la misma serie de movimientos en el lado opuesto.\"]','fuerza','[\"Cable_Judo_Flip/0.jpg\", \"Cable_Judo_Flip/1.jpg\"]','Cable_Judo_Flip',119) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con cable a un brazo','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Con la mano derecha, agarra una sola manija conectada a la polea del cable alto con un agarre supinado (palmas hacia arriba). Debes estar de pie directamente frente a la pila de pesas.\", \"Ahora tira de la manija hacia abajo para que la parte superior del brazo y el codo queden bloqueados al lado del cuerpo. La parte superior del brazo y el antebrazo deben formar un angulo agudo (menos de 90 grados). Puedes mantener el otro brazo por la cintura y puedes poner una pierna delante de ti y la otra detras para tener un mejor equilibrio. Esta sera tu posicion inicial.\", \"A medida que contraes los triceps, mueve el mango hacia abajo hasta que tu brazo este recto. Exhala mientras realizas este movimiento. Consejo: Solo deben moverse los antebrazos. Los brazos deben permanecer inmoviles en todo momento.\", \"Aprieta los triceps y manten durante un segundo esta posicion contraida.\", \"Vuelve lentamente el mango a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones y luego realiza el mismo movimiento con el otro brazo.\"]','fuerza','[\"Cable_One_Arm_Tricep_Extension/0.jpg\", \"Cable_One_Arm_Tricep_Extension/1.jpg\"]','Cable_Extension_de_triceps_con_un_brazo',121) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl predicador con cable','traccion','principiante','aislamiento','polea','[\"biceps\"]','[\"antebrazos\"]','[\"Coloca un banco predicador aproximadamente a 2 pies frente a una maquina de poleas.\", \"Fija una barra recta a la polea baja.\", \"Sientate en el banco predicador con los codos y la parte superior de los brazos firmemente apoyados en la parte superior del banco y pide a alguien que te pase la barra desde la polea baja.\", \"Agarra la barra y extiende completamente los brazos en la parte superior del banco predicador. Esta sera tu posicion inicial.\", \"Ahora empieza a levantar el peso hacia tus hombros y aprieta los biceps con fuerza en la parte superior del movimiento. Exhala mientras realizas este movimiento. Ademas, manten la posicion durante un segundo en la parte superior.\", \"Ahora baja lentamente el peso hasta la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Preacher_Curl/0.jpg\", \"Cable_Preacher_Curl/1.jpg\"]','Cable_Curl predicador',122) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cable Rear Delt Fly','traccion','principiante','aislamiento','polea','[\"hombros\"]','[]','[\"Ajusta las poleas a la altura adecuada y ajusta el peso. Las poleas deben estar por encima de tu cabeza.\", \"Agarra la polea izquierda con tu mano derecha y la polea derecha con tu mano izquierda, cruzandolas frente a ti. Esta sera tu posicion inicial.\", \"Inicia el movimiento moviendo tus brazos hacia atras y hacia afuera, manteniendo tus brazos rectos mientras ejecutas el movimiento.\", \"Haz una pausa al final del movimiento antes de volver a colocar las manijas en la posicion inicial.\"]','fuerza','[\"Cable_Rear_Delt_Fly/0.jpg\", \"Cable_Rear_Delt_Fly/1.jpg\"]','Cable_Delt_Trasero_Fly',123) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con cuerda por encima de la cabeza','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Fija una cuerda a la polea inferior de la maquina de poleas.\", \"Agarra la cuerda con ambas manos y extiende los brazos con las manos directamente por encima de la cabeza utilizando un agarre neutro (las palmas enfrentadas). Los codos deben estar cerca de la cabeza y los brazos deben estar perpendiculares al suelo con los nudillos apuntando al techo. Esta sera tu posicion inicial.\", \"Baja lentamente la cuerda detras de la cabeza mientras mantienes los brazos superiores inmoviles. Inhala mientras realizas este movimiento y haz una pausa cuando los triceps esten completamente estirados.\", \"Vuelve a la posicion inicial flexionando los triceps mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Cable_Rope_Overhead_Triceps_Extension/0.jpg\", \"Cable_Rope_Overhead_Triceps_Extension/1.jpg\"]','Cable_Extension_de_triceps_por_encima_de_la_cabeza_con_cuerda',125) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con cable y cuerda para deltoides posteriores','traccion','principiante','compuesto','polea','[\"hombros\"]','[\"biceps\", \"espalda_media\"]','[\"Sientate en la misma posicion en una estacion de remo con polea baja como lo harias si estuvieras haciendo remo con cable sentado durante la espalda.\", \"Fija una cuerda a la polea y agarrala con un agarre por encima. Tus brazos deben estar extendidos y paralelos al suelo con los codos hacia fuera.\", \"Manten la parte inferior de la espalda erguida y desliza las caderas hacia atras de modo que las rodillas queden ligeramente flexionadas. Esta sera tu posicion inicial.\", \"Tira del accesorio del cable hacia la parte superior del pecho, justo debajo del cuello, mientras mantienes los codos arriba y hacia los lados. Continua este movimiento mientras exhalas hasta que los codos se desplacen ligeramente por detras de la espalda. Consejo: Manten la parte superior de los brazos en posicion horizontal, perpendicular al torso y paralela al suelo durante todo el movimiento.\", \"Vuelve a la posicion inicial, con los brazos extendidos y los hombros estirados hacia delante. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Cable_Rope_Rear-Delt_Rows/0.jpg\", \"Cable_Rope_Rear-Delt_Rows/1.jpg\"]','Cable_Remo_deltoides_posterior_con_cuerda',126) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cable Russian Twists','traccion','principiante','compuesto','polea','[\"abdominales\"]','[]','[\"Conecta un accesorio de mango estandar y coloca la polea en una posicion intermedia.\", \"Tumbate en una pelota de estabilidad perpendicular a la polea y agarra el mango con una mano. Debes estar aproximadamente a un brazo de distancia de la polea, con la tension del peso en la polea.\", \"Agarra el mango con ambas manos y extiende completamente los brazos por encima del pecho. Tus manos deben estar directamente alineadas con la polea. Si no es asi, ajusta la polea hacia arriba o hacia abajo hasta que lo esten.\", \"Manten tus caderas elevadas y los abdominales contraidos. Gira tu torso alejandote de la polea durante un cuarto de rotacion completo. Tu cuerpo debe estar plano desde la cabeza hasta las rodillas.\", \"Haz una pausa durante un momento y, de forma lenta y controlada, vuelve a la posicion inicial. Debes seguir teniendo tension lateral en la polea en la posicion de descanso.\", \"Repite el mismo movimiento hasta el fallo.\", \"A continuacion, vuelve a colocarte y repite la misma serie de movimientos en el lado opuesto.\"]','fuerza','[\"Cable_Russian_Twists/0.jpg\", \"Cable_Russian_Twists/1.jpg\"]','Cable_Twists_rusos',127) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cable Sentado Crunch','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[]','[\"Sientate en un banco plano con la espalda mirando hacia una polea alta.\", \"Agarra el accesorio de cable con ambas manos (con las palmas de las manos mirando una hacia la otra) y coloca tus manos de forma segura sobre ambos hombros. Consejo: Deja que el peso hiperextienda ligeramente la parte inferior de la espalda. Esta sera tu posicion inicial.\", \"Con las caderas fijas, flexiona la cintura para que los codos se desplacen hacia las caderas. Exhala mientras realizas este paso.\", \"A medida que inhalas, vuelve lentamente a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Seated_Crunch/0.jpg\", \"Cable_Seated_Crunch/1.jpg\"]','Cable_Abdominales sentado',128) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de hombros con cable','empuje','principiante','compuesto','polea','[\"hombros\"]','[\"triceps\"]','[\"Mueve las poleas hasta la parte inferior de las torres y selecciona un peso adecuado.\", \"Colocate directamente entre los montantes. Agarra los cables y mantenlos a la altura de los hombros, con las palmas hacia delante. Esta sera tu posicion inicial.\", \"Manten la cabeza y el pecho erguidos, extiende los codos para presionar las manijas directamente sobre la cabeza.\", \"Despues de hacer una pausa en la parte superior, vuelve a la posicion inicial y repite.\"]','fuerza','[\"Cable_Shoulder_Press/0.jpg\", \"Cable_Shoulder_Press/1.jpg\"]','Press de hombros con cable',130) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros con cable','traccion','principiante','aislamiento','polea','[\"trapecios\"]','[]','[\"Agarra un cable bar attachment que esta attached to a low pulley con un agarre shoulder width o slightly wider overhand (palmas mirando hacia abajo).\", \"Stand erect close to the pulley con tus brazos extendidos frente a ti sosteniendo la barra. Esta sera tu posicion inicial.\", \"Eleva la barra elevando los hombros lo mas alto posible mientras exhalas. Manten la contraccion en la parte superior durante un segundo. Consejo: Los brazos deben permanecer extendidos en todo momento. Evita utilizar los biceps para ayudar a levantar la barra. Solo los hombros deben moverse hacia arriba y hacia abajo.\", \"Baja la barra a la posicion original.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Cable_Shrugs/0.jpg\", \"Cable_Shrugs/1.jpg\"]','Cable_Encogimiento de hombros',131) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de muñeca con cable','traccion','principiante','aislamiento','polea','[\"antebrazos\"]','[]','[\"Comienza colocando un banco plano frente a una polea baja con una barra recta acoplada.\", \"Utiliza tus brazos para agarrar la barra de la polea con un agarre estrecho a la anchura de los hombros en supinacion (palmas hacia arriba) y llevalos hacia arriba de modo que tus antebrazos descansen sobre la parte superior de tus muslos. Tus muñecas deben quedar colgando justo por debajo de tus rodillas.\", \"Comienza flexionando las muñecas hacia arriba y exhalando. Manten la contraccion durante un segundo.\", \"Baja lentamente las muñecas hacia atras hasta la posicion inicial mientras inhalas.\", \"Los antebrazos deben permanecer inmoviles, ya que la muñeca es el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Cable_Wrist_Curl/0.jpg\", \"Cable_Wrist_Curl/1.jpg\"]','Cable_Flexion de muñeca',132) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Prensa de pantorrillas','empuje','principiante','aislamiento','maquina','[\"pantorrillas\"]','[]','[\"Ajusta el asiento de modo que tus piernas esten solo ligeramente dobladas en la posicion inicial. Las puntas de los pies deben estar firmemente apoyadas en la plataforma.\", \"Selecciona un peso adecuado y agarra las asas. Esta sera tu posicion inicial.\", \"Estira las piernas extendiendo las rodillas, levantando apenas el peso de la pila. Los tobillos deben estar completamente flexionados, con los dedos de los pies apuntando hacia arriba. Ejecuta el movimiento presionando hacia abajo con las puntas de los pies tan lejos como sea posible.\", \"Despues de una breve pausa, invierte el movimiento y repite.\"]','fuerza','[\"Calf_Press/0.jpg\", \"Calf_Press/1.jpg\"]','Prensa de pantorrillas',133) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de pantorrillas con mancuernas','empuje','intermedio','aislamiento','mancuerna','[\"pantorrillas\"]','[]','[\"Agarrate a un objeto resistente para mantener el equilibrio y ponte de pie sobre una mancuerna, preferiblemente una con discos redondos para que ruede, ya que de esta forma tendras que esforzarte mas para mantener el equilibrio, lo que aumentara la eficacia del ejercicio.\", \"Ahora gira ligeramente el pie hacia delante para estirar bien la pantorrilla. Esta sera tu posicion inicial.\", \"Eleva el calf mientras ruedas el pie por encima del mango para conseguir una extension completa. Exhala durante la ejecucion de este movimiento. Contrae la pantorrilla con fuerza en la parte superior y manten durante un segundo. Consejo: A medida que subes, rueda la mancuerna ligeramente hacia atras.\", \"Ahora inhala mientras ruedas la mancuerna ligeramente hacia adelante a medida que bajas para conseguir un mejor estiramiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Calf_Raise_On_A_Dumbbell/0.jpg\", \"Calf_Raise_On_A_Dumbbell/1.jpg\"]','Elevacion de pantorrillas con mancuernas',135) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones de pantorrillas con bandas','empuje','principiante','aislamiento','bandas','[\"pantorrillas\"]','[]','[\"Coge una banda elastica y ponte de pie sobre ella con los dedos de los pies, asegurandote de que la longitud de la banda entre el pie y los brazos sea la misma en ambos lados.\", \"Mientras sostienes las asas de la banda, levanta los brazos a los lados de la cabeza como si te estuvieras preparando para realizar un press de hombros. Las palmas deben estar mirando hacia delante con los codos doblados y a los lados. Este movimiento creara tension en la banda. Esta sera tu posicion inicial.\", \"Manteniendo las manos junto a los hombros, ponte de puntillas mientras exhalas y contraes con fuerza las pantorrillas en la parte superior del movimiento.\", \"Despues de una contraccion de un segundo, vuelve lentamente a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Calf_Raises_-_With_Bands/0.jpg\", \"Calf_Raises_-_With_Bands/1.jpg\"]','Elevaciones de pantorrillas con bandas',136) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pantorrillas con los codos contra la pared','estatico','principiante','aislamiento','Ninguno','[\"pantorrillas\"]','[]','[\"Ponte de pie frente a una pared a un par de metros de distancia.\", \"Apoyate contra la pared, colocando tu peso en los antebrazos.\", \"Intenta mantener los talones en el suelo. Manten la posicion durante 10-20 segundos. Puedes alejarte o acercarte a la pared, aumentando o disminuyendo la dificultad, respectivamente.\"]','estiramiento','[\"Estiramiento_de_pantorrillas_con_los_codos_contra_la_pared/0.jpg\", \"Estiramiento_de_pantorrillas_con_los_codos_contra_la_pared/1.jpg\"]','Estiramiento de pantorrillas con los codos contra la pared',137) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pantorrillas con las manos contra la pared','estatico','principiante','aislamiento','Ninguno','[\"pantorrillas\"]','[]','[\"Ponte de pie frente a una pared a varios metros de distancia. Coloca los pies en posicion escalonada, con un pie delante.\", \"Inclinate hacia delante y apoya las manos en la pared, manteniendo el talon, la cadera y la cabeza en linea recta.\", \"Intenta mantener el talon en el suelo. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Calf_Stretch_Hands_Against_Wall/0.jpg\", \"Calf_Stretch_Hands_Against_Wall/1.jpg\"]','Estiramiento de pantorrillas con las manos en la pared',138) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pantorrillas-SMR','estatico','intermedio','Ninguno','rodillo_espuma','[\"pantorrillas\"]','[]','[\"Comienza sentado en el suelo. Coloca un rodillo de espuma debajo de la parte inferior de la pierna. La otra pierna puede cruzarse sobre la opuesta o colocarse en el suelo, soportando parte de tu peso. Esta sera tu posicion inicial.\", \"Coloca tus manos a los lados o justo detras de ti, y presiona hacia abajo para levantar las caderas del suelo, colocando gran parte de tu peso contra el musculo de la pantorrilla. Rueda desde debajo de la rodilla hasta por encima del tobillo, haciendo una pausa en los puntos de tension durante 10-30 segundos. Repite con la otra pierna.\"]','estiramiento','[\"Pantorrillas-SMR/0.jpg\", \"Pantorrillas-SMR/1.jpg\"]','Pantorrillas-SMR',140) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Car Peso Muerto','traccion','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\"]','[\"Este aparato suele tener asas de agarre neutro, aunque algunos tienen una barra recta que se puede abordar como un peso muerto normal. El aparato se puede cargar con un vehiculo u otros objetos pesados, como neumaticos de tractor o barriles.\", \"Colocate en el centro entre las asas si eres un buen levantador de peso muerto, o unos centimetros mas atras si eres un buen levantador de peso muerto. Los pies deben estar separados aproximadamente a la anchura de las caderas. Dobla las caderas para agarrar las asas. Con los pies y el agarre fijos, respira profundamente y luego baja las caderas y flexiona las rodillas.\", \"Mira hacia delante con la cabeza, manten el pecho arriba y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. A medida que el peso se eleva, junta los omoplatos mientras empujas las caderas hacia adelante.\", \"Baja el peso doblando las caderas y guiandolo hacia el suelo.\"]','hombre_fuerte','[\"Car_Deadlift/0.jpg\", \"Car_Deadlift/1.jpg\"]','Levantamiento de peso con coche',141) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Carioca Quick Step','Ninguno','principiante','Ninguno','Ninguno','[\"aductores\"]','[\"abdominales\", \"abductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Comienza con los pies separados unos centimetros y el brazo izquierdo arriba en una posicion relajada y atletica.\", \"Con el pie derecho, da un paso rapido hacia atras y levanta la rodilla.\", \"Lanza los brazos hacia atras cuando levantes la rodilla derecha, asegurandote de que la rodilla vaya recta hacia arriba y hacia abajo. Evita girar los pies mientras te mueves y sigue mirando hacia adelante mientras te mueves hacia el lado.\"]','pliometria','[\"Carioca_Quick_Step/0.jpg\", \"Carioca_Quick_Step/1.jpg\"]','Carioca_Quick_Step',143) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento del gato','estatico','principiante','Ninguno','Ninguno','[\"espalda_baja\"]','[\"espalda_media\", \"trapecios\"]','[\"Colocate en el suelo en tus manos y rodillas.\", \"Mete el vientre y redondea la columna, la zona lumbar, los hombros y el cuello, dejando caer la cabeza.\", \"Manten durante 15 segundos.\"]','estiramiento','[\"Cat_Stretch/0.jpg\", \"Cat_Stretch/1.jpg\"]','Estiramiento del gato',144) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Atrapar y lanzamiento por encima de la cabeza','empuje','principiante','compuesto','balon_medicinal','[\"dorsales\"]','[\"abdominales\", \"pecho\", \"hombros\"]','[\"Comienza de pie frente a una pared o a un compañero.\", \"Con ambas manos, coloca la pelota detras de la cabeza, estirandote tanto como sea posible, y lanza la pelota con fuerza hacia adelante.\", \"Asegurate de seguir el movimiento del lanzamiento, preparandote para recibir el rebote de tu lanzamiento. Si estas lanzando contra la pared, asegurate de estar lo suficientemente cerca de la pared como para recibir el rebote, y apunta un poco mas alto de lo que lo harias con un compañero.\"]','pliometria','[\"Catch_and_Overhead_Throw/0.jpg\", \"Catch_and_Overhead_Throw/1.jpg\"]','Atrapar y lanzar por encima de la cabeza',145) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con cadena','empuje','intermedio','compuesto','otro','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Comienza conectando las cadenas a los accesorios de la polea. Colocate en el banco plano en la misma posicion que durante una press con mancuernas. Las muñecas deben estar pronadas y los brazos perpendiculares al suelo. Esta sera tu posicion inicial.\", \"Baja las cadenas flexionando los codos, descargando parte de la cadena en el suelo.\", \"Continua hasta que el codo forme un angulo de 90 grados y, a continuacion, invierte el movimiento extendiendo el codo hasta el bloqueo.\"]','levantamiento de pesas','[\"Chain_Press/0.jpg\", \"Chain_Press/1.jpg\"]','Press con cadena',147) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pierna extendida en silla','estatico','principiante','aislamiento','otro','[\"isquiotibiales\"]','[\"aductores\"]','[\"Sientate erguido en una silla y agarra el asiento por los lados.\", \"Levanta una pierna, extendiendo la rodilla y flexionando el tobillo al hacerlo.\", \"Mueve lentamente esa pierna hacia fuera tan lejos como puedas, y luego vuelve al centro y baja.\", \"Repite con la otra pierna.\"]','estiramiento','[\"Chair_Leg_Extended_Stretch/0.jpg\", \"Chair_Leg_Extended_Stretch/1.jpg\"]','Chair_Leg_Extended_Stretch',148) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de espalda en silla','estatico','principiante','aislamiento','Ninguno','[\"dorsales\"]','[\"espalda_baja\"]','[\"Sientese erguido en una silla.\", \"Inclinese hacia un lado con el brazo por encima de la cabeza. Puede sujetarse a la silla con la mano libre.\", \"Mantenga la posicion durante 10 segundos y repita con el otro lado.\"]','estiramiento','[\"Chair_Lower_Back_Stretch/0.jpg\", \"Chair_Lower_Back_Stretch/1.jpg\"]','Estiramiento de la parte inferior de la espalda en silla',149) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla en silla','empuje','principiante','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, primero coloca la barra en la posicion que mejor se adapte a tu altura. Una vez que la barra este cargada, colocate debajo de ella y colocala sobre la espalda de tus hombros.\", \"Toma la barra con las manos mirando hacia adelante, desbloqueala y levantala del soporte extendiendo las piernas.\", \"Mueve los pies aproximadamente 18 pulgadas delante de la barra. Coloca las piernas con una postura a la anchura de los hombros y los dedos de los pies ligeramente apuntando hacia fuera. Mira hacia adelante en todo momento y manten la columna vertebral en posicion neutra o ligeramente arqueada. Esta sera tu posicion inicial.\", \"Baja lentamente la barra doblando las rodillas mientras mantienes una postura recta con la cabeza levantada. Continua bajando hasta que el angulo entre la parte superior e inferior de la pierna supere los 90 grados.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo con los talones de los pies, extendiendo las rodillas y volviendo a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Chair_Squat/0.jpg\", \"Chair_Squat/1.jpg\"]','Sentadilla en silla',150) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de la parte superior del cuerpo en silla','estatico','principiante','Ninguno','otro','[\"hombros\"]','[\"biceps\", \"pecho\"]','[\"Sientate en el borde de una silla, agarrandote al respaldo de la misma.\", \"Estira tus brazos, manteniendo la espalda recta, y tira de la parte superior del cuerpo hacia adelante para que sientas un estiramiento. Mantene la posicion durante 20-30 segundos.\"]','estiramiento','[\"Chair_Upper_Body_Stretch/0.jpg\", \"Chair_Upper_Body_Stretch/1.jpg\"]','Chair_Upper_Body_Stretch',151) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento del pecho y la parte frontal del hombro','estatico','principiante','aislamiento','otro','[\"pecho\"]','[\"hombros\"]','[\"Comienza de pie con las piernas juntas, sosteniendo una barra o un palo de escoba.\", \"Agarra el palo con las manos ligeramente mas separadas que el ancho de los hombros y mantenlo frente a ti con las palmas hacia abajo.\", \"Levanta con cuidado el palo por encima de la cabeza.\"]','estiramiento','[\"Estiramiento_del_pecho_y_la_parte_delantera_del_hombro/0.jpg\", \"Estiramiento_del_pecho_y_la_parte_delantera_del_hombro/1.jpg\"]','Estiramiento del pecho y la parte delantera de los hombros',152) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje de pecho desde una postura de tres puntos','empuje','principiante','compuesto','balon_medicinal','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Comienza en una postura de tres puntos, en cuclillas con la espalda recta y una mano en el suelo. Coloca la pelota medicinal directamente frente a ti.\", \"Para comenzar, da el primer paso mientras tiras de la pelota hacia tu pecho, colocando ambas manos en posicion para prepararte para el lanzamiento.\", \"Al ejecutar el segundo paso, lanza la pelota hacia adelante con la mayor fuerza posible.\"]','pliometria','[\"Chest_Push_from_3_point_stance/0.jpg\", \"Chest_Push_from_3_point_stance/1.jpg\"]','Empuje de pecho desde posicion de 3 puntos',153) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje con el pecho (respuesta multiple)','empuje','principiante','compuesto','balon_medicinal','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Comience en posicion de rodillas frente a una pared o utilice un compañero. Sosten el balon con ambas manos pegadas al pecho.\", \"Ejecuta el pase lanzandote hacia delante y hacia fuera con las caderas mientras empujas el balon con toda la fuerza posible.\", \"Sigue el movimiento cayendo hacia delante y sujetandote con las manos.\", \"Vuelve inmediatamente a la posicion erguida. Repite durante el numero deseado de repeticiones.\"]','pliometria','[\"Chest_Push_multiple_response/0.jpg\", \"Chest_Push_multiple_response/1.jpg\"]','Empuje_de_pecho_respuesta_multiple',154) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje de pecho (respuesta unica)','empuje','principiante','compuesto','balon_medicinal','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Comienza en posicion de rodillas sosteniendo el balon medicinal con ambas manos firmemente contra el pecho.\", \"Ejecuta el pase impulsandote hacia adelante y hacia afuera con las caderas mientras empujas el balon tan lejos como sea posible.\", \"Sigue el movimiento cayendo hacia adelante y sujetandote con las manos.\"]','pliometria','[\"Chest_Push_single_response/0.jpg\", \"Chest_Push_single_response/1.jpg\"]','Empuje con el pecho respuesta unica',155) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje con el pecho con lanzamiento en carrera','empuje','principiante','compuesto','balon_medicinal','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Comience en una postura atletica con las rodillas flexionadas, las caderas hacia atras y la espalda recta. Sostenga el balon medicinal cerca de sus piernas. Esta sera su posicion inicial.\", \"Mientras da el primer paso, lleve el balon medicinal hacia su pecho.\", \"Al dar el segundo paso, empuje el balon hacia adelante de forma explosiva y corra inmediatamente durante 10 yardas despues del lanzamiento. Si eres realmente rapido, ¡puedes atrapar tu propio pase!\"]','pliometria','[\"Chest_Push_with_Run_Release/0.jpg\", \"Chest_Push_with_Run_Release/1.jpg\"]','Empuje con el pecho y lanzamiento en carrera',156) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pecho sobre balon de estabilidad','estatico','principiante','aislamiento','fitball','[\"pecho\"]','[]','[\"Ponte en tus manos y rodillas junto a una pelota de ejercicios.\", \"Coloca tus codos en la parte superior de la pelota, manteniendo los brazos hacia los lados. Esta sera tu posicion inicial.\", \"Baja tu torso hacia el suelo, manteniendo los codos en la parte superior de la pelota. Manten el estiramiento durante 20-30 segundos y repite con el otro brazo.\"]','estiramiento','[\"Chest_Stretch_on_Stability_Ball/0.jpg\", \"Chest_Stretch_on_Stability_Ball/1.jpg\"]','Estiramiento del pecho sobre una pelota de estabilidad',157) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Postura del niño','estatico','principiante','Ninguno','Ninguno','[\"espalda_baja\"]','[\"gluteos\", \"espalda_media\"]','[\"Ponte a cuatro patas y camina con las manos hacia delante.\", \"Baja las nalgas para sentarte sobre los talones. Deja que los brazos se arrastren por el suelo mientras te sientas con la espalda recta para estirar toda la columna vertebral.\", \"Una vez que te hayas sentado sobre los talones, lleva las manos junto a los pies y relajate. Respira hacia la espalda. Descansa la frente en el suelo. Evita esta postura si tienes problemas en las rodillas.\"]','estiramiento','[\"Childs_Pose/0.jpg\", \"Childs_Pose/1.jpg\"]','Postura del niño',158) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de la barbilla hacia el pecho','estatico','principiante','Ninguno','Ninguno','[\"cuello\"]','[\"trapecios\"]','[\"Sientate en el suelo.\", \"Coloca ambas manos en la parte posterior de la cabeza, con los dedos entrelazados, los pulgares apuntando hacia abajo y los codos apuntando hacia delante. Lentamente, lleva la cabeza hacia el pecho. Manten la postura durante 20-30 segundos.\"]','estiramiento','[\"Chin_To_Chest_Stretch/0.jpg\", \"Chin_To_Chest_Stretch/1.jpg\"]','Estiramiento de barbilla al pecho',159) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circus Bell','empuje','experto','compuesto','otro','[\"hombros\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\", \"triceps\"]','[\"La campana de circo es una mancuerna de gran tamaño con un mango grueso. Comienza con la mancuerna entre tus pies y agarra el mango con ambas manos.\", \"Limpia la mancuerna extendiendo tus caderas y rodillas para llevar el implemento al hombro deseado, dejando ir con la mano extra.\", \"Asegurate de colocar una de las cabezas de la mancuerna detras del hombro para evitar perder el equilibrio. Para levantarla sobre la cabeza, flexiona las rodillas y empuja hacia arriba mientras extiendes la mancuerna sobre la cabeza, inclinandote ligeramente alejandote de ella mientras lo haces.\", \"Guia con cuidado la campana hacia el suelo, manteniendola bajo control tanto como sea posible. Es mejor realizar este ejercicio sobre una colchoneta de goma gruesa para evitar dañar el suelo.\"]','hombre_fuerte','[\"Circus_Bell/0.jpg\", \"Circus_Bell/1.jpg\"]','Campana de circo',161) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Clean','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Con una barra en el suelo cerca de las espinillas, agarra con las manos por encima (o en gancho) justo fuera de las piernas. Baja las caderas con el peso centrado en los talones, la espalda recta, la cabeza mirando hacia delante, el pecho hacia arriba y los hombros justo delante de la barra. Esta sera tu posicion inicial.\", \"\", \"Comienza el primer tiron empujando con los talones y extendiendo las rodillas. El angulo de la espalda debe permanecer igual y los brazos deben permanecer rectos. Mueve el peso con control mientras continuas por encima de las rodillas.\", \"A continuacion viene el segundo tiron, la principal fuente de aceleracion durante la limpieza. A medida que la barra se acerca a la posicion media del muslo, comienza a extender las caderas. En un movimiento de salto, acelera extendiendo las caderas, las rodillas y los tobillos, utilizando la velocidad para mover la barra hacia arriba. No deberia ser necesario tirar activamente con los brazos para acelerar el peso; al final del segundo tiron, el cuerpo deberia estar completamente extendido, inclinado ligeramente hacia atras, con los brazos aun extendidos.\", \"Una vez alcanzada la extension completa, pasa al tercer tiron encogiendo los hombros y flexionando los brazos de forma agresiva con los codos hacia arriba y hacia fuera. En el punto maximo de extension, tira agresivamente hacia abajo, rotando los codos por debajo de la barra mientras lo haces. Recibe la barra en una posicion de sentadilla frontal, cuya profundidad depende de la altura de la barra al final del tercer tiron. La barra debe colocarse sobre los hombros extendidos, tocando ligeramente la garganta con las manos relajadas. Continua descendiendo hasta la posicion de sentadilla inferior, lo que te ayudara en la recuperacion.\", \"Recupera inmediatamente impulsandote con los talones, manteniendo el torso erguido y los codos arriba. Continua hasta que te hayas levantado a una posicion de pie.\"]','halterofilia_olimpica','[\"Clean/0.jpg\", \"Clean/1.jpg\"]','Clean',162) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Clean Shrug','traccion','principiante','compuesto','barra','[\"trapecios\"]','[\"antebrazos\", \"hombros\"]','[\"Comience con un agarre doble por encima de la cabeza o en gancho, con los hombros separados a la anchura de los hombros y la barra colgando a la altura de la mitad del muslo. La espalda debe estar recta e inclinada ligeramente hacia delante.\", \"Encoja los hombros hacia las orejas. Aunque este ejercicio suele realizarse con mas peso que una limpieza, evite sobrecargarlo hasta el punto de que la ejecucion se ralentice.\"]','halterofilia_olimpica','[\"Clean_Shrug/0.jpg\", \"Clean_Shrug/1.jpg\"]','Encogimiento de hombros limpio',168) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con agarre cerrado','empuje','principiante','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Acuestate boca arriba en un banco plano. Con un agarre cerrado (aproximadamente al ancho de los hombros), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Mientras inhalas, baja lentamente hasta que sientas la barra en la parte media del pecho. Consejo: Asegurate de que, a diferencia del press de banca normal, mantienes los codos cerca del torso en todo momento para maximizar la participacion de los triceps.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos triceps. Bloquea los brazos en la posicion contraida, manten durante un segundo y luego empieza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra en el soporte.\"]','fuerza','[\"Close-Grip_Barbell_Bench_Press/0.jpg\", \"Close-Grip_Barbell_Bench_Press/1.jpg\"]','Press de banca con barra con agarre cerrado',170) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con barra EZ y agarre cerrado','traccion','principiante','aislamiento','barra','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie con el torso erguido mientras sostienes una barra EZ en el mango interior mas cercano. Las palmas de tus manos deben estar mirando hacia delante y ligeramente inclinadas hacia dentro debido a la forma de la barra. Los codos deben estar cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos hacia delante mientras contraes los biceps y exhalas. Consejo: Solo deben moverse los antebrazos.\", \"Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo y aprieta los biceps con fuerza.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Close-Grip_EZ_Bar_Curl/0.jpg\", \"Close-Grip_EZ_Bar_Curl/1.jpg\"]','Curl con barra EZ y agarre cerrado',172) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con barra EZ y agarre cerrado con banda','traccion','principiante','aislamiento','barra_ez','[\"biceps\"]','[\"antebrazos\"]','[\"Attacha una banda a cada extremo de la barra. Toma la barra, colocando un pie en el medio de la banda. Ponte de pie con un agarre estrecho y supinado en la barra EZ. Los codos deben estar cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores en su lugar, flexiona los codos para ejecutar el curl. Exhala al levantar el peso.\", \"Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo y aprieta los biceps con fuerza.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Close-Grip_EZ-Bar_Curl_with_Band/0.jpg\", \"Close-Grip_EZ-Bar_Curl_with_Band/1.jpg\"]','Curl con barra EZ y agarre cerrado con banda',173) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con barra EZ y agarre cerrado','empuje','principiante','compuesto','barra_ez','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Acuestese en un banco plano con una barra EZ cargada con un peso adecuado.\", \"Con un agarre estrecho, levante la barra y mantengala recta sobre su torso con los codos hacia dentro. Los brazos deben estar perpendiculares al suelo. Esta sera su posicion inicial.\", \"Ahora baje la barra hacia la parte inferior de su pecho mientras inhala. Manten los codos hacia dentro mientras realizas este movimiento.\", \"Utilizando los triceps para empujar la barra hacia arriba, presiona hacia atras hasta la posicion inicial extendiendo los codos mientras exhalas.\", \"Repite.\"]','fuerza','[\"Close-Grip_EZ-Bar_Press/0.jpg\", \"Close-Grip_EZ-Bar_Press/1.jpg\"]','Press con barra EZ y agarre cerrado',174) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion con agarre cerrado con mancuernas','empuje','intermedio','compuesto','solo_cuerpo','[\"triceps\"]','[\"abdominales\", \"pecho\", \"hombros\"]','[\"Acuestate en el suelo y coloca tus manos en una mancuerna vertical. Apoyando tu peso en los dedos de los pies y las manos, manten el torso rigido y los codos pegados al cuerpo con los brazos estirados. Esta sera tu posicion inicial.\", \"Baja tu cuerpo, permitiendo que los codos se flexionen mientras inhalas. Manten el cuerpo recto, sin permitir que las caderas se eleven o se hundan.\", \"Empuja la espalda hacia arriba hasta la posicion inicial extendiendo los codos. Exhala mientras realizas este paso.\", \"Despues de una pausa en la posicion contraida, repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Close-Grip_Push-Up_off_of_a_Dumbbell/0.jpg\", \"Close-Grip_Push-Up_off_of_a_Dumbbell/1.jpg\"]','Flexiones con agarre cerrado con mancuernas',176) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones con agarre cerrado de pie con barra','traccion','principiante','aislamiento','barra','[\"biceps\"]','[\"antebrazos\"]','[\"Sujete una barra con ambas manos, con las palmas hacia arriba y separadas unos centimetros.\", \"Pongase de pie con el torso recto y la cabeza erguida. Los pies deben estar separados aproximadamente a la anchura de los hombros y los codos cerca del torso. Esta sera su posicion inicial. Consejo: Mantenga los brazos y los codos fijos durante todo el movimiento.\", \"Levante la barra con un movimiento semicircular hasta que los antebrazos toquen los biceps. Exhala mientras realizas esta parte del movimiento y contrae los biceps con fuerza durante un segundo en la parte superior. Consejo: Evita doblar la espalda o realizar movimientos oscilantes mientras levantas el peso. Solo deben moverse los antebrazos.\", \"Vuelve lentamente la espalda hacia abajo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Close-Grip_Standing_Barbell_Curl/0.jpg\", \"Close-Grip_Standing_Barbell_Curl/1.jpg\"]','Curl con barra de pie con agarre cerrado',177) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Capullos','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Comienza tumbado boca arriba en el suelo. Tus piernas deben estar rectas y tus brazos extendidos detras de la cabeza. Esta sera tu posicion inicial.\", \"Para realizar el movimiento, lleva las rodillas hacia el pecho, rotando la pelvis para levantar los gluteos del suelo. Mientras lo haces, flexiona la columna vertebral, llevando los brazos por encima de la cabeza para realizar un movimiento de abdominales simultaneo.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"Cocoons/0.jpg\", \"Cocoons/1.jpg\"]','Capullos',178) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rueda de Conan','Ninguno','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"abdominales\", \"biceps\", \"pantorrillas\", \"antebrazos\", \"espalda_baja\", \"hombros\", \"trapecios\"]','[\"Con el peso cargado, toma un zurcher y manten en el extremo del implemento. Coloca la barra en el hueco del codo y manten sobre tu muñeca. Intenta mantener el peso fuera de los antebrazos.\", \"Comienza por levantando el peso del suelo. Manten una postura firme y erguida mientras comienzas a caminar, dando pasos cortos y rapidos. Mira hacia arriba y hacia fuera mientras giras en circulo. No manten la respiracion durante el ejercicio. Continua caminando hasta completar una o mas vueltas completas.\"]','hombre_fuerte','[\"Conans_Wheel/0.jpg\", \"Conans_Wheel/1.jpg\"]','Rueda de Conan',179) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones de concentracion','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Sientate en un banco plano con una mancuerna frente a ti entre tus piernas. Tus piernas deben estar separadas con las rodillas dobladas y los pies en el suelo.\", \"Usa tu brazo derecho para levantar la mancuerna. Coloca la espalda de tu brazo derecho en la parte superior de tu muslo derecho. Gira la palma de tu mano hasta que quede mirando hacia delante, alejandote de tu muslo. Consejo: Tu brazo debe estar extendido y la mancuerna debe estar por encima del suelo. Esta sera tu posicion inicial.\", \"Mientras mantienes el brazo superior inmovil, flexiona los pesos hacia delante mientras contraes los biceps y exhalas. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Consejo: En la parte superior del movimiento, asegurate de que el dedo meñique de tu brazo este mas alto que el pulgar. Esto garantiza una buena contraccion. Manten la posicion contraida durante un segundo mientras aprietas los biceps.\", \"Comienza lentamente a llevar las mancuernas de vuelta a la posicion inicial mientras inhalas. Precaucion: Evita los movimientos oscilantes en todo momento.\", \"Repite durante la cantidad recomendada de repeticiones. A continuacion, repite el movimiento con el brazo izquierdo.\"]','fuerza','[\"Concentration_Curls/0.jpg\", \"Concentration_Curls/1.jpg\"]','Curls de concentracion',180) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cross Body Martillo Curl','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie recto con una mancuerna en cada mano. Tus manos deben estar abajo a tu lado con las palmas hacia dentro.\", \"Mientras mantienes las palmas hacia dentro y sin girar el brazo, flexiona la mancuerna del brazo derecho hacia arriba, hacia el hombro izquierdo, mientras exhalas. Toca la parte superior de la mancuerna con el hombro y manten la contraccion durante un segundo.\", \"Baja lentamente la mancuerna por la misma trayectoria mientras inhalas y luego repite el mismo movimiento con el brazo izquierdo.\", \"Continua alternando de esta manera hasta completar la cantidad recomendada de repeticiones con cada brazo.\"]','fuerza','[\"Cross_Body_Hammer_Curl/0.jpg\", \"Cross_Body_Hammer_Curl/1.jpg\"]','Cross_Body_Hammer_Curl',181) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales cruzados','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Lie flat en tu espalda y bend tus rodillas aproximadamente 60 degrees.\", \"Manten tu pies flat en the suelo y place tus manos loosely behind tu cabeza. Esta sera tu posicion inicial.\", \"Now curl arriba y bring your derecho elbow y shoulder across tu cuerpo mientras bring your izquierdo knee in hacia tu izquierdo shoulder at the mismo time. Reach con your elbow y try to toca your knee. Exhala mientras realizas este movimiento. Consejo: Intenta llevar el hombro hacia la rodilla en lugar de solo el codo y recuerda que la clave es contraer los abdominales mientras realizas el movimiento, no solo mover el codo.\", \"Ahora vuelve a la posicion inicial mientras inhalas y repite con el codo izquierdo y la rodilla derecha.\", \"Continua alternando de esta forma hasta completar todas las repeticiones prescritas.\"]','fuerza','[\"Cross-Body_Crunch/0.jpg\", \"Cross-Body_Crunch/1.jpg\"]','Abdominales cruzados',183) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Crossover Inverso Zancada','traccion','intermedio','Ninguno','Ninguno','[\"espalda_baja\"]','[\"abdominales\", \"abductores\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Realiza una zancada trasera dando un paso hacia atras con un pie y flexionando las caderas y la rodilla delantera. Al hacerlo, gira el torso hacia la pierna delantera.\", \"Despues de una breve pausa, vuelve a la posicion inicial y repite en el otro lado, continuando de forma alterna.\"]','estiramiento','[\"Crossover_Reverse_Lunge/0.jpg\", \"Crossover_Reverse_Lunge/1.jpg\"]','Zancada cruzada inversa',184) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales - Manos por encima de la cabeza','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Tumbate en el suelo con la espalda plana y las rodillas dobladas con un angulo de unos 60 grados entre los isquiotibiales y las pantorrillas.\", \"Manten los pies planos en el suelo y estira los brazos por encima de la cabeza con las palmas cruzadas. Esta sera tu posicion inicial.\", \"Flexiona la parte superior del cuerpo hacia delante y levanta los omoplatos del suelo. En todo momento, manten los brazos alineados con la cabeza, el cuello y los hombros. No los muevas hacia delante desde esa posicion. Exhala mientras realizas esta parte del movimiento y manten la contraccion durante un segundo.\", \"Baja lentamente a la posicion inicial mientras inhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Crunch_-_Hands_Overhead/0.jpg\", \"Crunch_-_Hands_Overhead/1.jpg\"]','Abdominales con manos por encima de la cabeza',186) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Crunch - Legs On Exercise Ball','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate boca arriba con los pies apoyados en una pelota de ejercicios y las rodillas dobladas en un angulo de 90 grados.\", \"Coloca los pies separados entre tres y cuatro pulgadas y apunta los dedos hacia adentro para que se toquen.\", \"Coloca las manos ligeramente a ambos lados de la cabeza manteniendo los codos hacia adentro. Consejo: No cruces los dedos detras de la cabeza.\", \"Empuja la parte baja de la espalda hacia el suelo para aislar mejor los musculos abdominales. Esta sera tu posicion inicial.\", \"Empieza a levantar los hombros del suelo y sigue empujando hacia abajo con toda la fuerza que puedas con la parte baja de la espalda. Los hombros deben levantarse del suelo solo unos 10 cm, y la parte baja de la espalda debe permanecer en el suelo. Exhala mientras ejecutas esta parte del movimiento. Aprieta los abdominales con fuerza en la parte superior de la contraccion y manten durante un segundo. Consejo: Concentrate en un movimiento lento y controlado. Evita utilizar el impulso en todo momento.\", \"Vuelve lentamente la espalda abajo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Crunch_-_Legs_On_Exercise_Ball/0.jpg\", \"Crunch_-_Legs_On_Exercise_Ball/1.jpg\"]','Abdominales con piernas sobre pelota de ejercicios',187) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Tumbate boca arriba con los pies apoyados en el suelo o descansando en un banco con las rodillas dobladas en un angulo de 90 grados. Si tienes los pies apoyados en un banco, separalos entre tres y cuatro pulgadas y apunta los dedos hacia dentro para que se toquen.\", \"Ahora coloca las manos ligeramente a ambos lados de la cabeza manteniendo los codos hacia dentro. Consejo: No cruces los dedos detras de la cabeza.\", \"Mientras empujas la parte baja de la espalda hacia el suelo para aislar mejor los musculos abdominales, comienza a levantar los hombros del suelo.\", \"Sigue empujando hacia abajo con toda la fuerza que puedas con la parte baja de la espalda mientras contraes los abdominales y exhalas. Los hombros deben levantarse del suelo solo unos cuatro pulgadas, y la parte baja de la espalda debe permanecer en el suelo. En la parte superior del movimiento, contrae los abdominales con fuerza y manten la contraccion durante un segundo. Consejo: Concentrate en un movimiento lento y controlado, no hagas trampa utilizando el impulso.\", \"Despues de la contraccion de un segundo, comienza a bajar lentamente de nuevo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Crunches/0.jpg\", \"Crunches/1.jpg\"]','Abdominales',188) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press cubano','empuje','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"trapecios\"]','[\"Toma una mancuerna en cada mano con un agarre pronado en posicion de pie. Levanta tus brazos superiores de modo que queden paralelos al suelo, dejando que tus brazos inferiores cuelguen en posicion de \\\"espantapajaros\\\". Esta sera tu posicion inicial.\", \"Para iniciar el movimiento, gira externamente los hombros para mover el brazo superior 180 grados. Manten los brazos superiores en su sitio, rotando los brazos superiores hasta que las muñecas esten directamente por encima de los codos, con los antebrazos perpendiculares al suelo.\", \"Ahora presiona las mancuernas extendiendo los codos, estirando los brazos por encima de la cabeza.\", \"Vuelve a la posicion inicial mientras inhalas, invirtiendo los pasos.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Cuban_Press/0.jpg\", \"Cuban_Press/1.jpg\"]','Press cubano',189) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento del bailarin','estatico','principiante','Ninguno','Ninguno','[\"espalda_baja\"]','[\"abductores\", \"gluteos\"]','[\"Sientate en el suelo.\", \"Cruza la pierna derecha sobre la izquierda, manteniendo la rodilla flexionada. La pierna izquierda esta recta y apoyada en el suelo.\", \"Coloca el brazo izquierdo sobre la pierna derecha y la mano derecha en el suelo.\", \"Gira la parte superior del cuerpo hacia la derecha y manten la posicion durante 10-20 segundos. Cambia de lado.\"]','estiramiento','[\"Dancers_Stretch/0.jpg\", \"Dancers_Stretch/1.jpg\"]','Estiramiento de bailarines',190) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dead Bug','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Comienza acostado boca arriba con las manos extendidas por encima de ti hacia el techo.\", \"Lleva los pies, las rodillas y las caderas a 90 grados.\", \"Exhala con fuerza para bajar la caja toracica y aplanar la espalda contra el suelo, rotando la pelvis hacia arriba y apretando los gluteos. Manten esta posicion durante todo el movimiento. Esta sera tu posicion inicial.\", \"Inicia el ejercicio extendiendo una pierna, estirando la rodilla y la cadera para llevar la pierna justo por encima del suelo.\", \"Manten la posicion de la zona lumbar y la pelvis mientras realizas el movimiento, ya que la espalda tendera a arquearse.\", \"Manten la tension y vuelve a colocar la pierna de trabajo en la posicion inicial.\", \"Repite en el lado opuesto, alternando hasta completar la serie.\"]','fuerza','[\"Dead_Bug/0.jpg\", \"Dead_Bug/1.jpg\"]','Dead_Bug',191) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto con bandas','traccion','experto','compuesto','barra','[\"espalda_baja\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_media\", \"cuadriceps\", \"trapecios\"]','[\"Para hacer peso muerto con bandas cortas, simplemente colocalas sobre la barra antes de empezar y pisa sobre ellas para prepararte. Las bandas largas deberan fijarse a una base segura, como mancuernas pesadas o un soporte.\", \"Con los pies y el agarre fijos, respira profundamente y luego baja las caderas y flexiona las rodillas hasta que las espinillas toquen la barra. Mira hacia adelante con la cabeza, manten el pecho arriba y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. Una vez que la barra haya pasado las rodillas, tira de ella hacia atras con fuerza, juntando los omoplatos mientras empujas las caderas hacia adelante contra la barra.\", \"Baja la barra doblando las caderas y guiandola hacia el suelo.\"]','levantamiento de pesas','[\"Deadlift_with_Bands/0.jpg\", \"Deadlift_with_Bands/1.jpg\"]','Peso muerto con bandas',192) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca declinado con barra','empuje','principiante','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Asegura tus piernas en el extremo del banco declinado y tumbate lentamente en el banco.\", \"Con un agarre de anchura media (un agarre que crea un angulo de 90 grados en el centro del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. Los brazos deben estar perpendiculares al suelo. Esta sera tu posicion inicial. Consejo: Para proteger el manguito rotador, es mejor que un compañero te ayude a levantar la barra del soporte.\", \"Mientras inspiras, baja lentamente hasta que sientas la barra en la parte inferior del pecho.\", \"Despues de una pausa de un segundo, lleva la barra a la posicion inicial mientras exhalas y empuja la barra con los musculos del pecho. Bloquea los brazos y aprieta el pecho en la posicion contraida, manten durante un segundo y luego vuelve a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra en el soporte.\"]','fuerza','[\"Decline_Barbell_Bench_Press/0.jpg\", \"Decline_Barbell_Bench_Press/1.jpg\"]','Press de banca declinado con barra',194) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press declinado con agarre cerrado y skull crusher','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Asegura tus piernas en el extremo del banco declinado y tumbate lentamente en el banco.\", \"Con un agarre cerrado (un agarre ligeramente inferior al ancho de los hombros), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados y los codos hacia dentro. Los brazos deben estar perpendiculares al suelo. Esta sera tu posicion inicial. Consejo: Para proteger el manguito rotador, es mejor que un compañero te ayude a levantar la barra del soporte.\", \"Ahora baja la barra hacia la parte inferior del pecho mientras inhalas. Manten los codos hacia dentro mientras realizas este movimiento.\", \"Utilizando los triceps para empujar la barra hacia arriba, presiona hacia atras hasta la posicion inicial mientras exhalas.\", \"Mientras inhalas y mantienes la parte superior de los brazos fijos, lleva la barra hacia abajo lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que sientas que la barra toca ligeramente tu frente. Inhala mientras realizas esta parte del movimiento.\", \"Eleva la barra hasta la posicion inicial contrayendo los triceps y exhalando.\", \"Repite los pasos 3-6 hasta completar la cantidad recomendada de repeticiones.\"]','fuerza','[\"Decline_Close-Grip_Bench_To_Skull_Crusher/0.jpg\", \"Decline_Close-Grip_Bench_To_Skull_Crusher/1.jpg\"]','Press de banca declinado con agarre cerrado y elevacion de cabeza',195) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales declinados','traccion','intermedio','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Asegura tus piernas en el extremo del banco declinado y tumbate.\", \"Ahora coloca tus manos ligeramente a ambos lados de tu cabeza manteniendo tus codos hacia dentro. Consejo: No bloquees los dedos detras de la cabeza.\", \"Mientras empujas la parte baja de la espalda hacia abajo en el banco para aislar mejor los musculos abdominales, comienza a rodar los hombros fuera de el.\", \"Continua empujando hacia abajo con toda la fuerza que puedas con la parte baja de la espalda mientras contraes los abdominales y exhalas. Los hombros deben levantarse del banco solo aproximadamente cuatro pulgadas, y la parte baja de la espalda debe permanecer en el banco. En la parte superior del movimiento, contrae los abdominales con fuerza y manten la contraccion durante un segundo. Consejo: Concentrate en un movimiento lento y controlado, no hagas trampa utilizando el impulso.\", \"Despues de la contraccion de un segundo, comienza a bajar lentamente de nuevo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Decline_Crunch/0.jpg\", \"Decline_Crunch/1.jpg\"]','Abdominales declinados',196) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press declinado con mancuernas','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Asegura tus piernas en el extremo del banco declinado y tumbate con una mancuerna en cada mano sobre los muslos. Las palmas de las manos estaran enfrentadas entre si.\", \"Una vez tumbado, mueve las mancuernas frente a ti a la anchura de los hombros.\", \"Una vez a la anchura de los hombros, gira las muñecas hacia delante de modo que las palmas de las manos queden alejadas de ti. Esta sera tu posicion inicial.\", \"Baja lentamente las pesas hacia los lados mientras exhalas. Manten el control total de las mancuernas en todo momento. Consejo: Durante todo el movimiento, los antebrazos deben estar siempre perpendiculares al suelo.\", \"Mientras exhalas, empuja las mancuernas hacia arriba utilizando los musculos pectorales. Bloquea los brazos en la posicion contraida, aprieta el pecho, manten la posicion durante un segundo y luego empieza a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito en tu programa de entrenamiento.\"]','fuerza','[\"Decline_Dumbbell_Bench_Press/0.jpg\", \"Decline_Dumbbell_Bench_Press/1.jpg\"]','Press de banca declinado con mancuernas',197) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press declinado con mancuernas','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[]','[\"Asegura tus piernas al final del banco declinado y tumbate con una mancuerna en cada mano sobre tus muslos. Las palmas de tus manos estaran enfrentadas entre si.\", \"Una vez que estes tumbado, mueve las mancuernas frente a ti a la altura de los hombros. Las palmas de las manos deben estar enfrentadas y los brazos deben estar perpendiculares al suelo y completamente extendidos. Esta sera tu posicion inicial.\", \"Con una ligera flexion en los codos para evitar tension en el tendon del biceps, baja los brazos hacia ambos lados en un amplio arco hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento, los brazos deben permanecer fijos; el movimiento solo debe producirse en la articulacion del hombro.\", \"Vuelve los brazos a la posicion inicial mientras contraes los musculos del pecho y exhalas. Consejo: Asegurate de utilizar el mismo arco de movimiento que has utilizado para bajar las pesas.\", \"Manten durante un segundo la posicion contraida y repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Decline_Dumbbell_Flyes/0.jpg\", \"Decline_Dumbbell_Flyes/1.jpg\"]','Extension con mancuernas en declive',198) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuernas en declive','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Asegura tus piernas al final del banco declinado y acuestate boca abajo con una mancuerna en cada mano sobre tus muslos. Las palmas de tus manos estaran enfrentadas entre si.\", \"Una vez que estes acostado, mueve las mancuernas frente a ti a la altura de los hombros. Las palmas de las manos deben estar enfrentadas y los brazos deben estar perpendiculares al suelo y completamente extendidos. Esta sera tu posicion inicial.\", \"Mientras inhalas y mantienes los brazos superiores fijos (y los codos hacia dentro), baja las mancuernas lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que tus pulgares esten junto a tus orejas. Inhala mientras realizas esta parte del movimiento.\", \"Eleva las mancuernas hacia atras a la posicion inicial contrayendo los triceps y exhalando.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Decline_Dumbbell_Triceps_Extension/0.jpg\", \"Decline_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuernas en declive',199) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con barra EZ en declive','empuje','principiante','aislamiento','barra','[\"triceps\"]','[]','[\"Asegura tus piernas en el extremo del banco declinado y recuestate lentamente en el banco.\", \"Con un agarre cerrado (un agarre ligeramente inferior al ancho de los hombros), levanta la barra EZ del soporte y mantenla recta sobre ti con los brazos bloqueados y los codos hacia dentro. Los brazos deben estar perpendiculares al suelo. Esta sera tu posicion inicial. Consejo: Para proteger el manguito rotador, es mejor que un compañero te ayude a levantar la barra del soporte.\", \"Mientras inspiras y mantienes los brazos superiores fijos, baja la barra lentamente moviendo los antebrazos en un movimiento semicircular hacia ti hasta que sientas que la barra toca ligeramente tu frente. Inhala mientras realizas esta parte del movimiento.\", \"Eleva la barra a la posicion inicial contrayendo los triceps y exhalando.\", \"Repite hasta completar el numero recomendado de repeticiones.\"]','fuerza','[\"Decline_EZ_Bar_Triceps_Extension/0.jpg\", \"Decline_EZ_Bar_Triceps_Extension/1.jpg\"]','Extension de triceps con barra EZ en declive',200) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales oblicuos declinados','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Asegura tus piernas en el extremo del banco declinado y tumbate lentamente en el banco.\", \"Levanta la parte superior del cuerpo del banco hasta que tu torso forme un angulo de aproximadamente 35-45 grados con respecto al suelo.\", \"Coloca una mano junto a la cabeza y la otra en el muslo. Esta sera tu posicion inicial.\", \"Levanta lentamente la parte superior del cuerpo desde la posicion inicial mientras giras el torso hacia la izquierda. Continua haciendo abdominales hacia arriba mientras exhalas hasta que tu codo derecho toque tu rodilla izquierda. Manten esta posicion contraida durante un segundo. Consejo: Concentrate en mantener los abdominales tensos y en realizar el movimiento de forma lenta y controlada.\", \"Baja lentamente el cuerpo hacia atras hasta la posicion inicial mientras inhalas.\", \"Despues de completar una serie en el lado derecho con el numero de repeticiones recomendado, cambia al lado izquierdo. Consejo: Concentrate en girar realmente el torso y en sentir la contraccion cuando estes en la posicion superior.\"]','fuerza','[\"Decline_Oblique_Crunch/0.jpg\", \"Decline_Oblique_Crunch/1.jpg\"]','Decline_Oblique_Crunch',201) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion declinada','empuje','principiante','compuesto','Ninguno','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate en el suelo boca abajo y coloca tus manos aproximadamente a 36 pulgadas de distancia mientras sostienes tu torso arriba a la longitud de los brazos. Mueve tus pies hacia arriba a una caja o banco. Esta sera tu posicion inicial.\", \"A continuacion, baja hasta que tu pecho casi toque el suelo mientras inhalas.\", \"Ahora exhala y empuja la parte superior del cuerpo hacia arriba hasta la posicion inicial mientras aprietas el pecho.\", \"Despues de una breve pausa en la posicion superior contraida, puedes comenzar a bajar de nuevo durante tantas repeticiones como sea necesario.\"]','fuerza','[\"Decline_Push-Up/0.jpg\", \"Decline_Push-Up/1.jpg\"]','Flexiones declinadas',202) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales inversos declinados','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate boca arriba en un banco declinado y manten la parte superior del banco con ambas manos. No dejes que tu cuerpo se deslice hacia abajo desde esta posicion.\", \"Manten tus piernas paralelas al suelo utilizando tus abdominales para mantenerlas ahi mientras mantienes tus rodillas y pies juntos. Consejo: Tus piernas deben estar completamente extendidas con una ligera flexion en la rodilla. Esta sera tu posicion inicial.\", \"Mientras exhalas, mueve tus piernas hacia el torso mientras giras la pelvis hacia atras y levantas tus caderas del banco. Al final de este movimiento, tus rodillas tocaran tu pecho.\", \"Manten la contraccion durante un segundo y mueve tus piernas de vuelta a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Decline_Reverse_Crunch/0.jpg\", \"Decline_Reverse_Crunch/1.jpg\"]','Abdominales inversos en declive',203) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto deficitario','traccion','intermedio','compuesto','barra','[\"espalda_baja\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_media\", \"cuadriceps\", \"trapecios\"]','[\"Comience por disponer de una plataforma o discos de peso sobre los que pueda apoyarse, normalmente de 1 a 3 pulgadas de altura. Acerquese a la barra de modo que quede centrada sobre sus pies. Tus pies deben estar separados aproximadamente a la anchura de las caderas. Dobla las caderas para agarrar la barra a la anchura de los hombros, permitiendo que los omoplatos se protruyan. Normalmente, se utiliza un agarre por encima o un agarre por encima/por debajo en series mas pesadas.\", \"Con tus pies y tu agarre fijos, respira profundamente y luego baja las caderas y dobla las rodillas hasta que tus espinillas toquen la barra. Mira hacia delante con la cabeza, manten el pecho arriba y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. Una vez que la barra haya pasado las rodillas, tira de ella hacia atras con fuerza, juntando los omoplatos mientras empujas las caderas hacia delante contra la barra.\", \"Baja la barra flexionando las caderas y guiandola hacia el suelo.\"]','levantamiento de pesas','[\"Deficit_Deadlift/0.jpg\", \"Deficit_Deadlift/1.jpg\"]','Deficit_Deadlift',205) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto en profundidad','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para este ejercicio necesitaras dos cajas o bancos, uno de 12 a 16 pulgadas de alto y el otro de 22 a 26 pulgadas de alto.\", \"Ponte de pie en una de las dos cajas con los brazos a los lados; los pies deben estar juntos y ligeramente separados del borde, como en el salto en profundidad. Coloca la otra caja aproximadamente a dos o tres pies delante y frente al ejecutante.\", \"Comienza saltando de la caja inicial, aterrizando y despegando simultaneamente con ambos pies.\", \"Rebota impulsandote hacia arriba y hacia afuera con la mayor intensidad posible, utilizando los brazos y la extension completa del cuerpo para saltar a la caja mas alta. Una vez mas, deja que las piernas absorban el impacto.\"]','pliometria','[\"Depth_Jump_Leap/0.jpg\", \"Depth_Jump_Leap/1.jpg\"]','Salto en profundidad',206) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Maquina de fondos','empuje','principiante','compuesto','maquina','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Sientate de forma segura en una maquina de fondos, selecciona el peso y agarra firmemente las asas.\", \"Ahora manten los codos pegados a los costados para poner enfasis en los triceps. Los codos deben estar doblados en un angulo de 90 grados.\", \"A medida que contraes los triceps, extiende los brazos hacia abajo mientras exhalas. Consejo: En la parte inferior del movimiento, concentrate en mantener una ligera flexion en los brazos para mantener la tension en el musculo triceps.\", \"Ahora, lentamente, deja que tus brazos vuelvan a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dip_Machine/0.jpg\", \"Dip_Machine/1.jpg\"]','Maquina de fondos',207) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Fondos - Version triceps','empuje','principiante','compuesto','solo_cuerpo','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Para colocarte en la posicion inicial, manten tu cuerpo a la longitud del brazo con tus brazos casi bloqueados por encima de las barras.\", \"Ahora, inhala y baja lentamente. Tu torso debe permanecer erguido y tus codos deben permanecer cerca de tu cuerpo. Esto ayuda a centrarse mejor en la participacion del triceps. Baja hasta que se forme un angulo de 90 grados entre el brazo y el antebrazo.\", \"A continuacion, exhala y empuja tu torso hacia arriba utilizando los triceps para llevar tu cuerpo a la posicion inicial.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Dips_-_Triceps_Version/0.jpg\", \"Dips_-_Triceps_Version/1.jpg\"]','Fondos_-_Version_triceps',209) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones de pantorrillas con maquina','empuje','intermedio','aislamiento','otro','[\"pantorrillas\"]','[]','[\"Para este ejercicio necesitaras acceso a una maquina de elevacion de pantorrillas. Comienza colocando la parte inferior de la espalda y las caderas debajo de la palanca acolchada que se proporciona. La zona del coxis debe ser la que este en contacto con la almohadilla.\", \"Coloca ambos brazos en las asas laterales y coloca las puntas de los pies en el bloque de pantorrillas con los talones extendidos. Alinea los dedos de los pies hacia delante, hacia dentro o hacia fuera, dependiendo de la zona que desees trabajar, y estira las rodillas sin bloquearlas. Esta sera tu posicion inicial.\", \"Levanta los talones mientras exhalas, extendiendo los tobillos lo mas alto posible y flexionando las pantorrillas. Asegurate de que las rodillas permanezcan inmoviles en todo momento. No debe haber flexion en ningun momento. Manten la posicion contraida durante un segundo antes de empezar a bajar la espalda.\", \"Vuelve lentamente a la posicion inicial mientras inhalas bajando los talones a medida que flexionas los tobillos hasta que las pantorrillas esten estiradas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Donkey_Calf_Raises/0.jpg\", \"Donkey_Calf_Raises/1.jpg\"]','Elevaciones de pantorrillas con burro',210) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Doble con pesa rusa Alternado Hang Clean','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"biceps\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[\"Coloca dos pesas rusas entre tus pies. Para ponerte en la posicion inicial, empuja el trasero hacia atras y mira recto al frente.\", \"Lleva una pesa rusa al hombro y manten la otra pesa rusa en el suelo.\", \"Con un movimiento fluido, baja la pesa rusa superior mientras levantas la pesa rusa inferior.\"]','fuerza','[\"Double_Kettlebell_Alternating_Hang_Clean/0.jpg\", \"Double_Kettlebell_Alternating_Hang_Clean/1.jpg\"]','Doble_Kettlebell_Alternando_Hang_Clean',211) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Doble con pesa rusa Push Press','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"pantorrillas\", \"cuadriceps\", \"triceps\"]','[\"Limpia dos pesas rusas hasta tus hombros.\", \"Haz una sentadilla unos centimetros y revierte el movimiento rapidamente. Utiliza el impulso de las piernas para impulsar las pesas rusas sobre la cabeza.\", \"Una vez que las pesas rusas esten bloqueadas, baja las pesas rusas hasta tus hombros y repite.\"]','fuerza','[\"Double_Kettlebell_Push_Press/0.jpg\", \"Double_Kettlebell_Push_Press/1.jpg\"]','Empuje con doble pesa rusa',213) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Doble con pesa rusa Snatch','traccion','experto','compuesto','pesas rusas','[\"hombros\"]','[\"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Coloca dos pesas rusas detras de tus pies. Dobla tus rodillas y sienta tu espalda para levantar las pesas rusas.\", \"Balancea las pesas rusas entre tus piernas con fuerza y revierte la direccion.\", \"Impulsa con tus caderas y bloquea las pesas rusas sobre la cabeza en un movimiento ininterrumpido.\"]','fuerza','[\"Double_Kettlebell_Snatch/0.jpg\", \"Double_Kettlebell_Snatch/1.jpg\"]','Doble_Kettlebell_Arrancada',214) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Doble patada trasera con la pierna','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza de pie con las rodillas ligeramente flexionadas.\", \"Haz una sentadilla rapida a poca distancia, flexionando las caderas y las rodillas, y extiendete inmediatamente para saltar a la maxima altura vertical.\", \"Mientras subes, mete los talones flexionando las rodillas, intentando tocar los gluteos.\", \"Termina el movimiento aterrizando con las rodillas solo parcialmente flexionadas, utilizando las piernas para absorber el impacto.\"]','pliometria','[\"Double_Leg_Butt_Kick/0.jpg\", \"Double_Leg_Butt_Kick/1.jpg\"]','Doble_patada_hacia_atras_con_las_piernas',216) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Equilibrio hacia abajo','estatico','intermedio','aislamiento','fitball','[\"gluteos\"]','[\"abdominales\", \"isquiotibiales\"]','[\"Acuestate boca abajo sobre una pelota de ejercicios.\", \"Mientras descansas sobre tu estomago en la pelota, camina con tus manos hacia adelante por el suelo y levanta tus piernas, extendiendo tus codos y rodillas.\"]','fuerza','[\"Downward_Facing_Balance/0.jpg\", \"Downward_Facing_Balance/1.jpg\"]','Equilibrio hacia abajo',217) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Drop Push','empuje','intermedio','compuesto','otro','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Coloca cajas bajas u otras plataformas a una distancia de entre 60 y 90 cm entre si.\", \"Colocate en posicion de flexion entre ellas, apoyandote con las manos sobre las cajas.\", \"Con una buena postura, desciende de las plataformas empujando hacia arriba y moviendo las manos hasta la anchura de los hombros, amortiguando el aterrizaje y absorbiendo el impacto con los brazos.\"]','pliometria','[\"Drop_Push/0.jpg\", \"Drop_Push/1.jpg\"]','Empuje con caida',219) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dumbbell Alternado Bicep Curl','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie (torso erguido) con una mancuerna en cada mano sostenida a la longitud de los brazos. Los codos deben estar cerca del torso y las palmas de las manos deben estar mirando hacia los muslos.\", \"Mientras sostienes la parte superior del brazo inmovil, flexiona el peso derecho mientras giras la palma de las manos hasta que esten mirando hacia adelante. En este punto, continue contrayendo los biceps mientras exhala hasta que los biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Mantenga la posicion contraida durante un segundo mientras aprieta los biceps. Consejo: Solo deben moverse los antebrazos.\", \"Comience lentamente a llevar la mancuerna hacia atras a la posicion inicial mientras inhala. Consejo: Recuerda girar las palmas de las manos hacia atras a la posicion inicial (mirando hacia los muslos) mientras bajas.\", \"Repite el movimiento con la mano izquierda. Esto equivale a una repeticion.\", \"Continua alternando de esta forma durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Alternate_Bicep_Curl/0.jpg\", \"Dumbbell_Alternate_Bicep_Curl/1.jpg\"]','Flexion_alternada_de_biceps_con_mancuernas',220) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con mancuernas','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco plano con una mancuerna en cada mano apoyada sobre tus muslos. Las palmas de tus manos estaran enfrentadas entre si.\", \"Luego, usando tus muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para que puedas mantenerlas frente a ti a la altura de los hombros.\", \"Una vez a la altura de los hombros, gira las muñecas hacia delante de modo que las palmas de las manos queden mirando hacia fuera. Las mancuernas deben quedar justo a los lados del pecho, con el brazo y el antebrazo formando un angulo de 90 grados. Asegurate de mantener el control total de las mancuernas en todo momento. Esta sera tu posicion inicial.\", \"Luego, mientras exhalas, usa tu pecho para empujar las mancuernas hacia arriba. Bloquea tus brazos en la parte superior del levantamiento y aprieta tu pecho, manten durante un segundo y luego comienza a bajar lentamente. Consejo: Lo ideal es que bajar el peso te lleve aproximadamente el doble de tiempo que levantarlo.\", \"Repite el movimiento durante la cantidad prescrita de repeticiones de tu programa de entrenamiento.\"]','fuerza','[\"Dumbbell_Bench_Press/0.jpg\", \"Dumbbell_Bench_Press/1.jpg\"]','Press de banca con mancuernas',221) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con mancuernas con agarre neutro','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Toma una mancuerna en cada mano y recuestate boca arriba sobre un banco plano. Tus pies deben estar apoyados en el suelo y tus omoplatos retraidos.\", \"Manteniendo un agarre neutro, con las palmas enfrentadas, comienza con los brazos extendidos directamente por encima de ti, perpendiculares al suelo. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando los codos, bajando los brazos superiores hacia los costados. Desciende hasta que las mancuernas esten a la altura de tu torso.\", \"Haz una pausa, luego extiende los codos y vuelve a la posicion inicial.\"]','fuerza','[\"Dumbbell_Bench_Press_with_Neutral_Grip/0.jpg\", \"Dumbbell_Bench_Press_with_Neutral_Grip/1.jpg\"]','Press de banca con mancuernas con agarre neutro',222) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de biceps con mancuernas','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie recto con una mancuerna en cada mano a la longitud del brazo. Manten tus codos cerca de tu torso y rota las palmas de tus manos hasta que esten mirando hacia adelante. Esta sera tu posicion inicial.\", \"Ahora, manteniendo los brazos superiores inmoviles, exhala y flexiona los pesos mientras contraes tus biceps. Continua levantando las pesas hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Manten la posicion contraida durante una breve pausa mientras aprietas los biceps.\", \"Luego, inhala y comienza a bajar lentamente las mancuernas de vuelta a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Bicep_Curl/0.jpg\", \"Dumbbell_Bicep_Curl/1.jpg\"]','Flexion de biceps con mancuernas',223) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Limpiador con mancuernas','traccion','intermedio','compuesto','mancuerna','[\"isquiotibiales\"]','[\"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Comienza de pie con una mancuerna en cada mano con los pies separados a la anchura de los hombros.\", \"Baja las pesas al suelo flexionando las caderas y las rodillas, empujando las caderas hacia atras hasta que las mancuernas alcancen el suelo. Esta sera tu posicion inicial.\", \"Para iniciar el movimiento, salta violentamente hacia arriba extendiendo las caderas, las rodillas y los tobillos para acelerar las pesas hacia arriba. Manten un agarre neutro en las mancuernas y manten los brazos rectos hasta alcanzar la extension completa.\", \"Despues de la extension completa, vuelve a flexionar las caderas y las rodillas para recibir el peso en posicion de sentadilla. Deja que los brazos se flexionen, guiando las mancuernas hacia tus hombros.\", \"Al recibir el peso en posicion de sentadilla, extiende las caderas y las rodillas para terminar en posicion de pie con las pesas en tus hombros.\"]','fuerza','[\"Dumbbell_Clean/0.jpg\", \"Dumbbell_Clean/1.jpg\"]','Levantamiento con mancuernas',224) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con mancuernas en el suelo','empuje','intermedio','compuesto','mancuerna','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Tumbate en el suelo sosteniendo mancuernas en tus manos. Puedes doblar las rodillas. Comienza con las pesas completamente extendidas por encima de ti.\", \"Baja las pesas hasta que la parte superior de tus brazos entre en contacto con el suelo. Puedes doblar los codos para enfatizar el tamaño y la fuerza de los triceps, o para enfocarte en el pecho, coloca los brazos a los lados.\", \"Haz una pausa en la parte inferior y luego lleva el peso hacia arriba extendiendo los codos.\"]','levantamiento de pesas','[\"Dumbbell_Floor_Press/0.jpg\", \"Dumbbell_Floor_Press/1.jpg\"]','Press con mancuernas en el suelo',225) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Aperturas con mancuernas','empuje','principiante','aislamiento','mancuerna','[\"pecho\"]','[]','[\"Acuestate boca abajo en un banco plano con una mancuerna en cada mano apoyada sobre tus muslos. Las palmas de tus manos estaran enfrentadas entre si.\", \"Luego, usando tus muslos para ayudar a levantar las mancuernas, levanta las mancuernas una a la vez para que puedas mantenerlas frente a ti a la altura de los hombros con las palmas de tus manos enfrentadas entre si. Levanta las mancuernas hacia arriba como si las estuvieras presionando, pero detente y manten justo antes de bloquearlas. Esta sera tu posicion inicial.\", \"Con una ligera flexion en los codos para evitar tension en el tendon del biceps, baja los brazos a ambos lados en un arco amplio hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento, los brazos deben permanecer inmoviles; el movimiento solo debe producirse en la articulacion del hombro.\", \"Vuelve los brazos a la posicion inicial mientras contraes los musculos del pecho y exhalas. Consejo: Asegurate de utilizar el mismo arco de movimiento que has utilizado para bajar las pesas.\", \"Manten durante un segundo la posicion contraida y repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Dumbbell_Flyes/0.jpg\", \"Dumbbell_Flyes/1.jpg\"]','Aperturas con mancuernas',226) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo inclinado con mancuernas','traccion','principiante','compuesto','mancuerna','[\"espalda_media\"]','[\"Biceps\", \"Antebrazos\", \"Dorsales\", \"Hombros\"]','[\"Con un agarre neutro, inclinate sobre un banco inclinado.\", \"Toma una mancuerna en cada mano con un agarre neutro, comenzando con los brazos estirados. Esta sera tu posicion inicial.\", \"Retrae los omoplatos y flexiona los codos para remar las mancuernas hacia tu lado.\", \"Haz una pausa arriba del movimiento, y luego vuelve a la posicion inicial.\"]','fuerza','[\"Dumbbell_Incline_Row/0.jpg\", \"Dumbbell_Incline_Row/1.jpg\"]','Remo inclinado con mancuernas',227) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo inclinado con mancuernas','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Sientate en un banco inclinado mientras sostienes una mancuerna en cada mano sobre tus muslos.\", \"Eleva tus piernas hacia arriba para empujar las pesas hacia tus hombros e inclinate hacia atras. Coloca las mancuernas por encima de tus hombros con los brazos extendidos. Los brazos deben estar perpendiculares al suelo con las palmas hacia delante y los nudillos apuntando hacia el techo. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos rectos y bloqueados, levanta las mancuernas elevando los hombros del banco mientras exhalas.\", \"Vuelve a llevar las mancuernas a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Incline_Shoulder_Raise/0.jpg\", \"Dumbbell_Incline_Shoulder_Raise/1.jpg\"]','Elevacion inclinada de hombros con mancuernas',228) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancadas con mancuernas','empuje','principiante','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie con el torso erguido sosteniendo dos mancuernas en tus manos a los lados. Esta sera tu posicion inicial.\", \"Da un paso adelante con la pierna derecha aproximadamente 2 pies o mas desde el pie izquierdo, que permanece inmovil detras, y baja la parte superior del cuerpo, mientras mantienes el torso erguido y el equilibrio. Inhala mientras bajas. Nota: Al igual que en los otros ejercicios, no dejes que la rodilla se te vaya adelante mas alla de los dedos de los pies al bajar, ya que esto ejercera una tension excesiva en la articulacion de la rodilla. Asegurate de mantener la espinilla delantera perpendicular al suelo.\", \"Utilizando principalmente el talon del pie, empuja hacia arriba y vuelve a la posicion inicial mientras exhalas.\", \"Repite el movimiento durante el numero recomendado de repeticiones y luego hazlo con la pierna izquierda.\"]','fuerza','[\"Dumbbell_Lunges/0.jpg\", \"Dumbbell_Lunges/1.jpg\"]','Zancadas con mancuernas',229) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dumbbell Acostado One-Arm Rear Lateral Elevacion','traccion','intermedio','aislamiento','mancuerna','[\"hombros\"]','[\"espalda_media\"]','[\"Mientras sostienes una mancuerna en una mano, acuestate con el pecho hacia abajo en un banco ajustable ligeramente inclinado (unos 15 grados medidos desde el suelo). La otra mano se puede utilizar para mantener la pierna del banco durante la estabilidad.\", \"Coloca la palma de la mano que sostiene la mancuerna en una forma neutra (las palmas mirando hacia tu torso) mientras mantienes el brazo extendido con el codo ligeramente doblado. Esta sera tu posicion inicial.\", \"Ahora levanta el brazo con la mancuerna al lado hasta que el codo este a la altura de los hombros y el brazo este mas o menos paralelo al suelo mientras exhalas. Consejo: Manten el brazo perpendicular al torso mientras mantienes el brazo extendido durante todo el movimiento. Ademas, manten la contraccion en la parte superior durante un segundo.\", \"Baja lentamente la mancuerna a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/0.jpg\", \"Dumbbell_Lying_One-Arm_Rear_Lateral_Raise/1.jpg\"]','Elevacion lateral posterior con mancuernas tumbado con un brazo',230) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dumbbell Acostado Rear Lateral Elevacion','traccion','intermedio','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Mientras sostienes una mancuerna en cada mano, acuestate boca abajo en un banco ajustable ligeramente inclinado (unos 15 grados medidos desde el suelo).\", \"Coloca las palmas de las manos en posicion neutra (palmas mirando hacia tu torso) mientras mantienes los brazos extendidos con los codos ligeramente flexionados. Esta sera tu posicion inicial.\", \"Ahora levanta los brazos hacia los lados hasta que tus codos esten a la altura de los hombros y tus brazos esten aproximadamente paralelos al suelo mientras exhalas. Consejo: Manten tus brazos perpendiculares al torso mientras los mantienes extendidos durante todo el movimiento. Ademas, manten la contraccion en la parte superior durante un segundo.\", \"Baja lentamente las mancuernas a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones y luego cambia al otro brazo.\"]','fuerza','[\"Dumbbell_Lying_Rear_Lateral_Raise/0.jpg\", \"Dumbbell_Lying_Rear_Lateral_Raise/1.jpg\"]','Elevacion lateral posterior tumbado con mancuernas',232) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuerna a un brazo','empuje','intermedio','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Coge una mancuerna y sientate en un banco de press militar o en un banco utilitario que tenga un respaldo mientras colocas las mancuernas erguidas sobre tus muslos o te pones de pie con la espalda recta.\", \"Limpia la mancuerna hacia arriba para llevarla a la altura de los hombros y luego extiende el brazo por encima de tu cabeza de modo que todo el brazo quede perpendicular al suelo y junto a tu cabeza. La mancuerna debe quedar por encima de ti. La otra mano puede mantenerse completamente extendida al lado, por la cintura, apoyando el brazo superior que tiene la mancuerna o agarrandose a una superficie fija.\", \"Gira la muñeca de modo que la palma de la mano quede mirando hacia delante y el meñique hacia el techo. Esta sera tu posicion inicial.\", \"Baja lentamente la mancuerna detras de la cabeza mientras mantienes el brazo superior inmovil. Inhala mientras realizas este movimiento y haz una pausa cuando tus triceps esten completamente estirados.\", \"Vuelve a la posicion inicial flexionando los triceps mientras exhalas. Consejo: Es imprescindible que solo se mueva el antebrazo. El brazo debe permanecer inmovil junto a la cabeza en todo momento.\", \"Repite durante el numero recomendado de repeticiones y cambia de brazo.\"]','fuerza','[\"Dumbbell_One-Arm_Triceps_Extension/0.jpg\", \"Dumbbell_One-Arm_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuernas a un brazo',235) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical con mancuernas a un brazo','traccion','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"biceps\", \"trapecios\"]','[\"Coge una mancuerna y ponte de pie con el brazo extendido frente a ti con una ligera flexion en los codos y la espalda recta. Esta sera tu posicion inicial. Consejo: La mancuerna debe descansar sobre el muslo con la palma de las manos mirando hacia los muslos.\", \"La otra mano puede mantenerse completamente extendida al lado, por la cintura o agarrandose a una superficie fija. Esta sera tu posicion inicial.\", \"Usa tus hombros para levantar la mancuerna mientras exhalas. La mancuerna debe estar cerca del cuerpo mientras la mueves hacia arriba. Continua levantandola hasta que la mancuerna este casi alineada con tu barbilla. Consejo: Tus codos deben impulsar el movimiento. Al levantar la mancuerna, el codo debe estar siempre mas alto que el antebrazo. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja la mancuerna lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante el numero recomendado de repeticiones y cambia de brazo.\"]','fuerza','[\"Dumbbell_One-Arm_Upright_Row/0.jpg\", \"Dumbbell_One-Arm_Upright_Row/1.jpg\"]','Remo vertical con mancuerna a un brazo',236) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inclinado con mancuernas','traccion','intermedio','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Coge una mancuerna en cada mano y tumbate boca abajo en un banco inclinado con los hombros cerca de la parte superior de la inclinacion. Las rodillas pueden descansar en el asiento o las piernas pueden estar abiertas a los lados (mi forma preferida).\", \"Deja que los brazos se extiendan y cuelguen naturalmente frente a ti, de modo que esten perpendiculares al suelo.\", \"Ahora manten los codos pegados al cuerpo y las palmas hacia delante. Esta sera tu posicion inicial.\", \"Levanta las mancuernas contrayendo los biceps hasta que tus brazos esten completamente flexionados. Exhala mientras realizas esta parte del movimiento y asegurate de que solo se muevan los antebrazos. La parte superior de los brazos debe permanecer inmovil en todo momento.\", \"Baja las mancuernas hasta que tus brazos esten completamente extendidos.\", \"Repite durante el numero de repeticiones recomendado.\"]','fuerza','[\"Dumbbell_Prone_Incline_Curl/0.jpg\", \"Dumbbell_Prone_Incline_Curl/1.jpg\"]','Dumbbell_Prone_Incline_Curl',237) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion con mancuernas','traccion','principiante','compuesto','mancuerna','[\"hombros\"]','[\"biceps\"]','[\"Coge una mancuerna en cada brazo y ponte de pie con los brazos extendidos a los lados, con una ligera flexion en los codos y la espalda recta. Esta sera tu posicion inicial. Consejo: Las mancuernas deben estar junto a los muslos, con las palmas de las manos mirando hacia atras.\", \"Utiliza los hombros para levantar las mancuernas mientras exhalas. Las mancuernas deben estar al lado del cuerpo mientras las levantas. Continua levantandolas hasta que las mancuernas esten casi alineadas con tu barbilla. Consejo: Los codos deben impulsar el movimiento. Al levantar las mancuernas, el codo debe estar siempre mas alto que el antebrazo. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja las mancuernas lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Dumbbell_Raise/0.jpg\", \"Dumbbell_Raise/1.jpg\"]','Levantamiento con mancuernas',238) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancada trasera con mancuernas','empuje','intermedio','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie con el torso erguido sosteniendo dos mancuernas en tus manos a los lados. Esta sera tu posicion inicial.\", \"Da un paso atras con la pierna derecha a unos dos pies del pie izquierdo y baja la parte superior del cuerpo, mientras mantienes el torso erguido y el equilibrio. Inhala mientras bajas. Consejo: Al igual que en los otros ejercicios, no dejes que la rodilla se te vaya adelante mas alla de los dedos de los pies al bajar, ya que esto ejercera una tension excesiva en la articulacion de la rodilla. Asegurate de mantener la espinilla delantera perpendicular al suelo. Manten el torso erguido durante la zancada; es importante tener flexibles los flexores de la cadera. Una zancada larga enfatiza el gluteo mayor; una zancada corta enfatiza los cuadriceps.\", \"Empuja hacia arriba y vuelve a la posicion inicial mientras exhalas. Consejo: Utiliza la planta de los pies para empujar y acentuar los cuadriceps. Para centrarte en los gluteos, presiona con los talones.\", \"Ahora repite con la pierna opuesta.\"]','fuerza','[\"Dumbbell_Rear_Lunge/0.jpg\", \"Dumbbell_Rear_Lunge/1.jpg\"]','Zancada trasera con mancuernas',239) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones con mancuernas','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[\"trapecios\"]','[\"Este ejercicio correctivo fortalece los musculos que estabilizan el omoplato. Sosten un peso ligero en cada mano, colgando a los lados. Los pulgares deben apuntar hacia arriba.\", \"Comienza el movimiento levantando los brazos frente a ti, aproximadamente a 30 grados del centro. Los brazos deben estar completamente extendidos mientras realizas el movimiento.\", \"Continua hasta que los brazos esten paralelos al suelo y luego vuelve a la posicion inicial.\"]','fuerza','[\"Dumbbell_Scaption/0.jpg\", \"Dumbbell_Scaption/1.jpg\"]','Dumbbell_Scaption',240) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentado con mancuernas y salto sobre caja','empuje','intermedio','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Coloca una caja a un par de pies al lado de un banco. Sujeta una mancuerna contra tu pecho con ambas manos y sientate en el banco mirando hacia la caja. Esta sera tu posicion inicial.\", \"Planta los pies firmemente en el suelo mientras te inclinas hacia delante, extendiendo las caderas y las rodillas para saltar hacia arriba y hacia delante.\", \"Aterriza en la caja con ambos pies, absorbiendo el impacto al permitir que las caderas y las rodillas se doblen.\", \"Baja y vuelve a la posicion inicial.\"]','pliometria','[\"Dumbbell_Seated_Box_Jump/0.jpg\", \"Dumbbell_Seated_Box_Jump/1.jpg\"]','Salto con mancuernas sentado en caja',241) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de pantorrilla con mancuernas sentado a una pierna','empuje','principiante','aislamiento','mancuerna','[\"pantorrillas\"]','[]','[\"Coloca un bloque en el suelo a unos 30 cm de un banco plano.\", \"Sientate en un banco plano y coloca una mancuerna en la parte superior del muslo izquierdo, unos 7,5 cm por encima de la rodilla.\", \"Ahora coloca la planta del pie izquierdo sobre el bloque. Esta sera tu posicion inicial.\", \"Levanta los dedos de los pies lo mas alto posible mientras exhalas y contraes el musculo de la pantorrilla. Manten la contraccion durante un segundo.\", \"Vuelve lentamente a la posicion inicial, estirandote lo mas abajo posible.\", \"Repite durante el numero de repeticiones prescrito y luego repite con la pierna derecha.\"]','fuerza','[\"Dumbbell_Seated_One-Leg_Calf_Raise/0.jpg\", \"Dumbbell_Seated_One-Leg_Calf_Raise/1.jpg\"]','Elevacion de pantorrillas con mancuernas sentado a una pierna',242) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de hombros con mancuernas','empuje','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Mientras sostienes una mancuerna en cada mano, sientate en un banco de press militar o en un banco utilitario que tenga respaldo. Coloca las mancuernas erguidas sobre tus muslos.\", \"Ahora levanta las mancuernas a la altura de los hombros, una a la vez, utilizando tus muslos para ayudarte a impulsarlas hacia arriba hasta su posicion.\", \"Asegurate de girar tus muñecas de modo que las palmas de tus manos queden mirando hacia adelante. Esta es tu posicion inicial.\", \"Ahora, exhala y empuja las mancuernas hacia arriba hasta que toquen en la parte superior.\", \"Luego, despues de una breve pausa en la parte superior en posicion contraida, baja lentamente las pesas hacia atras hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Shoulder_Press/0.jpg\", \"Dumbbell_Shoulder_Press/1.jpg\"]','Press de hombros con mancuernas',243) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros con mancuernas','traccion','principiante','aislamiento','mancuerna','[\"trapecios\"]','[]','[\"Ponte de pie con una mancuerna en cada mano (las palmas mirando hacia tu torso), los brazos extendidos a los lados.\", \"Eleva las mancuernas elevando los hombros lo mas alto posible mientras exhalas. Manten la contraccion en la parte superior durante un segundo. Consejo: Los brazos deben permanecer extendidos en todo momento. Evita utilizar los biceps para ayudar a levantar las mancuernas. Solo los hombros deben moverse hacia arriba y hacia abajo.\", \"Baja las mancuernas hasta la posicion original.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Shrug/0.jpg\", \"Dumbbell_Shrug/1.jpg\"]','Encogimiento de hombros con mancuernas',244) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con mancuernas','empuje','principiante','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Ponte de pie recto mientras sostienes una mancuerna en cada mano (las palmas mirando hacia el lado de tus piernas).\", \"Coloca tus piernas con una postura media a la altura de los hombros y los dedos de los pies ligeramente apuntando hacia fuera. Manten la cabeza arriba en todo momento, ya que mirar hacia abajo te hara perder el equilibrio, y manten tambien la espalda recta. Esta sera tu posicion inicial. Nota: Para los fines de esta discusion, utilizaremos la postura media descrita anteriormente, que se centra en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas descritas en la seccion de posturas de los pies.\", \"Comienza a bajar lentamente el torso doblando las rodillas mientras mantienes una postura recta con la cabeza levantada. Continua bajando hasta que tus muslos esten paralelos al suelo. Consejo: Si has realizado el ejercicio correctamente, la parte delantera de las rodillas debe formar una linea recta imaginaria con los dedos de los pies, que es perpendicular a la parte delantera. Si tus rodillas estan mas alla de esa linea imaginaria (si estan mas alla de los dedos de los pies), entonces estas ejerciendo una tension excesiva sobre la rodilla y el ejercicio se ha realizado incorrectamente.\", \"Comienza a levantar el torso mientras exhalas empujando el suelo con el talon del pie principalmente, a medida que enderezas las piernas de nuevo y vuelves la espalda a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Squat/0.jpg\", \"Dumbbell_Squat/1.jpg\"]','Sentadilla con mancuernas',246) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con mancuernas en un banco','empuje','intermedio','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Ponte de pie recto con un banco plano detras de ti mientras sostienes una mancuerna en cada mano (las palmas mirando hacia el lado de tus piernas).\", \"Coloca tus piernas con una postura media a la anchura de los hombros con los dedos de los pies ligeramente apuntando hacia fuera. Manten la cabeza arriba en todo momento, ya que mirar hacia abajo te hara perder el equilibrio, y manten tambien la espalda recta. Esta sera tu posicion inicial. Nota: Para los fines de esta discusion, utilizaremos la postura media descrita anteriormente, que se centra en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas descritas en la seccion de posturas de los pies.\", \"Comienza a bajar lentamente el torso doblando las rodillas mientras mantienes una postura recta con la cabeza arriba. Continua bajando hasta que toques ligeramente el banco detras de ti. Inhala mientras realizas esta parte del movimiento. Consejo: Si has realizado el ejercicio correctamente, la parte delantera de las rodillas debe formar una linea recta imaginaria con los dedos de los pies, perpendicular a la parte delantera. Si tus rodillas estan mas alla de esa linea imaginaria (si estan mas alla de los dedos de los pies), entonces estas ejerciendo una tension excesiva sobre la rodilla y el ejercicio se ha realizado incorrectamente.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo con el talon del pie principalmente, a medida que enderezas las piernas de nuevo y vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Dumbbell_Squat_To_A_Bench/0.jpg\", \"Dumbbell_Squat_To_A_Bench/1.jpg\"]','Sentadilla con mancuernas en banco',247) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Step ups con mancuernas','empuje','intermedio','compuesto','mancuerna','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie recto mientras sostienes una mancuerna en cada mano (las palmas mirando hacia el lado de tus piernas).\", \"Coloca el pie derecho en la plataforma elevada. Sube a la plataforma extendiendo la cadera y la rodilla de tu pierna derecha. Utiliza principalmente el talon para levantar el resto de tu cuerpo y coloca tambien el pie de la pierna izquierda en la plataforma. Exhala mientras ejecutas la fuerza necesaria para subir.\", \"Baja con la pierna izquierda flexionando la cadera y la rodilla de la pierna derecha mientras inhalas. Vuelve a la posicion original de pie colocando el pie derecho junto al pie izquierdo en la posicion inicial.\", \"Repite con la pierna derecha durante el numero recomendado de repeticiones y luego realiza con la pierna izquierda.\"]','fuerza','[\"Dumbbell_Step_Ups/0.jpg\", \"Dumbbell_Step_Ups/1.jpg\"]','Step con mancuernas',248) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuernas - Agarre pronado','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Acuestate boca arriba en un banco plano sosteniendo dos mancuernas directamente sobre tus hombros. Tus brazos deben estar completamente extendidos y formar un angulo de 90 grados con respecto a tu torso y el suelo.\", \"Las palmas de tus manos deben estar mirando hacia adelante y tus codos deben estar pegados al cuerpo. Esta sera tu posicion inicial.\", \"Ahora, inhala y baja lentamente las mancuernas hasta que esten cerca de tus oidos. Asegurate de mantener la parte superior de los brazos fija y los codos pegados al cuerpo.\", \"A continuacion, exhala y utiliza los triceps para devolver el peso a la posicion inicial.\"]','fuerza','[\"Dumbbell_Tricep_Extension_-Pronated_Grip/0.jpg\", \"Dumbbell_Tricep_Extension_-Pronated_Grip/1.jpg\"]','Extension de triceps con mancuernas - Agarre pronado',249) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento dinamico de espalda','traccion','principiante','Ninguno','Ninguno','[\"dorsales\"]','[]','[\"Ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Manten los brazos rectos y balancealos hacia arriba frente a ti entre 5 y 10 veces, aumentando el rango de movimiento cada vez hasta que tus brazos esten por encima de tu cabeza.\"]','estiramiento','[\"Dynamic_Back_Stretch/0.jpg\", \"Dynamic_Back_Stretch/1.jpg\"]','Estiramiento dinamico de espalda',250) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento dinamico del pecho','traccion','principiante','Ninguno','Ninguno','[\"pecho\"]','[\"espalda_media\"]','[\"Ponte de pie con las manos juntas y los brazos extendidos directamente frente a ti. Esta sera tu posicion inicial.\", \"Manten los brazos rectos y muevelos rapidamente hacia atras lo mas lejos posible y vuelve a colocarlos delante, como si estuvieras aplaudiendo de forma exagerada. Repite el movimiento entre 5 y 10 veces, aumentando la velocidad a medida que lo haces.\"]','estiramiento','[\"Dynamic_Chest_Stretch/0.jpg\", \"Dynamic_Chest_Stretch/1.jpg\"]','Estiramiento dinamico del pecho',251) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos con los codos','traccion','principiante','aislamiento','Ninguno','[\"hombros\"]','[\"trapecios\"]','[\"Sientate o ponte de pie con los pies ligeramente separados.\", \"Coloca las manos sobre los hombros con los codos a la altura de los hombros y apuntando hacia fuera.\", \"Haz lentamente un circulo con los codos. Exhala al comenzar el circulo e inhala al completarlo.\"]','estiramiento','[\"Elbow_Circles/0.jpg\", \"Elbow_Circles/1.jpg\"]','Circulos con los codos',252) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Codo a rodilla','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Tumbate en el suelo, cruzando la pierna derecha sobre la rodilla izquierda doblada. Entrelaza las manos detras de la cabeza, comenzando con los omoplatos en el suelo. Esta sera tu posicion inicial.\", \"Realiza el movimiento flexionando la columna y girando el torso para llevar el codo izquierdo a la rodilla derecha.\", \"Vuelve a la posicion inicial y repite el movimiento durante el numero deseado de repeticiones antes de cambiar de lado.\"]','fuerza','[\"Elbow_to_Knee/0.jpg\", \"Elbow_to_Knee/1.jpg\"]','Codo_a_rodilla',253) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Codos hacia atras','estatico','principiante','aislamiento','Ninguno','[\"pecho\"]','[\"hombros\"]','[\"Ponte de pie recto.\", \"Coloca ambas manos en la parte baja de la espalda, con los dedos apuntando hacia abajo y los codos hacia fuera.\", \"A continuacion, tira suavemente de los codos hacia atras con el objetivo de juntarlos.\"]','estiramiento','[\"Codos_hacia_atras/0.jpg\", \"Codos_hacia_atras/1.jpg\"]','Codos hacia atras',254) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo elevado en polea','traccion','intermedio','compuesto','polea','[\"dorsales\"]','[\"espalda_media\", \"trapecios\"]','[\"Consigue una plataforma de algun tipo (puede ser una plataforma de aerobic o de elevacion de pantorrillas) que tenga una altura de entre 4 y 6 pulgadas.\", \"Colocala en el asiento de la maquina de remo con polea.\", \"Sientate en la maquina y coloca los pies en la plataforma delantera o en la barra transversal que se proporciona, asegurandote de que tus rodillas esten ligeramente flexionadas y no bloqueadas.\", \"Inclinate hacia delante manteniendo la alineacion natural de la espalda y agarra las asas de la barra en V.\", \"Con los brazos extendidos, tira de la espalda hasta que el torso forme un angulo de 90 grados con las piernas. La espalda debe estar ligeramente arqueada y el pecho debe sobresalir. Debes sentir un buen estiramiento en los dorsales mientras mantienes la barra frente a ti. Esta es la posicion inicial del ejercicio.\", \"Manteniendo el torso inmovil, tira de las asas hacia tu torso mientras mantienes los brazos cerca de el hasta que toques los abdominales. Exhala mientras realizas ese movimiento. En ese momento, debes apretar con fuerza los musculos de la espalda. Manten esa contraccion durante un segundo y vuelve lentamente a la posicion original mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Elevated_Cable_Rows/0.jpg\", \"Elevated_Cable_Rows/1.jpg\"]','Remo con cable elevado',256) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Eliptica','Ninguno','intermedio','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, subete a la eliptica y selecciona la opcion deseada en el menu. La mayoria de las elipticas tienen un ajuste manual, o puedes seleccionar un programa para ejecutar. Por lo general, puedes introducir tu edad y peso para estimar la cantidad de calorias quemadas durante el ejercicio. La elevacion se puede ajustar para cambiar la intensidad del entrenamiento.\", \"Las asas se pueden utilizar para controlar tu frecuencia cardiaca y ayudarte a mantener una intensidad adecuada.\"]','cardio','[\"Elliptical_Trainer/0.jpg\", \"Elliptical_Trainer/1.jpg\"]','Entrenador eliptico',257) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales con pelota de ejercicio','traccion','principiante','aislamiento','fitball','[\"abdominales\"]','[]','[\"Acuestese en una pelota de ejercicio con la curvatura inferior de la espalda presionada contra la superficie esferica de la pelota. Las piernas deben estar dobladas por las rodillas y presionadas firmemente contra el suelo. La parte superior del torso debe quedar colgando de la parte superior de la pelota. Los brazos deben mantenerse a lo largo del cuerpo o cruzados sobre el pecho, ya que estas posiciones evitan tensiones en el cuello (a diferencia de la posicion con las manos detras de la espalda o la cabeza).\", \"Baja el torso hasta una posicion de estiramiento manteniendo el cuello inmovil en todo momento. Esta sera tu posicion inicial.\", \"Con las caderas inmoviles, flexiona la cintura contrayendo los abdominales y encoge los hombros y el tronco hacia arriba hasta que sientas una agradable contraccion en los abdominales. Los brazos deben deslizarse simplemente por el lado de las piernas si los tienes a los lados o simplemente permanecer sobre el pecho si los tienes cruzados. La parte inferior de la espalda debe permanecer siempre en contacto con la pelota. Exhala mientras realizas este movimiento y manten la contraccion durante un segundo.\", \"Mientras inhalas, vuelve la espalda a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Exercise_Ball_Crunch/0.jpg\", \"Exercise_Ball_Crunch/1.jpg\"]','Abdominales con pelota de ejercicio',258) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extended Range One-Arm con Pesa Rusa Floor Press','empuje','principiante','compuesto','pesas rusas','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate en el suelo y coloca una pesa rusa en uno de los brazos para hacer press. La pesa rusa debe sujetarse por el asa. La pierna del mismo lado que estas haciendo press debe estar flexionada, con la rodilla cruzando la linea media del cuerpo.\", \"Presiona la pesa rusa extendiendo el codo y aduyendo el brazo, presionandola por encima de tu cuerpo. Vuelve a la posicion inicial.\"]','fuerza','[\"Extended_Range_One-Arm_Kettlebell_Floor_Press/0.jpg\", \"Extended_Range_One-Arm_Kettlebell_Floor_Press/1.jpg\"]','Press de suelo con kettlebell a un brazo con rango extendido',260) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rotacion externa con banda','traccion','principiante','compuesto','bandas','[\"hombros\"]','[]','[\"Ata la banda alrededor de un poste. La banda debe estar a la misma altura que tu codo. Ponte de pie con tu lado izquierdo a un par de pies de distancia de la banda.\", \"Agarra el extremo de la banda con tu mano derecha y manten el codo firmemente pegado al costado. Te recomendamos que mantengas una almohadilla o un rodillo de espuma en su lugar con el codo para mantenerlo firmemente en su posicion.\", \"Con la parte superior del brazo en posicion, el codo debe estar flexionado a 90 grados con la mano cruzando la parte delantera del torso. Esta sera la posicion inicial.\", \"Ejecuta el movimiento girando el brazo con un movimiento de reves, manteniendo el codo en su sitio.\", \"Continua todo lo que puedas, haz una pausa y luego vuelve a la posicion inicial.\"]','fuerza','[\"Rotacion_externa_con_banda/0.jpg\", \"Rotacion_externa_con_banda/1.jpg\"]','Rotacion externa con banda',262) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rotacion externa con cable','traccion','principiante','aislamiento','polea','[\"hombros\"]','[]','[\"Ajusta la polea a la misma altura que tu codo. Ponte de pie con tu lado izquierdo hacia la banda, a un par de pies de distancia.\", \"Agarra el mango con tu mano derecha y manten el codo firmemente pegado al costado. Te recomendamos que mantengas una almohadilla o un rodillo de espuma en su lugar con el codo para mantenerlo firmemente en su posicion.\", \"Con la parte superior del brazo en posicion, el codo debe estar flexionado a 90 grados con la mano cruzando la parte delantera del torso. Esta sera tu posicion inicial.\", \"Ejecuta el movimiento girando el brazo con un movimiento de reves, manteniendo el codo en su lugar.\"]','fuerza','[\"Rotacion_externa_con_cable/0.jpg\", \"Rotacion_externa_con_cable/1.jpg\"]','Rotacion externa con cable',263) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con barra EZ','traccion','principiante','aislamiento','barra_ez','[\"biceps\"]','[]','[\"Ponte de pie recto mientras sostienes una barra EZ por el mango exterior ancho. Las palmas de tus manos deben estar mirando hacia delante y ligeramente inclinadas hacia dentro debido a la forma de la barra. Manten tus codos cerca de tu torso. Esta sera tu posicion inicial.\", \"Ahora, mientras mantienes tus brazos superiores inmoviles, exhala y flexiona los pesos hacia delante mientras contraes los biceps. Concentrate solo en mover los antebrazos.\", \"Continua levantando el peso hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un momento y aprieta los biceps.\", \"Luego inhala y baja lentamente la barra hacia atras hasta la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"EZ-Bar_Curl/0.jpg\", \"EZ-Bar_Curl/1.jpg\"]','Curl con barra EZ',264) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('EZ-Bar Skullcrusher','empuje','principiante','aislamiento','barra_ez','[\"triceps\"]','[\"antebrazos\"]','[\"Con un agarre cerrado, levanta la barra EZ y mantenla con los codos hacia dentro mientras te tumbas en el banco. Tus brazos deben estar perpendiculares al suelo. Esta sera tu posicion inicial.\", \"Manteniendo la parte superior de los brazos fija, baja la barra permitiendo que los codos se flexionen. Inhala mientras realizas esta parte del movimiento. Haz una pausa una vez que la barra este directamente sobre la frente.\", \"Eleva la barra hasta la posicion inicial extendiendo los codos y exhalando.\", \"Repite.\"]','fuerza','[\"EZ-Bar_Skullcrusher/0.jpg\", \"EZ-Bar_Skullcrusher/1.jpg\"]','Skullcrusher con barra EZ',265) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Face Pull','traccion','intermedio','compuesto','polea','[\"hombros\"]','[\"espalda_media\"]','[\"De cara a una polea alta con una cuerda o dos asas, tira del peso directamente hacia tu cara, separando las manos mientras lo haces. Manten la parte superior de los brazos paralela al suelo.\"]','fuerza','[\"Face_Pull/0.jpg\", \"Face_Pull/1.jpg\"]','Traccion frontal',266) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Saltos rapidos','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza en una posicion relajada con una pierna ligeramente adelantada. Esta sera tu posicion inicial.\", \"Salta ejecutando un patron de pasos saltados de derecha-derecha-izquierda-izquierda, y asi sucesivamente, alternando adelante y atras.\", \"Realiza saltos rapidos manteniendo un contacto cercano con el suelo y reduciendo el tiempo en el aire, moviendote lo mas rapido posible.\"]','pliometria','[\"Saltos_rapidos/0.jpg\", \"Saltos_rapidos/1.jpg\"]','Saltos rapidos',268) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones de dedos','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Sujeta una barra con ambas manos y las palmas hacia arriba; las manos separadas aproximadamente a la anchura de los hombros.\", \"Coloca los pies planos en el suelo, a una distancia ligeramente superior a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Baja la barra lo mas lejos posible extendiendo los dedos. Deja que la barra ruede por las manos y cogela con la ultima articulacion de los dedos.\", \"Ahora flexiona la barra hacia arriba lo mas alto posible cerrando las manos mientras exhalas. Manten la contraccion en la parte superior.\"]','fuerza','[\"Finger_Curls/0.jpg\", \"Finger_Curls/1.jpg\"]','Flexiones de dedos',269) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca plano en polea','empuje','intermedio','aislamiento','polea','[\"pecho\"]','[]','[\"Coloca un banco plano entre dos poleas bajas de modo que, cuando te tumbes en el, tu pecho quede alineado con las poleas.\", \"Tumbate en el banco y manten los pies en el suelo.\", \"Pide a alguien que te entregue las asas en cada mano. Agarraras cada asa con las palmas hacia arriba.\", \"Extiende los brazos a los lados con una ligera flexion en los codos. Consejo: Manten esta flexion constante durante todo el movimiento. Tus brazos deben estar paralelos al suelo. Esta es tu posicion inicial.\", \"Ahora empieza a levantar los brazos en un movimiento semicircular directamente frente a ti, tirando de las poleas juntas hasta que ambas manos se encuentren en la parte superior del movimiento. Aprieta el pecho mientras realizas este movimiento y exhala durante el mismo. Ademas, manten la contraccion durante un segundo en la parte superior. Consejo: Cuando se realiza correctamente, en la posicion superior de este movimiento, tus brazos deben estar perpendiculares a tu torso y al suelo, tocando por encima de tu pecho.\", \"Vuelve lentamente a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Flat_Bench_Cable_Flyes/0.jpg\", \"Flat_Bench_Cable_Flyes/1.jpg\"]','Press de banca plano con poleas',270) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flat Bench Pierna Pull-In','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en una colchoneta de ejercicios o en un banco plano con las piernas fuera del extremo.\", \"Coloca tus manos debajo de los gluteos con las palmas hacia abajo o a los lados sosteniendote en el banco (o con las palmas hacia abajo a los lados en una colchoneta de ejercicios). Extiende tambien las piernas rectas. Esta sera tu posicion inicial.\", \"Dobla las rodillas y lleva la parte superior de los muslos hacia el abdomen mientras exhalas. Continua este movimiento hasta que las rodillas esten cerca del pecho. Manten la posicion contraida durante un segundo.\", \"Mientras inhalas, vuelve lentamente a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Flat_Bench_Leg_Pull-In/0.jpg\", \"Flat_Bench_Leg_Pull-In/1.jpg\"]','Traccion de piernas en banco plano',271) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de piernas en banco plano','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate con la espalda plana en un banco y las piernas extendidas frente a ti, fuera del extremo.\", \"Coloca las manos debajo de los gluteos con las palmas hacia abajo o a los lados, sujetandote al banco. Esta sera tu posicion inicial.\", \"Mientras mantienes las piernas extendidas, lo mas rectas posible, con las rodillas ligeramente dobladas pero bloqueadas, levanta las piernas hasta que formen un angulo de 90 grados con el suelo. Exhala mientras realizas esta parte del movimiento y manten la contraccion en la parte superior durante un segundo.\", \"Ahora, mientras inhalas, baja lentamente tus piernas hacia atras hasta la posicion inicial.\"]','fuerza','[\"Flat_Bench_Lying_Leg_Raise/0.jpg\", \"Flat_Bench_Lying_Leg_Raise/1.jpg\"]','Levantamiento de piernas tumbado en banco plano',272) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de gluteos y isquiotibiales en el suelo','traccion','intermedio','aislamiento','Ninguno','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Puedes usar un compañero durante este ejercicio o sujetar tus pies debajo de algo estable.\", \"Comienza en tus rodillas con tus piernas y torso erguidos. Si usas un compañero, el mantendra firmemente tus pies para mantenerte en posicion. Esta sera tu posicion inicial.\", \"Baja tuself por extending at the knee, taking care to NOT flex the caderas as you ve forward.\", \"Coloca tus manos frente a you as you reach the floor. This movimiento es very difficult y you may be unable to do it unaided. Use tus brazos to lightly push off the suelo to aid your return to the inicial position.\"]','fuerza','[\"Floor_Glute-Ham_Raise/0.jpg\", \"Floor_Glute-Ham_Raise/1.jpg\"]','Levantamiento de gluteos y isquiotibiales en el suelo',274) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press en el suelo','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Ajusta los ganchos en J para que esten a la altura adecuada para colocar la barra. Empieza tumbado en el suelo con la cabeza cerca del extremo de una jaula de potencia. Manten los omoplatos juntos y saca la barra de los ganchos.\", \"Baja la barra hacia la parte inferior del pecho o la parte superior del estomago, apretando la barra e intentando separarla mientras lo haces. Asegurate de mantener los codos pegados al cuerpo durante todo el movimiento. Baja la barra hasta que la parte superior de tus brazos toque el suelo y haz una pausa, evitando cualquier golpe o rebote del peso.\", \"Presiona la barra hacia arriba tan rapido como puedas, manteniendo la barra, tus muñecas y codos alineados mientras lo haces.\"]','levantamiento de pesas','[\"Floor_Press/0.jpg\", \"Floor_Press/1.jpg\"]','Press de suelo',275) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press en el suelo con cadenas','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Ajusta los ganchos en J para que esten a la altura adecuada para colocar la barra. Para este ejercicio, coloca las cadenas directamente sobre el extremo de la barra, tratando de mantener los extremos alejados de las placas.\", \"Comienza acostado en el suelo con la cabeza cerca del extremo de una jaula de potencia. Manten los omoplatos juntos y saca la barra de los ganchos.\", \"Baja la barra hacia la parte inferior del pecho o la parte superior del estomago, apretando la barra e intentando separarla mientras lo haces. Asegurate de mantener los codos pegados al cuerpo durante todo el movimiento. Baja la barra hasta que la parte superior de tus brazos toque el suelo y haz una pausa, evitando cualquier golpe o rebote del peso.\", \"Presiona la barra hacia arriba lo mas rapido que puedas, manteniendo la barra, tus muñecas y codos alineados mientras lo haces.\"]','levantamiento de pesas','[\"Floor_Press_with_Chains/0.jpg\", \"Floor_Press_with_Chains/1.jpg\"]','Press de suelo con cadenas',276) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pies-SMR','estatico','intermedio','Ninguno','otro','[\"pantorrillas\"]','[]','[\"Este ejercicio estira la fascia de los musculos de los pies. Comience sentado y sin zapatos. Con un rodillo para pies o un objeto similar, como un pequeño trozo de tubo de PVC, coloque el pie contra el rodillo a lo largo del arco del pie. Esta sera su posicion inicial.\", \"Presione hacia abajo con firmeza, rodando a lo largo del arco del pie. Mantenga la posicion durante 10-30 segundos y luego cambie de pie.\"]','estiramiento','[\"Foot-SMR/0.jpg\", \"Foot-SMR/1.jpg\"]','Pies-SMR',278) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrastre hacia delante con presion','empuje','intermedio','compuesto','otro','[\"pecho\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\", \"hombros\", \"triceps\"]','[\"Fija una cadena o cuerda con dos asas al trineo. Debes estar de espaldas al trineo, sosteniendo un asa en cada mano.\", \"Comienza el movimiento avanzando un paso. Inclinate hacia delante, extiende las piernas y las caderas para moverte, deteniendote en cada paso para extender los codos y presionando las manos hacia delante. Da un paso hacia delante hasta volver a la posicion inicial, preparado para presionar.\"]','hombre_fuerte','[\"Forward_Drag_with_Press/0.jpg\", \"Forward_Drag_with_Press/1.jpg\"]','Arrastre hacia delante con press',279) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con salto a mano alzada','empuje','intermedio','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Cruza los brazos sobre el pecho.\", \"Con la cabeza arriba y la espalda recta, coloca los pies a la anchura de los hombros.\", \"Manteniendo la espalda recta y el pecho arriba, haz una sentadilla mientras inhalas hasta que tus muslos superiores esten paralelos al suelo, o mas bajos.\", \"Ahora, presionando principalmente con la planta de los pies, salta recto hacia arriba en el aire lo mas alto posible, utilizando los muslos como resortes. Exhala durante esta parte del movimiento.\", \"Cuando vuelvas a tocar el suelo, haz inmediatamente una sentadilla y salta de nuevo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Freehand_Jump_Squat/0.jpg\", \"Freehand_Jump_Squat/1.jpg\"]','Salto en cuclillas sin pesas',281) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Saltos de rana','empuje','intermedio','compuesto','Ninguno','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie con las manos detras de la cabeza y haz una sentadilla manteniendo el torso erguido y la cabeza levantada. Esta sera tu posicion inicial.\", \"Salta varios metros hacia delante, evitando saltar innecesariamente alto. Cuando tus pies toquen el suelo, absorbe el impacto con las piernas y vuelve a saltar. Repite este movimiento entre 5 y 10 veces.\"]','estiramiento','[\"Saltos_de_rana/0.jpg\", \"Saltos_de_rana/1.jpg\"]','Saltos de rana',282) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales de rana','traccion','intermedio','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate con la espalda plana en el suelo (o en una colchoneta de ejercicios) y las piernas extendidas frente a ti.\", \"Ahora dobla las rodillas y coloca los muslos externos en el suelo (o en la colchoneta) mientras haces que las plantas de los pies se toquen entre si.\", \"Ahora intenta empujando ambos pies y llevandolos arriba lo mas cerca posible de ti mientras mantienes los muslos externos en el suelo (o al menos casi tocandolo). Consejo: En esta posicion tus piernas deben crear una forma de diamante.\", \"Ahora, cruza tus brazos frente a ti tocando los hombros opuestos. Esta sera tu posicion inicial.\", \"Mientras exhalas, aplana la parte inferior de la espalda contra el suelo mientras curvas el torso hacia arriba. Consejo: Esto sera como realizar el primer cuarto de movimiento de una sentadilla. Manten la posicion superior durante un segundo.\", \"Mientras inhalas, baja lentamente la espalda a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Frog_Sit-Ups/0.jpg\", \"Frog_Sit-Ups/1.jpg\"]','Abdominales de rana',283) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Front con Barra Sentadilla','empuje','experto','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Este ejercicio se realiza mejor dentro de una jaula de sentadillas por motivos de seguridad. Para comenzar, primero coloca la barra en la jaula que mejor se adapte a tu altura. Una vez elegida la altura correcta y cargada la barra, lleva los brazos hacia arriba por debajo de la barra mientras mantienes los codos altos y la parte superior del brazo ligeramente por encima del paralelo al suelo. Apoya la barra sobre los deltoides y cruza los brazos mientras agarras la barra con control total.\", \"Eleva la barra del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso.\", \"Alejate del soporte y coloca las piernas con una postura media, a la anchura de los hombros, con los dedos de los pies ligeramente apuntando hacia fuera. Manten la cabeza arriba en todo momento, ya que mirar hacia abajo te hara perder el equilibrio, y manten tambien la espalda recta. Esta sera tu posicion inicial. (Nota: A efectos de esta explicacion, utilizaremos la postura media descrita anteriormente, que se centra en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas descritas en la seccion de posicionamiento de los pies).\", \"Comienza a bajar lentamente la barra doblando las rodillas mientras mantienes una postura recta con la cabeza arriba. Continua bajando hasta que el angulo entre la parte superior de la pierna y las pantorrillas sea ligeramente inferior a 90 grados (que es el punto en el que la parte superior de las piernas esta por debajo de la paralela al suelo). Inhala mientras realizas esta parte del movimiento. Consejo: Si has realizado el ejercicio correctamente, la parte delantera de las rodillas debe formar una linea recta imaginaria con los dedos de los pies que sea perpendicular a la parte delantera. Si tus rodillas estan mas alla de esa linea imaginaria (si estan mas alla de los dedos de los pies), entonces estas ejerciendo una tension excesiva sobre la rodilla y el ejercicio se ha realizado incorrectamente.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con la parte media del pie mientras enderezas las piernas de nuevo y vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Front_Barbell_Squat/0.jpg\", \"Front_Barbell_Squat/1.jpg\"]','Frontal_con_barra_en_banco',284) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Front con Barra Sentadilla To A Bench','empuje','experto','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Este ejercicio se realiza mejor dentro de una jaula de sentadillas por motivos de seguridad. Para comenzar, primero coloca un banco plano detras de ti y coloca la barra en una jaula que se adapte mejor a tu altura. Una vez elegida la altura correcta y cargada la barra, lleva los brazos hacia arriba por debajo de la barra mientras mantienes los codos altos y la parte superior del brazo ligeramente por encima del paralelo al suelo. Apoya la barra en la parte superior de los deltoides y cruza los brazos mientras agarras la barra con control total.\", \"Eleva la barra del soporte empujando primero con las piernas y, al mismo tiempo, enderezando el torso.\", \"Alejate del soporte y coloca las piernas con una postura media, a la anchura de los hombros, con los dedos de los pies ligeramente apuntando hacia fuera. Manten la cabeza arriba en todo momento, ya que mirar hacia abajo te hara perder el equilibrio, y manten tambien la espalda recta. Esta sera tu posicion inicial. (Nota: A efectos de esta explicacion, utilizaremos la postura media descrita anteriormente, que se centra en el desarrollo general; sin embargo, puedes elegir cualquiera de las tres posturas descritas en la seccion de posicionamiento de los pies).\", \"Comienza a bajar lentamente la barra doblando las rodillas mientras mantienes una postura recta con la cabeza arriba. Continua bajando hasta que tus gluteos toquen el banco. Inhala mientras realizas esta parte del movimiento. Consejo: Si has realizado el ejercicio correctamente, la parte delantera de las rodillas debe formar una linea recta imaginaria con los dedos de los pies, perpendicular a la parte delantera. Si tus rodillas estan mas alla de esa linea imaginaria (si estan mas alla de los dedos de los pies), entonces estas ejerciendo una tension excesiva sobre las rodillas y el ejercicio se ha realizado incorrectamente.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con el talon del pie mientras enderezas las piernas de nuevo y vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Front_Barbell_Squat_To_A_Bench/0.jpg\", \"Front_Barbell_Squat_To_A_Bench/1.jpg\"]','Frontal con barra a banco',285) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto frontal sobre caja','empuje','principiante','compuesto','otro','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"cuadriceps\"]','[\"Comienza con una caja de una altura adecuada a 1-2 pies frente a ti. Ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Realiza una sentadilla corta como preparacion para el salto, balanceando los brazos hacia atras.\", \"Rebota desde esta posicion, extendiendo las caderas, las rodillas y los tobillos para saltar lo mas alto posible. Balancea los brazos hacia delante y hacia arriba.\", \"Aterriza en la caja con las rodillas flexionadas, absorbiendo el impacto con las piernas. Puedes saltar desde la caja hacia atras al suelo, o preferiblemente bajar un pie a la vez.\"]','pliometria','[\"Front_Box_Jump/0.jpg\", \"Front_Box_Jump/1.jpg\"]','Salto frontal sobre caja',286) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Saltos frontales con conos (o saltos de vallas)','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Coloca una fila de conos u otras barreras pequeñas, separandolos unos pocos centimetros entre si.\", \"Ponte de pie frente al primer cono con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Comienza saltando con ambos pies sobre el primer cono, balanceando ambos brazos mientras saltas.\", \"Absorbe el impacto del aterrizaje flexionando las rodillas, rebotando del primer salto para saltar sobre el siguiente cono.\", \"Continua hasta que hayas saltado sobre todos los conos.\"]','pliometria','[\"Front_Cone_Hops_or_hurdle_hops/0.jpg\", \"Front_Cone_Hops_or_hurdle_hops/1.jpg\"]','Saltos frontales sobre conos o saltos de vallas',288) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion frontal inclinada con mancuernas','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Sientate en un banco inclinado con la inclinacion ajustada entre 30 y 60 grados mientras sostienes una mancuerna en cada mano. Consejo: Puedes cambiar el angulo para trabajar el musculo de forma ligeramente diferente cada vez.\", \"Extiende los brazos rectos frente a ti y manten las palmas hacia abajo con las mancuernas levantadas aproximadamente 1 pulgada por encima de los muslos. Esta sera tu posicion inicial.\", \"Levanta lentamente las mancuernas rectas hacia arriba hasta que esten ligeramente por encima de los hombros, mientras mantienes los codos bloqueados. Aprieta en la parte superior durante un segundo y asegurate de exhalar durante esta parte del movimiento. Consejo: Manten la cabeza apoyada contra el banco y las piernas en el suelo en todo momento.\", \"Baja los brazos hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Front_Incline_Dumbbell_Raise/0.jpg\", \"Front_Incline_Dumbbell_Raise/1.jpg\"]','Elevacion frontal inclinada con mancuernas',290) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones frontales con piernas','traccion','principiante','Ninguno','solo_cuerpo','[\"isquiotibiales\"]','[]','[\"Pongase de pie junto a una silla u otro soporte, sosteniendolo con una mano.\", \"Balancee la pierna hacia delante, manteniendo la pierna recta. Continue con un balanceo hacia abajo, llevando la pierna tan atras como le permita su flexibilidad. Repita entre 5 y 10 veces y luego cambie de pierna.\"]','estiramiento','[\"Front_Leg_Raises/0.jpg\", \"Front_Leg_Raises/1.jpg\"]','Elevaciones frontales de piernas',291) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion frontal y pullover','traccion','principiante','compuesto','barra','[\"pecho\"]','[\"dorsales\", \"hombros\", \"triceps\"]','[\"Acuestate en un banco plano mientras sostienes una barra con las palmas hacia abajo y separadas aproximadamente 15 pulgadas.\", \"Coloca la barra en la parte superior de los muslos, extiende los brazos y bloquealos mientras mantienes una ligera flexion en los codos. Esta sera tu posicion inicial.\", \"Ahora levanta el peso con un movimiento semicircular y manteniendo los brazos rectos mientras inhalas. Continua con el mismo movimiento hasta que la barra este al otro lado, por encima de tu cabeza. (Consejo: la barra recorrera aproximadamente 180 grados). En este punto, tus brazos deben estar paralelos al suelo, con las palmas de las manos mirando hacia el techo.\", \"Ahora vuelve a colocar la barra en la posicion inicial invirtiendo el movimiento mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Front_Raise_And_Pullover/0.jpg\", \"Front_Raise_And_Pullover/1.jpg\"]','Elevacion frontal y pullover',293) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla frontal (agarre limpio)','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"abdominales\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, primero coloca la barra en un soporte ligeramente por debajo del nivel de los hombros. Apoya la barra en la parte superior de los deltoides, empujando hacia las claviculas y tocando ligeramente la garganta. Tus manos deben estar en un agarre limpio, tocando la barra solo con los dedos para ayudar a mantenerla en su posicion.\", \"Eleva la barra del soporte empujando primero con las piernas y al mismo tiempo enderezando el torso. Alejate del soporte y coloca tus piernas en una postura media, con los pies separados a la anchura de los hombros y los dedos ligeramente apuntando hacia fuera. Manten la cabeza y los codos arriba en todo momento. Esta sera tu posicion inicial.\", \"Dobla las rodillas, sentandote entre tus piernas. Continua bajando hasta que tus isquiotibiales esten en tus pantorrillas. Manten tus rodillas alineadas con tus pies utilizando conscientemente tus abductores para empujar tus rodillas hacia fuera mientras te pones en cuclillas.\", \"Comienza a levantar la barra mientras exhalas empujando el suelo principalmente con el talon o la parte media del pie mientras enderezas las piernas de nuevo y vuelves a la posicion inicial.\"]','fuerza','[\"Front_Squat_Clean_Grip/0.jpg\", \"Front_Squat_Clean_Grip/1.jpg\"]','Sentadilla frontal con agarre limpio',294) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadillas frontales con dos pesas rusas','empuje','intermedio','compuesto','pesas rusas','[\"cuadriceps\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Limpia dos pesas rusas a tus hombros. Limpia las pesas rusas a tus hombros extendiendo las piernas y las caderas mientras tiras de las pesas rusas hacia tus hombros. Gira las muñecas mientras lo haces.\", \"Mirando recto al frente en todo momento, haz una sentadilla tan baja como puedas y haz una pausa en la parte inferior. Mientras te agachas, empuja tus rodillas hacia fuera. Debes agacharte entre tus piernas, manteniendo el torso erguido, con la cabeza y el pecho hacia arriba.\", \"Levantate hacia atras impulsandote con los talones y repite.\"]','fuerza','[\"Front_Squats_With_Two_Kettlebells/0.jpg\", \"Front_Squats_With_Two_Kettlebells/1.jpg\"]','Sentadillas frontales con dos pesas rusas',295) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lat Pulldown con rango de movimiento completo','traccion','intermedio','compuesto','polea','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"De pie o sentado en un banco alto, agarra dos cables de estribo que estan unidos a las poleas altas. Agarralos con la mano opuesta, de modo que tus brazos queden cruzados aproximadamente y tus palmas miren hacia adelante.\", \"Manten el pecho arriba y un ligero arco en la parte baja de la espalda, y tira de las asas hacia abajo como si estuvieras haciendo un pulldown normal. El rango de movimiento sera mas bien un arco. Durante el movimiento, gira tus manos de modo que en la posicion inferior tus palmas miren una hacia la otra en lugar de hacia adelante. Vuelve lentamente a la posicion inicial y repite.\"]','fuerza','[\"Full_Range-Of-Motion_Lat_Pulldown/0.jpg\", \"Full_Range-Of-Motion_Lat_Pulldown/1.jpg\"]','Traccion lateral con rango de movimiento completo',297) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominadas Gironda Sternum','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"biceps\", \"espalda_media\"]','[\"Agarra la barra de dominadas con un agarre por debajo de los hombros.\", \"Ahora cuelgate con los brazos completamente extendidos, saca el pecho y inclinate hacia atras. Consejo: Te inclinaras hacia atras durante todo el movimiento. Esta sera tu posicion inicial.\", \"Empieza tirando de ti mismo hacia la barra con la columna arqueada durante todo el movimiento y la cabeza inclinada hacia atras lo mas lejos posible de la barra. Exhala mientras realizas esta parte del movimiento. Consejo: En el extremo superior del movimiento, tus caderas y piernas estaran en un angulo de aproximadamente 45 grados con respecto al suelo.\", \"Sigue tirando hasta que tu clavicula pase la barra y la parte inferior de tu pecho o esternon la toque. Manten esa contraccion durante un segundo. Consejo: Cuando hayas completado esta parte del movimiento, tu cabeza estara paralela al suelo.\", \"Empieza a volver lentamente a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Gironda_Sternum_Chins/0.jpg\", \"Gironda_Sternum_Chins/1.jpg\"]','Dominadas Gironda en el esternon',298) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de gluteos y isquiotibiales','traccion','intermedio','compuesto','maquina','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Comienza ajustando el equipo a tu cuerpo. Coloca tus pies contra la plataforma entre los rodillos mientras te acuestas boca abajo. Tus rodillas deben quedar justo detras de la almohadilla.\", \"Comienza desde la parte inferior del movimiento. Manten la espalda arqueada mientras comienzas el movimiento flexionando las rodillas. Presiona los dedos de los pies contra la plataforma mientras lo haces. Manten la parte superior del cuerpo recta y continua hasta que tu cuerpo este erguido.\", \"Vuelve a la posicion inicial, manteniendo el descenso bajo control.\"]','levantamiento de pesas','[\"Glute_Ham_Raise/0.jpg\", \"Glute_Ham_Raise/1.jpg\"]','Elevaciones de gluteos y isquiotibiales',299) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con pesas','empuje','principiante','compuesto','pesas rusas','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"hombros\"]','[\"Ponte de pie sosteniendo una pesa rusa ligera por los cuernos cerca del pecho. Esta sera tu posicion inicial.\", \"Haz una sentadilla entre tus piernas hasta que tus isquiotibiales esten a la altura de tus pantorrillas. Manten el pecho y la cabeza arriba y la espalda recta.\", \"En la posicion inferior, haz una pausa y usa los codos para empujar las rodillas hacia fuera. Vuelve a la posicion inicial y repite durante 10-20 repeticiones.\"]','fuerza','[\"Goblet_Squat/0.jpg\", \"Goblet_Squat/1.jpg\"]','Sentadilla con copa',301) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Buenos dias','empuje','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"abdominales\", \"gluteos\", \"espalda_baja\"]','[\"Comienza con una barra en un soporte a la altura de los hombros. Coloca la barra sobre la parte posterior de los hombros, como si fueras a hacer una sentadilla de potencia, no sobre los hombros. Manten la espalda recta, los omoplatos juntos y las rodillas ligeramente flexionadas. Da un paso hacia atras desde el soporte.\", \"Comienza doblando las caderas, moviendolas hacia atras mientras te inclinas hasta quedar casi en paralelo. Manten la espalda arqueada y la columna cervical correctamente alineada.\", \"Invierte el movimiento extendiendo las caderas con los gluteos y los isquiotibiales. Continua hasta que hayas vuelto a la posicion inicial.\"]','levantamiento de pesas','[\"Good_Morning/0.jpg\", \"Good_Morning/1.jpg\"]','Buenos dias',302) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Buenos dias sin clavijas','empuje','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"abdominales\", \"gluteos\", \"espalda_baja\"]','[\"Comienza con una barra en un soporte a aproximadamente la misma altura que tu estomago. Inclinate debajo de la barra y coloca la barra en la parte posterior de tus hombros como lo harias en una sentadilla de potencia, no en la parte superior de tus hombros. A la altura adecuada, debes estar casi paralelo al suelo cuando te inclines. Manten la espalda recta, los omoplatos juntos y las rodillas ligeramente flexionadas. Manten la espalda arqueada y la columna cervical correctamente alineada.\", \"Comienza el movimiento extendiendo las caderas con los gluteos y los isquiotibiales, y te quedaras de pie con el peso. Baja lentamente el peso hacia los soportes y vuelve a la posicion inicial.\"]','levantamiento de pesas','[\"Good_Morning_off_Pins/0.jpg\", \"Good_Morning_off_Pins/1.jpg\"]','Buenos_dias_sin_pasadores',303) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Gorilla Chin/Crunch','traccion','intermedio','compuesto','solo_cuerpo','[\"abdominales\"]','[\"biceps\", \"dorsales\"]','[\"Cuelgate de una barra de dominadas con un agarre por debajo (las palmas mirando hacia ti) que sea ligeramente mas ancho que el ancho de los hombros.\", \"Ahora dobla tus rodillas en un angulo de 90 grados para que las pantorrillas esten paralelas al suelo mientras los muslos permanecen perpendiculares a el. Esta sera tu posicion inicial.\", \"Mientras exhalas, levantate mientras flexionas las rodillas al mismo tiempo hasta que tus rodillas esten al nivel del pecho. Deja de subir tan pronto como tu nariz este al mismo nivel que la barra. Consejo: Cuando llegues a este punto, tambien deberias estar terminando el crunch al mismo tiempo.\", \"Empieza a inhalar lentamente mientras vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Gorilla_Chin_Crunch/0.jpg\", \"Gorilla_Chin_Crunch/1.jpg\"]','Abdominales con barra',304) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de ingle y espalda','estatico','intermedio','compuesto','Ninguno','[\"aductores\"]','[]','[\"Sientate en el suelo con las rodillas dobladas y los pies juntos.\", \"Entrelaza los dedos detras de la cabeza. Esta sera tu posicion inicial.\", \"Curva el cuerpo hacia abajo, llevando los codos hacia la parte interior de los muslos. Tras una breve pausa, vuelve a la posicion inicial con la cabeza arriba y la espalda recta. Repite entre 10 y 20 repeticiones.\"]','estiramiento','[\"Groin_and_Back_Stretch/0.jpg\", \"Groin_and_Back_Stretch/1.jpg\"]','Estiramiento de ingle y espalda',305) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Groiners','traccion','intermedio','compuesto','solo_cuerpo','[\"aductores\"]','[]','[\"Comienza en posicion de flexion en el suelo. Esta sera tu posicion inicial.\", \"Usando ambas piernas, salta hacia adelante aterrizando con los pies junto a las manos. Manten la cabeza arriba mientras lo haces.\", \"Vuelve a la posicion inicial y repite inmediatamente el movimiento, continuando durante 10-20 repeticiones.\"]','estiramiento','[\"Groiners/0.jpg\", \"Groiners/1.jpg\"]','Groiners',306) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hammer Curls','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Ponte de pie con el torso erguido y una mancuerna en cada mano, sosteniendola a la longitud de los brazos. Los codos deben estar cerca del torso.\", \"Las palmas de las manos deben estar mirando hacia tu torso. Esta sera tu posicion inicial.\", \"Ahora, mientras mantienes la parte superior del brazo inmovil, exhala y flexiona el peso hacia adelante mientras contraes los biceps. Continua levantando el peso hasta que los biceps esten completamente contraidos y la mancuerna este al nivel de los hombros. Manten la posicion contraida durante un breve instante mientras aprietas los biceps. Consejo: Concentrate en mantener el codo inmovil y solo mover el antebrazo.\", \"Despues de la breve pausa, inhala y comienza lentamente a bajar las mancuernas hacia atras hasta la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Hammer_Curls/0.jpg\", \"Hammer_Curls/1.jpg\"]','Hammer_Curls',308) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado con mancuernas con agarre en martillo','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco inclinado con una mancuerna en cada mano sobre los muslos. Las palmas de las manos estaran enfrentadas entre si.\", \"Utilizando los muslos para ayudarte a levantar las mancuernas, levanta las mancuernas un brazo a la vez para poder mantenerlas a la altura de los hombros.\", \"Una vez a la altura de los hombros, manten las palmas de las manos con un agarre neutro (las palmas enfrentadas entre si). Manten los codos hacia fuera con la parte superior de los brazos alineados con los hombros (perpendiculares al torso) y los codos doblados formando un angulo de 90 grados entre la parte superior del brazo y el antebrazo. Esta sera tu posicion inicial.\", \"Ahora baja las pesas lentamente a tu lado mientras inhalas. Manten el control total de las mancuernas en todo momento.\", \"Mientras exhalas, empuja las mancuernas hacia arriba utilizando los musculos pectorales. Bloquea los brazos en la posicion contraida, manten durante un segundo y luego comienza a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca las mancuernas detras de tus muslos y luego en el suelo. Esta es la forma mas segura de deshacerte de las mancuernas.\"]','fuerza','[\"Hammer_Grip_Incline_DB_Bench_Press/0.jpg\", \"Hammer_Grip_Incline_DB_Bench_Press/1.jpg\"]','Press de banca inclinado con mancuernas y agarre en martillo',309) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de isquiotibiales','estatico','principiante','aislamiento','Ninguno','[\"isquiotibiales\"]','[]','[\"Acuestate boca arriba con una pierna extendida por encima de ti, con la cadera a noventa grados. Manten la otra pierna apoyada en el suelo.\", \"Pasa un cinturon, una banda elastica o una cuerda por la planta del pie. Esta sera tu posicion inicial.\", \"Tira del cinturon para crear tension en las pantorrillas y los isquiotibiales. Manten este estiramiento durante 10-30 segundos y repite con la otra pierna.\"]','estiramiento','[\"Hamstring_Stretch/0.jpg\", \"Hamstring_Stretch/1.jpg\"]','Estiramiento de isquiotibiales',310) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Isquiotibiales-SMR','estatico','principiante','aislamiento','rodillo_espuma','[\"isquiotibiales\"]','[]','[\"En posicion sentada, extiende tus piernas sobre un rodillo de espuma de modo que quede en la parte posterior de la parte superior de las piernas. Coloca tus manos a los lados o detras de ti para ayudar a soportar tu peso. Esta sera tu posicion inicial.\", \"Con tus manos, levanta tus caderas del suelo y desplaza tu peso sobre el rodillo de espuma hacia una pierna. Relaja los isquiotibiales de la pierna que estas estirando.\", \"Rueda sobre el rodillo desde debajo de la cadera hasta por encima de la parte posterior de la rodilla, deteniendote en los puntos de tension durante 10-30 segundos. Repite con la otra pierna.\"]','estiramiento','[\"Hamstring-SMR/0.jpg\", \"Hamstring-SMR/1.jpg\"]','Isquiotibiales-SMR',311) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones en vertical','empuje','experto','compuesto','solo_cuerpo','[\"hombros\"]','[\"triceps\"]','[\"Con la espalda contra la pared, flexiona la cintura y coloca ambas manos en el suelo a la altura de los hombros.\", \"Impulsate hacia arriba contra la pared con los brazos estirados. Tu cuerpo debe quedar boca abajo con los brazos y las piernas completamente estirados. Manten todo el cuerpo lo mas recto posible. Consejo: Si es la primera vez que lo haces, pide ayuda a alguien para que te ayude. Ademas, asegurate de mantener la cabeza mirando hacia la pared, en lugar de mirar hacia abajo.\", \"Bajate lentamente al suelo mientras inhalas hasta que tu cabeza casi toque el suelo. Consejo: Es de suma importancia que bajes lentamente para evitar lesiones en la cabeza.\", \"Empujate hacia arriba lentamente mientras exhalas hasta que tus codos esten casi bloqueados.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Handstand_Push-Ups/0.jpg\", \"Handstand_Push-Ups/1.jpg\"]','Handstand_Push-Ups',312) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hang Clean','traccion','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"hombros\", \"trapecios\"]','[\"Comienza con un agarre doble por encima de la cabeza o en gancho, con la barra colgando a la altura de la mitad del muslo. La espalda debe estar recta e inclinada ligeramente hacia delante.\", \"Comience extendiendo agresivamente las caderas, las rodillas y los tobillos, impulsando el peso hacia arriba. Al hacerlo, encoge los hombros hacia las orejas.\", \"Recupere inmediatamente impulsando con los talones, manteniendo el torso erguido y los codos arriba. Continue hasta que se haya levantado a una posicion de pie.\"]','halterofilia_olimpica','[\"Hang_Clean/0.jpg\", \"Hang_Clean/1.jpg\"]','Hang_Clean',313) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hang Clean - Por debajo de las rodillas','traccion','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"hombros\", \"trapecios\"]','[\"Comienza con un agarre doble por encima de la cabeza o en gancho, con la barra colgando justo por debajo de las rodillas. Tu espalda debe estar recta e inclinada ligeramente hacia adelante.\", \"Comienza extendiendo agresivamente las caderas, rodillas y tobillos, impulsando el peso hacia arriba. Mientras lo haces, encoge los hombros hacia las orejas. Cuando hayas logrado la extension completa, pasa al tercer tiron encogiendo agresivamente los hombros y flexionando los brazos con los codos hacia arriba y hacia fuera.\", \"En el punto maximo de la extension, tira agresivamente hacia abajo, rotando los codos por debajo de la barra mientras lo haces. Recibe la barra en una posicion de sentadilla frontal, cuya profundidad depende de la altura de la barra al final del tercer tiron. La barra debe colocarse sobre los hombros extendidos, tocando ligeramente la garganta con las manos relajadas. Continua descendiendo hasta la posicion de sentadilla completa, lo que te ayudara en la recuperacion.\", \"Recupera inmediatamente impulsandote con los talones, manteniendo el torso erguido y los codos arriba. Continua hasta que te hayas levantado a una posicion de pie.\"]','halterofilia_olimpica','[\"Hang_Clean_-_Below_the_Knees/0.jpg\", \"Hang_Clean_-_Below_the_Knees/1.jpg\"]','Hang_Clean_-_Por debajo de las rodillas',314) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hang Snatch','traccion','experto','compuesto','barra','[\"isquiotibiales\"]','[\"abdominales\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Comienza con un agarre amplio en la barra, con un agarre por encima o en gancho. Los pies deben estar directamente debajo de las caderas con los pies girados hacia fuera. Las rodillas deben estar ligeramente flexionadas y el torso inclinado hacia delante. La columna vertebral debe estar completamente extendida y la cabeza mirando hacia delante. La barra debe estar a la altura de las caderas. Esta sera tu posicion inicial.\", \"Extiende agresivamente las piernas y las caderas. En la extension maxima, encoge los hombros y deja que los codos se flexionen hacia los lados.\", \"A medida que mueves los pies a la posicion de recepcion, empujate con fuerza por debajo de la barra mientras la elevas sobre la cabeza. Recibe la barra con el cuerpo lo mas bajo posible y los brazos completamente extendidos sobre la cabeza.\", \"Vuelve a la posicion de pie con el peso sobre la cabeza. A continuacion, devuelve el peso al suelo de forma controlada.\"]','halterofilia_olimpica','[\"Hang_Snatch/0.jpg\", \"Hang_Snatch/1.jpg\"]','Arrancada colgada',315) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hang Snatch - Por debajo de las rodillas','traccion','experto','compuesto','barra','[\"isquiotibiales\"]','[\"abdominales\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Comienza con un agarre amplio en la barra, con un agarre por encima o en gancho. Los pies deben estar directamente debajo de las caderas con los pies girados hacia fuera. Las rodillas deben estar ligeramente flexionadas y el torso inclinado hacia delante. La columna vertebral debe estar completamente extendida y la cabeza mirando hacia delante. La barra debe estar justo por debajo de las rodillas. Esta sera tu posicion inicial.\", \"Extiende agresivamente las piernas y las caderas. En la extension maxima, encoge los hombros y deja que los codos se flexionen hacia los lados.\", \"A medida que mueves los pies a la posicion de recepcion, empujate con fuerza por debajo de la barra mientras la elevas sobre la cabeza. Recibe la barra con el cuerpo lo mas bajo posible y los brazos completamente extendidos sobre la cabeza.\", \"Vuelve a la posicion de pie con el peso sobre la cabeza y, a continuacion, devuelve el peso al suelo de forma controlada.\"]','halterofilia_olimpica','[\"Hang_Snatch_-_Below_Knees/0.jpg\", \"Hang_Snatch_-_Below_Knees/1.jpg\"]','Arrancada colgada - Por debajo de las rodillas',316) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Barra colgante Good Morning','empuje','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"abdominales\", \"gluteos\", \"espalda_baja\"]','[\"Comienza con una barra en un soporte a aproximadamente la misma altura que tu estomago. Suspende la barra utilizando cadenas o correas de suspension.\", \"Inclinate debajo de la barra y coloca la barra sobre la parte posterior de tus hombros como lo harias en una sentadilla de potencia, no sobre tus trapecios. A la altura adecuada, deberias estar casi paralelo al suelo cuando te inclines. Manten la espalda recta, los omoplatos juntos y las rodillas ligeramente flexionadas. Manten la espalda arqueada y la columna cervical correctamente alineada.\", \"Comienza el movimiento extendiendo las caderas con los gluteos y los isquiotibiales, y te quedaras de pie con el peso.\", \"Baja lentamente el peso hasta la posicion inicial, donde estara sostenido por las cadenas.\"]','levantamiento de pesas','[\"Hanging_Bar_Good_Morning/0.jpg\", \"Hanging_Bar_Good_Morning/1.jpg\"]','Barra colgante - Buenos dias',317) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Equilibrio con arranque','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"abdominales\", \"antebrazos\", \"gluteos\", \"isquiotibiales\", \"hombros\", \"triceps\"]','[\"Este ejercicio te ayuda a aprender el arranque. Comienza sosteniendo un peso ligero sobre la espalda de los hombros. Los pies deben estar ligeramente mas separados que el ancho de las caderas, con los pies girados hacia fuera, la misma posicion que se adoptaria para realizar una sentadilla.\", \"Comienza flexionando ligeramente las rodillas y levantando la espalda para descargar brevemente la barra. Impulsate por debajo de la barra, elevandola por encima de la cabeza mientras desciendes hasta una sentadilla completa.\", \"Vuelve a la posicion de pie.\"]','halterofilia_olimpica','[\"Heaving_Snatch_Balance/0.jpg\", \"Heaving_Snatch_Balance/1.jpg\"]','Balance de arranque con levantamiento',320) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('High en Polea Curls','traccion','intermedio','compuesto','polea','[\"biceps\"]','[]','[\"Ponte de pie entre un par de poleas altas y agarra un asa con cada brazo. Coloca la parte superior de los brazos de forma que queden paralelos al suelo, con las palmas de las manos mirando hacia ti. Esta sera tu posicion inicial.\", \"Flexiona los brazos hacia ti hasta que las asas queden junto a tus orejas. Asegurate de flexionar los biceps y exhalar al hacerlo. Los brazos superiores deben permanecer fijos y solo deben moverse los antebrazos. Manten durante un segundo la posicion contraida mientras aprietas los biceps.\", \"Lentamente, lleva los brazos a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"High_Cable_Curls/0.jpg\", \"High_Cable_Curls/1.jpg\"]','Curls con cable alto',322) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos de cadera (boca abajo)','traccion','principiante','aislamiento','solo_cuerpo','[\"abductores\"]','[\"aductores\"]','[\"Colocate en tus manos y rodillas en el suelo. Manteniendo una buena postura, levanta una rodilla doblada del suelo. Esta sera tu posicion inicial.\", \"Manteniendo la rodilla en posicion doblada, gira el femur en un arco, intentando hacer un gran circulo con la rodilla.\", \"Realiza este ejercicio lentamente durante varias repeticiones y repite en el otro lado.\"]','estiramiento','[\"Hip_Circles_prone/0.jpg\", \"Hip_Circles_prone/1.jpg\"]','Circulos de cadera boca abajo',323) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de cadera con bandas','empuje','principiante','compuesto','bandas','[\"gluteos\"]','[\"isquiotibiales\"]','[\"Fija un extremo de la banda a la parte inferior de un poste y ata el otro a un tobillo.\", \"De cara al punto de fijacion de la banda, mantente pegado a la columna para estabilizarte.\", \"Manten la cabeza y el pecho erguidos, mueve la pierna con resistencia hacia atras tan lejos como puedas mientras mantienes la rodilla recta.\", \"Vuelve a colocar la pierna en la posicion inicial.\"]','fuerza','[\"Hip_Extension_with_Bands/0.jpg\", \"Hip_Extension_with_Bands/1.jpg\"]','Extension de cadera con bandas',324) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de cadera con banda','traccion','principiante','compuesto','bandas','[\"cuadriceps\"]','[]','[\"Fija un extremo de la banda a la parte inferior de un poste y fija el otro a un tobillo.\", \"Colocate de espaldas al punto de fijacion de la banda.\", \"Manten la cabeza y el pecho erguidos, levanta la rodilla hasta 90 grados y haz una pausa.\", \"Vuelve a colocar la pierna en la posicion inicial.\"]','fuerza','[\"Hip_Flexion_with_Band/0.jpg\", \"Hip_Flexion_with_Band/1.jpg\"]','Flexion de cadera con banda',325) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de cadera con banda','empuje','principiante','compuesto','bandas','[\"gluteos\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Despues de elegir una banda adecuada, tumbate en el centro del soporte, despues de fijar la banda a ambos lados. Si tu soporte no tiene clavijas, la banda se puede fijar con mancuernas pesadas u objetos similares, solo asegurate de que no se muevan.\", \"Ajusta tu posicion para que la banda quede directamente sobre tus caderas. Dobla tus rodillas y coloca tus pies planos en el suelo. Las manos pueden estar en el suelo o sujetando la banda en su posicion.\", \"Manteniendo los hombros en el suelo, empuja con los talones para levantar las caderas, empujando la banda tan alto como puedas.\", \"Haz una pausa en la parte superior del movimiento y vuelve a la posicion inicial.\"]','levantamiento de pesas','[\"Hip_Lift_with_Band/0.jpg\", \"Hip_Lift_with_Band/1.jpg\"]','Elevacion de cadera con banda',326) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abraza una pelota','estatico','principiante','aislamiento','fitball','[\"espalda_baja\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Sientate en el suelo.\", \"Coloca una pelota de ejercicios entre ambas piernas y baja las caderas hacia el suelo.\", \"Abraza la pelota con los brazos para sostener tu cuerpo. Ajusta las piernas de modo que los pies queden planos en el suelo y las rodillas alineadas con los tobillos. Manten un buen agarre en la pelota para que no ruede alejandote de ti y te haga caer de espaldas sobre tus gluteos.\"]','estiramiento','[\"Hug_A_Ball/0.jpg\", \"Hug_A_Ball/1.jpg\"]','Abrazar una pelota',327) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abraza las rodillas contra el pecho','estatico','principiante','Ninguno','Ninguno','[\"espalda_baja\"]','[\"gluteos\"]','[\"Tumbate boca arriba y lleva ambas rodillas hacia el pecho.\", \"Sujeta tus brazos por debajo de las rodillas, no por encima (eso ejerceria demasiada presion sobre las articulaciones de las rodillas).\", \"Lleva lentamente las rodillas hacia los hombros. Esto tambien estira los musculos de los gluteos.\"]','estiramiento','[\"Abrazar_las_rodillas_contra_el_pecho/0.jpg\", \"Abrazar_las_rodillas_contra_el_pecho/1.jpg\"]','Abrazar_las_rodillas_contra_el_pecho',328) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Saltos de vallas','empuje','principiante','compuesto','otro','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Coloca una fila de vallas u otras barreras pequeñas, separandolas unos centimetros entre si.\", \"Ponte de pie frente a la primera valla con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Empieza saltando con ambos pies por encima de la primera valla, balanceando ambos brazos mientras saltas.\", \"Absorbe el impacto del aterrizaje doblando las rodillas y rebota del primer salto para saltar por encima de la siguiente valla. Continua hasta que hayas saltado todos los vallas.\"]','pliometria','[\"Hurdle_Hops/0.jpg\", \"Hurdle_Hops/1.jpg\"]','Salto de vallas',329) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con barra inclinada','empuje','intermedio','aislamiento','barra','[\"triceps\"]','[\"antebrazos\"]','[\"Sujeta una barra con un agarre por encima (palmas hacia abajo) que este un poco mas cerca que el ancho de los hombros.\", \"Tumbate boca arriba en un banco inclinado ajustado a cualquier angulo entre 45 y 75 grados.\", \"Lleva la barra sobre la cabeza con los brazos extendidos y los codos hacia dentro. Los brazos deben estar alineados con el torso por encima de la cabeza. Esta sera tu posicion inicial.\", \"Ahora baja la barra con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Inhala mientras realizas este movimiento. Consejo: Manten la parte superior de los brazos fija y cerca de la cabeza en todo momento. Solo deben moverse los antebrazos.\", \"Regresa a la posicion inicial mientras exhalas y contraes los triceps. Manten la contraccion durante un segundo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Incline_Barbell_Triceps_Extension/0.jpg\", \"Incline_Barbell_Triceps_Extension/1.jpg\"]','Extension de triceps con barra inclinada',335) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado en polea','empuje','principiante','compuesto','polea','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Ajusta el peso a una cantidad adecuada y sientate, agarrando las asas. Tus brazos superiores deben estar aproximadamente a 45 grados del cuerpo, con la cabeza y el pecho levantados. Los codos deben estar doblados a aproximadamente 90 grados. Esta sera tu posicion inicial.\", \"Comienza extendiendo los codos, presionando las asas juntas recto frente a ti. Manten los omoplatos retraidos mientras ejecutas el movimiento.\", \"Despues de hacer una pausa en la extension completa, vuelve a la posicion inicial, manteniendo la tension en las poleas.\"]','fuerza','[\"Incline_Cable_Chest_Press/0.jpg\", \"Incline_Cable_Chest_Press/1.jpg\"]','Press inclinado con cable',337) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Incline con mancuerna en banco con las palmas hacia dentro','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco inclinado con una mancuerna en cada mano sobre los muslos. Las palmas de las manos estaran enfrentadas entre si.\", \"Utilizando los muslos para ayudarte a levantar las mancuernas, levanta las mancuernas un brazo a la vez para poder mantenerlas a la altura de los hombros.\", \"Una vez a la altura de los hombros, manten las palmas de las manos con un agarre neutro (las palmas enfrentadas entre si). Manten los codos hacia fuera con la parte superior de los brazos alineados con los hombros (perpendiculares al torso) y los codos doblados formando un angulo de 90 grados entre la parte superior del brazo y el antebrazo. Esta sera tu posicion inicial.\", \"Ahora baja las pesas lentamente a tu lado mientras inhalas. Manten el control total de las mancuernas en todo momento.\", \"Mientras exhalas, empuja las mancuernas hacia arriba utilizando los musculos pectorales. Bloquea los brazos en la posicion contraida, manten durante un segundo y luego comienza a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca las mancuernas detras de tus muslos y luego en el suelo. Esta es la forma mas segura de deshacerte de las mancuernas.\"]','fuerza','[\"Incline_Dumbbell_Bench_With_Palms_Facing_In/0.jpg\", \"Incline_Dumbbell_Bench_With_Palms_Facing_In/1.jpg\"]','Inclinacion con mancuernas en banco con las palmas hacia dentro',339) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inclinado con mancuernas','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Sientate con la espalda en un banco inclinado con una mancuerna en cada mano, sostenidas a la longitud de los brazos. Manten los codos cerca del torso y gira las palmas de las manos hasta que queden mirando hacia delante. Esta sera tu posicion inicial.\", \"Mientras mantienes la parte superior del brazo inmovil, flexiona los pesos hacia delante mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Manten la posicion contraida durante un segundo.\", \"Comienza lentamente a llevar las mancuernas de vuelta a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Incline_Dumbbell_Curl/0.jpg\", \"Incline_Dumbbell_Curl/1.jpg\"]','Curl inclinado con mancuernas',340) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curls con mancuernas en inclinacion','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Sientate en un banco inclinado con una mancuerna en cada mano. Debes presionar firmemente contra la espalda con los pies juntos. Deja que las mancuernas cuelguen recto abajo a los lados, sosteniendolas con un agarre neutro. Esta sera tu posicion inicial.\", \"Inicia el movimiento flexionando el codo, intentando mantener el brazo superior inmovil.\", \"Continua hasta la parte superior del movimiento y haz una pausa, luego vuelve lentamente a la posicion inicial.\"]','fuerza','[\"Incline_Hammer_Curls/0.jpg\", \"Incline_Hammer_Curls/1.jpg\"]','Flexiones inclinadas con mancuernas',344) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inclinado de biceps interno','Ninguno','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Sosten una mancuerna en cada mano y recuestate boca arriba en un banco inclinado.\", \"Las mancuernas deben estar colgando a lo largo del brazo a los lados y las palmas deben estar mirando hacia afuera. Esta sera tu posicion inicial.\", \"Ahora, mientras exhalas, flexiona el peso hacia afuera y hacia arriba mientras mantienes los antebrazos alineados con los deltoides laterales. Continua el curl hasta que las mancuernas esten a la altura de los hombros y a los lados de tus deltoides. Consejo: El final del movimiento debe parecerse a una pose de doble biceps.\", \"Despues de una segunda contraccion en la parte superior del movimiento, comienza a inhalar y baja lentamente las pesas de vuelta a la posicion inicial utilizando la misma trayectoria que has utilizado para levantarlas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Incline_Inner_Biceps_Curl/0.jpg\", \"Incline_Inner_Biceps_Curl/1.jpg\"]','Flexion inclinada del biceps interno',345) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Pongase de pie frente a un banco o una plataforma elevada y resistente. Coloque las manos en el borde del banco o la plataforma, ligeramente mas separadas que el ancho de los hombros.\", \"Coloque la parte delantera de los pies detras del banco o la plataforma con los brazos y el cuerpo rectos. Los brazos deben estar perpendiculares al cuerpo. Manteniendo el cuerpo recto, baje el pecho hasta el borde de la caja o la plataforma doblando los brazos.\", \"Empuje el cuerpo hacia arriba hasta que los brazos esten extendidos. Repita.\"]','fuerza','[\"Flexion_inclinada/0.jpg\", \"Flexion_inclinada/1.jpg\"]','Flexion inclinada',346) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada con agarre cerrado','empuje','principiante','compuesto','solo_cuerpo','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Ponte de pie frente a una barra Smith o una plataforma elevada y resistente a una altura adecuada.\", \"Coloca tus manos una junto a otra en la barra.\", \"Coloca tus pies detras de la barra con los brazos y el cuerpo rectos. Esta sera tu posicion inicial.\", \"Manteniendo el cuerpo recto, baja el pecho hasta la barra flexionando los brazos.\", \"Vuelve a la posicion inicial extendiendo los codos y empujandote hacia arriba.\"]','fuerza','[\"Incline_Push-Up_Close-Grip/0.jpg\", \"Incline_Push-Up_Close-Grip/1.jpg\"]','Flexion inclinada con agarre cerrado',347) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada con salto en profundidad','empuje','principiante','compuesto','otro','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Para este ejercicio necesitaras una caja de aproximadamente 12 pulgadas de alto y dos colchonetas gruesas o steps de aerobic.\", \"Coloca los steps justo fuera de tus hombros y coloca tus pies encima de la caja de modo que estes en posicion de flexion inclinada, con las manos justo dentro de los steps. Esta sera tu posicion inicial.\", \"Comienza doblando los codos para bajar el cuerpo, invirtiendo rapidamente la posicion para empujar el cuerpo fuera del suelo. Al despegar del suelo, mueve las manos hacia los escalones, doblando los codos para absorber el impacto.\", \"Repite el movimiento para volver a la posicion inicial.\"]','pliometria','[\"Incline_Push-Up_Depth_Jump/0.jpg\", \"Incline_Push-Up_Depth_Jump/1.jpg\"]','Flexion inclinada con salto en profundidad',348) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada media','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Ponte de pie frente a una barra Smith o una plataforma elevada y resistente a una altura adecuada.\", \"Coloca tus manos en la barra, con tus manos aproximadamente a la anchura de los hombros.\", \"Coloca tus pies detras de la barra con los brazos y el cuerpo rectos. Esta sera tu posicion inicial.\", \"Manteniendo el cuerpo recto, baja el pecho hacia la barra flexionando los brazos.\", \"Vuelve a la posicion inicial extendiendo los codos y empujandote hacia arriba.\"]','fuerza','[\"Incline_Push-Up_Medium/0.jpg\", \"Incline_Push-Up_Medium/1.jpg\"]','Flexion inclinada media',349) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada con agarre inverso','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Ponte de pie frente a la barra de una maquina Smith o una plataforma elevada y resistente a una altura adecuada.\", \"Coloca tus manos en la barra con las palmas hacia arriba, con tus manos separadas aproximadamente a la anchura de los hombros.\", \"Coloca tus pies detras de la barra con los brazos y el cuerpo rectos. Esta sera tu posicion inicial.\", \"Manteniendo el cuerpo recto, baja el pecho hacia la barra flexionando los brazos.\", \"Vuelve a la posicion inicial extendiendo los codos y empujando el pecho hacia arriba.\"]','fuerza','[\"Incline_Push-Up_Reverse_Grip/0.jpg\", \"Incline_Push-Up_Reverse_Grip/1.jpg\"]','Flexion inclinada con agarre inverso',350) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion inclinada con agarre ancho','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Ponte de pie frente a la barra de una maquina Smith o una plataforma elevada y resistente a una altura adecuada.\", \"Coloca tus manos en la barra, con tus manos mas separadas que el ancho de los hombros.\", \"Coloca tus pies detras de la barra con los brazos y el cuerpo rectos. Tus brazos deben estar perpendiculares al cuerpo. Esta sera tu posicion inicial.\", \"Manteniendo el cuerpo recto, baja el pecho hacia la barra flexionando los brazos.\", \"Vuelve a la posicion inicial extendiendo los codos y empujandote hacia arriba.\"]','fuerza','[\"Incline_Push-Up_Wide/0.jpg\", \"Incline_Push-Up_Wide/1.jpg\"]','Flexiones inclinadas con las manos separadas',351) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento intermedio de la ingle','estatico','intermedio','aislamiento','otro','[\"isquiotibiales\"]','[]','[\"Acuestate boca arriba con tus piernas extendidas. Enrolla un cinturon, una cuerda o una banda alrededor de uno de tus pies y balancea esa pierna hacia el lado tanto como puedas. Esta sera tu posicion inicial.\", \"Tira suavemente del cinturon para crear tension en los musculos de la ingle y los isquiotibiales. Manten la posicion durante 10-20 segundos y repite en el otro lado.\"]','estiramiento','[\"Intermediate_Groin_Stretch/0.jpg\", \"Intermediate_Groin_Stretch/1.jpg\"]','Estiramiento intermedio de la ingle',352) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento intermedio del flexor de la cadera y el cuadriceps','estatico','intermedio','compuesto','otro','[\"cuadriceps\"]','[]','[\"Acuestate boca abajo en el suelo, con una cuerda, cinturon o banda enrollada alrededor de un pie.\", \"Flexiona la rodilla y extiende la cadera de la pierna que vas a estirar, utilizando ambas manos para tirar del cinturon. La rodilla y la cadera deben despegarse del suelo, creando tension en los flexores de la cadera y los cuadriceps. Manten el estiramiento durante 10-20 segundos y repite con la otra pierna.\"]','estiramiento','[\"Intermediate_Hip_Flexor_and_Quad_Stretch/0.jpg\", \"Intermediate_Hip_Flexor_and_Quad_Stretch/1.jpg\"]','Estiramiento intermedio de flexores de cadera y cuadriceps',353) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo invertido con correas','traccion','principiante','compuesto','otro','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Cuelga una cuerda o correas de suspension de un soporte u otro objeto estable. Agarra los extremos y colocate en posicion supina colgado de las cuerdas. Tu cuerpo debe estar recto con los talones en el suelo y los brazos completamente extendidos. Esta sera tu posicion inicial.\", \"Comienza flexionando el codo, tirando de tu pecho hacia tus manos. Retrae los omoplatos mientras realizas el movimiento.\", \"Haz una pausa arriba del movimiento y vuelve a la posicion inicial.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Inverted_Row_with_Straps/0.jpg\", \"Inverted_Row_with_Straps/1.jpg\"]','Remo invertido con correas',356) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cruz de hierro','empuje','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"pecho\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[]','fuerza','[\"Iron_Cross/0.jpg\", \"Iron_Cross/1.jpg\"]','Cruz de hierro',357) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cruces de hierro (estiramiento)','traccion','intermedio','compuesto','Ninguno','[\"cuadriceps\"]','[]','[\"Acuestate boca abajo en el suelo, con los brazos extendidos a los lados y las palmas de las manos apoyadas en el suelo. Esta sera tu posicion inicial.\", \"Para empezar, flexiona una rodilla y lleva esa pierna hacia la espalda de tu cuerpo, intentando tocar el suelo cerca de la mano opuesta.\", \"Vuelve rapidamente la pierna a la posicion inicial y repite rapidamente con la otra pierna. Continua alternando durante 10-20 repeticiones.\"]','estiramiento','[\"Iron_Crosses_stretch/0.jpg\", \"Iron_Crosses_stretch/1.jpg\"]','Estiramiento de cruces de hierro',358) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Apretones isometricos de pecho','estatico','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Mientras estas sentado o de pie, dobla los brazos en un angulo de 90 grados y junta las palmas de las manos frente al pecho. Consejo: Las manos deben estar abiertas con las palmas juntas y los dedos mirando hacia adelante (perpendiculares al torso).\", \"Empuja ambas manos una contra otra mientras contraes el pecho. Empieza con una tension suave y aumenta lentamente. Sigue respirando con normalidad mientras realizas esta contraccion.\", \"Manten durante el numero de segundos recomendado.\", \"Ahora libera la tension lentamente.\", \"Descansa durante el tiempo recomendado y repite.\"]','pliometria','[\"Isometric_Chest_Squeezes/0.jpg\", \"Isometric_Chest_Squeezes/1.jpg\"]','Contracciones isometricas del pecho',359) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ejercicio isometrico para el cuello: frontal y posterior','estatico','principiante','aislamiento','solo_cuerpo','[\"cuello\"]','[]','[\"Con la cabeza y el cuello en posicion neutra (posicion normal con la cabeza erguida mirando hacia adelante), coloca ambas manos en la parte delantera de la cabeza.\", \"Ahora empuja suavemente hacia adelante mientras contraes los musculos del cuello, pero resistiendo cualquier movimiento de la cabeza. Empieza con una tension lenta y aumenta poco a poco. Sigue respirando con normalidad mientras realizas esta contraccion.\", \"Manten durante el numero de segundos recomendado.\", \"Ahora libera la tension lentamente.\", \"Descansa durante el tiempo recomendado y repite con tus manos colocadas en la parte posterior de la cabeza.\"]','fuerza','[\"Ejercicio isometrico para el cuello: parte delantera y trasera/0.jpg\", \"Ejercicio isometrico para el cuello: parte delantera y trasera/1.jpg\"]','Ejercicio isometrico para el cuello: parte delantera y trasera',360) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ejercicio isometrico para el cuello: lados','estatico','principiante','aislamiento','solo_cuerpo','[\"cuello\"]','[]','[\"Con la cabeza y el cuello en posicion neutra (posicion normal con la cabeza erguida mirando hacia adelante), coloca la mano izquierda en el lado izquierdo de la cabeza.\", \"Ahora empuja suavemente hacia la izquierda mientras contraes los musculos del cuello izquierdo, pero resistiendo cualquier movimiento de la cabeza. Empieza con una tension lenta y aumenta poco a poco. Sigue respirando con normalidad mientras realizas esta contraccion.\", \"Manten durante el numero de segundos recomendado.\", \"Ahora libera la tension lentamente.\", \"Descansa durante el tiempo recomendado y repite con la mano derecha colocada en el lado derecho de la cabeza.\"]','fuerza','[\"Ejercicio isometrico para el cuello - Lados/0.jpg\", \"Ejercicio isometrico para el cuello - Lados/1.jpg\"]','Ejercicio isometrico para el cuello - Lados',361) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Limpiaparabrisas isometricos','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Adopta una posicion de flexion, apoyando tu peso en tus manos y dedos de los pies mientras mantienes tu cuerpo recto. Las manos deben estar ligeramente mas separadas que el ancho de los hombros. Esta sera tu posicion inicial.\", \"Comienza desplazando el peso del cuerpo lo mas posible hacia un lado, permitiendo que el codo de ese lado se flexione a medida que bajas el cuerpo.\", \"Invierte el movimiento extendiendo el brazo flexionado, empujandote hacia arriba y luego cayendo hacia el otro lado.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Isometric_Wipers/0.jpg\", \"Isometric_Wipers/1.jpg\"]','Isometric_Wipers',362) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de la banda iliotibial y los gluteos','estatico','intermedio','Ninguno','otro','[\"abductores\"]','[]','[\"Enrolla un cinturon, una cuerda o una banda alrededor de uno de tus pies y balancea esa pierna a traves de tu cuerpo hacia el lado opuesto, manteniendo la pierna extendida mientras te tumbas en el suelo. Esta sera tu posicion inicial.\", \"Manteniendo el pie separado del suelo, tira del cinturon, utilizando la tension para levantar los dedos de los pies. Manten durante 10-20 segundos y repite en el otro lado.\"]','estiramiento','[\"IT_Band_and_Glute_Stretch/0.jpg\", \"IT_Band_and_Glute_Stretch/1.jpg\"]','IT_Band_and_Glute_Stretch',363) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales en tijera','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Tumbate boca arriba en el suelo (o en una colchoneta de ejercicios) con los brazos extendidos rectos detras de la cabeza y las piernas tambien extendidas. Esta sera tu posicion inicial.\", \"Mientras exhalas, flexiona la cintura y, al mismo tiempo, levanta las piernas y los brazos hasta que se unan en una posicion de tijera. Consejo: Las piernas deben estar extendidas y levantadas en un angulo de aproximadamente 35-45 grados con respecto al suelo, y los brazos deben estar extendidos y paralelos a las piernas. La parte superior del torso debe estar separada del suelo.\", \"Mientras inhalas, baja los brazos y las piernas hasta la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Jackknife_Sit-Up/0.jpg\", \"Jackknife_Sit-Up/1.jpg\"]','Abdominales en tijera',364) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Janda Abdominal','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Coloca tu cuerpo en el suelo en la posicion basica de abdominales; las rodillas en un angulo de noventa grados con los pies planos en el suelo y los brazos cruzados sobre el pecho o a los lados. Esta sera tu posicion inicial.\", \"Mientras contraes con fuerza los gluteos y los isquiotibiales, llena tus pulmones de aire y, en un ascenso lento (de tres a seis segundos), exhala lentamente. Consejo: Es importante contraer los gluteos y los isquiotibiales, ya que esto provocara que los flexores de la cadera se desactiven en un proceso llamado inhibicion reciproca, lo que basicamente significa que los musculos opuestos a los contraidos se relajaran.\", \"Mientras inhalas, lleva lentamente la espalda de forma controlada a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Janda_Sit-Up/0.jpg\", \"Janda_Sit-Up/1.jpg\"]','Janda_Sit-Up',365) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('JM Press','empuje','principiante','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Comienza el ejercicio de la misma manera que lo harias con un press de banca con agarre cerrado. Te acostaras en un banco plano mientras sostienes una barra a la longitud de los brazos (completamente extendidos) con los codos hacia adentro. Sin embargo, en lugar de tener los brazos perpendiculares al torso, asegurate de que la barra este colocada en linea recta sobre la parte superior del pecho. Esta sera tu posicion inicial.\", \"Ahora, comenzando desde una posicion completamente extendida, baja la barra como si estuvieras realizando una extension de triceps tumbado. Inhala mientras realizas este movimiento. Cuando llegues a la mitad, deja que la barra ruede aproximadamente una pulgada hacia atras moviendo los brazos superiores hacia tus piernas hasta que esten perpendiculares al torso. Consejo: Manten la flexion de los codos constante mientras llevas los brazos superiores hacia delante.\", \"Mientras exhalas, empuja la barra hacia arriba utilizando los triceps para realizar un press de banca con agarre cerrado.\", \"Ahora vuelve a la posicion inicial y empieza de nuevo.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"JM_Press/0.jpg\", \"JM_Press/1.jpg\"]','JM_Press',369) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Carga de barril','traccion','intermedio','compuesto','otro','[\"espalda_baja\"]','[\"abdominales\", \"biceps\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_media\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Para cargar barriles, coloca el numero deseado a una distancia de la plataforma de carga, normalmente entre 9 y 15 metros.\", \"Comienza agarrando el asa cercana del primer barril, inclinandolo hacia un lado para agarrar el borde opuesto de la parte inferior del barril. Eleva el barril hasta tu pecho.\", \"Cuanto mas alto puedas colocar el barril, mas rapido podras moverte hacia la plataforma. Por lo general, no se permite cargarlo sobre los hombros. Asegurate de mantener un agarre firme en el barril. Muevete lo mas rapido posible hacia la plataforma y cargalo, extendiendo las caderas, las rodillas y los tobillos para levantarlo lo mas alto posible.\", \"Regresa a la posicion inicial para recuperar el siguiente barril y repite hasta completar la prueba.\"]','hombre_fuerte','[\"Keg_Load/0.jpg\", \"Keg_Load/1.jpg\"]','Carga_de_barril',371) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Figura 8','traccion','intermedio','Ninguno','pesas rusas','[\"abdominales\"]','[\"isquiotibiales\", \"hombros\"]','[\"Coloca una pesa rusa entre tus piernas y adopta una postura mas ancha que el ancho de los hombros. Inclinate hacia delante empujando el trasero hacia fuera y manteniendo la espalda recta.\", \"Coge una pesa rusa y pasala a tu otra mano entre tus piernas. La mano receptora debe alcanzar desde detras de las piernas. Ve hacia atras y hacia delante durante varias repeticiones.\"]','fuerza','[\"Kettlebell_Figura_8/0.jpg\", \"Kettlebell_Figura_8/1.jpg\"]','Kettlebell_Figura_8',374) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Hang Clean','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"pantorrillas\", \"gluteos\", \"espalda_baja\", \"hombros\", \"trapecios\"]','[\"Coloca la kettlebell entre tus pies. Para colocarte en la posicion inicial, empuja el trasero hacia atras y mira al frente.\", \"Lleva la kettlebell a tus hombros. Lleva la kettlebell a tus hombros extendiendo las piernas y las caderas mientras levantas la kettlebell hacia tus hombros. La muñeca debe girar al hacerlo.\", \"Baja la pesa rusa hasta una posicion colgante entre tus piernas mientras mantienes los isquiotibiales cargados. Manten la cabeza arriba en todo momento.\"]','fuerza','[\"Kettlebell_Hang_Clean/0.jpg\", \"Kettlebell_Hang_Clean/1.jpg\"]','Kettlebell_Hang_Clean',375) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto con una sola pierna con pesa rusa','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\"]','[\"Sujeta una pesa rusa por el asa con una mano. Ponte de pie sobre una pierna, del mismo lado que mantienes la pesa rusa.\", \"Manteniendo la rodilla ligeramente flexionada, realiza un peso muerto con las piernas rigidas doblando la cadera y extendiendo la pierna libre hacia atras para mantener el equilibrio.\", \"Continua bajando la pesa rusa hasta que estes paralelo al suelo y luego vuelve a la posicion erguida.\"]','fuerza','[\"Kettlebell_One-Legged_Deadlift/0.jpg\", \"Kettlebell_One-Legged_Deadlift/1.jpg\"]','Kettlebell_Peso muerto a una pierna',376) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Pirate Ships','empuje','principiante','compuesto','pesas rusas','[\"hombros\"]','[\"abdominales\"]','[\"Con una postura amplia, manten una pesa rusa con ambas manos. Deja que cuelgue a la altura de la cintura con los brazos extendidos. Esta sera tu posicion inicial.\", \"Inicia el movimiento girando hacia un lado, balanceando la pesa rusa hasta la altura de la cabeza. Haz una breve pausa en la parte superior del movimiento.\", \"Deja que la pesa caiga mientras giras hacia el lado opuesto, volviendo a levantar la pesa rusa a la altura de la cabeza.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Kettlebell_Pirate_Ships/0.jpg\", \"Kettlebell_Pirate_Ships/1.jpg\"]','Kettlebell_Barcos_piratas',378) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Pistol Sentadilla','empuje','experto','compuesto','pesas rusas','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"hombros\"]','[\"Levanta una pesa rusa con las dos manos y sujetala por los cuernos. Manten una pierna separada del suelo y haz una sentadilla con la otra.\", \"Haz una sentadilla flexionando la rodilla y sentandote con las caderas, sosteniendo la pesa rusa frente a ti.\", \"Manten la posicion inferior durante un segundo y luego invierte el movimiento, impulsandote con el talon y manteniendo la cabeza y el pecho erguidos.\", \"Baja de nuevo y repite.\"]','fuerza','[\"Kettlebell_Pistol_Squat/0.jpg\", \"Kettlebell_Pistol_Squat/1.jpg\"]','Kettlebell_Pistola_Sentadilla',379) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentado con pesas rusas','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"triceps\"]','[\"Sientate en el suelo y separa las piernas comodamente.\", \"Lleva una pesa rusa hasta el hombro.\", \"Empuja la pesa rusa hacia arriba y hacia fuera hasta que quede bloqueada sobre la cabeza. Vuelve a la posicion inicial.\"]','fuerza','[\"Kettlebell_Seated_Press/0.jpg\", \"Kettlebell_Seated_Press/1.jpg\"]','Press sentado con pesas rusas',380) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tiron alto sumo con pesas rusas','traccion','intermedio','compuesto','pesas rusas','[\"trapecios\"]','[\"aductores\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\", \"hombros\"]','[\"Coloca una pesa rusa en el suelo entre tus pies. Coloca tus pies en una postura amplia y agarra la pesa rusa con las dos manos. Echa las caderas hacia atras lo maximo posible, con las rodillas flexionadas. Manten el pecho y la cabeza erguidos. Esta sera tu posicion inicial.\", \"Comienza extendiendo las caderas y las rodillas, al tiempo que levantas la pesa rusa hasta los hombros, elevando los codos al hacerlo. Invierte el movimiento para volver a la posicion inicial.\"]','fuerza','[\"Kettlebell_Sumo_High_Pull/0.jpg\", \"Kettlebell_Sumo_High_Pull/1.jpg\"]','Kettlebell_Sumo_High_Pull',382) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Thruster','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"cuadriceps\", \"triceps\"]','[\"Limpia dos pesas rusas hasta tus hombros. Limpia las pesas rusas hasta tus hombros extendiendo las piernas y las caderas mientras tiras de las pesas rusas hacia tus hombros. Gira tus muñecas mientras lo haces. Esta sera tu posicion inicial.\", \"Comienza a hacer sentadillas flexionando tus caderas y rodillas, bajando tus caderas entre tus piernas. Manten la espalda recta mientras desciendes lo mas bajo que puedas.\", \"En la parte inferior, invierte la direccion y haz una sentadilla extendiendo las rodillas y las caderas, impulsandote con los talones. Mientras lo haces, presiona ambas pesas rusas sobre la cabeza extendiendo los brazos hacia arriba, utilizando el impulso de la sentadilla para ayudar a impulsar las pesas hacia arriba.\", \"Al comenzar la siguiente repeticion, vuelve a colocar las pesas sobre los hombros.\"]','fuerza','[\"Kettlebell_Thruster/0.jpg\", \"Kettlebell_Thruster/1.jpg\"]','Kettlebell_Thruster',383) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kettlebell Turkish Get-Up (estilo Zancada)','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"abdominales\", \"isquiotibiales\", \"cuadriceps\", \"triceps\"]','[\"Acuestate boca arriba en el suelo y presiona una pesa rusa hasta la posicion superior extendiendo el codo. Dobla la rodilla del mismo lado que la pesa rusa.\", \"Manteniendo la pesa rusa bloqueada en todo momento, gira hacia el lado opuesto y utiliza el brazo que no estas trabajando para ayudarte a impulsarte hacia delante hasta la posicion de zancada. Con la mano libre, empujate hasta una posicion sentada y luego pasa a una rodilla.\", \"Mientras miras hacia arriba a la pesa rusa, levantate lentamente. Invierte el movimiento hasta la posicion inicial y repite.\"]','fuerza','[\"Kettlebell_Turkish_Get-Up_Lunge_style/0.jpg\", \"Kettlebell_Turkish_Get-Up_Lunge_style/1.jpg\"]','Kettlebell_Levantamiento_turco_estilo_zancada',384) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Kipping Muscle Up','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"abdominales\", \"biceps\", \"antebrazos\", \"espalda_media\", \"hombros\", \"trapecios\", \"triceps\"]','[\"Sujeta los anillos con un agarre falso, con la base de las palmas de las manos en la parte superior de los anillos.\", \"Comienza con un movimiento balanceando ligeramente las piernas hacia atras.\", \"Contrarresta ese movimiento balanceando las piernas hacia adelante y hacia arriba, echando la barbilla y el pecho hacia atras, tirando de ti mismo hacia arriba con ambos brazos mientras lo haces. Cuando alcances la posicion superior de la dominada, tira de los anillos hacia tus axilas mientras giras los hombros hacia delante, permitiendo que tus codos se muevan recto detras de ti. Esto te coloca en la posicion adecuada para continuar con la parte de flexion del movimiento.\", \"Manteniendo el control y la estabilidad, extiende el codo para completar el movimiento.\", \"Ten cuidado al bajar al suelo.\"]','fuerza','[\"Kipping_Muscle_Up/0.jpg\", \"Kipping_Muscle_Up/1.jpg\"]','Kipping_Muscle_Up',387) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rodilla cruzada','estatico','principiante','Ninguno','Ninguno','[\"gluteos\"]','[\"abductores\", \"espalda_baja\"]','[\"Acuestate en el suelo con la pierna derecha estirada. Dobla la pierna izquierda y bajala cruzandola por el cuerpo, sujetando la rodilla hacia el suelo con la mano derecha. (No es necesario que la rodilla toque el suelo si estas tenso).\", \"Coloca el brazo izquierdo comodamente a tu lado y gira la cabeza hacia la izquierda. Imagina que tienes un peso atado al coxis. Deja que el coxis caiga hacia el suelo mientras el pecho se estira en la direccion opuesta para estirar la zona lumbar. Cambia de lado.\"]','estiramiento','[\"Knee_Across_The_Body/0.jpg\", \"Knee_Across_The_Body/1.jpg\"]','Rodilla a lo largo del cuerpo',388) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos con las rodillas','traccion','principiante','compuesto','solo_cuerpo','[\"pantorrillas\"]','[\"isquiotibiales\", \"cuadriceps\"]','[\"Ponte de pie con las piernas juntas y las manos en la cintura.\", \"Ahora mueve las rodillas con un movimiento circular mientras respiras normalmente.\", \"Repite durante el numero recomendado de repeticiones.\"]','estiramiento','[\"Knee_Circles/0.jpg\", \"Knee_Circles/1.jpg\"]','Circulos con las rodillas',389) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de rodillas/caderas en barras paralelas','traccion','principiante','aislamiento','otro','[\"abdominales\"]','[]','[\"Coloca tu cuerpo en el banco de elevacion vertical de piernas de modo que tus antebrazos descansen sobre las almohadillas junto al torso y sujetandote a las asas. Tus brazos estaran doblados en un angulo de 90 grados.\", \"El torso debe estar recto con la parte inferior de la espalda presionada contra la almohadilla de la maquina y las piernas extendidas apuntando hacia el suelo. Esta sera tu posicion inicial.\", \"Ahora, mientras exhalas, levanta las piernas hacia arriba manteniendolas extendidas. Continua este movimiento hasta que tus piernas esten aproximadamente paralelas al suelo y luego manten la contraccion durante un segundo. Consejo: No utilices ningun impulso ni balanceo al realizar este ejercicio.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Knee_Hip_Raise_On_Parallel_Bars/0.jpg\", \"Knee_Hip_Raise_On_Parallel_Bars/1.jpg\"]','Elevacion de rodillas y caderas en barras paralelas',390) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ejercicio de brazos arrodillado','traccion','principiante','Ninguno','Ninguno','[\"hombros\"]','[\"abdominales\"]','[\"Este ejercicio ayuda a aumentar la eficiencia de los brazos durante la carrera. Comienza arrodillado, con el pie izquierdo delante y la rodilla derecha hacia abajo. Aplica presion a traves del talon delantero para mantener activados los gluteos y los isquiotibiales.\", \"Comienza bloqueando los brazos en largos movimientos pendulares. Cierra el angulo de los brazos, bloqueandolos como lo harias al trotar, pasando a correr y finalmente a esprintar.\", \"Tan pronto como tus manos pasen la cadera, aceleralas hacia adelante durante el movimiento de esprint para moverlas lo mas rapido posible.\", \"Cambia de rodilla y repite.\"]','pliometria','[\"Kneeling_Arm_Drill/0.jpg\", \"Kneeling_Arm_Drill/1.jpg\"]','Ejercicio de brazos arrodillado',392) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps de rodillas en polea','empuje','intermedio','aislamiento','polea','[\"triceps\"]','[]','[\"Coloca un banco de lado frente a una maquina de polea alta.\", \"Sujeta un accesorio de barra recta por encima de tu cabeza con las manos separadas aproximadamente 15 cm y las palmas hacia abajo.\", \"Colocate de espaldas a la maquina y arrodillate.\", \"Coloca tu cabeza y la parte superior de tus brazos en el banco. Los codos deben estar doblados con los antebrazos apuntando hacia la polea alta. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos cerca de la cabeza en todo momento con los codos hacia dentro, empuja la barra hacia fuera con un movimiento semicircular hasta que los codos esten bloqueados y los brazos paralelos al suelo. Contrae los triceps con fuerza y manten esta posicion durante un segundo. Exhala mientras realizas este movimiento.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Kneeling_Cable_Triceps_Extension/0.jpg\", \"Kneeling_Cable_Triceps_Extension/1.jpg\"]','Extension de triceps con cable de rodillas',394) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de antebrazos de rodillas','estatico','principiante','aislamiento','Ninguno','[\"antebrazos\"]','[]','[\"Comienza arrodillandote en una colchoneta con las palmas de las manos planas y los dedos apuntando hacia tus rodillas.\", \"Inclinate lentamente hacia atras manteniendo las palmas de las manos planas en el suelo hasta que sientas un estiramiento en tus muñecas y antebrazos. Manten la posicion durante 20-30 segundos.\"]','estiramiento','[\"Estiramiento_del_antebrazo_de_rodillas/0.jpg\", \"Estiramiento_del_antebrazo_de_rodillas/1.jpg\"]','Estiramiento de antebrazos de rodillas',395) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de cadera de rodillas','estatico','principiante','aislamiento','Ninguno','[\"cuadriceps\"]','[\"cuadriceps\"]','[\"Arrodillate en una colchoneta y lleva la rodilla derecha hacia arriba, de modo que la planta del pie quede en el suelo, y extiende la pierna izquierda hacia atras, de modo que la parte superior del pie quede en el suelo.\", \"Desplaza tu peso hacia delante hasta que sientas un estiramiento en la cadera. Manten la posicion durante 15 segundos y luego repite con el otro lado.\"]','estiramiento','[\"Flexor de cadera de rodillas/0.jpg\", \"Flexor de cadera de rodillas/1.jpg\"]','Flexor de cadera arrodillado',397) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto de rodillas Sentadilla','empuje','experto','compuesto','barra','[\"gluteos\"]','[\"Pantorrillas\", \"isquiotibiales\", \"cuadriceps\"]','[\"Comienza arrodillado en el suelo con una barra apoyada en la espalda sobre tus hombros, o puedes usar el peso de tu cuerpo durante este ejercicio. Esto se puede hacer dentro de una jaula de potencia para facilitar la extraccion.\", \"Sientate con la espalda y las caderas hasta que tus gluteos toquen tus pies, manteniendo la cabeza y el pecho erguidos.\", \"Explota hacia arriba con tus caderas, generando suficiente potencia para aterrizar con los pies planos en el suelo.\", \"Continua con la sentadilla impulsandote con los talones y extendiendo las rodillas para llegar a una posicion de pie.\"]','halterofilia_olimpica','[\"Kneeling_Jump_Squat/0.jpg\", \"Kneeling_Jump_Squat/1.jpg\"]','Sentadilla con salto de rodillas',398) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo de una sola mano con polea alta de rodillas','traccion','principiante','compuesto','polea','[\"dorsales\"]','[\"biceps\", \"espalda_media\"]','[\"Conecta una sola manija a una polea alta y selecciona el peso.\", \"Arrodillate frente a la torre de poleas, tomando la polea con una mano con el brazo extendido. Esta sera tu posicion inicial.\", \"Comenzando con la palma de la mano hacia adelante, tira del peso hacia abajo hacia tu torso flexionando el codo y retrae el omoplato. Mientras lo haces, gira la muñeca para que, al completar el movimiento, la palma de la mano quede mirando hacia ti.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"Kneeling_Single-Arm_High_Pulley_Row/0.jpg\", \"Kneeling_Single-Arm_High_Pulley_Row/1.jpg\"]','Remo de rodillas con un solo brazo en polea alta',399) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla de rodillas','empuje','intermedio','compuesto','barra','[\"gluteos\"]','[\"abdominales\", \"isquiotibiales\", \"espalda_baja\"]','[\"Coloca la barra a la altura adecuada en una jaula de potencia. Arrodillate detras de la barra; puede ser beneficioso colocar una colchoneta debajo para proteger tus rodillas. Deslizate por debajo de la barra, colocandola sobre la espalda de tus hombros. Los omoplatos deben estar retraidos y la barra ajustada a la espalda. Levanta el peso.\", \"Con la cabeza mirando hacia delante, sientate con el trasero hasta que toque las pantorrillas.\", \"Invierte el movimiento, volviendo el torso a una posicion erguida.\"]','levantamiento de pesas','[\"Kneeling_Squat/0.jpg\", \"Kneeling_Squat/1.jpg\"]','Sentadilla de rodillas',400) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Landmine 180','traccion','principiante','compuesto','barra','[\"abdominales\"]','[\"gluteos\", \"espalda_baja\", \"hombros\"]','[\"Coloca una barra en una landmine o fijala bien en una esquina. Carga la barra con un peso adecuado.\", \"Levanta la barra del suelo, llevandola a la altura de los hombros con ambas manos y los brazos extendidos frente a ti. Adopta una postura amplia. Esta sera tu posicion inicial.\", \"Realiza el movimiento girando el tronco y las caderas mientras balanceas el peso completamente hacia un lado. Manten tus brazos extendidos durante todo el ejercicio.\", \"Invierte el movimiento para balancear el peso completamente hacia el lado opuesto.\", \"Continua alternando el movimiento hasta completar la serie.\"]','fuerza','[\"Landmine_180s/0.jpg\", \"Landmine_180s/1.jpg\"]','Landmine_180s',401) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto lateral','empuje','principiante','compuesto','solo_cuerpo','[\"aductores\"]','[\"abductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Asume una posicion de media sentadilla mirando a 90 grados de tu direccion de desplazamiento. Esta sera tu posicion inicial.\", \"Deja que tu pierna delantera haga un movimiento contrario hacia dentro mientras desplazas tu peso hacia la pierna exterior.\", \"Empuja inmediatamente y extiende, intentando saltar al lado tan lejos como sea posible.\", \"Al aterrizar, empuja inmediatamente en la direccion opuesta, volviendo a tu posicion inicial original.\", \"Continua adelante y atras durante varias repeticiones.\"]','pliometria','[\"Lateral_Bound/0.jpg\", \"Lateral_Bound/1.jpg\"]','Salto lateral',403) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto lateral sobre caja','empuje','principiante','compuesto','otro','[\"aductores\"]','[\"abductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Adopta una posicion comoda de pie, con una caja pequeña colocada a tu lado. Esta sera tu posicion inicial.\", \"Haz una sentadilla rapida para iniciar el reflejo de estiramiento e inmediatamente cambia de direccion para saltar hacia arriba y hacia un lado.\", \"Levanta las rodillas lo suficiente para asegurarte de que tus pies tengan suficiente espacio sobre la caja.\", \"Aterriza en el centro de la caja, utilizando tus piernas para absorber el impacto.\", \"Salta con cuidado al otro lado de la caja y continua yendo hacia adelante y hacia atras durante varias repeticiones.\"]','pliometria','[\"Lateral_Box_Jump/0.jpg\", \"Lateral_Box_Jump/1.jpg\"]','Salto lateral sobre caja',404) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Saltos laterales con conos','empuje','principiante','compuesto','otro','[\"aductores\"]','[\"abductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"cuadriceps\"]','[\"Coloca varios conos en fila a varios pies de distancia entre si.\", \"Ponte de pie junto al extremo de los conos, mirando en angulo de 90 grados con respecto a la direccion del movimiento. Esta sera tu posicion inicial.\", \"Comienza el salto flexionando las rodillas para iniciar un reflejo de estiramiento, e inmediatamente invierte la direccion para impulsarte del suelo, saltando hacia arriba y hacia un lado por encima del cono.\", \"Utiliza tus piernas para absorber el impacto al aterrizar, y rebota hacia el siguiente salto, continuando por la fila de conos.\"]','pliometria','[\"Lateral_Cone_Hops/0.jpg\", \"Lateral_Cone_Hops/1.jpg\"]','Saltos laterales con conos',405) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion lateral - Con bandas','empuje','principiante','aislamiento','bandas','[\"hombros\"]','[]','[\"Para empezar, ponte de pie sobre una banda elastica de modo que la tension comience a la longitud del brazo. Agarra las asas con un agarre pronado (las palmas mirando hacia los muslos) que sea ligeramente inferior a la anchura de los hombros. Las asas deben descansar en los lados de los muslos. Tus brazos deben estar extendidos con una ligera flexion en los codos y tu espalda debe estar recta. Esta sera tu posicion inicial.\", \"Usa tus hombros para levantar las asas a los lados mientras exhalas. Continua levantando las asas hasta que esten ligeramente por encima de la posicion paralela. Consejo: A medida que levantas las asas, inclina ligeramente la mano como si estuvieras vertiendo agua y manten los brazos extendidos. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja los mangos lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lateral_Raise_-_With_Bands/0.jpg\", \"Lateral_Raise_-_With_Bands/1.jpg\"]','Elevacion lateral con bandas',406) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Latissimus Dorsi-SMR','estatico','principiante','aislamiento','rodillo_espuma','[\"dorsales\"]','[]','[\"Mientras estas tumbado en el suelo, coloca un rodillo de espuma debajo de la espalda y a un lado, justo detras de la axila. Esta sera tu posicion inicial.\", \"Manten el brazo del lado que estas estirando detras y al lado de ti mientras desplazas tu peso hacia los dorsales, manteniendo la parte superior del cuerpo separada del suelo. Manten durante 10-30 segundos y cambia de lado.\"]','estiramiento','[\"Latissimus_Dorsi-SMR/0.jpg\", \"Latissimus_Dorsi-SMR/1.jpg\"]','Latissimus_Dorsi-SMR',407) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Leg Pull-In','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en una colchoneta de ejercicios con las piernas extendidas y las manos con las palmas hacia abajo a los lados o debajo de los gluteos. Consejo: Yo prefiero tener las manos a los lados. Esta sera tu posicion inicial.\", \"Dobla las rodillas y lleva la parte superior de los muslos hacia el abdomen mientras exhalas. Continua el movimiento hasta que tus rodillas esten a la altura del pecho. Contrae los abdominales mientras ejecutas este movimiento y manten la posicion durante un segundo en la parte superior. Consejo: Mientras realizas el movimiento, la parte inferior de las piernas (pantorrillas) debe permanecer siempre paralela al suelo.\", \"Vuelve a la posicion inicial mientras inhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Leg_Pull-In/0.jpg\", \"Leg_Pull-In/1.jpg\"]','Leg_Pull-In',411) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Leg-Over Floor Press','empuje','intermedio','compuesto','pesas rusas','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate en el suelo con una pesa rusa colocada sobre tu pecho, sujetandola por el asa. Extiende la pierna del lado de trabajo sobre la pierna del lado contrario. El brazo libre se puede extender hacia un lado para apoyarte.\", \"Presiona la pesa rusa hasta bloquearla en posicion.\", \"Baja el peso hasta que el codo toque el suelo, manteniendo la pesa rusa por encima del codo. Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Leg-Over_Floor_Press/0.jpg\", \"Leg-Over_Floor_Press/1.jpg\"]','Press de piernas sobre el suelo',412) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de isquiotibiales con pierna levantada','empuje','principiante','aislamiento','Ninguno','[\"isquiotibiales\"]','[]','[\"Acuestate boca arriba, dobla una rodilla y apoya el pie en el suelo para estabilizar la columna.\", \"Extiende la otra pierna en el aire. Si estas tenso, no podras estirarla. No pasa nada. Extiende la rodilla de modo que la planta del pie levantado quede mirando hacia el techo (o lo mas cerca posible).\", \"Estira lentamente las piernas tanto como puedas y luego lleva la pierna hacia la nariz. Cambia de lado.\"]','estiramiento','[\"Leg-Up_Hamstring_Stretch/0.jpg\", \"Leg-Up_Hamstring_Stretch/1.jpg\"]','Leg-Up_Hamstring_Stretch',413) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Apalancamiento con press de pecho','empuje','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Carga un peso adecuado en los pasadores y ajusta el asiento a tu altura. Las asas deben estar cerca de la parte inferior o media de los pectorales al comienzo del movimiento.\", \"Tu pecho y cabeza deben estar arriba y tus omoplatos retraidos. Esta sera tu posicion inicial.\", \"Presiona las manijas hacia adelante extendiendo los codos.\", \"Despues de una breve pausa en la parte superior, devuelve el peso justo por encima de la posicion inicial, manteniendo la tension en los musculos y sin devolver el peso hasta los topes hasta completar la serie.\"]','fuerza','[\"Leverage_Chest_Press/0.jpg\", \"Leverage_Chest_Press/1.jpg\"]','Press de pecho con palanca',414) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Leverage Peso Muerto','traccion','principiante','compuesto','maquina','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Carga los pasadores con un peso adecuado. Colocate directamente entre las asas. Agarra las asas inferiores con un agarre comodo y luego baja las caderas mientras respiras. Mira hacia delante con la cabeza y manten el pecho erguido. Esta sera tu posicion inicial.\", \"Vuelve a colocar el peso en la posicion inicial.\"]','fuerza','[\"Leverage_Deadlift/0.jpg\", \"Leverage_Deadlift/1.jpg\"]','Peso muerto con palanca',415) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Leverage Declinado Pecho Press','empuje','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Carga un peso adecuado en los pasadores y ajusta el asiento a tu altura. Las asas deben estar cerca de la parte inferior de los pectorales al comienzo del movimiento. Tu pecho y cabeza deben estar arriba y tus omoplatos retraidos. Esta sera tu posicion inicial.\", \"Presiona las asas hacia adelante extendiendo los codos.\", \"Despues de una breve pausa en la parte superior, devuelve el peso justo por encima de la posicion inicial, manteniendo la tension en los musculos y sin devolver el peso hasta los topes hasta que se complete la serie.\"]','fuerza','[\"Leverage_Decline_Chest_Press/0.jpg\", \"Leverage_Decline_Chest_Press/1.jpg\"]','Press de pecho declinado con palanca',416) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo alto con palanca','traccion','principiante','compuesto','maquina','[\"espalda_media\"]','[\"dorsales\"]','[\"Carga un peso adecuado en los pasadores y ajusta la altura del asiento para que puedas alcanzar las asas que tienes encima. Ajusta la rodillera para ayudarte a mantenerte abajo. Agarra las asas con un agarre pronado. Esta sera tu posicion inicial.\", \"Tira de las asas hacia tu torso, retraiendo los omoplatos mientras flexionas el codo.\", \"Haz una pausa en la parte inferior del movimiento y luego devuelve lentamente las asas a la posicion inicial.\", \"Para multiples repeticiones, evita devolver completamente el peso a los topes para mantener la tension en los musculos que se estan trabajando.\"]','fuerza','[\"Leverage_High_Row/0.jpg\", \"Leverage_High_Row/1.jpg\"]','Remo alto con palanca',417) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inclinado con palanca','empuje','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Carga un peso adecuado en los pasadores y ajusta el asiento a tu altura. Las manijas deben estar cerca de la parte superior de los pectorales al comienzo del movimiento. El pecho y la cabeza deben estar arriba y los omoplatos retraidos. Esta sera tu posicion inicial.\", \"Presiona las asas hacia adelante extendiendo los codos.\", \"Despues de una breve pausa en la parte superior, devuelve el peso justo por encima de la posicion inicial, manteniendo la tension en los musculos y sin devolver el peso hasta los topes hasta completar la serie.\"]','fuerza','[\"Leverage_Incline_Chest_Press/0.jpg\", \"Leverage_Incline_Chest_Press/1.jpg\"]','Press de pecho inclinado con palanca',418) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo isometrico con palanca','traccion','principiante','compuesto','maquina','[\"dorsales\"]','[\"biceps\", \"espalda_media\"]','[\"Carga un peso adecuado en los pasadores y ajusta la altura del asiento para que las asas esten al nivel del pecho. Agarra las asas con un agarre neutro o pronado. Esta sera tu posicion inicial.\", \"Tira de las asas hacia tu torso, retraiendo los omoplatos mientras flexionas el codo.\", \"Haz una pausa en la parte inferior del movimiento y luego devuelve lentamente las asas a la posicion inicial. Para realizar varias repeticiones, evita devolver completamente el peso hasta los topes para mantener la tension en los musculos que se estan trabajando.\"]','fuerza','[\"Leverage_Iso_Row/0.jpg\", \"Leverage_Iso_Row/1.jpg\"]','Remo con palanca',419) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros con palanca','traccion','principiante','aislamiento','maquina','[\"trapecios\"]','[\"antebrazos\"]','[\"Carga los pines con un peso adecuado. Colocate directamente entre las asas.\", \"Agarra las asas superiores con un agarre comodo y luego baja las caderas mientras respiras. Mira hacia delante con la cabeza y manten el pecho erguido.\", \"Empuja el suelo con los talones, extendiendo las caderas y las rodillas mientras te levantas hasta quedar de pie. Manten los brazos rectos durante todo el movimiento, terminando con los hombros hacia atras. Esta sera tu posicion inicial.\", \"Levanta el peso encogiendo los hombros hacia las orejas, moviendolos recto hacia arriba y hacia abajo.\", \"Haz una pausa en la parte superior del movimiento y luego vuelve a colocar el peso en la posicion inicial.\"]','fuerza','[\"Leverage_Shrug/0.jpg\", \"Leverage_Shrug/1.jpg\"]','Leverage_Shrug',421) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tecnica lineal de inicio en 3 partes','empuje','principiante','compuesto','Ninguno','[\"isquiotibiales\"]','[\"pantorrillas\", \"cuadriceps\"]','[\"Este ejercicio te ayuda a acelerar lo mas rapido posible en un sprint desde una parada completa. Es util utilizar una linea como punto de partida. Comienza con los dos pies en la linea. Coloca el pie izquierdo con el dedo del pie junto al tobillo derecho. Coloca el pie derecho entre 10 y 15 cm detras del izquierdo.\", \"Coloca la mano derecha sobre la linea y acerca la nariz a la rodilla izquierda.\", \"Haz una sentadilla mientras te inclinas hacia delante, con la cabeza mas baja que las caderas y el peso sobre la pierna izquierda. Esta sera tu posicion inicial.\", \"Levanta la mano izquierda hasta que quede paralela al suelo, apuntando hacia atras, y explota cuando estes listo.\"]','pliometria','[\"Linear_3-Part_Start_Technique/0.jpg\", \"Linear_3-Part_Start_Technique/1.jpg\"]','Tecnica de salida lineal en tres partes',422) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Mirando al techo','estatico','principiante','aislamiento','Ninguno','[\"cuadriceps\"]','[]','[\"Arrodillate en el suelo, sosteniendo tus talones con ambas manos.\", \"Eleva tus nalgas hacia arriba y hacia adelante mientras llevas la cabeza hacia atras para mirar hacia arriba al techo, para arquear la espalda.\"]','estiramiento','[\"Mirando_al_techo/0.jpg\", \"Mirando_al_techo/1.jpg\"]','Mirando_al_techo',427) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bajo en polea cruzada','empuje','principiante','aislamiento','polea','[\"pecho\"]','[\"hombros\"]','[\"Para colocarte en la posicion inicial, coloca las poleas en la posicion baja, selecciona la resistencia que vas a utilizar y agarra un mango con cada mano.\", \"Da un paso adelante, tensando las poleas. Las palmas de las manos deben mirar hacia delante, las manos por debajo de la cintura y los brazos estirados. Esta sera tu posicion inicial.\", \"Con los brazos ligeramente flexionados, lleva las manos hacia arriba y hacia la linea media del cuerpo. Tus manos deben juntarse frente a tu pecho, con las palmas hacia arriba.\", \"Vuelve tus brazos a la posicion inicial despues de una breve pausa.\"]','fuerza','[\"Low_Cable_Crossover/0.jpg\", \"Low_Cable_Crossover/1.jpg\"]','Cruce bajo con cable',428) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de espalda inferior','estatico','principiante','Ninguno','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate boca abajo con los brazos extendidos a los lados. Esta sera tu posicion inicial.\", \"Utilizando los musculos inferiores de la espalda, extiende la columna levantando el pecho del suelo. No utilices los brazos para impulsarte. Manten la cabeza levantada durante el movimiento. Repite entre 10 y 20 repeticiones.\"]','estiramiento','[\"Lower_Back_Curl/0.jpg\", \"Lower_Back_Curl/1.jpg\"]','Flexion de espalda baja',431) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lower Back-SMR','estatico','principiante','Ninguno','rodillo_espuma','[\"espalda_baja\"]','[]','[\"En posicion sentada, coloca un rodillo de espuma debajo de la parte baja de la espalda. Cruza los brazos frente a ti y protrae los hombros. Esta sera tu posicion inicial.\", \"Levanta las caderas del suelo e inclinate hacia atras, manteniendo el peso en la parte baja de la espalda. Ahora desplaza ligeramente el peso hacia un lado, manteniendo el peso fuera de la columna vertebral y en los musculos adyacentes a ella. Rueda sobre la parte baja de la espalda, sosteniendo los puntos de tension durante 10-30 segundos. Repite en el otro lado.\"]','estiramiento','[\"Lower_Back-SMR/0.jpg\", \"Lower_Back-SMR/1.jpg\"]','Lower_Back-SMR',432) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancada Pass Through','empuje','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\", \"Cuadriceps\"]','[\"Ponte de pie con el torso erguido sosteniendo una pesa rusa en la mano derecha. Esta sera tu posicion inicial.\", \"Da un paso adelante con el pie izquierdo y baja la parte superior del cuerpo flexionando la cadera y la rodilla, manteniendo el torso erguido. Baja la rodilla trasera hasta que casi toque el suelo.\", \"Mientras das la zancada, pasa la pesa rusa por debajo de la pierna delantera a la mano opuesta.\", \"Empujando con el talon del pie, vuelve a la posicion inicial.\", \"Repite el movimiento durante el numero recomendado de repeticiones, alternando las piernas.\"]','fuerza','[\"Lunge_Pass_Through/0.jpg\", \"Lunge_Pass_Through/1.jpg\"]','Zancada con paso',433) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Zancada Sprint','empuje','intermedio','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ajusta una barra en una maquina Smith a una altura adecuada. Colocate debajo de la barra, colocandola sobre la espalda de tus hombros. Desengancha la barra y luego separa los pies, moviendo un pie hacia adelante y otro hacia atras. Esta sera tu posicion inicial.\", \"Baja la rodilla trasera casi hasta el suelo, flexionando las rodillas y bajando las caderas al hacerlo.\", \"En la parte inferior del descenso, invierte inmediatamente la direccion. Impulsa explosivamente el talon del pie delantero con una ligera presion del pie trasero. Salta hacia arriba e invierte la posicion de las piernas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Lunge_Sprint/0.jpg\", \"Lunge_Sprint/1.jpg\"]','Zancada_Sprint',434) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lying Bent Pierna Groin','estatico','experto','Ninguno','otro','[\"aductores\"]','[]','[\"Acuestate boca arriba con tus rodillas dobladas y las plantas de los pies juntas. Pide a tu compañero que te sujete las rodillas. Esta sera tu posicion inicial.\", \"Intenta apretar las rodillas, mientras tu compañero evita que se produzca cualquier movimiento.\", \"Despues de 10-20 segundos, relaja los musculos mientras tu compañero empuja suavemente tus rodillas hacia el suelo. Asegurate de informar a tu compañero cuando el estiramiento sea adecuado para evitar lesiones o estiramientos excesivos.\"]','estiramiento','[\"Lying_Bent_Leg_Groin/0.jpg\", \"Lying_Bent_Leg_Groin/1.jpg\"]','Lying_Bent_Leg_Groin',435) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Recostado en polea Curl','traccion','intermedio','aislamiento','polea','[\"biceps\"]','[]','[\"Agarra una barra recta o un accesorio de barra E-Z que este conectado a la polea baja con ambas manos, utilizando un agarre por debajo (palmas hacia arriba) a la altura de los hombros.\", \"Tumbate boca arriba sobre una colchoneta de ejercicios frente a la pila de pesas con los pies apoyados en el marco de la maquina de poleas y las piernas estiradas.\", \"Con los brazos extendidos y los codos pegados al cuerpo, flexiona ligeramente los brazos. Esta sera tu posicion inicial.\", \"Mientras mantienes la parte superior de los brazos fijos y los codos cerca del cuerpo, flexiona la barra lentamente hacia el pecho mientras exhalas y contraes los biceps.\", \"Despues de una segunda contraccion en la parte superior del movimiento, vuelve lentamente a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Lying_Cable_Curl/0.jpg\", \"Lying_Cable_Curl/1.jpg\"]','Flexion con cable tumbado',436) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lying Cambered con Barra Remo','traccion','principiante','aislamiento','barra','[\"espalda_media\"]','[\"biceps\", \"dorsales\", \"trapecios\"]','[\"Coloca una barra curvada debajo de un banco de ejercicios.\", \"Acuestate boca abajo en el banco de ejercicios y agarra la barra con las palmas hacia abajo (agarre pronado) a una distancia mayor que el ancho de los hombros. Esta sera tu posicion inicial.\", \"Mientras exhalas, rema la barra hacia arriba manteniendo los codos cerca del cuerpo, ya sea hacia el pecho, para trabajar la parte superior media de la espalda, o hacia el estomago, si tu objetivo es trabajar los dorsales.\", \"Despues de un segundo en la parte superior, baja lentamente hacia la posicion inicial mientras inhalas.\"]','fuerza','[\"Lying_Cambered_Barbell_Row/0.jpg\", \"Lying_Cambered_Barbell_Row/1.jpg\"]','Remo con barra en barra inclinada tumbado',437) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con barra y agarre cerrado tumbado en polea alta','traccion','principiante','aislamiento','polea','[\"biceps\"]','[]','[\"Coloca un banco plano frente a una polea alta o una maquina de jalon lateral.\", \"Sujeta el accesorio de barra recta con un agarre por debajo (palmas hacia arriba) que sea aproximadamente del ancho de los hombros.\", \"Acuestate boca arriba con la cabeza sobre el extremo del banco.\", \"Ahora extiende los brazos rectos por encima de los hombros. Tu torso y tus brazos deben formar un angulo de 90 grados y los codos deben estar hacia dentro. Esta sera tu posicion inicial.\", \"Mientras exhalas, flexiona la barra hacia abajo con un movimiento semicircular hasta que toque tu barbilla. Contrae los biceps durante un segundo en la posicion superior contraida. Consejo: Mientras ejecutas este movimiento, solo deben moverse los antebrazos. En ningun momento deben moverse los brazos superiores. Deben permanecer perpendiculares durante todo el movimiento.\", \"Regresa a la posicion inicial lentamente.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_Close-Grip_Bar_Curl_On_High_Pulley/0.jpg\", \"Lying_Close-Grip_Bar_Curl_On_High_Pulley/1.jpg\"]','Curl con barra y agarre cerrado tumbado en polea alta',438) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con barra y agarre cerrado detras de la cabeza','empuje','intermedio','aislamiento','barra','[\"triceps\"]','[]','[\"Mientras sostienes una barra o barra EZ Curl con un agarre pronado (las palmas mirando hacia adelante), acuestate boca arriba en un banco plano con la cabeza cerca del extremo del banco. Consejo: Si estas sosteniendo una barra, agarrala con un agarre a la anchura de los hombros y, si estas utilizando una barra EZ, agarrala por las asas interiores.\", \"Extiende los brazos frente a ti y lleva lentamente la barra hacia atras con un movimiento semicircular (mientras mantienes los brazos extendidos) hasta una posicion por encima de la cabeza. Al final de este paso, tus brazos deben estar sobre la cabeza y paralelos al suelo. Esta sera tu posicion inicial. Consejo: Manten los codos hacia dentro en todo momento.\", \"Mientras inhalas, baja la barra doblando los codos y manteniendo la parte superior del brazo fija. Sigue bajando la barra hasta que tus antebrazos esten perpendiculares al suelo.\", \"Mientras exhalas, lleva la barra hacia arriba hasta la posicion inicial empujando la barra hacia arriba con un movimiento semicircular hasta que la parte inferior de los brazos tambien este paralela al suelo. Contract the triceps hard en la parte superior of the movimiento durante a segundo. Consejo: Again, solo the antebrazos should move. The upper brazos should remain stationary at todos times.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/0.jpg\", \"Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head/1.jpg\"]','Extension de triceps con barra y agarre cerrado tumbado detras de la cabeza',439) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con barra y agarre cerrado tumbado hasta la barbilla','empuje','intermedio','aislamiento','barra_ez','[\"triceps\"]','[]','[\"Mientras sostienes una barra o barra EZ Curl con un agarre pronado (las palmas mirando hacia adelante), acuestate boca arriba en un banco plano con la cabeza fuera del extremo del banco. Consejo: Si estas sosteniendo una barra, agarrala con un agarre a la anchura de los hombros y si estas usando una barra EZ, agarrala por las asas interiores.\", \"Extiende los brazos frente a ti mientras mantienes la barra sobre tu pecho. Los brazos deben estar perpendiculares al torso (angulo de 90 grados). Esta sera tu posicion inicial.\", \"Mientras inhalas, baja la barra con un movimiento semicircular doblando los codos y manteniendo los brazos fijos y los codos hacia dentro. Sigue bajando la barra hasta que toque ligeramente tu barbilla.\", \"Mientras exhalas, lleva la barra hacia arriba hasta la posicion inicial empujando la barra hacia arriba con un movimiento semicircular. Contrae los triceps con fuerza en la parte superior del movimiento durante un segundo. Consejo: Una vez mas, solo deben moverse los antebrazos. Los brazos superiores deben permanecer inmoviles en todo momento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Press de triceps con barra y agarre cerrado tumbado hasta la barbilla/0.jpg\", \"Press de triceps con barra y agarre cerrado tumbado hasta la barbilla/1.jpg\"]','Press de triceps con barra y agarre cerrado tumbado hasta la barbilla',440) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cruce tumbado','estatico','experto','Ninguno','solo_cuerpo','[\"abductores\"]','[]','[\"Acuestate boca arriba con tus piernas extendidas.\", \"Cruza una pierna sobre tu cuerpo con la rodilla doblada, intentando tocar el suelo con la rodilla. Tu compañero debe arrodillarse a tu lado, sosteniendo tu hombro abajo con una mano y controlando la pierna cruzada con la otra. Esta sera tu posicion inicial.\", \"Intenta levantar la rodilla doblada del suelo mientras tu compañero impide cualquier movimiento real.\", \"Despues de 10-20 segundos, relaja la pierna mientras tu compañero presiona suavemente la rodilla hacia el suelo. Repite con el otro lado.\"]','estiramiento','[\"Lying_Crossover/0.jpg\", \"Lying_Crossover/1.jpg\"]','Crossover tumbado',441) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps tumbado con mancuernas','empuje','intermedio','aislamiento','mancuerna','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Acuestese en un banco plano mientras sostiene dos mancuernas directamente frente a usted. Sus brazos deben estar completamente extendidos en un angulo de 90 grados con respecto a su torso y el suelo. Las palmas deben estar hacia adentro y los codos deben estar pegados al cuerpo. Esta es la posicion inicial.\", \"Mientras inhalas y mantienes los brazos superiores fijos con los codos pegados al cuerpo, baja lentamente el peso hasta que las mancuernas esten cerca de tus orejas.\", \"En ese momento, mientras mantienes los codos pegados al cuerpo y los brazos superiores fijos, utiliza los triceps para llevar el peso hacia arriba hasta la posicion inicial mientras exhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_Dumbbell_Tricep_Extension/0.jpg\", \"Lying_Dumbbell_Tricep_Extension/1.jpg\"]','Extension de triceps con mancuernas tumbado',442) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Resistencia del cuello con placa tumbado boca arriba','traccion','intermedio','aislamiento','otro','[\"cuello\"]','[]','[\"Acuestate boca arriba con todo el cuerpo recto en un banco plano mientras sostienes una placa de peso sobre la frente. Consejo: Tendras que colocarte de manera que tus hombros esten ligeramente por encima del extremo del banco plano para que los trapecios, el cuello y la cabeza queden fuera del banco. Esta sera tu posicion inicial.\", \"Mientras mantienes la placa fija en la frente, baja lentamente la cabeza hacia atras con un movimiento semicircular mientras inhalas.\", \"Levanta la cabeza hacia atras hasta la posicion inicial con un movimiento semicircular mientras exhalas. Manten la contraccion durante un segundo.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Lying_Face_Up_Plate_Neck_Resistance/0.jpg\", \"Lying_Face_Up_Plate_Neck_Resistance/1.jpg\"]','Resistencia del cuello con placa tumbado boca arriba',444) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Gluteos tumbado','estatico','experto','Ninguno','solo_cuerpo','[\"gluteos\"]','[\"abductores\"]','[\"Acuestate boca arriba con tu compañero arrodillado a tu lado.\", \"Flexiona la cadera de una pierna, levantandola del suelo. Gira la pierna de modo que el pie quede sobre la cadera opuesta, con la parte inferior de la pierna perpendicular a tu cuerpo. Tu compañero debe mantener la rodilla y el tobillo en su sitio. Esta sera tu posicion inicial.\", \"Intenta empujar la pierna hacia tu compañero, que debe impedir cualquier movimiento real de la pierna.\", \"Despues de 10-20 segundos, relajate completamente mientras tu compañero empuja suavemente el tobillo y la rodilla hacia tu pecho. Asegurate de informar a tu compañero cuando el estiramiento sea adecuado para evitar lesiones o estiramientos excesivos.\"]','estiramiento','[\"Lying_Glute/0.jpg\", \"Lying_Glute/1.jpg\"]','Gluteo tumbado',445) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Isquiotibiales tumbado','estatico','experto','Ninguno','otro','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"Acuestate boca arriba con tus piernas extendidas. Tu compañero debe estar arrodillado a tu lado. Levanta una pierna hacia el techo y haz que tu compañero te sujete el tobillo. Tu compañero puede usar su hombro para sujetar tu pierna si es necesario. Esta sera tu posicion inicial.\", \"Con tu compañero sosteniendo tu pierna en su sitio, intenta flexionar la rodilla, contrayendo los isquiotibiales durante 10-20 segundos.\", \"A continuacion, relaja la pierna, permitiendo que tu compañero empuje suavemente la pierna hacia tu cabeza. Asegurate de informar a tu compañero cuando el estiramiento sea adecuado para evitar lesiones o estiramientos excesivos. Cambia de lado una vez completado.\"]','estiramiento','[\"Lying_Hamstring/0.jpg\", \"Lying_Hamstring/1.jpg\"]','Isquiotibiales tumbado',446) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de barra en banco alto tumbado','traccion','intermedio','aislamiento','barra','[\"biceps\"]','[]','[\"Acuestese boca arriba en un banco plano alto mientras sostiene una barra con un agarre supinado (las palmas hacia arriba). Consejo: Si esta sosteniendo una barra, agarrela con un agarre a la anchura de los hombros y, si esta utilizando una barra E-Z, agarrela por las asas interiores. La parte superior del cuerpo debe colocarse de manera que la parte superior del pecho quede sobre el extremo del banco y la barra cuelgue frente a ti con los brazos extendidos y perpendiculares al suelo. Esta sera tu posicion inicial.\", \"Mientras mantienes los codos y la parte superior de los brazos fijos, flexiona el peso hacia arriba con un movimiento semicircular mientras contraes los biceps y exhalas. Manten en la parte superior del movimiento durante un segundo.\", \"Mientras inhalas, vuelve lentamente a la posicion inicial. Consejo: Manten el control total del peso en todo momento y evita cualquier balanceo. Recuerda, solo los antebrazos deben moverse durante todo el movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_High_Bench_Barbell_Curl/0.jpg\", \"Lying_High_Bench_Barbell_Curl/1.jpg\"]','Curl con barra en banco alto tumbado',447) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de piernas tumbado','traccion','principiante','aislamiento','maquina','[\"isquiotibiales\"]','[]','[\"Ajusta la palanca de la maquina a tu altura y tumbate boca abajo en la maquina de flexion de piernas con la almohadilla de la palanca en la parte posterior de tus piernas (unos centimetros por debajo de las pantorrillas). Consejo: Es preferible utilizar una maquina de flexion de piernas que este inclinada en lugar de plana, ya que una posicion inclinada es mas favorable para la activacion de los isquiotibiales.\", \"Manten el torso plano en el banco, asegurate de que tus piernas esten completamente estiradas y agarra las asas laterales de la maquina. Coloca los dedos de los pies rectos (o tambien puedes utilizar cualquiera de las otras dos posturas descritas en la seccion de posicionamiento de los pies). Esta sera tu posicion inicial.\", \"Mientras exhalas, flexiona las piernas hacia arriba tanto como sea posible sin levantar la parte superior de las piernas de la almohadilla. Una vez que alcances la posicion de contraccion completa, mantenla durante un segundo.\", \"Mientras inhalas, lleva las piernas hacia atras a la posicion inicial. Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_Leg_Curls/0.jpg\", \"Lying_Leg_Curls/1.jpg\"]','Flexiones de piernas tumbado',448) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Maquina de sentadillas tumbado','empuje','intermedio','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Ajusta la maquina de piernas a una altura que te permita entrar en ella con las rodillas dobladas y los muslos ligeramente por debajo del paralelo.\", \"Una vez seleccionado el peso, colocate dentro de la maquina boca arriba con las rodillas dobladas y los muslos ligeramente por debajo del paralelo a la plataforma. Asegurate de que las rodillas no sobrepasen los dedos de los pies. El angulo creado entre los isquiotibiales y las pantorrillas debe ser ligeramente inferior a 90 grados (ya que tu posicion inicial requiere que comiences ligeramente por debajo del paralelo). Tu espalda y tu cabeza deben descansar en la maquina mientras tus hombros estan presionados bajo las almohadillas para los hombros.\", \"Coloca tus manos en las asas y posiciona tus pies ligeramente apuntando hacia fuera a una posicion del ancho de los hombros. Esta sera tu posicion inicial.\", \"Mientras presionas con las puntas de los pies mientras exhalas, endereza todo el cuerpo mientras contraes los cuadriceps. Manten la posicion contraida durante un segundo. Consejo: Dado que estas inicialmente por debajo del paralelo, puedes optar por usar tus manos para ayudarte a subir presionando en tus muslos solo en la primera repeticion.\", \"Descende lentamente mientras inhalas, pero en lugar de bajar completamente hasta la posicion inicial, detente cuando tus muslos esten paralelos a la plataforma. El angulo entre tus isquiotibiales y pantorrillas debe ser de 90 grados.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_Machine_Squat/0.jpg\", \"Lying_Machine_Squat/1.jpg\"]','Sentadilla tumbado en maquina',449) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion lateral tumbado con un brazo','traccion','intermedio','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Mientras sostienes una mancuerna en una mano, acuestate con el pecho hacia abajo en un banco plano. La otra mano se puede usar para mantenerte en la pata del banco durante la estabilidad.\", \"Coloca la palma de la mano que sostiene la mancuerna en una forma neutral (las palmas mirando hacia tu torso) mientras mantienes el brazo extendido con el codo ligeramente doblado. Esta sera tu posicion inicial.\", \"Ahora levanta el brazo con la mancuerna al lado hasta que el codo este a la altura de los hombros y el brazo este mas o menos paralelo al suelo mientras exhalas. Consejo: Manten el brazo perpendicular al torso mientras mantienes el brazo extendido durante todo el movimiento. Ademas, manten la contraccion en la parte superior durante un segundo.\", \"Baja lentamente la mancuerna hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_One-Arm_Lateral_Raise/0.jpg\", \"Lying_One-Arm_Lateral_Raise/1.jpg\"]','Elevacion lateral con un brazo tumbado',450) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cuadriceps tumbado boca abajo','Ninguno','experto','Ninguno','solo_cuerpo','[\"cuadriceps\"]','[]','[\"Acuestate boca abajo en el suelo con tu compañero arrodillado a tu lado. Flexiona una rodilla y levanta esa pierna del suelo, intentando tocar tus gluteos con el pie. Tu compañero debe sujetarte la rodilla y el tobillo. Esta sera tu posicion inicial.\", \"Intenta extender la rodilla mientras tu compañero impide cualquier movimiento real.\", \"Despues de 10-20 segundos, relaja los musculos mientras tu compañero empuja suavemente el pie hacia los gluteos, estirando aun mas los cuadriceps y los flexores de la cadera.\", \"Despues de 10-20 segundos, cambia de lado.\"]','estiramiento','[\"Lying_Prone_Quadriceps/0.jpg\", \"Lying_Prone_Quadriceps/1.jpg\"]','Cuadriceps boca abajo',451) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion deltoides posterior tumbado','traccion','intermedio','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Mientras sostienes una mancuerna en cada mano, acuestate boca abajo en un banco plano.\", \"Coloca las palmas de las manos en una posicion neutra (palmas mirando hacia tu torso) mientras mantienes los brazos extendidos con los codos ligeramente flexionados. Esta sera tu posicion inicial.\", \"Ahora levanta los brazos a los lados hasta que tus codos esten a la altura de los hombros y tus brazos esten aproximadamente paralelos al suelo mientras exhalas. Consejo: Manten tus brazos perpendiculares al torso mientras los mantienes extendidos durante todo el movimiento. Ademas, manten la contraccion en la parte superior durante un segundo.\", \"Baja lentamente las mancuernas a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones y luego cambia al otro brazo.\"]','fuerza','[\"Lying_Rear_Delt_Raise/0.jpg\", \"Lying_Rear_Delt_Raise/1.jpg\"]','Elevacion posterior del deltoides tumbado',452) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con barra en T tumbado','traccion','intermedio','compuesto','maquina','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Carga la maquina de remo con barra en T con el peso deseado y ajusta la altura de las piernas para que la parte superior del pecho quede en la parte superior de la almohadilla. Consejo: En algunas maquinas, lo unico que puedes hacer es colocarte en el escalon adecuado que te permita estar a una altura que tenga la parte superior del pecho en la parte superior de la almohadilla.\", \"Tumbate boca abajo en la almohadilla y agarra las asas. Puedes usar las palmas hacia abajo, hacia arriba o hacia dentro, dependiendo de que parte de la espalda quieras trabajar.\", \"Eleva la barra del soporte y extiende los brazos frente a ti. Esta sera tu posicion inicial.\", \"Mientras exhalas, levanta lentamente el peso y contrae la espalda en la parte superior del movimiento. Consejo: Manten los brazos lo mas cerca posible del torso durante todo el movimiento para trabajar mejor los musculos de la espalda. Ademas, no levantes el cuerpo de la colchoneta en ningun momento y evita utilizar los biceps para levantar el peso.\", \"Despues de una segunda contraccion en la parte superior del movimiento, mientras inhalas, baja lentamente la espalda a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Lying_T-Bar_Row/0.jpg\", \"Lying_T-Bar_Row/1.jpg\"]','Remo tumbado con barra en T',454) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca en maquina','empuje','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Sientate en la maquina de press de pecho y selecciona el peso.\", \"Pisa la palanca que proporciona la maquina, ya que te ayudara a llevar las asas hacia delante para que puedas agarrar las asas y extender completamente los brazos.\", \"Agarra las asas con las palmas hacia abajo y levanta los codos para que tus brazos superiores queden paralelos al suelo a los lados de tu torso. Consejo: Tus antebrazos apuntaran hacia adelante, ya que estas agarrando las manijas. Una vez que lleves las manijas hacia adelante y extiendas los brazos, estaras en la posicion inicial.\", \"Ahora lleva las manijas hacia ti mientras inhalas.\", \"Empuja las manijas alejandote de ti mientras flexionas los pectorales y exhalas. Manten la contraccion durante un segundo antes de volver a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\", \"Cuando termines, vuelve a pisar la palanca y devuelve lentamente las manijas a su posicion original.\"]','fuerza','[\"Machine_Bench_Press/0.jpg\", \"Machine_Bench_Press/1.jpg\"]','Press de banca en maquina',456) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Maquina de flexiones de biceps','traccion','principiante','aislamiento','maquina','[\"biceps\"]','[]','[\"Ajusta el asiento a la altura adecuada y selecciona el peso. Coloque la parte superior de los brazos contra las almohadillas y agarre las asas. Esta sera su posicion inicial.\", \"Realice el movimiento flexionando el codo, tirando del antebrazo hacia el brazo.\", \"Haga una pausa en la parte superior del movimiento y, a continuacion, devuelva lentamente el peso a la posicion inicial.\", \"Evite devolver el peso completamente hasta el tope hasta que haya completado la serie para mantener la tension en los musculos que esta trabajando.\"]','fuerza','[\"Machine_Bicep_Curl/0.jpg\", \"Machine_Bicep_Curl/1.jpg\"]','Maquina de flexion de biceps',457) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de biceps en maquina','traccion','principiante','aislamiento','maquina','[\"biceps\"]','[]','[\"Sientate en la maquina de curl predicador y selecciona el peso.\", \"Coloca la parte posterior de la parte superior de los brazos (los triceps) en la almohadilla del predicador y agarra las asas con las palmas hacia arriba. Consejo: Asegurate de que cuando coloques los brazos en la almohadilla mantienes los codos hacia dentro. Esta sera tu posicion inicial.\", \"Ahora levanta las asas mientras exhalas y contraes los biceps. En la parte superior de la posicion, asegurate de mantener la contraccion durante un segundo. Consejo: Solo deben moverse los antebrazos. Los brazos superiores deben permanecer inmoviles y en la almohadilla en todo momento.\", \"Baja las asas lentamente hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Machine_Preacher_Curls/0.jpg\", \"Machine_Preacher_Curls/1.jpg\"]','Maquina de curl predicador',458) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Maquina de press de hombros (militar)','empuje','principiante','compuesto','maquina','[\"hombros\"]','[\"triceps\"]','[\"Sientate en la maquina de press de hombros y selecciona el peso.\", \"Agarra las asas a los lados mientras mantienes los codos doblados y alineados con el torso. Esta sera tu posicion inicial.\", \"Ahora levanta las asas mientras exhalas y extiendes los brazos completamente. En la parte superior de la posicion, asegurate de mantener la contraccion durante un segundo.\", \"Baja las manijas lentamente hacia la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Machine_Shoulder_Military_Press/0.jpg\", \"Machine_Shoulder_Military_Press/1.jpg\"]','Maquina_Press_militar_de_hombros',459) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps en maquina','empuje','principiante','aislamiento','maquina','[\"triceps\"]','[]','[\"Ajusta el asiento a la altura adecuada y selecciona el peso. Coloca la parte superior de los brazos contra las almohadillas y agarra las manijas. Esta sera tu posicion inicial.\", \"Realiza el movimiento extendiendo el codo, tirando del antebrazo alejandolo del brazo.\", \"Haz una pausa al completar el movimiento y luego devuelve lentamente el peso a la posicion inicial.\", \"Evita devolver el peso completamente hasta el tope hasta que se complete la serie para mantener la tension en los musculos que se estan trabajando.\"]','fuerza','[\"Machine_Triceps_Extension/0.jpg\", \"Machine_Triceps_Extension/1.jpg\"]','Extension de triceps en maquina',460) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pase de balon medicinal con el pecho','empuje','principiante','compuesto','balon_medicinal','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Necesitaras un compañero para realizar este ejercicio. Si no tienes uno, este movimiento se puede realizar contra una pared.\", \"Comienza frente a tu compañero sosteniendo el balon medicinal a la altura del torso con ambas manos.\", \"Tira del balon hacia tu pecho y revierte el movimiento extendiendo los codos. Para aplicaciones deportivas, puedes dar un paso al lanzar.\", \"Tu compañero debe atrapar el balon y lanzartelo a la espalda.\", \"Recibe el lanzamiento con ambas manos a la altura del pecho.\"]','pliometria','[\"Medicine_Ball_Chest_Pass/0.jpg\", \"Medicine_Ball_Chest_Pass/1.jpg\"]','Medicine_Ball_Chest_Pass',461) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Medicine Ball Full Twist','traccion','principiante','compuesto','balon_medicinal','[\"abdominales\"]','[\"hombros\"]','[\"Para este ejercicio necesitaras un balon medicinal y un compañero. Ponte espalda con espalda con tu compañero, separados entre 60 y 90 cm. Esta sera tu posicion inicial.\", \"Sosten el balon frente al tronco. Abre las caderas y gira los hombros al mismo tiempo que tu compañero.\", \"Para una rotacion completa, tu y tu compañero debeis girar en la misma direccion, es decir, en sentido contrario a las agujas del reloj.\", \"Pasa el balon a tu compañero y ahora ambos podeis girar en la direccion opuesta para repetir el procedimiento.\"]','pliometria','[\"Medicine_Ball_Full_Twist/0.jpg\", \"Medicine_Ball_Full_Twist/1.jpg\"]','Medicine_Ball_Full_Twist',462) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento con pelota medicinal','empuje','principiante','compuesto','balon_medicinal','[\"hombros\"]','[\"abdominales\", \"isquiotibiales\", \"cuadriceps\"]','[\"Adopta una postura de semisentadilla con un balon medicinal en tus manos. Tus brazos deben colgar de manera que el balon quede cerca de tus pies.\", \"Comienza empujando las caderas hacia adelante mientras extiendes las piernas y saltas.\", \"Al hacerlo, balancea los brazos hacia arriba y por encima de la cabeza, manteniendolos extendidos, y suelta el balon en el punto mas alto del movimiento. El objetivo es lanzar el balon lo mas lejos posible detras de ti.\"]','pliometria','[\"Medicine_Ball_Scoop_Throw/0.jpg\", \"Medicine_Ball_Scoop_Throw/1.jpg\"]','Lanzamiento de pelota medicinal con cuchara',463) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Encogimiento de hombros medio','traccion','intermedio','aislamiento','mancuerna','[\"espalda_media\"]','[]','[\"Acuestate boca abajo en un banco inclinado mientras sostienes una mancuerna en cada mano. Tus brazos deben estar completamente extendidos colgando hacia abajo y apuntando hacia el suelo. Las palmas de tus manos deben estar enfrentadas entre si. Esta sera tu posicion inicial.\", \"Mientras exhalas, junta los omoplatos y manten la contraccion durante un segundo completo. Consejo: Este movimiento es como la accion inversa de un abrazo, o como intentar realizar laterales traseros como si no tuvieras brazos.\", \"Mientras inhalas, lleva la espalda a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Middle_Back_Shrug/0.jpg\", \"Middle_Back_Shrug/1.jpg\"]','Encogimiento de hombros en la parte media de la espalda',464) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de la espalda media','estatico','principiante','aislamiento','Ninguno','[\"espalda_media\"]','[\"abdominales\", \"dorsales\", \"espalda_baja\"]','[\"Ponte de pie con los pies separados a la anchura de los hombros y las manos en las caderas.\", \"Gira la cintura hasta que sientas un estiramiento. Manten la posicion durante 10 a 15 segundos y luego gira hacia el otro lado.\"]','estiramiento','[\"Middle_Back_Stretch/0.jpg\", \"Middle_Back_Stretch/1.jpg\"]','Estiramiento de la parte media de la espalda',465) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Monster Walk','traccion','principiante','compuesto','bandas','[\"abductores\"]','[]','[\"Coloca una banda alrededor de ambos tobillos y otra alrededor de ambas rodillas. Debe haber suficiente tension para que esten ajustadas cuando tus pies esten separados a la anchura de los hombros.\", \"Para empezar, da pasos cortos hacia delante alternando el pie izquierdo y el derecho.\", \"Despues de varios pasos, haz justo lo contrario y camina hacia atras hasta donde empezaste.\"]','fuerza','[\"Monster_Walk/0.jpg\", \"Monster_Walk/1.jpg\"]','Caminata del monstruo',467) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Escaladores','traccion','principiante','compuesto','Ninguno','[\"cuadriceps\"]','[\"pecho\", \"isquiotibiales\", \"hombros\"]','[\"Comienza en posicion de flexion, con el peso apoyado en tus manos y dedos de los pies. Flexiona la rodilla y la cadera, lleva una pierna hasta que la rodilla quede aproximadamente debajo de la cadera. Esta sera tu posicion inicial.\", \"Invierte explosivamente la posicion de tus piernas, extendiendo la pierna doblada hasta que quede recta y apoyada en los dedos del pie, y llevando el otro pie hacia arriba con la cadera y la rodilla flexionadas. Repite de forma alterna durante 20-30 segundos.\"]','pliometria','[\"Mountain_Climbers/0.jpg\", \"Mountain_Climbers/1.jpg\"]','Escaladores de montaña',468) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Serie de garras en movimiento','Ninguno','principiante','compuesto','Ninguno','[\"isquiotibiales\"]','[\"pantorrillas\", \"cuadriceps\"]','[\"Este movimiento te ayuda a preparar tu forma de correr para que puedas destacar en las carreras de velocidad. Mientras corres, asegurate de flexionar la rodilla, con el objetivo de patear con los gluteos a medida que se extiende la cadera.\", \"Recarga el cuadriceps a medida que la pierna se mueve hacia atras, atacando el suelo en el siguiente paso.\", \"Asegurate de que, mientras corres, bloqueas con los brazos, golpeando con un rapido movimiento 1-2.\"]','pliometria','[\"Moving_Claw_Series/0.jpg\", \"Moving_Claw_Series/1.jpg\"]','Serie de garra en movimiento',469) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arranque muscular','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"triceps\"]','[\"Comienza con una barra cargada sostenida a media altura del muslo con un agarre amplio. Los pies deben estar directamente debajo de las caderas, con los pies girados hacia fuera segun sea necesario. Baja las caderas, con el pecho arriba y la cabeza mirando hacia adelante. Los hombros deben estar justo frente a la barra. Esta sera la posicion inicial.\", \"Comience el tiron impulsando con la parte delantera de los talones, levantando la barra. Pase al segundo tiron extendiendo las caderas, rodillas y tobillos, impulsando la barra hacia arriba lo mas rapido posible. La barra debe estar cerca del cuerpo.\", \"Continue levantando la barra hasta la posicion sobre la cabeza, sin doblar las rodillas.\"]','halterofilia_olimpica','[\"Muscle_Snatch/0.jpg\", \"Muscle_Snatch/1.jpg\"]','Arranque muscular',470) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadillas con postura estrecha','empuje','intermedio','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Coloca la espalda de tu torso contra el respaldo acolchado de la maquina y engancha los hombros bajo las almohadillas para hombros que se proporcionan.\", \"Coloca tus piernas en la plataforma con una postura estrecha, menos ancha que el ancho de los hombros, con los dedos de los pies ligeramente apuntando hacia fuera. Tus pies deben estar separados alrededor de 3 pulgadas o menos. Consejo: Manten la cabeza arriba en todo momento y tambien manten la espalda en el acolchado en todo momento.\", \"Coloca tus brazos en las manijas laterales de la maquina y desengancha las barras de seguridad (lo cual en la mayoria de los diseños se hace moviendo las manijas laterales de una posicion frontal a una posicion diagonal).\", \"Ahora estira tus piernas sin bloquear las rodillas. Esta sera tu posicion inicial.\", \"Comienza a bajar lentamente la unidad doblando las rodillas mientras mantienes una postura recta con la cabeza arriba (la espalda en el acolchado en todo momento). Continua bajando hasta que el angulo entre la parte superior de las piernas y las pantorrillas sea ligeramente inferior a 90 grados (que es el punto en el que la parte superior de las piernas esta por debajo de paralela al suelo). Inhala mientras realizas esta parte del movimiento.\", \"Comienza a subir la unidad mientras exhalas empujando el suelo principalmente con los talones de tus pies mientras estiras las piernas de nuevo y vuelves a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Narrow_Stance_Hack_Squats/0.jpg\", \"Narrow_Stance_Hack_Squats/1.jpg\"]','Sentadillas con postura estrecha',472) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion natural de gluteos y isquiotibiales','traccion','intermedio','compuesto','solo_cuerpo','[\"isquiotibiales\"]','[\"pantorrillas\", \"gluteos\", \"espalda_baja\"]','[\"Usando la almohadilla para las piernas de una maquina de jalon lateral o un banco predicador, colocate de manera que tus tobillos esten debajo de las almohadillas, las rodillas en el asiento y tu estes mirando alejandote de la maquina. Debes estar erguido y mantener una buena postura.\", \"Esta sera tu posicion inicial. Baja con control hasta que tus rodillas esten casi completamente estiradas.\", \"Manteniendo el control, levantate hasta la posicion inicial.\", \"Si no puedes completar una repeticion, utiliza una banda, un compañero o empuja desde una caja para ayudarte a completar la repeticion.\"]','fuerza','[\"Natural_Glute_Ham_Raise/0.jpg\", \"Natural_Glute_Ham_Raise/1.jpg\"]','Elevacion natural de gluteos y isquiotibiales',475) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de cuello','empuje','intermedio','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco plano. Con un agarre de anchura media (un agarre que crea un angulo de 90 grados en el centro del movimiento entre los antebrazos y la parte superior de los brazos), levanta la barra del soporte y mantenla recta sobre tu cuello con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Mientras inhalas, baja lentamente hasta que sientas la barra en tu cuello.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra usando los musculos del pecho. Bloquea los brazos y aprieta el pecho en la posicion contraida, manten durante un segundo y luego comienza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir).\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra de nuevo en el soporte.\"]','fuerza','[\"Neck_Press/0.jpg\", \"Neck_Press/1.jpg\"]','Press de cuello',476) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Neck-SMR','estatico','intermedio','Ninguno','otro','[\"cuello\"]','[]','[\"Con un rodillo muscular o un rodillo de amasar, coloca el rodillo detras de la cabeza y contra el cuello. Asegurate de no colocar el rodillo directamente contra la columna vertebral, sino ligeramente girado para que el rodillo presione los musculos a ambos lados de la columna. Esta sera tu posicion inicial.\", \"Empezando por la parte superior del cuello, rueda lentamente hacia abajo por los musculos del cuello, haciendo pausas en los puntos de tension durante 10-30 segundos.\"]','estiramiento','[\"Neck-SMR/0.jpg\", \"Neck-SMR/1.jpg\"]','Neck-SMR',477) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales oblicuos - En el suelo','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Comienza acostandote sobre tu lado derecho con las piernas una encima de la otra. Asegurate de que tus rodillas esten ligeramente dobladas.\", \"Coloca tu mano izquierda detras de tu cabeza.\", \"Una vez que estes en esta posicion inicial, comienza moviendo tu codo izquierdo hacia arriba como lo harias en un crunch normal, excepto que esta vez el enfasis principal esta en tus oblicuos.\", \"Haz el crunch tan alto como puedas, manten la contraccion durante un segundo y luego baja lentamente la espalda hasta la posicion inicial.\", \"Recuerda inhalar durante la parte excentrica (descenso) del ejercicio y exhalar durante la parte concentrica (elevacion) del ejercicio.\"]','fuerza','[\"Oblique_Crunches_-_On_The_Floor/0.jpg\", \"Oblique_Crunches_-_On_The_Floor/1.jpg\"]','Abdominales oblicuos en el suelo',479) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla olimpica','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comience con una barra apoyada en la parte superior de los trapecios. El pecho debe estar levantado y la cabeza mirando hacia adelante. Adopte una postura con los pies separados a la anchura de las caderas y girados hacia fuera segun sea necesario.\", \"Descienda flexionando las rodillas, evitando mover las caderas hacia atras tanto como sea posible. Esto requiere que las rodillas se desplacen hacia adelante; asegurese de que permanezcan alineadas con los pies. El objetivo es mantener el torso lo mas erguido posible. Continua bajando, manteniendo el peso en la parte delantera del talon.\", \"En el momento en que las piernas superiores entren en contacto con las inferiores, invierte el movimiento, impulsando el peso hacia arriba.\"]','halterofilia_olimpica','[\"Olympic_Squat/0.jpg\", \"Olympic_Squat/1.jpg\"]','Sentadilla olimpica',480) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral de cuadriceps','estatico','principiante','aislamiento','Ninguno','[\"cuadriceps\"]','[]','[\"Comienza acostado sobre tu lado derecho, con la rodilla derecha doblada en un angulo de 90 grados descansando en el suelo frente a ti (esto estabiliza el torso).\", \"Dobla tu rodilla izquierda detras de ti y manten tu pie izquierdo con tu mano izquierda. Para estirar el flexor de la cadera, presiona tu cadera izquierda hacia adelante mientras empujas tu pie izquierdo hacia atras con la mano. Cambia de lado.\"]','estiramiento','[\"On_Your_Side_Quad_Stretch/0.jpg\", \"On_Your_Side_Quad_Stretch/1.jpg\"]','Estiramiento de cuadriceps de lado',481) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de cuadriceps tumbado boca arriba','estatico','principiante','aislamiento','otro','[\"cuadriceps\"]','[]','[\"Acuestese en un banco plano o escalon, y cuelgue una pierna y un brazo por el lado.\", \"Doble la rodilla y mantenga la parte superior del pie. Mientras lo hace, tenga cuidado de no arquear la parte baja de la espalda.\", \"Tire del ombligo hacia la columna vertebral para mantenerse en posicion neutra. Presiona el pie hacia abajo y contra la mano. Para añadir el estiramiento de la cadera, levanta la cadera de la pierna que estas sosteniendo hacia el techo.\", \"Cambia de lado.\"]','estiramiento','[\"On-Your-Back_Quad_Stretch/0.jpg\", \"On-Your-Back_Quad_Stretch/1.jpg\"]','Estiramiento de cuadriceps tumbado boca arriba',482) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Un brazo contra la pared','estatico','principiante','aislamiento','Ninguno','[\"dorsales\"]','[]','[\"Desde una posicion de pie, coloca un brazo doblado contra una pared o puerta.\", \"Inclinate lentamente hacia tu brazo hasta que sientas un estiramiento en los dorsales.\"]','estiramiento','[\"Un_brazo_contra_la_pared/0.jpg\", \"Un_brazo_contra_la_pared/1.jpg\"]','Un brazo contra la pared',483) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Una dominada con un brazo','traccion','experto','compuesto','otro','[\"espalda_media\"]','[\"biceps\", \"antebrazos\", \"dorsales\"]','[\"Para este ejercicio, comienza colocando una toalla alrededor de una barra de dominadas.\", \"Agarra la barra de dominadas con la palma de la mano mirando hacia ti. Una mano agarrara la barra de dominadas y la otra agarrara la toalla.\", \"Lleva tu torso hacia atras unos 30 grados mas o menos, creando una curvatura en la parte inferior de la espalda y sacando el pecho. Esta es tu posicion inicial.\", \"Sube el torso hasta que la barra toque la parte superior del pecho, llevando los hombros y la parte superior de los brazos hacia abajo y hacia atras. Exhala mientras realizas esta parte del movimiento. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa. La parte superior del torso debe permanecer inmovil mientras se mueve en el espacio y solo deben moverse los brazos. Los antebrazos no deben hacer ningun otro trabajo que no sea sostener la barra.\", \"Despues de un segundo en la posicion contraida, comienza a inhalar y baja lentamente el torso hasta la posicion inicial, cuando tus brazos esten completamente extendidos y los dorsales esten completamente estirados.\", \"Repite este movimiento durante la cantidad prescrita de repeticiones.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One_Arm_Chin-Up/0.jpg\", \"One_Arm_Chin-Up/1.jpg\"]','Dominadas con un brazo',484) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con mancuerna con un brazo','empuje','principiante','compuesto','mancuerna','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco plano con una mancuerna en una mano sobre el muslo.\", \"Utilizando el muslo para ayudarte a levantar la mancuerna, levantala hacia arriba para poder mantenerla frente a ti a la altura de los hombros. Use la mano que no esta levantando para ayudar a colocar la mancuerna correctamente sobre usted.\", \"Una vez a la altura de los hombros, gire la muñeca hacia adelante de modo que la palma de la mano quede mirando hacia fuera. Esta sera su posicion inicial.\", \"Baje las pesas lentamente hacia los lados mientras inhala. Manten el control total de la mancuerna en todo momento. Consejo: Utiliza la mano con la que no estas levantando para ayudar a mantener el equilibrio de la mancuerna, ya que al principio puede que te cueste un poco. Utiliza la mano que no esta levantando solo si es necesario. De lo contrario, mantenla descansando al lado.\", \"Mientras exhalas, empuja las mancuernas hacia arriba utilizando los musculos pectorales. Bloquea los brazos en la posicion contraida, aprieta el pecho, manten la posicion durante un segundo y luego empieza a bajar lentamente. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito en tu programa de entrenamiento.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One_Arm_Dumbbell_Bench_Press/0.jpg\", \"One_Arm_Dumbbell_Bench_Press/1.jpg\"]','Press de banca con mancuernas a un brazo',485) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One Brazo con Mancuerna Preacher Curl','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Coge una mancuerna con el brazo derecho y coloca la parte superior del brazo sobre el banco preacher o el banco inclinado. La mancuerna debe mantenerse a la altura de los hombros. Esta sera tu posicion inicial.\", \"Mientras inhalas, baja lentamente la mancuerna hasta que el brazo este extendido y el biceps completamente estirado.\", \"Mientras exhalas, utiliza el biceps para flexionar el peso hacia arriba hasta que el biceps este completamente contraido y la mancuerna este a la altura de los hombros. Recuerda que, para garantizar una contraccion completa, debes llevar el dedo meñique mas alto que el pulgar.\", \"Aprieta los biceps con fuerza durante un segundo en la posicion contraida y repite durante el numero recomendado de repeticiones.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One_Arm_Dumbbell_Preacher_Curl/0.jpg\", \"One_Arm_Dumbbell_Preacher_Curl/1.jpg\"]','Flexion con mancuernas con un brazo',486) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuerna con un brazo pronado','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Acuestese boca arriba en un banco mientras sostiene una mancuerna a la longitud de los brazos. Su brazo debe estar perpendicular a su cuerpo. La palma de la mano debe estar mirando hacia sus pies, ya que se requiere un agarre pronado para realizar este ejercicio.\", \"Coloque su mano que no esta levantando en su biceps como apoyo.\", \"Comienza lentamente a bajar la mancuerna mientras inhalas.\", \"Luego, comienza a levantar la mancuerna mientras contraes el triceps. Recuerda exhalar durante la fase concentrica (la parte de levantamiento del ejercicio).\", \"Repite hasta que hayas realizado tus repeticiones establecidas.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One_Arm_Pronated_Dumbbell_Triceps_Extension/0.jpg\", \"One_Arm_Pronated_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuerna con un brazo pronado',489) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Media langosta','estatico','principiante','Ninguno','Ninguno','[\"cuadriceps\"]','[\"abdominales\", \"biceps\", \"pecho\"]','[\"Acuestate boca abajo en el suelo.\", \"Coloca la mano izquierda debajo de la cadera izquierda para proteger la cadera y el hueso pubico.\", \"Dobla la rodilla derecha para poder sujetar el pie con la mano derecha.\", \"Eleva el pie en el aire y, al mismo tiempo, levanta los hombros del suelo. Esto tambien estira el flexor de la cadera derecha, el pecho y los hombros. Cambia de lado. Si no te molesta la espalda, puedes intentarlo con ambos brazos y piernas al mismo tiempo.\"]','estiramiento','[\"One_Half_Locust/0.jpg\", \"One_Half_Locust/1.jpg\"]','Media langosta',491) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Suspension con una mano','estatico','principiante','Ninguno','otro','[\"dorsales\"]','[\"biceps\"]','[\"Agarrate a una barra de dominadas con una mano, utilizando un agarre pronado. Manten los pies en el suelo o en un escalon. Deja que la mayor parte de tu peso cuelgue de esa mano, mientras mantienes los pies en el suelo. Manten la posicion durante 10-20 segundos y cambia de lado.\"]','estiramiento','[\"One_Handed_Hang/0.jpg\", \"One_Handed_Hang/1.jpg\"]','One_Handed_Hang',492) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Una rodilla al pecho','estatico','principiante','compuesto','Ninguno','[\"gluteos\"]','[\"isquiotibiales\", \"espalda_baja\"]','[\"Comienza acostado en el suelo.\", \"Extiende una pierna recta y lleva la otra rodilla hacia el pecho. Sujetala por debajo de la articulacion de la rodilla para proteger la rotula.\", \"Tira suavemente de la rodilla hacia la nariz.\", \"Cambia de lado. Esto estira los gluteos y la parte inferior de la espalda de la pierna doblada y el flexor de la cadera de la pierna recta.\"]','estiramiento','[\"One_Knee_To_Chest/0.jpg\", \"One_Knee_To_Chest/1.jpg\"]','Una_rodilla_al_pecho',493) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One Pierna con Barra Sentadilla','empuje','experto','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza de pie a unos 2 o 3 pies frente a un banco plano con la espalda mirando hacia el banco. Coloca una barra frente a ti en el suelo. Consejo: Tus pies deben estar separados a la anchura de los hombros.\", \"Dobla las rodillas y utiliza un agarre pronado con las manos separadas a una distancia mayor que la anchura de los hombros para levantar la barra hasta que puedas apoyarla en tu pecho.\", \"A continuacion, levanta la barra por encima de tu cabeza y apoyala en la base de tu cuello. Mueve un pie hacia atras de modo que tu dedo del pie quede apoyado en el banco plano. Tu otro pie debe estar inmovil frente a ti. Manten la cabeza arriba en todo momento, ya que mirar hacia abajo te hara perder el equilibrio, y manten tambien la espalda recta. Consejo: Asegurate de que tu espalda este recta y el pecho hacia fuera mientras realizas este ejercicio.\", \"Mientras inhalas, baja lentamente la pierna hasta que el muslo quede paralelo al suelo. En este punto, la rodilla debe estar por encima de los dedos de los pies. Tu pecho debe estar directamente sobre la mitad del muslo.\", \"Llevando con el pecho y las caderas y contrayendo los cuadriceps, eleva la pierna hacia atras hasta la posicion inicial mientras exhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de pierna y repite el movimiento.\"]','fuerza','[\"One_Leg_Barbell_Squat/0.jpg\", \"One_Leg_Barbell_Squat/1.jpg\"]','Sentadilla con barra con una pierna',494) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm Flat Bench con Mancuerna Flye','empuje','principiante','aislamiento','mancuerna','[\"pecho\"]','[]','[\"Acuestate boca arriba en un banco plano con una mancuerna en una mano apoyada sobre el muslo. La palma de la mano con la mancuerna debe estar en una posicion neutra.\", \"Utiliza los muslos para ayudarte a levantar la mancuerna, limpia la mancuerna para que puedas mantenerla frente a ti con el brazo levantado completamente extendido. Recuerda mantener un agarre neutro en este ejercicio. La mano que no levanta debe estar al lado sosteniendo el banco plano para un mejor apoyo. Esta sera tu posicion inicial.\", \"El brazo con el peso debe tener una ligera flexion en el codo para evitar tension en el tendon del biceps. Comienza bajando el brazo con el peso en un arco amplio hasta que sientas un estiramiento en el pecho. Inhala mientras realizas esta parte del movimiento. Consejo: Ten en cuenta que durante todo el movimiento, el brazo levantado debe permanecer inmovil; el movimiento solo debe producirse en la articulacion del hombro.\", \"Vuelve a colocar el brazo levantado detras de la posicion inicial mientras contraes los musculos del pecho y exhalas. Consejo: Asegurate de utilizar el mismo arco de movimiento que has utilizado para bajar las pesas.\", \"Manten durante un segundo la posicion contraida y repite el movimiento durante el numero de repeticiones prescrito.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"One-Arm_Flat_Bench_Dumbbell_Flye/0.jpg\", \"One-Arm_Flat_Bench_Dumbbell_Flye/1.jpg\"]','One-Arm_Flat_Bench_Dumbbell_Flye',496) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones laterales con polea alta con un brazo','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[]','[\"Conecta un mango estandar a una torre. Mueve el cable a la posicion mas alta de la polea.\", \"Ponte de pie de lado al cable. Con una mano, alcanza hacia arriba y agarra el mango con un agarre por debajo.\", \"Tira del cable hacia abajo hasta que el codo toque tu costado y el mango este por encima de tu hombro.\", \"Coloca los pies separados a la anchura de las caderas. Coloca la mano libre en la cadera para ayudar a medir el punto de pivote.\", \"Manten el brazo en posicion estatica. Contrae los oblicuos para bajar el peso en un crunch lateral.\", \"Una vez que alcances la contraccion maxima, suelta lentamente el peso hasta la posicion inicial. La columna de pesas nunca debe descargarse en posicion de reposo. El objetivo es mantener una tension constante durante la serie.\", \"Repite hasta el fallo.\", \"A continuacion, cambia de posicion y repite la misma serie de movimientos en el lado opuesto.\"]','fuerza','[\"One-Arm_High-Pulley_Cable_Side_Bends/0.jpg\", \"One-Arm_High-Pulley_Cable_Side_Bends/1.jpg\"]','Flexiones laterales con polea alta con un brazo',497) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion lateral inclinada con un brazo','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Acuestese de lado en un banco inclinado con una mancuerna en la mano. Asegurate de que el hombro presiona contra el banco inclinado y el brazo queda apoyado sobre tu cuerpo con la palma alrededor de tu ombligo.\", \"Sujeta una mancuerna en tu brazo superior mientras lo mantienes extendido frente a ti paralelo al suelo. Esta es tu posicion inicial.\", \"Mientras mantienes la mancuerna paralela al suelo en todo momento, realiza una elevacion lateral. Tu brazo debe subir recto hasta que apunte al techo. Consejo: Exhala mientras realizas este movimiento. Manten la mancuerna en esa posicion y siente la contraccion en los hombros durante un segundo.\", \"Mientras inhalas, baja el peso a lo largo de tu espalda hasta la posicion inicial.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One-Arm_Incline_Lateral_Raise/0.jpg\", \"One-Arm_Incline_Lateral_Raise/1.jpg\"]','Elevacion lateral inclinada con un brazo',498) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm con Pesa Rusa Clean','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\", \"hombros\", \"trapecios\"]','[\"Coloca una pesa rusa entre tus pies. Mientras te inclinas hacia abajo para agarrar la pesa rusa, empuja con el trasero hacia atras y manten la mirada al frente.\", \"Lleva la pesa rusa a tus hombros extendiendo las piernas y las caderas mientras la levantas hacia tus hombros. La muñeca debe girar al hacerlo.\", \"Vuelve a colocar el peso en la posicion inicial.\"]','fuerza','[\"One-Arm_Kettlebell_Clean/0.jpg\", \"One-Arm_Kettlebell_Clean/1.jpg\"]','One-Arm_Kettlebell_Clean',499) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm con Pesa Rusa Clean and Jerk','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[]','[\"Sujeta una pesa rusa por el asa.\", \"Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia el hombro. Gira la muñeca al hacerlo, de modo que la palma quede mirando hacia delante.\", \"Inclina el cuerpo doblando las rodillas, manteniendo el torso erguido.\", \"Inmediatamente invierte la direccion, impulsandote con los talones, en esencia saltando para crear impulso. Mientras lo haces, presiona la pesa sobre la cabeza para bloquearla extendiendo los brazos, utilizando el impulso de tu cuerpo para mover el peso.\", \"Recibe el peso sobre la cabeza volviendo a una posicion de sentadilla debajo del peso.\", \"Manteniendo el peso sobre la cabeza, vuelve a la posicion de pie. Baja el peso al suelo para realizar la siguiente repeticion.\"]','fuerza','[\"One-Arm_Kettlebell_Clean_and_Jerk/0.jpg\", \"One-Arm_Kettlebell_Clean_and_Jerk/1.jpg\"]','Levantamiento y tiron con pesa rusa con un brazo',500) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de suelo con pesa rusa a un brazo','empuje','intermedio','compuesto','pesas rusas','[\"pecho\"]','[\"triceps\"]','[\"Tumbate en el suelo sosteniendo una pesa rusa con una mano, con el brazo apoyado en el suelo. La palma de la mano debe estar mirando hacia dentro.\", \"Presiona la pesa rusa hacia arriba, hacia el techo, girando la muñeca.\", \"Baja la pesa rusa a la posicion inicial y repite.\"]','fuerza','[\"One-Arm_Kettlebell_Floor_Press/0.jpg\", \"One-Arm_Kettlebell_Floor_Press/1.jpg\"]','Press de suelo con pesa rusa a un brazo',501) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con pesa rusa con un brazo','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"triceps\"]','[\"Lleva la pesa rusa al hombro. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia el hombro. Gira la muñeca al hacerlo, de modo que la palma quede mirando hacia delante. Esta sera tu posicion inicial.\", \"Sosten la pesa rusa con el codo hacia fuera, y empujala hacia arriba y hacia fuera hasta que quede bloqueada sobre la cabeza.\", \"Baja la pesa rusa hacia el hombro con control y repite. Asegurate de contraer los dorsales, los gluteos y el abdomen con fuerza para ganar estabilidad y fuerza.\"]','fuerza','[\"One-Arm_Kettlebell_Para_Press/0.jpg\", \"One-Arm_Kettlebell_Para_Press/1.jpg\"]','Press con pesa rusa a un brazo para',504) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm con Pesa Rusa Push Press','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"pantorrillas\", \"cuadriceps\", \"triceps\"]','[\"Sujeta una pesa rusa por el asa. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia el hombro. Gira la muñeca mientras lo haces, de modo que la palma quede mirando hacia delante. Esta sera tu posicion inicial.\", \"Baja el cuerpo flexionando las rodillas, manteniendo el torso erguido.\", \"Inmediatamente invierte la direccion, impulsandote con los talones, esencialmente saltando para crear impulso. Mientras lo haces, presiona la pesa rusa sobre la cabeza para bloquearla extendiendo los brazos, utilizando el impulso de tu cuerpo para mover el peso. Baja el peso para realizar la siguiente repeticion.\"]','fuerza','[\"One-Arm_Kettlebell_Push_Press/0.jpg\", \"One-Arm_Kettlebell_Push_Press/1.jpg\"]','Empuje con pesa rusa a un brazo',505) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con pesa rusa a un brazo','traccion','intermedio','compuesto','pesas rusas','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca una pesa rusa frente a tus pies. Dobla ligeramente las rodillas y luego empuja el trasero hacia fuera tanto como sea posible mientras te inclinas para colocarte en la posicion inicial. Agarra la pesa rusa y llevala hacia el estomago, retraiendo el omoplato y flexionando el codo. Manten la espalda recta. Baja y repite.\"]','fuerza','[\"One-Arm_Kettlebell_Row/0.jpg\", \"One-Arm_Kettlebell_Row/1.jpg\"]','Remo con pesa rusa a un brazo',506) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm con Pesa Rusa Snatch','traccion','experto','compuesto','pesas rusas','[\"hombros\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\", \"triceps\"]','[\"Coloca una pesa rusa entre tus pies. Dobla las rodillas y empuja el trasero hacia atras para colocarte en la posicion inicial correcta.\", \"Mira al frente y balancea la pesa rusa hacia atras entre tus piernas.\", \"Inmediatamente invierte la direccion y empuja con tus caderas y rodillas, acelerando la pesa rusa hacia arriba. A medida que la pesa rusa se eleva hasta tu hombro, gira la mano y empuja hacia arriba, utilizando el impulso para recibir el peso bloqueado sobre la cabeza.\"]','fuerza','[\"One-Arm_Kettlebell_Snatch/0.jpg\", \"One-Arm_Kettlebell_Snatch/1.jpg\"]','Arrancada con pesa rusa a un brazo',507) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrancada con pesa rusa a un brazo','empuje','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"gluteos\", \"isquiotibiales\", \"cuadriceps\", \"triceps\"]','[\"Sujeta una pesa rusa por el asa. Lleva la pesa rusa al hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia el hombro. Gira la muñeca al hacerlo, de modo que la palma quede mirando hacia delante. Esta sera tu posicion inicial.\", \"Inclina el cuerpo doblando las rodillas, manteniendo el torso erguido.\", \"Inmediatamente invierte la direccion, impulsandote con los talones, esencialmente saltando para crear impulso. Mientras lo haces, presiona la pesa rusa sobre la cabeza para bloquearla extendiendo los brazos, utilizando el impulso de tu cuerpo para mover el peso.\", \"Recibe el peso sobre la cabeza volviendo a una posicion de sentadilla debajo del peso, colocando una pierna delante de ti y otra detras.\", \"Manteniendo el peso sobre la cabeza, vuelve a una posicion de pie y junta los pies. Baja el peso para realizar la siguiente repeticion.\"]','fuerza','[\"One-Arm_Kettlebell_Split_Jerk/0.jpg\", \"One-Arm_Kettlebell_Split_Jerk/1.jpg\"]','One-Arm_Kettlebell_Split_Jerk',508) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrancada dividida con pesa rusa a un brazo','traccion','experto','compuesto','pesas rusas','[\"hombros\"]','[\"isquiotibiales\", \"cuadriceps\"]','[\"Sosten una pesa rusa en una mano por el asa.\", \"Haz una sentadilla hacia el suelo y luego invierte el movimiento, extendiendo las caderas, las rodillas y, por ultimo, los tobillos, para levantar la pesa rusa sobre la cabeza.\", \"Despues de extender completamente el cuerpo, desciende a una posicion de zancada para recibir el peso sobre la cabeza, con una pierna delante y otra detras. Asegurate de impulsar con las caderas y bloquear las pesas rusas sobre la cabeza en un movimiento ininterrumpido.\", \"Regresa a la posicion de pie, sosteniendo el peso sobre la cabeza, y junta los pies. Baja el peso para volver a la posicion inicial.\"]','fuerza','[\"One-Arm_Kettlebell_Split_Snatch/0.jpg\", \"One-Arm_Kettlebell_Split_Snatch/1.jpg\"]','Arranque con kettlebell a un brazo y split',509) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm con Pesa Rusa Swings','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"pantorrillas\", \"gluteos\", \"espalda_baja\", \"hombros\"]','[]','fuerza','[\"One-Arm_Kettlebell_Swings/0.jpg\", \"One-Arm_Kettlebell_Swings/1.jpg\"]','Balanceo con pesa rusa a un brazo',510) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con barra larga con un brazo','traccion','principiante','compuesto','barra','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca una barra en un landmine o en una esquina para evitar que se mueva. Carga un peso adecuado en tu extremo.\", \"Ponte de pie junto a la barra y agarra con una mano cerca del collarin. Utilizando tus caderas y piernas, levantate hasta quedar de pie.\", \"Adopta una postura con las rodillas flexionadas, las caderas hacia atras y el pecho hacia arriba. Tu brazo debe estar extendido. Esta sera tu posicion inicial.\", \"Tira del peso hacia tu lado retraiendo el hombro y flexionando el codo. No tires bruscamente del peso ni hagas trampa durante el movimiento.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"One-Arm_Long_Bar_Row/0.jpg\", \"One-Arm_Long_Bar_Row/1.jpg\"]','Remo con barra larga a un brazo',511) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Golpe con balon medicinal con un brazo','traccion','principiante','compuesto','balon_medicinal','[\"abdominales\"]','[\"dorsales\", \"hombros\"]','[\"Comienza en posicion de pie con una postura atletica escalonada. Sujeta un balon medicinal en una mano, en el mismo lado que la pierna trasera. Esta sera tu posicion inicial.\", \"Comienza enrollando el brazo, levantando el balon medicinal por encima de la cabeza. Mientras lo haces, extiende las caderas, las rodillas y los tobillos para cargar peso durante el lanzamiento.\", \"En la extension maxima, flexiona los hombros, la columna vertebral y las caderas para lanzar la pelota con fuerza contra el suelo directamente frente a ti.\", \"Atrapa la pelota en el rebote y continua durante el numero deseado de repeticiones.\"]','fuerza','[\"One-Arm_Medicine_Ball_Slam/0.jpg\", \"One-Arm_Medicine_Ball_Slam/1.jpg\"]','Golpe con balon medicinal con un brazo',512) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm Open Palm con Pesa Rusa Clean','traccion','intermedio','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\"]','[\"Coloca una pesa rusa entre tus pies.\", \"Agarra el asa con una mano y levanta la pesa rapidamente, dejala girar para que la bola de la pesa caiga en la palma de tu mano.\", \"Lanza la pesa frente a ti y atrapa el asa con una mano.\", \"Lleva la pesa al suelo y repite. Asegurate de trabajar ambos brazos.\"]','fuerza','[\"One-Arm_Open_Palm_Kettlebell_Clean/0.jpg\", \"One-Arm_Open_Palm_Kettlebell_Clean/1.jpg\"]','Levantamiento de pesas rusas con una mano y palma abierta',513) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('One-Arm Sobre Cabeza con Pesa Rusa Sentadillas','empuje','experto','compuesto','pesas rusas','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"hombros\"]','[\"Limpia y presiona una pesa rusa con un brazo. Limpia la pesa rusa hasta el hombro extendiendo las piernas y las caderas mientras tiras de la pesa rusa hacia el hombro. Gira la muñeca mientras lo haces. Presiona el peso sobre la cabeza extendiendo el codo. Esta sera tu posicion inicial.\", \"Mirando al frente y manteniendo la pesa rusa bloqueada por encima de ti, flexiona las rodillas y las caderas y baja el torso entre las piernas, manteniendo la cabeza y el pecho erguidos.\", \"Haz una pausa en la posicion inferior durante un segundo antes de levantar la espalda hasta la parte superior, impulsandote con los talones de los pies.\"]','fuerza','[\"One-Arm_Overhead_Kettlebell_Squats/0.jpg\", \"One-Arm_Overhead_Kettlebell_Squats/1.jpg\"]','Sentadillas con pesa rusa por encima de la cabeza con un brazo',514) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto lateral con un brazo','traccion','experto','compuesto','barra','[\"cuadriceps\"]','[\"abdominales\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\"]','[\"Ponte de pie al lado de una barra, cerca de su centro. Dobla las rodillas y baja el cuerpo hasta que puedas alcanzar la barra.\", \"Agarra la barra como si estuvieras agarrando un maletin (con las palmas hacia ti, ya que la barra esta de lado). Es posible que necesites una muñequera si estas utilizando un peso considerable. Esta es tu posicion inicial.\", \"Utiliza las piernas para ayudar a levantar la barra mientras exhalas. Tus brazos deben extenderse completamente al levantar la barra hasta que estes en posicion de pie.\", \"Baja lentamente la barra hacia atras mientras inhalas. Consejo: Asegurate de doblar las rodillas mientras bajas el peso para evitar lesiones.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo y repite el movimiento.\"]','fuerza','[\"One-Arm_Side_Deadlift/0.jpg\", \"One-Arm_Side_Deadlift/1.jpg\"]','One-Arm_Side_Deadlift',515) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Palma abierta con pesa rusa limpia','traccion','experto','compuesto','pesas rusas','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\"]','[\"Coloca una pesa rusa entre tus pies. Limpia la pesa rusa extendiendo las piernas y las caderas mientras levantas la pesa rusa hacia tus hombros.\", \"Suelta la pesa rusa cuando suba y deja que gire para que la bola de la pesa rusa aterrice en las palmas de tus manos.\", \"Suelta la pesa rusa frente a ti y agarra el mango con ambas manos. Baja la pesa rusa a la posicion inicial y repite.\"]','fuerza','[\"Open_Palm_Kettlebell_Clean/0.jpg\", \"Open_Palm_Kettlebell_Clean/1.jpg\"]','Limpiador con kettlebell con palma abierta',518) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl con polea por encima de la cabeza','traccion','intermedio','aislamiento','polea','[\"biceps\"]','[]','[\"Para empezar, coloca un peso que te resulte comodo en cada lado de la maquina de poleas. Nota: Asegurate de que la cantidad de peso seleccionada sea la misma en cada lado.\", \"Ahora ajusta la altura de las poleas en cada lado y asegurate de que esten colocadas a una altura superior a la de tus hombros.\", \"Ponte de pie en el centro de ambos lados y utiliza un agarre por debajo (con las palmas mirando hacia el techo) para agarrar cada asa. Tus brazos deben estar completamente extendidos y paralelos al suelo, con los pies separados a la anchura de los hombros. Tu cuerpo debe estar alineado de manera uniforme con las asas. Esta es la posicion inicial.\", \"Mientras exhalas, aprieta lentamente los biceps en cada lado hasta que tus antebrazos y biceps se toquen.\", \"Mientras inhalas, mueve tus antebrazos hacia atras a la posicion inicial. Nota: Todo tu cuerpo permanece inmovil durante este ejercicio, excepto los antebrazos.\", \"Repite durante la cantidad recomendada de repeticiones prescritas en tu programa.\"]','fuerza','[\"Overhead_Cable_Curl/0.jpg\", \"Overhead_Cable_Curl/1.jpg\"]','Curl con cable por encima de la cabeza',520) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Latissimus de espaldas','estatico','experto','Ninguno','otro','[\"dorsales\"]','[\"triceps\"]','[\"Sientate erguido en el suelo con tu compañero detras de ti. Levanta un brazo recto hacia arriba y flexiona el codo, intentando tocar tu espalda con la mano. Tu compañero debe sujetarte el triceps y la muñeca. Esta sera tu posicion inicial.\", \"Intenta llevar el brazo hacia tu lado mientras tu compañero te impide hacerlo.\", \"Despues de 10-20 segundos, relaja el brazo y deja que tu compañero estire aun mas el dorsal aplicando una suave presion sobre el triceps. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Overhead_Lat/0.jpg\", \"Overhead_Lat/1.jpg\"]','Latissimus con cable por encima de la cabeza',521) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Overhead Slam','traccion','principiante','compuesto','balon_medicinal','[\"dorsales\"]','[]','[\"Sujeta una pelota medicinal con ambas manos y ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Inicia el contramovimiento levantando la pelota por encima de la cabeza y extendiendo completamente el cuerpo.\", \"Invierte el movimiento, golpeando la pelota contra el suelo directamente frente a ti con toda la fuerza que puedas.\", \"Recibe la pelota con ambas manos en el rebote y repite el movimiento.\"]','pliometria','[\"Overhead_Slam/0.jpg\", \"Overhead_Slam/1.jpg\"]','Golpe por encima de la cabeza',522) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla por encima de la cabeza','empuje','experto','compuesto','barra','[\"cuadriceps\"]','[\"abdominales\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"hombros\", \"triceps\"]','[\"Comienza colocando una barra frente a ti en el suelo. Tus pies deben estar separados a una distancia mayor que el ancho de tus hombros.\", \"Dobla las rodillas y utiliza un agarre pronado (palmas hacia ti) para agarrar la barra. Tus manos deben estar separadas a una distancia mayor que el ancho de tus hombros antes de levantar la barra. Una vez que estes en posicion, levanta la barra hasta que puedas apoyarla en tu pecho.\", \"Mueve la barra por encima y ligeramente detras de tu cabeza y asegurate de que tus brazos esten completamente extendidos. Manten la cabeza arriba en todo momento y tambien manten la espalda recta. Retrae los omoplatos. Esta es tu posicion inicial.\", \"Baja lentamente el peso doblando las rodillas hasta que tus muslos esten paralelos al suelo mientras inhalas. Consejo: Manten la espalda recta mientras realizas este ejercicio para evitar lesiones y tus brazos deben permanecer extendidos y por encima de la cabeza en todo momento.\", \"Ahora utiliza los pies y las piernas para ayudar a llevar el peso hacia arriba hasta la posicion inicial mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','halterofilia_olimpica','[\"Overhead_Squat/0.jpg\", \"Overhead_Squat/1.jpg\"]','Sentadilla por encima de la cabeza',523) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento por encima de la cabeza','estatico','principiante','compuesto','Ninguno','[\"abdominales\"]','[\"pecho\", \"antebrazos\", \"dorsales\", \"triceps\"]','[\"Ponte de pie con la espalda recta, entrelaza los dedos y abre las palmas hacia el techo. Manten los hombros hacia abajo mientras extiendes los brazos hacia arriba.\", \"Para estirar todo el torso, tira del coxis hacia abajo y estabiliza el torso mientras lo haces. Estira los musculos tanto de la parte delantera como de la espalda del torso.\"]','estiramiento','[\"Overhead_Stretch/0.jpg\", \"Overhead_Stretch/1.jpg\"]','Estiramiento por encima de la cabeza',524) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Triceps por encima de la cabeza','estatico','experto','Ninguno','solo_cuerpo','[\"triceps\"]','[\"dorsales\"]','[\"Sientate erguido en el suelo con tu compañero detras de ti. Levanta un brazo recto hacia arriba y flexiona el codo, intentando tocar tu espalda con la mano. Tu compañero debe sujetarte el codo y la muñeca. Esta sera tu posicion inicial.\", \"Intenta extender el brazo recto hacia arriba mientras tu compañero te impide hacerlo.\", \"Despues de 10-20 segundos, relaja el brazo y deja que tu compañero estire aun mas el triceps aplicando una suave presion en la muñeca. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Overhead_Triceps/0.jpg\", \"Overhead_Triceps/1.jpg\"]','Triceps por encima de la cabeza',525) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pallof Press','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[\"pecho\", \"hombros\", \"triceps\"]','[\"Conecta un mango estandar a una torre y, si es posible, coloca la polea a la altura de los hombros. Si no es posible, bastara con una polea baja.\", \"Con tu lado hacia la polea, agarra el mango con ambas manos y alejate de la torre. Debes estar aproximadamente a un brazo de distancia de la polea, con la tension del peso en la polea.\", \"Con tus pies separados a la anchura de las caderas y las rodillas ligeramente flexionadas, manten la polea en el centro de tu pecho. Esta sera tu posicion inicial.\", \"Presiona el cable alejandote de tu pecho, extendiendo completamente ambos brazos. Tu core debe estar tenso y activado.\", \"Manten la repeticion durante varios segundos antes de volver a la posicion inicial.\", \"Al finalizar la serie, repite mirando en la otra direccion.\"]','fuerza','[\"Pallof_Press/0.jpg\", \"Pallof_Press/1.jpg\"]','Pallof_Press',526) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pallof Press con rotacion','traccion','principiante','compuesto','polea','[\"abdominales\"]','[\"pecho\", \"hombros\", \"triceps\"]','[\"Conecta un mango estandar a una torre y coloca la polea a la altura de los hombros.\", \"De espaldas a la polea, agarra el mango con una mano y alejate de la torre. Debes estar aproximadamente a un brazo de distancia alejandote de la polea, con la tension del peso en la polea. Alinea el brazo extendido con el cable.\", \"Con los pies separados a la anchura de las caderas, tira de la polea hacia tu pecho y agarra el mango con la otra mano. Ambas manos deben estar en el mango en este momento.\", \"Mirando hacia delante, empuja la polea alejandola de tu pecho. Tu core debe estar tenso y activado.\", \"Manteniendo tus caderas rectas, gira tu torso alejandote de la polea hasta completar un cuarto de vuelta.\", \"Manten tu postura rigida y los brazos rectos. Regresa a la posicion neutral de forma lenta y controlada. Tus brazos deben estar extendidos frente a ti.\", \"Con la tension lateral aun activando tu abdomen, lleva tus manos a tu pecho e inmediatamente empuja hacia afuera hasta una posicion completamente extendida. Esto constituye una repeticion.\", \"Repite hasta el fallo.\", \"Luego, reposiciona y repite la misma serie de movimientos en el lado opuesto.\"]','fuerza','[\"Pallof_Press_With_Rotation/0.jpg\", \"Pallof_Press_With_Rotation/1.jpg\"]','Pallof_Press_con_rotacion',527) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Palmas hacia abajo con mancuernas, flexion de muñecas sobre un banco','traccion','principiante','aislamiento','mancuerna','[\"antebrazos\"]','[]','[\"Comienza colocando dos mancuernas a un lado de un banco plano.\", \"Arrodillate con ambas rodillas de modo que tu cuerpo quede frente al banco plano.\", \"Usa tus brazos para agarrar ambas mancuernas con un agarre pronado (palmas hacia abajo) y llevalas hacia arriba de modo que tus antebrazos queden apoyados contra el banco plano. Tus muñecas deben quedar colgando por el borde.\", \"Comienza flexionando las muñecas hacia arriba y exhalando.\", \"Baja lentamente tus muñecas hacia atras hasta la posicion inicial mientras inhalas.\", \"Tus antebrazos deben permanecer inmoviles, ya que las muñecas son el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/0.jpg\", \"Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench/1.jpg\"]','Flexion de muñeca con mancuernas con las palmas hacia abajo sobre un banco',528) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de muñeca con las palmas hacia abajo sobre un banco','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Comienza colocando una barra en un lado de un banco plano.\", \"Arrodillate con ambas rodillas de modo que tu cuerpo quede frente al banco plano.\", \"Usa tus brazos para agarrar la barra con un agarre pronado (palmas hacia abajo) y levantalas de modo que tus antebrazos queden apoyados contra el banco plano. Tus muñecas deben quedar colgando por el borde.\", \"Comienza flexionando las muñecas hacia arriba y exhalando.\", \"Baja lentamente las muñecas hacia atras hasta la posicion inicial mientras inhalas.\", \"Tus antebrazos deben permanecer inmoviles, ya que las muñecas son el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Palms-Down_Wrist_Curl_Over_A_Bench/0.jpg\", \"Palms-Down_Wrist_Curl_Over_A_Bench/1.jpg\"]','Flexion de muñecas con las palmas hacia abajo sobre un banco',529) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de muñecas con barra con las palmas hacia arriba sobre un banco','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Comienza colocando una barra a un lado de un banco plano.\", \"Arrodillate con ambas rodillas de modo que tu cuerpo quede frente al banco plano.\", \"Usa tus brazos para agarrar la barra con un agarre supinado (palmas hacia arriba) y levantalas de modo que tus antebrazos queden apoyados contra el banco plano. Tus muñecas deben quedar colgando por el borde.\", \"Comienza flexionando las muñecas hacia arriba y exhalando.\", \"Baja lentamente las muñecas hacia atras hasta la posicion inicial mientras inhalas.\", \"Tus antebrazos deben permanecer inmoviles, ya que las muñecas son el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/0.jpg\", \"Palms-Up_Barbell_Wrist_Curl_Over_A_Bench/1.jpg\"]','Palmas hacia arriba con barra, flexion de muñecas sobre un banco',530) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Fondos en barras paralelas','empuje','principiante','compuesto','otro','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Ponte de pie entre un par de barras paralelas. Coloca una mano en cada barra y luego da un pequeño salto para ayudarte a colocarte en la posicion inicial con los brazos extendidos.\", \"Comienza flexionando los codos, bajando el cuerpo hasta que los brazos formen un angulo de 90 grados. Evita balancearte y manten una buena postura durante todo el descenso.\", \"Invierte el movimiento extendiendo el codo, empujandote hacia arriba hasta la posicion inicial.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Parallel_Bar_Dip/0.jpg\", \"Parallel_Bar_Dip/1.jpg\"]','Fondos en barras paralelas',532) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Inclinacion pelvica en puente','estatico','intermedio','compuesto','Ninguno','[\"espalda_baja\"]','[]','[\"Acuestate boca arriba con los pies en el suelo, los talones directamente debajo de las rodillas.\", \"Levanta solo el coxis hacia el techo para estirar la parte baja de la espalda. (No levantes toda la columna todavia). Mete el estomago.\", \"Para hacer un puente, levanta toda la columna excepto el cuello.\"]','estiramiento','[\"Inclinacion_pelvica_en_puente/0.jpg\", \"Inclinacion_pelvica_en_puente/1.jpg\"]','Inclinacion pelvica en puente',533) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de los peroneos','estatico','intermedio','Ninguno','otro','[\"pantorrillas\"]','[]','[\"En posicion sentada, pasa un cinturon, una cuerda o una banda alrededor de un pie. Esta sera tu posicion inicial.\", \"Con la pierna extendida y el talon separado del suelo, tira del cinturon para que el pie quede invertido, con la parte interior del pie tirando hacia ti. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Peroneals_Stretch/0.jpg\", \"Peroneals_Stretch/1.jpg\"]','Peroneos_Stretch',534) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peroneos-SMR','estatico','intermedio','Ninguno','rodillo_espuma','[\"pantorrillas\"]','[]','[\"Acuestate de lado, apoyando tu peso en tu antebrazo y en un rodillo de espuma colocado en la parte exterior de tu pierna. La pierna superior puede estar encima de la pierna inferior o cruzada frente a ti. Esta sera tu posicion inicial.\", \"Levanta las caderas del suelo y comienza a rodar desde debajo de la rodilla hasta por encima del tobillo en el lado de la pierna, haciendo pausas en los puntos de tension durante 10-30 segundos. Repite con la otra pierna.\"]','estiramiento','[\"Peroneals-SMR/0.jpg\", \"Peroneals-SMR/1.jpg\"]','Peroneos-SMR',535) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Puente de cadera con pelota fisioterapeutica','empuje','principiante','compuesto','fitball','[\"gluteos\"]','[\"isquiotibiales\"]','[\"Acuestate sobre una pelota de manera que la parte superior de tu espalda quede sobre la pelota con tus caderas sin apoyo. Ambos pies deben estar apoyados en el suelo, separados a la altura de las caderas o mas. Esta sera tu posicion inicial.\", \"Comienza extendiendo las caderas usando tus gluteos e isquiotibiales, levantando tus caderas hacia arriba mientras haces un puente.\", \"Haz una pausa en la parte superior del movimiento y regresa a la posicion inicial.\"]','fuerza','[\"Physioball_Hip_Bridge/0.jpg\", \"Physioball_Hip_Bridge/1.jpg\"]','Fisioball_Puente de cadera',536) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con barra','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"antebrazos\", \"dorsales\", \"espalda_media\", \"hombros\"]','[\"Las prensas con pasadores eliminan la fase excentrica del press de banca, desarrollando la fuerza inicial. Tambien te permiten entrenar el rango de movimiento deseado.\", \"El banco debe colocarse arriba en una jaula de potencia. Ajusta los pasadores al punto deseado en tu rango de movimiento, ya sea justo en el bloqueo o a una pulgada de tu pecho. La barra debe moverse a los pines y prepararse durante el levantamiento.\", \"Comienza por recostarte en el banco, con la barra directamente sobre el punto de contacto durante tu press de banca habitual. Mete los pies debajo de ti y arquea la espalda. Usando la barra para ayudar a soportar tu peso, levanta los hombros del banco y retractalos, apretando los omoplatos. Usa los pies para empujar los trapecios contra el banco. Manten esta posicion corporal firme durante todo el movimiento.\", \"Puedes adoptar un agarre estandar en el banco, o a la anchura de los hombros, para centrarte en los triceps. La barra, las muñecas y los codos deben permanecer alineados en todo momento. Concentrate en apretar la barra e intentar separarla.\", \"Empuja la barra hacia arriba con tanta fuerza como sea posible. Los codos deben estar pegados al cuerpo hasta el bloqueo.\", \"Vuelve a colocar la barra en los soportes, haciendo una pausa antes de comenzar la siguiente repeticion.\"]','levantamiento de pesas','[\"Pin_Presses/0.jpg\", \"Pin_Presses/1.jpg\"]','Press con pines',537) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Piriforme-SMR','estatico','intermedio','aislamiento','rodillo_espuma','[\"gluteos\"]','[]','[\"Sientate con las nalgas sobre un rodillo de espuma. Dobla las rodillas y luego cruza una pierna de modo que el tobillo quede sobre la rodilla. Esta sera tu posicion inicial.\", \"Desplaza tu peso hacia el lado de la pierna cruzada, rodando sobre las nalgas hasta que sientas tension en la parte superior del gluteo. Puedes ayudar al estiramiento utilizando una mano para tirar de la rodilla doblada hacia tu pecho. Manten esta posicion durante 10-30 segundos y luego cambia de lado.\"]','estiramiento','[\"Piriformis-SMR/0.jpg\", \"Piriformis-SMR/1.jpg\"]','Piriforme-SMR',538) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Plancha','estatico','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Ponte boca abajo en el suelo, apoyando tu peso en los dedos de los pies y los antebrazos. Tus brazos deben estar doblados y directamente debajo de los hombros.\", \"Manten tu cuerpo recto en todo momento y manten esta posicion el mayor tiempo posible. Para aumentar la dificultad, puedes levantar un brazo o una pierna.\"]','fuerza','[\"Plank/0.jpg\", \"Plank/1.jpg\"]','Plancha',539) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Plate Twist','traccion','intermedio','compuesto','otro','[\"abdominales\"]','[]','[\"Acuestate en el suelo o en una colchoneta de ejercicios con las piernas completamente extendidas y la parte superior del cuerpo erguida. Agarra la placa por los lados con ambas manos frente a los abdominales con los brazos ligeramente flexionados.\", \"Cruza lentamente las piernas cerca de los tobillos y levantalas del suelo. Las rodillas tambien deben estar ligeramente flexionadas. Nota: Mueve ligeramente la parte superior del cuerpo hacia atras para ayudarte a mantener el equilibrio al realizar este ejercicio. Esta es la posicion inicial.\", \"Mueve la placa hacia el lado izquierdo y toca el suelo con ella. Exhala mientras realizas este movimiento.\", \"Vuelve a la posicion inicial mientras inhalas y luego repite el movimiento, pero esta vez hacia el lado derecho del cuerpo. Consejo: Realiza un movimiento lento y controlado en todo momento. Los movimientos bruscos pueden lesionar la espalda.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Plate_Twist/0.jpg\", \"Plate_Twist/1.jpg\"]','Placa_Giro',541) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Deslizamientos de isquiotibiales en plataforma','traccion','principiante','aislamiento','otro','[\"isquiotibiales\"]','[\"gluteos\"]','[\"Para este movimiento se necesita un suelo de madera o similar. Tumbate boca arriba con las piernas estiradas. Coloca una toalla de gimnasio o un peso ligero debajo del talon. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando la rodilla, manteniendo la otra pierna estirada.\", \"Continua acercando el talon hacia ti, deslizandolo por el suelo.\", \"Cuando la rodilla este completamente flexionada, invierte el movimiento para volver a la posicion inicial.\"]','fuerza','[\"Platform_Hamstring_Slides/0.jpg\", \"Platform_Hamstring_Slides/1.jpg\"]','Plataforma_Deslizamientos_Isquiotibiales',542) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Plyo con Pesa Rusa Pushups','empuje','experto','compuesto','pesas rusas','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Coloca una pesa rusa en el suelo. Ponte en posicion de flexion, con los dedos de los pies en el suelo y una mano sosteniendo la pesa rusa, con los codos extendidos. Esta sera tu posicion inicial.\", \"Comienza bajando lo mas que puedas, manteniendo la espalda recta.\", \"Rapidamente y con fuerza, invierte la direccion, empujandote hacia arriba al otro lado de la pesa rusa, cambiando de mano al hacerlo. Continua el movimiento descendiendo y repitiendo el movimiento hacia adelante y hacia atras.\"]','fuerza','[\"Plyo_Kettlebell_Pushups/0.jpg\", \"Plyo_Kettlebell_Pushups/1.jpg\"]','Flexiones con pesas rusas',544) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion pliometrica','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Ponte en posicion boca abajo en el suelo, apoyando tu peso en tus manos y dedos de los pies.\", \"Tus brazos deben estar completamente extendidos con las manos a la altura de los hombros. Manten tu cuerpo recto durante todo el movimiento. Esta sera tu posicion inicial.\", \"Desciende flexionando los codos, bajando tu pecho hacia el suelo.\", \"En la parte inferior, invierte el movimiento empujandote hacia arriba mediante la extension del codo lo mas rapido posible. Intenta empujar la parte superior del cuerpo hacia arriba hasta que tus manos se separen del suelo.\", \"Vuelve a la posicion inicial y repite el ejercicio.\", \"Para aumentar la dificultad, añade palmadas al movimiento mientras estas en el aire.\"]','pliometria','[\"Plyo_Push-up/0.jpg\", \"Plyo_Push-up/1.jpg\"]','Flexiones pliometricas',545) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento del tibial posterior','estatico','intermedio','Ninguno','otro','[\"pantorrillas\"]','[]','[\"En posicion sentada, pasa un cinturon, una cuerda o una banda alrededor de uno de los pies. Esta sera tu posicion inicial.\", \"Con la pierna extendida y el talon separado del suelo, tira del cinturon para que el pie se evarde, con la parte exterior del pie tirando hacia ti. Manten durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Posterior_Tibialis_Stretch/0.jpg\", \"Posterior_Tibialis_Stretch/1.jpg\"]','Estiramiento del tibial posterior',546) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Power Clean desde bloques','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"cuadriceps\"]','[\"Con una barra en cajas de la altura deseada, agarra justo fuera de las piernas. Baja las caderas con el peso centrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho hacia arriba y los hombros justo frente a la barra. Esta sera tu posicion inicial.\", \"Comienza el primer tiron impulsandote con los talones y extendiendo las rodillas. El angulo de la espalda debe permanecer igual y los brazos deben permanecer rectos. A medida que la barra se acerque a la mitad del muslo, comienza a extender las caderas.\", \"En un movimiento de salto, acelera extendiendo las caderas, las rodillas y los tobillos, utilizando la velocidad para mover la barra hacia arriba. No deberia ser necesario tirar activamente de los brazos para acelerar el peso. Al final del segundo tiron, el cuerpo debe estar completamente extendido, inclinandose ligeramente hacia atras, con los brazos aun extendidos.\", \"A medida que se logra la extension completa, pasa al tercer tiron encogiendo los hombros y flexionando los brazos de forma agresiva con los codos hacia arriba y hacia fuera. En el punto maximo de extension, colocate debajo de la barra lo suficientemente lejos como para poder apoyarla sobre los hombros, girando los codos debajo de la barra mientras lo haces. La barra debe colocarse sobre los hombros extendidos, tocando ligeramente la garganta con las manos relajadas.\", \"Recupere inmediatamente impulsandose con los talones, manteniendo el torso erguido y los codos arriba. Continue hasta que se haya levantado a una posicion de pie y complete la repeticion devolviendo el peso a las cajas.\"]','halterofilia_olimpica','[\"Power_Clean_from_Blocks/0.jpg\", \"Power_Clean_from_Blocks/1.jpg\"]','Power_Clean_desde_bloques',548) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Preacher Martillo con Mancuerna Curl','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Coloca la parte superior de ambos brazos en la parte superior del banco predicador mientras mantienes una mancuerna en cada mano con las palmas enfrentadas entre si (agarre neutro).\", \"Mientras inspiras, baja lentamente las mancuernas hasta que el brazo este extendido y el biceps completamente estirado.\", \"Mientras espiras, utiliza el biceps para curvar el peso hacia arriba hasta que el biceps este completamente contraido y las mancuernas esten a la altura de los hombros.\", \"Aprieta el biceps con fuerza durante un segundo en la posicion contraida y repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Preacher_Hammer_Dumbbell_Curl/0.jpg\", \"Preacher_Hammer_Dumbbell_Curl/1.jpg\"]','Curl predicador con mancuernas',555) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press abdominal','empuje','experto','compuesto','barra','[\"abdominales\"]','[\"pecho\", \"hombros\", \"triceps\"]','[\"Para empezar, tumbate boca abajo en un banco con una barra apoyada en tu pecho. Coloca tus piernas de forma que queden bien sujetas en la extension del banco abdominal. Esta es la posicion inicial.\", \"Mientras inhalas, contrae los abdominales y los gluteos. Simultaneamente, flexiona el torso como si estuvieras haciendo una abdominal y empuja la barra hacia una posicion sobre la cabeza mientras exhalas. Consejo: Usa tus brazos para empujar la barra hacia fuera mientras realizas este ejercicio, sin dejar de concentrarte en los musculos abdominales.\", \"Baja la parte superior del cuerpo hacia abajo hasta la posicion inicial mientras llevas la barra hacia abajo hasta tu torso. Recuerda respirar mientras bajas el cuerpo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Press_Sit-Up/0.jpg\", \"Press_Sit-Up/1.jpg\"]','Press con abdominales',556) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Prone Manual Hamstring','estatico','principiante','aislamiento','Ninguno','[\"isquiotibiales\"]','[]','[\"Necesitaras un compañero para este ejercicio. Tumbate boca abajo con las piernas estiradas. Tu compañero colocara la mano en tu talon.\", \"Para empezar, flexiona la rodilla para levantar la pierna. Tu compañero debe ofrecer resistencia, inicialmente ligera y aumentando la presion a medida que se completa el movimiento. Comunicate con tu compañero para controlar los niveles de resistencia adecuados.\", \"Haz una pausa arriba, volviendo la pierna a la posicion inicial mientras tu compañero ofrece resistencia en la otra direccion.\"]','fuerza','[\"Prone_Manual_Hamstring/0.jpg\", \"Prone_Manual_Hamstring/1.jpg\"]','Prone_Manual_Hamstring',557) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Prowler Sprint','empuje','principiante','compuesto','otro','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Pecho\", \"Gluteos\", \"Cuadriceps\", \"Hombros\"]','[\"Coloca el trineo en una superficie adecuada, cargado con un peso adecuado. El trineo debe proporcionar suficiente resistencia como para requerir esfuerzo, pero no tan pesado como para que te ralentice significativamente.\", \"Puedes usar las asas altas o bajas durante este ejercicio. Coloca tus manos en las asas con los brazos extendidos, inclinandote hacia el implemento.\", \"Con una buena postura, impulsa el suelo con pasos cortos y alternos. Muevete lo mas rapido que puedas durante una distancia corta.\"]','cardio','[\"Prowler_Sprint/0.jpg\", \"Prowler_Sprint/1.jpg\"]','Sprint con prowler',558) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Pull Through','traccion','principiante','compuesto','polea','[\"gluteos\"]','[\"isquiotibiales\", \"espalda_baja\"]','[\"Comienza de pie a unos pasos frente a una polea baja con una cuerda o asa conectada. Colocate de espaldas a la maquina, a horcajadas sobre la polea, con los pies bien separados.\", \"Comienza el movimiento estirando las piernas lo mas lejos posible, doblando las caderas. Manten las rodillas ligeramente flexionadas. Manten los brazos rectos y extiende la cadera para ponerte recto. Evita tirar hacia arriba con los hombros; todo el movimiento debe originarse en las caderas.\"]','fuerza','[\"Pull_Through/0.jpg\", \"Pull_Through/1.jpg\"]','Tiron',559) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Push Press','empuje','experto','compuesto','barra','[\"hombros\"]','[\"cuadriceps\", \"triceps\"]','[]','halterofilia_olimpica','[\"Push_Press/0.jpg\", \"Push_Press/1.jpg\"]','Empuje_Press',561) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion hasta plancha lateral','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Get into pushup posicion en the toes con tus manos just outside of shoulder width.\", \"Perform a pushup por allowing the codos to flex. As you descend, keep tu cuerpo straight.\", \"Haz una flexion y, al subir, desplaza tu peso hacia el lado izquierdo del cuerpo, gira hacia ese lado mientras llevas el brazo derecho hacia arriba, hacia el techo, en una plancha lateral.\", \"Baja el brazo hacia atras hasta el suelo durante otra flexion y luego gira hacia el otro lado.\", \"Repite la serie, alternando cada lado, durante 10 o mas repeticiones.\"]','fuerza','[\"Push_Up_to_Side_Plank/0.jpg\", \"Push_Up_to_Side_Plank/1.jpg\"]','Flexion con plancha lateral',563) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion amplia','Ninguno','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"abdominales\", \"hombros\", \"triceps\"]','[\"Con las manos bien separadas, apoya tu cuerpo sobre los dedos de los pies y las manos en posicion de plancha. Los codos deben estar extendidos y el cuerpo recto. No dejes que las caderas se hundan. Esta sera tu posicion inicial.\", \"Para empezar, flexiona los codos, bajando el pecho al suelo mientras inhalas.\", \"Utilizando los musculos pectorales, empuja la parte superior del cuerpo hacia arriba hasta la posicion inicial extendiendo los codos. Exhala mientras realizas este paso.\", \"Despues de hacer una pausa en la posicion contraida, repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Push-Up_Wide/0.jpg\", \"Push-Up_Wide/1.jpg\"]','Flexiones amplias',564) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones - Posicion cerrada para triceps','empuje','intermedio','compuesto','solo_cuerpo','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Acuestate en el suelo boca abajo y coloca tus manos mas cerca que el ancho de los hombros durante una posicion de manos cerrada. Asegurate de que estas sosteniendo tu torso arriba a la distancia de los brazos.\", \"Baja hasta que tu pecho casi toque el suelo mientras inhalas.\", \"Usando tus triceps y algunos de tus musculos pectorales, presiona la parte superior de tu cuerpo hacia arriba a la posicion inicial y aprieta tu pecho. Exhala mientras realizas este paso.\", \"Despues de una pausa de un segundo en la posicion contraida, repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Push-Ups_-_Close_Triceps_Position/0.jpg\", \"Push-Ups_-_Close_Triceps_Position/1.jpg\"]','Flexiones - Posicion de triceps cerrado',565) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones con los pies sobre una pelota de ejercicios','empuje','intermedio','compuesto','fitball','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate en el suelo boca abajo y coloca tus manos aproximadamente a 36 pulgadas de distancia entre si, sosteniendo tu torso arriba a la longitud de los brazos.\", \"Coloca los dedos de los pies sobre una pelota de ejercicios. Esto permitira que tu cuerpo se eleve.\", \"Baja hasta que tu pecho casi toque el suelo mientras inhalas.\", \"Usando tus musculos pectorales, empuja la parte superior de tu cuerpo hacia arriba hasta la posicion inicial y aprieta tu pecho. Exhala mientras realizas este paso.\", \"Despues de una pausa de un segundo en la posicion contraida, repite el movimiento durante la cantidad prescrita de repeticiones.\"]','fuerza','[\"Push-Ups_With_Feet_On_An_Exercise_Ball/0.jpg\", \"Push-Ups_With_Feet_On_An_Exercise_Ball/1.jpg\"]','Flexiones con los pies sobre una pelota de ejercicios',567) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones (posiciones de manos cerradas y amplias)','empuje','principiante','compuesto','solo_cuerpo','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate en el suelo boca abajo y con el cuerpo recto, con los dedos de los pies en el suelo y las manos mas separadas que el ancho de los hombros para una posicion de manos amplia, y mas juntas que el ancho de los hombros para una posicion de manos cerrada. Asegurate de mantener el torso levantado a la altura de los brazos.\", \"Baja hasta que el pecho casi toque el suelo mientras inhalas.\", \"Utilizando los musculos pectorales, empuja la parte superior del cuerpo hacia arriba hasta la posicion inicial y contrae el pecho. Exhala mientras realizas este paso.\", \"Despues de una breve pausa en la posicion contraida, repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Pushups_Close_and_Wide_Hand_Positions/0.jpg\", \"Pushups_Close_and_Wide_Hand_Positions/1.jpg\"]','Flexiones con manos juntas y separadas',569) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Piramide','estatico','principiante','Ninguno','fitball','[\"espalda_baja\"]','[\"hombros\"]','[\"Comienza rodando el torso hacia adelante sobre la pelota, de modo que tus caderas descansen sobre la pelota y se conviertan en el punto mas alto de tu cuerpo.\", \"Apoya las manos y los pies en el suelo. Los brazos y las piernas pueden estar ligeramente doblados o rectos, dependiendo del tamaño de la pelota, tu flexibilidad y la longitud de tus extremidades. Esto tambien ayuda a desarrollar la fuerza estabilizadora en el torso y los hombros.\"]','estiramiento','[\"Piramide/0.jpg\", \"Piramide/1.jpg\"]','Piramide',570) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de cuadriceps','estatico','intermedio','Ninguno','otro','[\"cuadriceps\"]','[]','[\"Acuestate de lado. Pasa un cinturon, una cuerda o una banda alrededor de tu pie superior. Flexiona la rodilla y extiende la cadera, intentando tocar los gluteos con el pie y sujetando el cinturon con las manos. Esta sera tu posicion inicial.\", \"Con el cinturon sobre el hombro o sobre la cabeza, tira suavemente para aumentar el estiramiento de los cuadriceps. Manten la posicion durante 10-20 segundos y luego cambia de lado.\"]','estiramiento','[\"Quad_Stretch/0.jpg\", \"Quad_Stretch/1.jpg\"]','Cuadriceps-SMR',571) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cuadriceps-SMR','estatico','intermedio','aislamiento','rodillo_espuma','[\"cuadriceps\"]','[]','[\"Acuestate boca abajo en el suelo con tu peso apoyado en tus manos o antebrazos. Coloca un rodillo de espuma debajo de una pierna en el cuadriceps y manten el pie separado del suelo. Asegurate de relajar la pierna tanto como sea posible. Esta sera tu posicion inicial.\", \"Desplaza todo el peso que puedas sobre la pierna que vas a estirar, rueda el rodillo desde por encima de la rodilla hasta por debajo de la cadera, manteniendo los puntos de tension durante 10-30 segundos. Cambia de lado.\"]','estiramiento','[\"Cuadriceps-SMR/0.jpg\", \"Cuadriceps-SMR/1.jpg\"]','Cuadriceps-SMR',572) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto rapido','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Necesitaras una caja para este ejercicio.\", \"Comienza de pie frente a la caja, a una distancia de entre 30 y 60 cm de su borde.\", \"Utilizando tus caderas, salta sobre la caja y aterriza con ambas piernas. Asegurate de aterrizar con las piernas flexionadas y los pies planos.\", \"Inmediatamente despues de aterrizar, extiende completamente todo el cuerpo y balancea los brazos por encima de la cabeza para impulsarte y saltar de la caja. Usa tus piernas para absorber el impacto del aterrizaje.\"]','pliometria','[\"Quick_Leap/0.jpg\", \"Quick_Leap/1.jpg\"]','Quick_Leap',573) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Entrega en rack','traccion','intermedio','compuesto','barra','[\"hombros\"]','[\"antebrazos\", \"trapecios\"]','[\"Este ejercicio enseña a llevar la barra a la posicion de rack en los hombros. Comienza sosteniendo una barra en la posicion de espantapajaros, con los brazos superiores paralelos al suelo y los antebrazos colgando. Utiliza un agarre en gancho, con los dedos envueltos alrededor de los pulgares.\", \"Comienza girando los codos alrededor de la barra, llevandola a los hombros. A medida que tus codos se adelantan, relaja el agarre. Los hombros deben estar protraidos, proporcionando un apoyo para la barra, que debe tocar ligeramente la garganta.\", \"Es importante que la barra permanezca cerca del cuerpo en todo momento, ya que con una carga mas pesada cualquier distancia provocara una colision no deseada. A medida que el movimiento se vuelve mas suave, se puede aumentar la velocidad y la carga antes de seguir progresando.\"]','halterofilia_olimpica','[\"Rack_Delivery/0.jpg\", \"Rack_Delivery/1.jpg\"]','Entrega en rack',574) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rack Pulls','traccion','intermedio','compuesto','barra','[\"espalda_baja\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"trapecios\"]','[\"Coloca la barra en un power rack con los pasadores. Los pasadores deben colocarse en el punto deseado: justo debajo de las rodillas, justo por encima o en la mitad del muslo. Colocate frente a la barra en la posicion adecuada para realizar un peso muerto. Los pies deben estar debajo de las caderas, las manos separadas a la anchura de los hombros, la espalda arqueada y las caderas hacia atras para activar los isquiotibiales. Dado que el peso suele ser pesado, puedes utilizar un agarre mixto, un agarre en gancho o utilizar correas para ayudar a sostener el peso.\", \"Con la cabeza mirando hacia adelante, extiende las caderas y las rodillas, tirando del peso hacia arriba y hacia atras hasta bloquearlo. Asegurate de tirar de los hombros hacia atras al completar el movimiento.\", \"Vuelve a colocar el peso en los pasadores y repite.\"]','levantamiento de pesas','[\"Rack_Pulls/0.jpg\", \"Rack_Pulls/1.jpg\"]','Tirones en rack',576) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion trasera de piernas','empuje','principiante','Ninguno','solo_cuerpo','[\"cuadriceps\"]','[]','[\"Colocate con las manos y las rodillas sobre una colchoneta de ejercicios. La cabeza debe mirar hacia adelante y la flexion de las rodillas debe crear un angulo de 90 grados entre los isquiotibiales y las pantorrillas. Esta sera tu posicion inicial.\", \"Extiende una pierna hacia arriba y detras de ti. La rodilla y la cadera deben extenderse por completo. Repite durante 5-10 repeticiones y luego cambia de lado.\"]','estiramiento','[\"Rear_Leg_Raises/0.jpg\", \"Rear_Leg_Raises/1.jpg\"]','Elevaciones de piernas traseras',577) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Bicicleta reclinada','Ninguno','principiante','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, sientate en la bicicleta y ajusta el asiento a tu altura.\", \"Selecciona la opcion deseada en el menu. Puedes empezar a pedalear para encenderla. Puedes utilizar el ajuste manual o seleccionar un programa. Normalmente, puedes introducir tu edad y peso para calcular la cantidad de calorias quemadas durante el ejercicio. El nivel de resistencia se puede cambiar durante el entrenamiento. Las asas se pueden utilizar para controlar tu frecuencia cardiaca y ayudarte a mantener una intensidad adecuada.\", \"Las bicicletas reclinadas ofrecen comodidad, beneficios cardiovasculares y tienen menos impacto que otras actividades. Una persona de 68 kg quemara aproximadamente 230 calorias pedaleando a un ritmo moderado durante 30 minutos, en comparacion con las 450 calorias o mas que se queman corriendo.\"]','cardio','[\"Recumbent_Bike/0.jpg\", \"Recumbent_Bike/1.jpg\"]','Bicicleta reclinada',578) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje de retorno desde la postura','empuje','principiante','compuesto','balon_medicinal','[\"hombros\"]','[\"pecho\", \"triceps\"]','[\"Necesitaras un compañero para este ejercicio.\", \"Comienza en una postura atletica de 2 o 3 puntos.\", \"A la señal, muevete a una posicion para recibir el pase de tu compañero.\", \"Atrapa el balon medicinal con ambas manos y lanzalo inmediatamente hacia tu compañero.\", \"Puedes modificar este ejercicio corriendo por diferentes rutas.\"]','pliometria','[\"Return_Push_from_Stance/0.jpg\", \"Return_Push_from_Stance/1.jpg\"]','Empuje de retorno desde la posicion de pie',579) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press inverso con banda desde el banco','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"antebrazos\", \"dorsales\", \"espalda_media\", \"hombros\"]','[\"Coloca un banco dentro de una jaula de potencia, con la barra ajustada a la altura correcta. Comienza por fijar las bandas a las clavijas de las bandas o a la parte superior de la jaula. Asegurate de que estaras en la posicion correcta debajo de las bandas. Fija el otro extremo a la barra.\", \"Acuestate en el banco, mete los pies debajo de ti y arquea la espalda. Utilizando la barra para ayudarte a soportar tu peso, levanta los hombros del banco y retractalos, apretando los omoplatos. Utiliza los pies para empujar los trapecios contra el banco. Manten esta posicion corporal firme durante todo el movimiento. Sea cual sea la anchura de tu agarre, debe cubrir el anillo de la barra.\", \"Tira de la barra fuera de la jaula sin protraer los hombros. Concentrate en apretar la barra e intenta separarla. Baja la barra hasta la parte inferior del pecho o la parte superior del estomago. La barra, la muñeca y el codo deben permanecer alineados en todo momento.\", \"Haz una pausa cuando la barra toque tu torso y luego empuja la barra hacia arriba con tanta fuerza como sea posible. Los codos deben estar pegados al cuerpo hasta el bloqueo.\"]','levantamiento de pesas','[\"Reverse_Band_Bench_Press/0.jpg\", \"Reverse_Band_Bench_Press/1.jpg\"]','Press de banca inverso con banda',580) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto sumo con banda inversa','traccion','experto','compuesto','barra','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[\"Comienza con una barra cargada en el suelo dentro de una jaula de potencia. Fija las bandas a la parte superior de la jaula, utilizando clavijas o el propio marco. Fija el otro extremo a la barra.\", \"Acercate a la barra de modo que esta se cruce con el centro de los pies. Los pies deben estar muy separados, cerca de los collares. Dobla las caderas para agarrar la barra. Los brazos deben estar directamente debajo de los hombros, dentro de las piernas, y puedes usar un agarre pronado, un agarre mixto o un agarre en gancho. Relaja los hombros, lo que en efecto alarga tus brazos.\", \"Respira y luego baja tus caderas, mirando hacia adelante con la cabeza y el pecho hacia arriba. Empuja contra el suelo, separando los pies, con tu peso en la mitad posterior de tus pies. Extiende las caderas y las rodillas.\", \"A medida que la barra pasa por las rodillas, inclina la espalda e impulsa las caderas hacia la barra, juntando los omoplatos.\", \"Devuelve el peso al suelo flexionando las caderas y controlando el peso en el descenso.\"]','levantamiento de pesas','[\"Reverse_Band_Sumo_Deadlift/0.jpg\", \"Reverse_Band_Sumo_Deadlift/1.jpg\"]','Peso muerto sumo inverso con banda',584) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inverso con barra','traccion','principiante','aislamiento','barra','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie con el torso erguido mientras sostienes una barra a la anchura de los hombros con los codos cerca del torso. Las palmas de las manos deben estar mirando hacia abajo (agarre pronado). Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas el musculo.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Barbell_Curl/0.jpg\", \"Reverse_Barbell_Curl/1.jpg\"]','Curl inverso con barra',585) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inverso con barra en banco predicador','traccion','intermedio','aislamiento','barra_ez','[\"biceps\"]','[\"antebrazos\"]','[\"Agarra una barra EZ con las palmas hacia abajo (pronadas) y a la anchura de los hombros.\", \"Ahora coloca la parte superior de ambos brazos sobre el banco preacher y manten los brazos extendidos. Esta sera tu posicion inicial.\", \"Mientras exhalas, utiliza los biceps para curvar el peso hacia arriba hasta que tus biceps esten completamente contraidos y la barra este a la altura de los hombros. Aprieta los biceps con fuerza durante un segundo en la posicion contraida.\", \"Mientras inspiras, baja lentamente la barra hasta que tus brazos superiores esten extendidos y los biceps esten completamente estirados.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Barbell_Preacher_Curls/0.jpg\", \"Reverse_Barbell_Preacher_Curls/1.jpg\"]','Curls inversos con barra en banco',586) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inverso en polea','traccion','principiante','aislamiento','polea','[\"biceps\"]','[\"antebrazos\"]','[\"Ponte de pie con el torso erguido mientras sostienes un accesorio de barra que esta conectado a una polea baja con un agarre pronado (palmas hacia abajo) y a la anchura de los hombros. Asegurate tambien de mantener los codos cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas el musculo.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Cable_Curl/0.jpg\", \"Reverse_Cable_Curl/1.jpg\"]','Curl inverso con cable',587) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales inversos','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en el suelo con tus piernas fully extendido y brazos al lado of tu torso con the palms en the floor. Tus brazos deben estar stationary during the entire exercise.\", \"Move tus piernas arriba so que your muslos estan perpendicular a the suelo y pies estan together y paralelo al suelo. Esta es la posicion inicial.\", \"Mientras inhalas, mueve tus piernas hacia el torso mientras giras la pelvis hacia atras y levantas tus caderas del suelo. Al final de este movimiento, tus rodillas tocaran tu pecho.\", \"Manten la contraccion durante un segundo y mueve tus piernas hacia atras a la posicion inicial mientras exhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Crunch/0.jpg\", \"Reverse_Crunch/1.jpg\"]','Abdominales inversos',588) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Reverse Flyes','traccion','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Para empezar, tumbate boca abajo en un banco inclinado con el pecho y el abdomen presionando contra la inclinacion. Sujeta las mancuernas en cada mano con las palmas enfrentadas (agarre neutro).\", \"Extiende los brazos frente a ti de modo que queden perpendiculares al angulo del banco. Las piernas deben permanecer fijas mientras aplicas presion con la punta de los pies. Esta es la posicion inicial.\", \"Manteniendo una ligera flexion en los codos, mueve las pesas hacia fuera y alejandote de cada otro (a los lados) en un movimiento arqueado mientras exhalas. Consejo: Intenta juntar los omoplatos para obtener los mejores resultados de este ejercicio.\", \"Los brazos deben estar elevados hasta que esten paralelos al suelo.\", \"Siente la contraccion y baja lentamente las pesas por la espalda hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Flyes/0.jpg\", \"Reverse_Flyes/1.jpg\"]','Aperturas inversas',589) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Reverse Flyes con rotacion externa','traccion','intermedio','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Para empezar, tumbate en un banco inclinado a 30 grados con el pecho y el abdomen presionando contra la inclinacion.\", \"Sujeta las mancuernas en cada mano con las palmas mirando hacia el suelo. Tus brazos deben estar frente a ti, de modo que esten perpendiculares al angulo del banco. Consejo: Tus codos deben tener una ligera flexion. Las piernas deben estar fijas mientras aplicas presion con la parte anterior de los dedos de los pies (tus talones no deben tocar el suelo). Esta es la posicion inicial.\", \"Manteniendo la ligera flexion de los codos, mueve las pesas hacia fuera y alejandote de cada otro en un movimiento de arco mientras exhalas.\", \"A medida que levantas el peso, tu muñeca debe girar externamente 90 grados para que pases de un agarre con las palmas hacia abajo (pronado) a un agarre con las palmas enfrentadas (neutro). Consejo: Intenta juntar los omoplatos para obtener los mejores resultados de este ejercicio.\", \"Los brazos deben elevarse hasta que esten al nivel de la cabeza.\", \"Siente la contraccion y baja lentamente las pesas hacia la espalda hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Flyes_With_External_Rotation/0.jpg\", \"Reverse_Flyes_With_External_Rotation/1.jpg\"]','Aperturas inversas con rotacion externa',590) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo inclinado con agarre inverso','traccion','intermedio','compuesto','barra','[\"espalda_media\"]','[\"biceps\", \"dorsales\", \"hombros\"]','[\"Ponte de pie mientras sostienes una barra con un agarre supinado (las palmas hacia arriba).\", \"Dobla ligeramente las rodillas y lleva el torso hacia adelante, doblandote por la cintura, mientras mantienes la espalda recta hasta que este casi paralela al suelo. Consejo: Asegurate de mantener la cabeza erguida. La barra debe colgar directamente frente a ti, con los brazos perpendiculares al suelo y el torso recto. Esta es tu posicion inicial.\", \"Mientras mantienes el torso inmovil, levanta la barra mientras exhalas, manteniendo los codos pegados al cuerpo y sin ejercer ninguna fuerza con los antebrazos, salvo la necesaria para sostener el peso. En la posicion superior contraida, aprieta los musculos de la espalda y manten durante un segundo.\", \"Baja lentamente el peso de nuevo a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Grip_Bent-Over_Rows/0.jpg\", \"Reverse_Grip_Bent-Over_Rows/1.jpg\"]','Remo inclinado con agarre inverso',591) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con agarre inverso','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Comienza colocando un accesorio de barra (recto o en-z) en una maquina de polea alta.\", \"De cara al accesorio de barra, agarralo con las palmas hacia arriba (agarre supinado) a la altura de los hombros. Baja la barra utilizando los dorsales hasta que tus brazos esten completamente extendidos a los lados. Consejo: Los codos deben estar pegados a los costados y los pies separados a la altura de los hombros. Esta es la posicion inicial.\", \"Eleva lentamente el accesorio de barra hacia arriba mientras inhalas, de modo que quede alineado con tu pecho. Solo deben moverse los antebrazos, los codos y la parte superior de los brazos deben permanecer fijos a los lados en todo momento.\", \"A continuacion, comienza a bajar la barra de polea hacia atras hasta la posicion inicial mientras exhalas y contraes los triceps con fuerza.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Grip_Triceps_Pushdown/0.jpg\", \"Reverse_Grip_Triceps_Pushdown/1.jpg\"]','Extension de triceps con agarre inverso',592) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hiperextension inversa','traccion','intermedio','Ninguno','maquina','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\"]','[\"Coloca tus pies entre las almohadillas despues de cargar un peso adecuado. Tumbate en la almohadilla superior, dejando que tus caderas cuelguen por la parte trasera, mientras agarras las asas para mantener tu posicion.\", \"Para comenzar el movimiento, flexiona las caderas, tirando de las piernas hacia delante.\", \"Invierte el movimiento extendiendo las caderas, llevando la pierna hacia atras. Es muy importante no extender demasiado la cadera en este movimiento, deteniendote antes de completar el rango de movimiento.\", \"Vuelve a flexionar la cadera, tirando del carro hacia delante tan lejos como puedas.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Reverse_Hyperextension/0.jpg\", \"Reverse_Hyperextension/1.jpg\"]','Hiperextension inversa',593) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Maquina de aperturas inversas','traccion','principiante','aislamiento','maquina','[\"hombros\"]','[]','[\"Ajusta las asas para que esten completamente hacia atras. Selecciona el peso adecuado y ajusta la altura del asiento para que las asas esten al nivel de los hombros. Agarra las asas con las manos mirando hacia dentro. Esta sera tu posicion inicial.\", \"En un movimiento semicircular, tira de tus manos hacia fuera y hacia atras, contrayendo los deltoides posteriores.\", \"Manten los brazos ligeramente doblados durante todo el movimiento, realizando todo el movimiento en la articulacion del hombro.\", \"Haz una pausa en la parte posterior del movimiento y devuelve lentamente el peso a la posicion inicial.\"]','fuerza','[\"Reverse_Machine_Flyes/0.jpg\", \"Reverse_Machine_Flyes/1.jpg\"]','Aperturas inversas en maquina',594) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curls inversos con placa','traccion','principiante','aislamiento','otro','[\"biceps\"]','[\"antebrazos\"]','[\"Comienza de pie con una placa con peso sujeta con ambas manos y los brazos completamente extendidos. Utiliza un agarre pronado (palmas hacia abajo) y asegurate de que tus dedos agarren el lado rugoso de la placa mientras que tu pulgar agarra el lado liso. Nota: Para obtener los mejores resultados, agarra la placa con peso en la posicion de las 11:00 y la 1:00.\", \"Tus pies deben estar separados a la anchura de los hombros y la placa con peso debe estar cerca de la ingle. Esta es la posicion inicial.\", \"Levanta lentamente la placa hacia arriba mientras mantienes los codos y la parte superior de los brazos fijos hasta que tus biceps y antebrazos se toquen mientras exhalas. La placa debe estar alineada uniformemente con tu torso en este punto.\", \"Siente la contraccion durante un segundo y comienza a bajar el peso hacia atras hasta la posicion inicial mientras inhalas\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Reverse_Plate_Curls/0.jpg\", \"Reverse_Plate_Curls/1.jpg\"]','Curls con placa inversa',595) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de triceps inverso en banco','empuje','intermedio','compuesto','barra','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Acuestese boca arriba en un banco plano. Con un agarre cerrado y supinado (aproximadamente a la anchura de los hombros), levante la barra del soporte y mantengala recta sobre usted con los brazos extendidos frente a usted y perpendiculares al suelo. Esta sera su posicion inicial.\", \"Mientras inhala, baje lentamente hasta que sienta la barra en la parte media del pecho. Consejo: Asegurate de que, a diferencia de una press de banca normal, mantienes los codos cerca del torso en todo momento para maximizar la participacion de los triceps.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos triceps. Bloquea los brazos en la posicion contraida, manten durante un segundo y luego empieza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra en el soporte.\"]','fuerza','[\"Reverse_Triceps_Bench_Press/0.jpg\", \"Reverse_Triceps_Bench_Press/1.jpg\"]','Press de banca inverso para triceps',596) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rombos-SMR','estatico','intermedio','Ninguno','rodillo_espuma','[\"espalda_media\"]','[\"trapecios\"]','[\"Acuestate boca arriba con la espalda en el suelo. Coloca un rodillo de espuma debajo de la parte superior de la espalda y cruza los brazos frente a ti, extendiendo los hombros. Esta sera tu posicion inicial.\", \"Levanta las caderas del suelo, colocando tu peso sobre el rodillo de espuma. Desplaza tu peso hacia un lado cada vez, rodando sobre la parte media y superior de la espalda. Haz una pausa en los puntos de tension durante 10-30 segundos.\"]','estiramiento','[\"Rhomboids-SMR/0.jpg\", \"Rhomboids-SMR/1.jpg\"]','Rombos-SMR',597) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rickshaw Carry','Ninguno','intermedio','compuesto','otro','[\"antebrazos\"]','[\"abdominales\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[\"Coloca el bastidor en el punto inicial y cargalo con el peso adecuado. De pie en el centro del bastidor, comienza agarrando las asas e impulsandote con los talones para levantar el bastidor. Asegurate de que el pecho y la cabeza esten arriba y la espalda recta.\", \"Comienza inmediatamente a caminar a paso ligero con pasos rapidos y controlados. Manten el pecho arriba y la cabeza hacia delante, y asegurate de seguir respirando. Lleva el bastidor al suelo despues de haber llegado al punto final.\"]','hombre_fuerte','[\"Rickshaw_Carry/0.jpg\", \"Rickshaw_Carry/1.jpg\"]','Transporte de rickshaw',598) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rickshaw Peso Muerto','traccion','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\"]','[\"Carga el marco con el peso deseado. Colocate en el centro entre las asas. Tus pies deben estar separados aproximadamente a la anchura de las caderas. Dobla las caderas para agarrar las asas, permitiendo que tus omoplatos se protruyan.\", \"Con tus pies y tu agarre fijos, respira profundamente y luego baja las caderas y flexiona las rodillas. Mira hacia adelante con la cabeza, manten el pecho arriba y la espalda arqueada, y comienza a empujar con los talones para mover el peso hacia arriba. A medida que el peso se eleva, junta los omoplatos mientras empujas las caderas hacia adelante.\", \"Baja el peso doblando las caderas y guiandolo hacia el suelo.\"]','hombre_fuerte','[\"Rickshaw_Deadlift/0.jpg\", \"Rickshaw_Deadlift/1.jpg\"]','Rickshaw_Deadlift',599) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Fondos en anillas','empuje','intermedio','compuesto','otro','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Agarra un anillo con cada mano y luego da un pequeño salto para ayudarte a colocarte en la posicion inicial con los brazos extendidos.\", \"Comienza flexionando los codos, bajando el cuerpo hasta que los brazos formen un angulo de 90 grados. Evita balancearte y manten una buena postura durante todo el descenso.\", \"Invierte el movimiento extendiendo el codo, empujandote hacia arriba hasta la posicion inicial.\", \"Repite durante el numero deseado de repeticiones.\"]','fuerza','[\"Ring_Dips/0.jpg\", \"Ring_Dips/1.jpg\"]','Fondos en anillas',600) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto cohete','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Comienza en una postura relajada con los pies separados a la anchura de los hombros y manten los brazos pegados al cuerpo.\", \"Para iniciar el movimiento, haz una sentadilla hasta la mitad y explota hacia arriba lo mas alto posible.\", \"Extiende completamente todo el cuerpo, llegando por encima de la cabeza tan lejos como sea posible. Al aterrizar, absorbe el impacto con las piernas.\"]','pliometria','[\"Rocket_Jump/0.jpg\", \"Rocket_Jump/1.jpg\"]','Salto cohete',601) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominadas/Pulldowns','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Agarra la barra de dominadas con las palmas mirando hacia delante y con un agarre amplio.\", \"Con ambos brazos extendidos frente a ti sosteniendo la barra con el ancho de agarre elegido, lleva el torso hacia atras unos 30 grados mas o menos mientras creas una curvatura en la parte baja de la espalda y sacas el pecho. Esta es tu posicion inicial.\", \"Tira de tu torso hacia arriba hasta que la barra toque la parte superior de tu pecho, llevando los hombros y la parte superior de los brazos hacia abajo y hacia atras. Exhala mientras realizas esta parte del movimiento. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa. La parte superior del torso debe permanecer inmovil mientras se mueve en el espacio y solo deben moverse los brazos. Los antebrazos no deben hacer ningun otro trabajo que no sea mantener la barra.\", \"Despues de un segundo en la posicion contraida, empieza a inhalar y baja lentamente el torso hasta la posicion inicial, cuando tus brazos esten completamente extendidos y los dorsales esten completamente estirados.\", \"Ahora repite los mismos movimientos descritos anteriormente, excepto que esta vez tu torso permanecera recto mientras subes y la barra tocara la parte posterior del cuello en lugar de la parte superior del pecho. Consejo: Utiliza la cabeza para inclinarte ligeramente hacia delante, ya que te ayudara a ejecutar correctamente esta parte del ejercicio.\", \"Una vez que te hayas bajado hasta la posicion inicial, repite el ejercicio durante el numero de repeticiones prescrito en tu programa.\"]','fuerza','[\"Rocky_Pull-Ups_Pulldowns/0.jpg\", \"Rocky_Pull-Ups_Pulldowns/1.jpg\"]','Rocky_Pull-Ups_Pulldowns',603) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto rumano','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"pantorrillas\", \"gluteos\", \"espalda_baja\"]','[\"Coloca una barra frente a ti en el suelo y agarrala con un agarre pronado (palmas hacia abajo) un poco mas ancho que el ancho de los hombros. Consejo: Dependiendo del peso utilizado, es posible que necesites muñequeras para realizar el ejercicio y tambien una plataforma elevada para permitir un mejor rango de movimiento.\", \"Dobla ligeramente las rodillas y manten las espinillas verticales, las caderas hacia atras y la espalda recta. Esta sera tu posicion inicial.\", \"Manten la espalda y los brazos completamente rectos en todo momento, usa las caderas para levantar la barra mientras exhalas. Consejo: El movimiento no debe ser rapido, sino constante y controlado.\", \"Una vez que estes completamente erguido, baja la barra empujando las caderas hacia atras, doblando ligeramente las rodillas, a diferencia de lo que se hace en las sentadillas. Consejo: Respira profundamente al inicio del movimiento y manten el pecho erguido. Aguanta la respiracion mientras bajas y exhala al completar el movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Romanian_Deadlift/0.jpg\", \"Romanian_Deadlift/1.jpg\"]','Peso muerto rumano',604) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto rumano desde deficit','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"antebrazos\", \"gluteos\", \"espalda_baja\", \"trapecios\"]','[\"Comienza de pie mientras sostienes una barra a la longitud del brazo frente a ti. Puedes colocarte en una plataforma elevada para aumentar el rango de movimiento.\", \"Comienza flexionando ligeramente las rodillas y luego flexiona la cadera, moviendo el trasero hacia atras lo mas lejos posible, bajando el torso tanto como te lo permita tu flexibilidad. La espalda debe permanecer en extension absoluta en todo momento, y la barra debe permanecer en contacto con las piernas. Si se realiza correctamente, se debe sentir una fuerte tension en los isquiotibiales.\", \"Invierta el movimiento para volver a la posicion inicial.\"]','halterofilia_olimpica','[\"Romanian_Deadlift_from_Deficit/0.jpg\", \"Romanian_Deadlift_from_Deficit/1.jpg\"]','Peso muerto rumano desde deficit',605) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Subida de cuerda','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"biceps\", \"antebrazos\", \"espalda_media\", \"hombros\"]','[\"Agarra la cuerda con ambas manos por encima de tu cabeza. Tira de la cuerda hacia abajo mientras das un pequeño salto.\", \"Envuelve la cuerda alrededor de una pierna, utilizando tus pies para sujetarla. Alcanza la mayor altura posible con tus brazos, agarrando la cuerda con fuerza.\", \"Suelta la cuerda de tus pies mientras te impulsas hacia arriba con tus brazos, llevando tus rodillas hacia tu pecho.\", \"Vuelve a sujetar los pies en la cuerda y luego ponte de pie para dar otro salto alto y mantenerte en la cuerda. Continua hasta llegar a la parte superior de la cuerda.\", \"Para bajar, afloja el agarre de los pies en la cuerda mientras te deslizas hacia abajo con un movimiento de mano sobre mano.\"]','fuerza','[\"Rope_Climb/0.jpg\", \"Rope_Climb/1.jpg\"]','Subida de cuerda',606) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales con cuerda','traccion','principiante','aislamiento','polea','[\"abdominales\"]','[]','[\"Arrodillate a 1-2 pies frente a un sistema de cable con una cuerda atada.\", \"Despues de seleccionar un peso adecuado, agarra la cuerda con ambas manos por encima de la cabeza. El torso debe estar erguido en la posicion inicial.\", \"Para comenzar, flexiona la columna vertebral, intentando llevar la caja toracica hacia tus piernas mientras tiras de la polea hacia abajo.\", \"Haz una pausa en la parte inferior del movimiento y luego vuelve lentamente a la posicion inicial.\", \"Estos pueden hacerse con giros o de lado para trabajar los oblicuos.\"]','fuerza','[\"Rope_Crunch/0.jpg\", \"Rope_Crunch/1.jpg\"]','Abdominales con cuerda',607) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto con cuerda','Ninguno','intermedio','Ninguno','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Sujete un extremo de la cuerda con cada mano. Coloque la cuerda detras de usted en el suelo. Levante los brazos y gire la cuerda por encima de la cabeza, llevandola hacia abajo frente a usted. Cuando llegue al suelo, salte por encima de ella. Encuentra un buen ritmo de giro que puedas mantener. Se pueden utilizar diferentes velocidades y tecnicas para introducir variaciones.\", \"Saltar a la comba es emocionante, pone a prueba tu coordinacion y requiere mucha energia. Una persona de 68 kg quemara aproximadamente 350 calorias saltando a la comba durante 30 minutos, en comparacion con las mas de 450 calorias que se queman corriendo.\"]','cardio','[\"Rope_Jumping/0.jpg\", \"Rope_Jumping/1.jpg\"]','Saltar a la comba',608) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de hombros alrededor del mundo','estatico','principiante','Ninguno','otro','[\"hombros\"]','[\"biceps\", \"pecho\"]','[\"Ponte de pie recto con tus piernas juntas, sosteniendo una barra o un palo de escoba.\", \"Sosten el palo detras de tus caderas con un agarre mas ancho que el ancho de tus hombros. Tus palmas deben estar hacia abajo y tus pulgares hacia afuera.\", \"Levanta lentamente tus brazos detras de tu cabeza. No fuerces si te cuesta levantarlos mas.\"]','estiramiento','[\"Round_The_World_Shoulder_Stretch/0.jpg\", \"Round_The_World_Shoulder_Stretch/1.jpg\"]','Estiramiento de hombros alrededor del mundo',610) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo, Estacionario','Ninguno','intermedio','Ninguno','maquina','[\"cuadriceps\"]','[\"biceps\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"espalda_media\"]','[\"Para empezar, sientate en la maquina de remo. Asegurate de que tus talones descansan comodamente contra la base de los pedales y que las correas estan bien sujetas. Selecciona el programa que desees utilizar, si procede. Sientate con la espalda recta e inclinate hacia delante por las caderas.\", \"Hay tres fases de movimiento cuando se utiliza una maquina de remo. La primera fase es cuando te inclinas hacia delante en la maquina. Tus rodillas estan dobladas y contra tu pecho. La parte superior del cuerpo se inclina ligeramente hacia adelante, manteniendo una buena postura. A continuacion, empuje contra los pedales y extienda las piernas mientras lleva las manos a la zona superior del abdomen, apretando los hombros hacia atras al hacerlo. Para evitar forzar la espalda, utilice principalmente los musculos de las piernas y las caderas.\", \"La fase de recuperacion consiste simplemente en estirar los brazos, doblar las rodillas y llevar el cuerpo hacia adelante de nuevo mientras se pasa a la primera fase.\"]','cardio','[\"Remo_Estacionario/0.jpg\", \"Remo_Estacionario/1.jpg\"]','Remo_Estacionario',611) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento del corredor','estatico','principiante','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"La forma mas facil de hacer este estiramiento es empezar de pie, poner una pierna detras y bajar lentamente el torso hacia el suelo.\", \"Manten el talon delantero en el suelo (si se levanta, echa la otra pierna mas atras).\", \"Coloca las manos a ambos lados de la pierna delantera. Para sacar mas partido a este estiramiento, empuja el trasero hacia arriba, hacia el techo, y luego bajalo gradualmente hacia el suelo. Estiraras el flexor de la cadera de la pierna trasera y los isquiotibiales y gluteos de la delantera.\"]','estiramiento','[\"Runners_Stretch/0.jpg\", \"Runners_Stretch/1.jpg\"]','Estiramiento para corredores',612) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Correr, cinta de correr','Ninguno','principiante','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, subete a la cinta y selecciona la opcion deseada en el menu. La mayoria de las cintas tienen un ajuste manual, o puedes seleccionar un programa para correr. Normalmente, puedes introducir tu edad y peso para calcular la cantidad de calorias quemadas durante el ejercicio. La elevacion se puede ajustar para cambiar la intensidad del entrenamiento.\", \"Las cintas de correr ofrecen comodidad, beneficios cardiovasculares y suelen tener menos impacto que correr al aire libre. Una persona de 68 kg quemara mas de 450 calorias corriendo a 13 km/h durante 30 minutos. Mantenga una postura adecuada mientras corre y solo sujete los mangos cuando sea necesario, como al bajarse o al comprobar su frecuencia cardiaca.\"]','cardio','[\"Running_Treadmill/0.jpg\", \"Running_Treadmill/1.jpg\"]','Cinta de correr',613) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Giro ruso','traccion','intermedio','compuesto','solo_cuerpo','[\"abdominales\"]','[\"espalda_baja\"]','[\"Acuestate en el suelo colocando tus pies debajo de algo que no se mueva o pidiendo a un compañero que los sujete. Tus piernas deben estar dobladas por las rodillas.\", \"Eleva la parte superior del cuerpo de modo que se cree una V imaginaria con tus muslos. Tus brazos deben estar completamente extendidos frente a ti, perpendiculares a tu torso y con las manos entrelazadas. Esta es la posicion inicial.\", \"Gira el torso hacia el lado derecho hasta que tus brazos esten paralelos al suelo mientras exhalas.\", \"Manten la contraccion durante un segundo y vuelve a la posicion inicial mientras exhalas. Ahora muevete al lado opuesto realizando las mismas tecnicas que aplicaste al lado derecho.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Russian_Twist/0.jpg\", \"Russian_Twist/1.jpg\"]','Giro ruso',614) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Carga con saco de arena','traccion','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abdominales\", \"biceps\", \"pantorrillas\", \"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"espalda_media\", \"hombros\", \"trapecios\"]','[\"Para cargar sacos de arena u otros objetos, comience con los implementos colocados a una distancia de la plataforma de carga, normalmente 50 pies.\", \"Comience levantando el saco de arena. Los sacos de arena son extremadamente incomodos, y la forma de levantarlos puede variar dependiendo del saco de arena concreto que se utilice. Alcance lo mas lejos posible alrededor de el, extendiendo las caderas y las rodillas para levantarlo alto. Por lo general, no se permite cargarlo sobre los hombros.\", \"Muevete lo mas rapido posible hacia la plataforma y cargalo, extendiendo las caderas, las rodillas y los tobillos para levantarlo lo mas alto posible. Colocalo sobre la plataforma, asegurandote de que no se caiga.\", \"Regresa a la posicion inicial para recuperar el siguiente saco de arena y repite hasta completar el ejercicio.\"]','hombre_fuerte','[\"Sandbag_Load/0.jpg\", \"Sandbag_Load/1.jpg\"]','Carga de sacos de arena',615) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominada escapular','traccion','principiante','aislamiento','Ninguno','[\"trapecios\"]','[\"dorsales\", \"espalda_media\"]','[\"Agarra una barra de dominadas con las palmas hacia abajo.\", \"Desde una posicion colgada, levantate unos centimetros sin usar los brazos. Hazlo presionando la cintura escapular con un movimiento inverso al encogimiento de hombros.\", \"Haz una pausa al completar el movimiento y luego vuelve lentamente a la posicion inicial antes de realizar mas repeticiones.\"]','fuerza','[\"Scapular_Pull-Up/0.jpg\", \"Scapular_Pull-Up/1.jpg\"]','Suspension escapular',616) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Patada de tijera','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Para empezar, tumbate boca abajo con la espalda apoyada contra el suelo o sobre una colchoneta de ejercicios (opcional). Tus brazos deben estar completamente extendidos a los lados con las palmas hacia abajo. Nota: Los brazos deben permanecer inmoviles durante todo el ejercicio.\", \"Con una ligera flexion en las rodillas, levanta las piernas hacia arriba de modo que los talones queden a unos 15 cm del suelo. Esta es la posicion inicial.\", \"Ahora levanta la pierna izquierda hasta formar un angulo de aproximadamente 45 grados, mientras bajas la pierna derecha hasta que el talon quede a unas 2-3 pulgadas del suelo.\", \"Cambia de movimiento levantando la pierna derecha y bajando la izquierda. Recuerda respirar mientras realizas este ejercicio.\", \"Repite durante el numero recomendado de repeticiones.\"]','estiramiento','[\"Scissor_Kick/0.jpg\", \"Scissor_Kick/1.jpg\"]','Patada de tijera',617) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto de tijera','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Adopta una posicion de zancada con un pie delante con la rodilla flexionada y la rodilla trasera casi tocando el suelo.\", \"Asegurate de que la rodilla delantera este sobre la linea media del pie. Extendiendo ambas piernas, salta lo mas alto posible, balanceando los brazos para ganar impulso.\", \"Mientras saltas lo mas alto que puedas, cambia la posicion de tus piernas, moviendo la pierna delantera hacia atras y la pierna trasera hacia delante.\", \"Al aterrizar, absorbe el impacto con las piernas adoptando la posicion de zancada, y repite.\"]','pliometria','[\"Scissors_Jump/0.jpg\", \"Scissors_Jump/1.jpg\"]','Salto de tijera',618) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de isquiotibiales con banda sentado','traccion','principiante','aislamiento','otro','[\"isquiotibiales\"]','[]','[\"Fija una banda cerca del suelo y coloca un banco a un par de pies de distancia de ella.\", \"Sientate en el banco y fija la banda detras de tus tobillos, comenzando con las piernas estiradas. Esta sera tu posicion inicial.\", \"Flexiona las rodillas, llevando tus pies hacia el banco. Es posible que tengas que inclinar ligeramente la espalda para evitar que tus pies golpeen el suelo.\", \"Haz una pausa al completar el movimiento y luego vuelve lentamente a la posicion inicial.\"]','fuerza','[\"Seated_Band_Hamstring_Curl/0.jpg\", \"Seated_Band_Hamstring_Curl/1.jpg\"]','Flexion de isquiotibiales con banda sentado',619) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Twist con barra sentado','traccion','principiante','aislamiento','barra','[\"abdominales\"]','[]','[\"Comienza sentado en el extremo de un banco plano con una barra colocada sobre tus muslos. Tus pies deben estar separados a la altura de los hombros.\", \"Sujeta la barra con las palmas hacia abajo y asegurate de que tus manos esten separadas a una distancia mayor que la altura de los hombros. Comienza a levantar la barra por encima de tu cabeza hasta que tus brazos esten completamente extendidos.\", \"Ahora baja la barra detras de tu cabeza hasta que descanse en la base de tu cuello. Esta es la posicion inicial.\", \"Mientras mantienes tus pies y tu cabeza fijos, mueve tu cintura de lado a lado para que tus musculos oblicuos sientan la contraccion. Solo muevete de lado a lado hasta donde te lo permita tu cintura. Estirar o mover demasiado puede provocar una lesion. Consejo: Realiza el movimiento de forma lenta y controlada.\", \"Recuerda exhalar mientras giras el cuerpo hacia un lado e inhalar al mover la espalda a la posicion inicial.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Seated_Barbell_Twist/0.jpg\", \"Seated_Barbell_Twist/1.jpg\"]','Giro con barra sentado',621) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuerna sentado e inclinado hacia delante con un brazo','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Sientate al final de un banco plano con una mancuerna en un brazo utilizando un agarre neutro (las palmas de las manos mirando hacia ti).\", \"Dobla ligeramente las rodillas y lleva el torso hacia delante, doblando la cintura, mientras mantienes la espalda recta hasta que este casi paralela al suelo. Asegurate de mantener la cabeza erguida.\", \"El brazo con la mancuerna debe estar cerca del torso y alineado con el (levantado hasta que quede paralelo al suelo, mientras que los antebrazos apuntan hacia el suelo y las manos sostienen las pesas). Consejo: Debe haber un angulo de 90 grados entre los antebrazos y el brazo. Esta es tu posicion inicial.\", \"Manteniendo el brazo inmovil, utiliza los triceps para levantar el peso mientras exhalas hasta que el antebrazo quede paralelo al suelo y todo el brazo este extendido. Al igual que en muchos otros ejercicios de brazos, solo se mueve el antebrazo.\", \"Despues de una segunda contraccion en la parte superior, baja lentamente la mancuerna hacia la posicion inicial mientras inhalas.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg\", \"Seated_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuerna con un brazo sentado e inclinado',622) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuernas sentado e inclinado hacia delante','empuje','intermedio','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Sientate al final de un banco plano con una mancuerna en ambos brazos utilizando un agarre neutro (las palmas de las manos mirando hacia ti).\", \"Dobla ligeramente las rodillas y lleva el torso hacia delante, doblando la cintura, mientras mantienes la espalda recta hasta que este casi paralela al suelo. Asegurate de mantener la cabeza erguida.\", \"Los brazos con las mancuernas deben estar cerca del torso y alineados con el (levantados hasta que esten paralelos al suelo, mientras que los antebrazos apuntan hacia el suelo y las manos sostienen las pesas). Consejo: Debe haber un angulo de 90 grados entre los antebrazos y la parte superior del brazo. Esta es tu posicion inicial.\", \"Manteniendo los brazos superiores fijos, utiliza los triceps para levantar el peso mientras exhalas hasta que los antebrazos esten paralelos al suelo y todo el brazo este extendido. Al igual que en muchos otros ejercicios de brazos, solo se mueve el antebrazo.\", \"Despues de una segunda contraccion en la parte superior, baja lentamente las mancuernas hacia la posicion inicial mientras inhalas.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg\", \"Seated_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuernas a dos brazos sentado e inclinado',624) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Biceps sentado','estatico','experto','aislamiento','solo_cuerpo','[\"biceps\"]','[\"pecho\", \"hombros\"]','[\"Sientate en el suelo con las rodillas dobladas y tu compañero de pie detras de ti. Extiende los brazos rectos detras de ti con las palmas enfrentadas. Tu compañero te sujetara las muñecas. Esta sera la posicion inicial.\", \"Intenta flexionar los codos, mientras tu compañero impide cualquier movimiento real.\", \"Despues de 10-20 segundos, relaja los brazos mientras tu compañero tira suavemente de tus muñecas hacia arriba para estirar los biceps. Asegurate de avisar a tu compañero cuando el estiramiento sea adecuado para evitar lesiones o estiramientos excesivos.\"]','estiramiento','[\"Seated_Biceps/0.jpg\", \"Seated_Biceps/1.jpg\"]','Biceps sentado',625) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo sentado en polea con press de hombros','empuje','principiante','compuesto','polea','[\"hombros\"]','[\"triceps\"]','[\"Ajusta el peso a una cantidad adecuada y sientate, agarrando las asas. Tus brazos superiores deben estar aproximadamente a 90 grados del cuerpo, con la cabeza y el pecho levantados. Los codos tambien deben estar doblados a aproximadamente 90 grados. Esta sera tu posicion inicial.\", \"Comienza extendiendo los codos, presionando las manijas juntas por encima de tu cabeza.\", \"Despues de hacer una pausa en la parte superior, vuelve a colocar las manijas en la posicion inicial. Asegurate de mantener la tension en las poleas.\", \"Tambien puedes ejecutar este movimiento con la espalda fuera de la almohadilla y alternar las manos.\"]','fuerza','[\"Seated_Cable_Shoulder_Press/0.jpg\", \"Seated_Cable_Shoulder_Press/1.jpg\"]','Press de hombros con cable sentado',627) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de pantorrillas sentado','empuje','principiante','aislamiento','maquina','[\"pantorrillas\"]','[]','[\"Sientate en la maquina y coloca los dedos de los pies en la parte inferior de la plataforma, con los talones extendidos. Elige la posicion de los dedos de los pies que prefieras (hacia delante, hacia dentro o hacia fuera) segun se indica al principio de este capitulo.\", \"Coloca la parte inferior de los muslos debajo de la almohadilla de la palanca, que debera ajustarse segun la altura de tus muslos. Ahora coloca tus manos en la parte superior de la almohadilla de la palanca para evitar que se deslice hacia adelante.\", \"Eleva la palanca ligeramente empujando los talones hacia arriba y suelta la barra de seguridad. Esta sera tu posicion inicial.\", \"Baja lentamente los talones doblando los tobillos hasta que las pantorrillas esten completamente estiradas. Inhala mientras realizas este movimiento.\", \"Levanta los talones extendiendo los tobillos lo mas alto posible mientras contraes las pantorrillas y exhalas. Manten la contraccion maxima durante un segundo.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Calf_Raise/0.jpg\", \"Seated_Calf_Raise/1.jpg\"]','Elevacion de pantorrillas sentado',628) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pantorrillas sentado','estatico','principiante','Ninguno','Ninguno','[\"pantorrillas\"]','[\"isquiotibiales\", \"espalda_baja\"]','[\"Sientate con la espalda recta en una colchoneta de ejercicios.\", \"Dobla una rodilla y apoya ese pie en el suelo para estabilizar el torso.\", \"Estira la otra pierna y flexiona el tobillo.\", \"Con una banda elastica, una toalla o la mano, si puedes alcanzarla, tira de los dedos de los pies hacia ti. Manten la posicion durante 10 a 20 segundos y luego cambia de lado.\"]','estiramiento','[\"Estiramiento de pantorrillas sentado/0.jpg\", \"Estiramiento de pantorrillas sentado/1.jpg\"]','Estiramiento de pantorrillas sentado',629) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de concentracion con barra con agarre cerrado sentado','traccion','intermedio','aislamiento','barra','[\"biceps\"]','[]','[\"Sientate en un banco plano con una barra o barra E-Z frente a ti, entre tus piernas. Tus piernas deben estar separadas, con las rodillas dobladas y los pies en el suelo.\", \"Usa tus brazos para levantar la barra y coloca la parte posterior de tus brazos superiores sobre la parte interna de tus muslos (a unos nueve centimetros de la parte delantera de la rodilla). Para realizar este ejercicio es necesario un agarre supinado mas estrecho que el ancho de los hombros. Consejo: Los brazos deben estar extendidos a la longitud de los brazos y la barra debe estar por encima del suelo. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos hacia delante mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas los biceps.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas. Consejo: Evita los movimientos oscilantes en todo momento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Close-Grip_Concentration_Barbell_Curl/0.jpg\", \"Seated_Close-Grip_Concentration_Barbell_Curl/1.jpg\"]','Curl de barra concentrado con agarre cerrado sentado',630) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl sentado con mancuernas','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Sientate en un banco plano con una mancuerna en cada mano, sosteniendolas a la longitud de los brazos. Los codos deben estar cerca del torso.\", \"Gira las palmas de las manos para que queden mirando hacia tu torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos fijos, flexiona los pesos y comienza a girar las muñecas una vez que las mancuernas pasen tus muslos, de modo que las palmas de tus manos queden mirando hacia adelante al final del movimiento. Asegurate de contraer los biceps mientras exhalas y de que solo se muevan los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas los biceps.\", \"Comienza lentamente a llevar las mancuernas de vuelta a la posicion inicial mientras inhalas y giras las muñecas de vuelta a una posicion neutra.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Dumbbell_Curl/0.jpg\", \"Seated_Dumbbell_Curl/1.jpg\"]','Curl con mancuernas sentado',631) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de biceps interno sentado con mancuernas','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Sientate en el extremo de un banco plano con una mancuerna en cada mano, sosteniendolas a la longitud de los brazos. Los codos deben estar cerca del torso.\", \"Gira las palmas de las manos para que queden mirando hacia dentro en una posicion neutra. Esta sera tu posicion inicial.\", \"Mientras sostienes la parte superior de los brazos inmoviles, flexiona las mancuernas hacia fuera y hacia arriba, girando las palmas hacia fuera a medida que levantas y manteniendo los antebrazos alineados con los deltoides externos. Consejos:\", \"Solo deben moverse los antebrazos. Continua el movimiento hasta que los biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Sosten la posicion contraida durante un segundo mientras aprietas los biceps.\", \"Comienza lentamente a llevar las mancuernas hacia atras a la posicion inicial mientras inhalas. Recuerda rotar los brazos mientras bajas las mancuernas para que puedas cambiar la espalda a un agarre neutro.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Dumbbell_Inner_Biceps_Curl/0.jpg\", \"Seated_Dumbbell_Inner_Biceps_Curl/1.jpg\"]','Curl de biceps interno con mancuernas sentado',632) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de muñeca con mancuernas sentado con las palmas hacia abajo','traccion','principiante','aislamiento','mancuerna','[\"antebrazos\"]','[]','[\"Comienza colocando dos mancuernas en el suelo frente a un banco plano.\", \"Sientate en el borde del banco plano con tus piernas separadas aproximadamente a la anchura de los hombros. Asegurate de mantener los pies en el suelo.\", \"Usa tus brazos para agarrar ambas mancuernas y llevalas hacia arriba de modo que tus antebrazos descansen contra tus muslos con las palmas de las manos mirando hacia abajo. Tus muñecas deben quedar colgando sobre el borde de tus muslos.\", \"Comienza flexionando las muñecas hacia arriba y exhalando.\", \"Baja lentamente tus muñecas hacia atras hasta la posicion inicial mientras inhalas. Asegurate de inhalar durante esta parte del ejercicio. Consejo: Tus antebrazos deben permanecer inmoviles, ya que la muñeca es el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cuando termines, simplemente baja las mancuernas al suelo.\"]','fuerza','[\"Seated_Dumbbell_Palms-Down_Wrist_Curl/0.jpg\", \"Seated_Dumbbell_Palms-Down_Wrist_Curl/1.jpg\"]','Curl de muñeca con mancuernas sentado con las palmas hacia abajo',633) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de muñeca con mancuernas sentado con las palmas hacia arriba','traccion','principiante','aislamiento','mancuerna','[\"antebrazos\"]','[]','[\"Comienza colocando dos mancuernas en el suelo frente a un banco plano.\", \"Sientate en el borde del banco plano con tus piernas separadas aproximadamente a la anchura de los hombros. Asegurate de mantener los pies en el suelo.\", \"Usa tus brazos para agarrar ambas mancuernas y llevalas hacia arriba de modo que tus antebrazos descansen contra tus muslos con las palmas de las manos hacia arriba. Tus muñecas deben quedar colgando sobre el borde de tus muslos.\", \"Comienza flexionando las muñecas hacia arriba y exhalando.\", \"Baja lentamente tus muñecas hacia atras hasta la posicion inicial mientras inhalas. Asegurate de inhalar durante esta parte del ejercicio. Consejo: Tus antebrazos deben permanecer inmoviles, ya que la muñeca es el unico movimiento necesario para realizar este ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cuando termines, simplemente baja las mancuernas al suelo.\"]','fuerza','[\"Seated_Dumbbell_Palms-Up_Wrist_Curl/0.jpg\", \"Seated_Dumbbell_Palms-Up_Wrist_Curl/1.jpg\"]','Curl de muñeca con mancuernas sentado con las palmas hacia arriba',634) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press con mancuernas sentado','empuje','principiante','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Coge un par de mancuernas y sientate en un banco de press militar o en un banco multiusos que tenga un respaldo, colocando las mancuernas erguidas sobre tus muslos.\", \"Lleva las mancuernas hacia arriba una a una utilizando tus muslos para elevarlas hasta la altura de los hombros a cada lado.\", \"Gira las muñecas de modo que las palmas de tus manos queden mirando hacia delante. Esta es tu posicion inicial.\", \"Mientras exhalas, empuja las mancuernas hacia arriba hasta que toquen en la parte superior.\", \"Despues de una pausa de un segundo, baja lentamente la espalda a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Dumbbell_Press/0.jpg\", \"Seated_Dumbbell_Press/1.jpg\"]','Press con mancuernas sentado',635) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de piernas sentado en banco plano','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Sientate en un banco con las piernas estiradas frente a ti ligeramente por debajo del paralelo y los brazos apoyados a los lados del banco. El torso debe estar inclinado hacia atras en un angulo de unos 45 grados con respecto al banco. Esta sera tu posicion inicial.\", \"Acerca las rodillas hacia ti mientras acercas el torso a ellas al mismo tiempo. Exhala mientras realizas este movimiento.\", \"Despues de una pausa de un segundo, vuelve a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Flat_Bench_Leg_Pull-In/0.jpg\", \"Seated_Flat_Bench_Leg_Pull-In/1.jpg\"]','Sentado en banco plano con piernas hacia dentro',636) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de isquiotibiales sentado en el suelo','estatico','principiante','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"Sientate en una colchoneta con la pierna derecha extendida frente a ti y la pierna izquierda doblada con el pie contra la parte interna del muslo derecho.\", \"Inclinate hacia adelante desde las caderas y alcanza el tobillo hasta que sientas un estiramiento en los isquiotibiales. Manten la posicion durante 15 segundos y luego repite con el otro lado.\"]','estiramiento','[\"Seated_Floor_Hamstring_Stretch/0.jpg\", \"Seated_Floor_Hamstring_Stretch/1.jpg\"]','Estiramiento de isquiotibiales sentado en el suelo',637) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Deltoides frontal sentado','estatico','experto','Ninguno','solo_cuerpo','[\"hombros\"]','[\"pecho\"]','[\"Sientate erguido en el suelo con las piernas flexionadas y tu compañero detras de ti. Estira los brazos rectos hacia los lados, con las palmas de las manos mirando hacia el suelo. Intenta moverlos lo mas atras posible, mientras tu asistente te sujeta las muñecas. Esta sera tu posicion inicial.\", \"Manteniendo tus codos rectos, intenta mover tus brazos hacia delante, con tu compañero sujetandote suavemente para evitar cualquier movimiento durante 10-20 segundos.\", \"Ahora, relaja tus musculos y deja que tu compañero aumente suavemente el estiramiento en los hombros y el pecho. Manten durante 10 a 20 segundos.\"]','estiramiento','[\"Seated_Front_Deltoid/0.jpg\", \"Seated_Front_Deltoid/1.jpg\"]','Deltoides anterior sentado',638) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Gluteo sentado','estatico','experto','Ninguno','solo_cuerpo','[\"gluteos\"]','[\"aductores\"]','[\"En posicion sentada con las rodillas flexionadas, cruza un tobillo sobre la rodilla opuesta. Tu compañero se colocara detras de ti. Ahora, inclinate hacia adelante mientras tu compañero te sujeta los hombros con las manos. Esta sera tu posicion inicial.\", \"Intenta empujar tu torso hacia atras durante 10-20 segundos, mientras tu compañero evita cualquier movimiento real de tu torso.\", \"Ahora relaja los musculos mientras tu compañero aumenta el estiramiento empujando suavemente tu torso hacia adelante durante 10-20 segundos.\"]','estiramiento','[\"Seated_Glute/0.jpg\", \"Seated_Glute/1.jpg\"]','Sentado_Gluteos',639) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de isquiotibiales y pantorrillas sentado','estatico','intermedio','Ninguno','otro','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"Enrolla un cinturon, una cuerda o una banda alrededor de un pie. Sientate con ambas piernas extendidas. Esta sera tu posicion inicial.\", \"Inclinandote ligeramente hacia adelante, tira del cinturon para llevar los dedos del pie hacia atras. Manten esta posicion durante 10-20 segundos y luego repite con la otra pierna.\"]','estiramiento','[\"Seated_Hamstring_and_Calf_Stretch/0.jpg\", \"Seated_Hamstring_and_Calf_Stretch/1.jpg\"]','Estiramiento de isquiotibiales y pantorrillas sentado',642) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Resistencia del cuello con arnes para la cabeza sentado','traccion','intermedio','aislamiento','otro','[\"cuello\"]','[]','[\"Coloque una correa para el cuello en el suelo al final de un banco plano. Una vez que haya seleccionado los pesos, sientese al final del banco plano con los pies separados a una distancia mayor que el ancho de los hombros. Los dedos de los pies deben apuntar hacia fuera.\", \"Mueva lentamente el torso hacia delante hasta que quede casi paralelo al suelo. Con ambas manos, coloque firmemente la correa alrededor de la cabeza. Consejo: Asegurese de que las pesas sigan en el suelo para evitar cualquier tension en el cuello. Ahora agarre la pesa con ambas manos mientras eleva el torso hacia atras hasta que quede casi perpendicular al suelo. Nota: Tu cabeza y torso deben estar ligeramente inclinados hacia adelante para realizar este ejercicio.\", \"Ahora coloca ambas manos sobre tus rodillas. Esta es la posicion inicial.\", \"Baja lentamente tu cuello hasta que tu barbilla toque la parte superior de tu pecho mientras inhalas.\", \"Mientras exhalas, lleva tu cuello a la posicion inicial.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Head_Harness_Neck_Resistance/0.jpg\", \"Seated_Head_Harness_Neck_Resistance/1.jpg\"]','Resistencia del cuello con arnes para la cabeza sentado',643) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de piernas sentado','traccion','principiante','aislamiento','maquina','[\"isquiotibiales\"]','[]','[\"Ajusta la palanca de la maquina a tu altura y sientate en la maquina con la espalda apoyada en el respaldo acolchado.\", \"Coloca la parte posterior de la pierna sobre la palanca acolchada (unos centimetros por debajo de las pantorrillas) y fija la almohadilla para las piernas contra tus muslos, justo por encima de las rodillas. A continuacion, agarra las asas laterales de la maquina mientras apuntas con los dedos de los pies hacia delante (o tambien puedes utilizar cualquiera de las otras dos posturas) y asegurate de que las piernas esten completamente rectas frente a ti. Esta sera tu posicion inicial.\", \"Mientras exhalas, tira de la palanca de la maquina lo mas lejos posible hacia la parte posterior de tus muslos flexionando las rodillas. Manten el torso inmovil en todo momento. Sosten la posicion contraida durante un segundo.\", \"Vuelve lentamente a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Leg_Curl/0.jpg\", \"Seated_Leg_Curl/1.jpg\"]','Flexion de piernas sentado',644) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de piernas sentado','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Sientate en un banco con las piernas estiradas frente a ti ligeramente por debajo del paralelo y los brazos apoyados a los lados del banco. El torso debe estar inclinado hacia atras en un angulo de unos 45 grados con respecto al banco. Esta sera tu posicion inicial.\", \"Acerca las rodillas hacia ti mientras acercas el torso a ellas al mismo tiempo. Exhala mientras realizas este movimiento.\", \"Despues de una pausa de un segundo, vuelve a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Leg_Tucks/0.jpg\", \"Seated_Leg_Tucks/1.jpg\"]','Flexiones de piernas sentado',645) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo sentado con mancuerna con una sola mano y palmas hacia abajo','traccion','intermedio','aislamiento','mancuerna','[\"antebrazos\"]','[]','[\"Sientate en un banco plano con una mancuerna en la mano derecha.\", \"Coloca los pies planos en el suelo, a una distancia ligeramente superior a la anchura de los hombros.\", \"Inclinate hacia delante y coloca el antebrazo derecho sobre la parte superior del muslo derecho con la palma hacia abajo. Consejo: Asegurate de que la parte posterior de la muñeca quede sobre tus rodillas. Esta sera tu posicion inicial.\", \"Baja la mancuerna lo mas lejos posible mientras mantienes un agarre firme sobre ella. Inhala mientras realizas este movimiento.\", \"Ahora flexiona la mancuerna lo mas alto posible mientras contraes los antebrazos y exhalas. Manten la contraccion durante un segundo antes de bajar de nuevo. Consejo: El unico movimiento debe producirse en la muñeca.\", \"Realiza el numero recomendado de repeticiones, cambia de brazo y repite el movimiento.\"]','fuerza','[\"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/0.jpg\", \"Seated_One-Arm_Dumbbell_Palms-Down_Wrist_Curl/1.jpg\"]','Flexion de muñeca con mancuerna sentado con un brazo y palmas hacia abajo',647) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de muñeca con mancuerna con una mano sentado con las palmas hacia arriba','traccion','principiante','aislamiento','mancuerna','[\"antebrazos\"]','[]','[\"Sientate en un banco plano con una mancuerna en tu mano derecha.\", \"Coloca tus pies planos en el suelo, a una distancia ligeramente superior a la anchura de los hombros.\", \"Inclinate hacia delante y coloca tu antebrazo derecho sobre la parte superior de tu muslo derecho con la palma hacia arriba. Consejo: Asegurate de que la parte delantera de la muñeca quede sobre tus rodillas. Esta sera tu posicion inicial.\", \"Baja la mancuerna lo mas lejos posible mientras mantienes un agarre firme sobre la mancuerna. Inhala mientras realizas este movimiento.\", \"Ahora flexiona la mancuerna lo mas alto posible mientras contraes los antebrazos y exhalas. Manten la contraccion durante un segundo antes de bajar de nuevo. Consejo: El unico movimiento debe producirse en la muñeca.\", \"Realiza el numero recomendado de repeticiones, cambia de brazo y repite el movimiento.\"]','fuerza','[\"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/0.jpg\", \"Seated_One-Arm_Dumbbell_Palms-Up_Wrist_Curl/1.jpg\"]','Flexion de muñeca con mancuerna con una mano sentado con las palmas hacia arriba',648) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de cabeza sentado','estatico','principiante','aislamiento','Ninguno','[\"abdominales\"]','[]','[\"Sientate con la espalda recta en una colchoneta de ejercicios.\", \"Junta las plantas de los pies con los pies a una distancia de entre 15 y 20 cm delante de las caderas.\", \"Coloca una mano en el suelo a tu lado y la otra mano detras de la cabeza.\", \"Eleva el codo hacia el techo mientras inclinas el torso hacia el otro lado. Manten la posicion durante 10 a 20 segundos y luego cambia de lado.\"]','estiramiento','[\"Seated_Overhead_Stretch/0.jpg\", \"Seated_Overhead_Stretch/1.jpg\"]','Estiramiento por encima de la cabeza sentado',649) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion de muñecas con barra sentado y palmas hacia arriba','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Sujeta una barra con ambas manos y las palmas hacia arriba; las manos separadas aproximadamente a la anchura de los hombros.\", \"Coloca los pies planos en el suelo, a una distancia ligeramente superior a la anchura de los hombros.\", \"Inclinate hacia delante y coloca los antebrazos sobre la parte superior de los muslos con las palmas hacia arriba. Consejo: Asegurate de que la parte delantera de las muñecas quede sobre tus rodillas. Esta sera tu posicion inicial.\", \"Baja la barra lo mas lejos posible mientras inhalas y mantienes un agarre firme.\", \"Ahora flexiona la barra hacia arriba lo mas alto posible mientras flexionas los antebrazos y exhalas. Manten la contraccion en la parte superior durante un segundo y Consejo: Solo debe moverse la muñeca.\"]','fuerza','[\"Seated_Palm-Up_Barbell_Wrist_Curl/0.jpg\", \"Seated_Palm-Up_Barbell_Wrist_Curl/1.jpg\"]','Flexiones de muñeca con barra sentado con las palmas hacia arriba',650) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de muñeca con barra sentado con las palmas hacia abajo','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Sosten una barra con ambas manos y las palmas hacia abajo; las manos separadas aproximadamente a la anchura de los hombros.\", \"Coloca tus pies planos en el suelo, a una distancia ligeramente superior a la anchura de los hombros.\", \"Inclinate hacia delante y coloca los antebrazos sobre la parte superior de los muslos con las palmas hacia abajo. Consejo: Asegurate de que la espalda de las muñecas quede sobre tus rodillas. Esta sera tu posicion inicial.\", \"Baja la barra lo mas lejos posible mientras inhalas y mantienes un agarre firme.\", \"Ahora flexiona la barra hacia arriba lo mas alto posible mientras flexionas los antebrazos y exhalas. Manten la contraccion en la parte superior durante un segundo y Consejo: Solo debe moverse la muñeca.\"]','fuerza','[\"Seated_Palms-Down_Barbell_Wrist_Curl/0.jpg\", \"Seated_Palms-Down_Barbell_Wrist_Curl/1.jpg\"]','Flexion de muñeca con barra sentado con las palmas hacia abajo',651) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de triceps sentado','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Sientate en un banco con respaldo y agarra una mancuerna con ambas manos y mantenla sobre la cabeza a la longitud del brazo. Consejo: una mejor manera es que alguien te la entregue, especialmente si es muy pesada. La resistencia debe descansar en las palmas de tus manos con los pulgares alrededor de ella. La palma de la mano debe estar mirando hacia dentro. Esta sera tu posicion inicial.\", \"Manteniendo los brazos cerca de la cabeza (codos hacia dentro) y perpendiculares al suelo, baja la resistencia con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Consejo: Los brazos deben permanecer fijos y solo deben moverse los antebrazos. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la mancuerna. Exhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Seated_Triceps_Press/0.jpg\", \"Seated_Triceps_Press/1.jpg\"]','Press de triceps sentado',653) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos con los hombros','traccion','principiante','Ninguno','Ninguno','[\"hombros\"]','[\"trapecios\"]','[\"Con los hombros relajados y los brazos descansando sueltos a los lados (o en el regazo si estas sentado), gira suavemente los hombros hacia delante, arriba, atras y abajo.\", \"Invierte la direccion. Puedes hacer este ejercicio alternando los hombros o ambos al mismo tiempo.\"]','estiramiento','[\"Shoulder_Circles/0.jpg\", \"Shoulder_Circles/1.jpg\"]','Circulos con los hombros',657) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de hombros con bandas','empuje','principiante','compuesto','bandas','[\"hombros\"]','[\"triceps\"]','[\"Para empezar, colocate sobre una banda elastica de modo que la tension comience a la longitud del brazo. Agarra las asas y levantalas de modo que las manos esten a la altura de los hombros a cada lado.\", \"Gira las muñecas de modo que las palmas de las manos queden mirando hacia delante. Los codos deben estar flexionados, con los brazos y antebrazos alineados con el torso. Esta es la posicion inicial.\", \"Mientras exhalas, levanta las asas hasta que los brazos esten completamente extendidos por encima de la cabeza.\"]','fuerza','[\"Shoulder_Press_-_With_Bands/0.jpg\", \"Shoulder_Press_-_With_Bands/1.jpg\"]','Press de hombros con bandas',658) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de hombros','traccion','principiante','Ninguno','Ninguno','[\"hombros\"]','[\"dorsales\"]','[\"Relaja los brazos a los lados y levanta los hombros hacia las orejas, luego vuelve a bajarlos.\"]','estiramiento','[\"Elevacion_de_hombros/0.jpg\", \"Elevacion_de_hombros/1.jpg\"]','Elevacion de hombros',659) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de hombros','traccion','principiante','Ninguno','Ninguno','[\"hombros\"]','[]','[\"Extiende el brazo izquierdo por delante del cuerpo y mantenlo recto.\"]','estiramiento','[\"Shoulder_Stretch/0.jpg\", \"Shoulder_Stretch/1.jpg\"]','Estiramiento de hombros',660) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Puente lateral','estatico','principiante','Ninguno','solo_cuerpo','[\"abdominales\"]','[\"hombros\"]','[]','fuerza','[\"Side_Bridge/0.jpg\", \"Side_Bridge/1.jpg\"]','Puente lateral',661) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto lateral-Sprint','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"isquiotibiales\"]','[\"Pongase de pie al lado de un cono o una valla.\", \"Comience este ejercicio saltando lateralmente por encima del obstaculo, rebotando desde el aterrizaje para saltar hacia atras hasta el punto de partida.\", \"Salte durante el numero de repeticiones prescrito lo mas rapido posible y termine este ejercicio corriendo a toda velocidad una distancia corta tras aterrizar el ultimo salto.\"]','pliometria','[\"Side_Hop-Sprint/0.jpg\", \"Side_Hop-Sprint/1.jpg\"]','Salto lateral-Sprint',662) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Side Jackknife','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[]','fuerza','[\"Side_Jackknife/0.jpg\", \"Side_Jackknife/1.jpg\"]','Side_Jackknife',663) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion lateral','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Elige un par de mancuernas y ponte de pie con el torso recto y las mancuernas a los lados, a la longitud de los brazos, con las palmas de las manos mirando hacia ti. Esta sera tu posicion inicial.\", \"Mientras mantienes el torso en una posicion fija (sin balancearte), levanta las mancuernas a los lados con una ligera flexion en los codos y las manos ligeramente inclinadas hacia delante, como si estuvieras vertiendo agua en un vaso. Continua subiendo hasta que tus brazos esten paralelos al suelo. Exhala mientras ejecutas este movimiento y haz una pausa durante un segundo en la parte superior.\", \"Baja las mancuernas lentamente hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Side_Lateral_Raise/0.jpg\", \"Side_Lateral_Raise/1.jpg\"]','Elevacion lateral lateral',664) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion lateral lateral a frontal','empuje','principiante','aislamiento','mancuerna','[\"hombros\"]','[\"trapecios\"]','[\"En posicion de pie, manten un par de mancuernas a tu lado. Esta sera tu posicion inicial.\", \"Manteniendo tus codos ligeramente flexionados, levanta las pesas directamente frente a ti a la altura de los hombros, evitando cualquier balanceo o trampa.\", \"En la parte superior del ejercicio, mueve las pesas frente a ti, manteniendo los brazos extendidos.\", \"Baja las pesas con un movimiento controlado.\", \"En la siguiente repeticion, levanta las pesas frente a ti a la altura de los hombros antes de moverlas lateralmente a los lados.\", \"Baja las pesas a la posicion inicial.\"]','fuerza','[\"Side_Laterals_to_Front_Raise/0.jpg\", \"Side_Laterals_to_Front_Raise/1.jpg\"]','Elevacion lateral hacia delante',665) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones laterales de pierna','traccion','principiante','Ninguno','solo_cuerpo','[\"aductores\"]','[]','[\"Ponte de pie junto a una silla, a la que puedes agarrarte como apoyo. Ponte de pie sobre una pierna. Esta sera tu posicion inicial.\", \"Manteniendo la pierna recta, levantala lo mas lejos posible hacia un lado y balanceala hacia atras, permitiendo que cruce la pierna opuesta.\", \"Repite este movimiento de balanceo entre 5 y 10 veces, aumentando el rango de movimiento a medida que lo haces.\"]','estiramiento','[\"Side_Leg_Raises/0.jpg\", \"Side_Leg_Raises/1.jpg\"]','Elevaciones laterales de pierna',666) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral de la ingle acostado','estatico','principiante','aislamiento','Ninguno','[\"aductores\"]','[\"isquiotibiales\"]','[\"Comienza acostandote sobre tu lado derecho y dobla la rodilla derecha frente a ti para estabilizar el torso.\", \"Apoya la cabeza en tu mano derecha o en el hombro. Eleva la pierna izquierda hacia arriba y mantenla por la parte posterior de la rodilla (mas facil) o por el pie (mas dificil).\", \"Lleva la rodilla izquierda hacia el hombro izquierdo y, al mismo tiempo, presiona el pie o la rodilla hacia el suelo. Para intensificar este estiramiento, estira la pierna izquierda. Cambia de lado.\"]','estiramiento','[\"Side_Lying_Groin_Stretch/0.jpg\", \"Side_Lying_Groin_Stretch/1.jpg\"]','Estiramiento lateral de la ingle',667) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral del cuello','estatico','principiante','aislamiento','Ninguno','[\"cuello\"]','[]','[\"Comienza con los hombros relajados e inclina suavemente la cabeza hacia el hombro.\", \"Ayuda al estiramiento tirando suavemente del lado de la cabeza.\"]','estiramiento','[\"Side_Neck_Stretch/0.jpg\", \"Side_Neck_Stretch/1.jpg\"]','Estiramiento lateral del cuello',668) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto lateral de pie','empuje','principiante','compuesto','Ninguno','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Comienza de pie con los pies separados a la anchura de las caderas en una postura atletica. Tu cabeza y pecho deben estar erguidos, con las rodillas y caderas ligeramente flexionadas. Esta sera tu posicion inicial.\", \"Inclinate hacia la derecha, extiende las caderas, rodillas y tobillos para saltar en el aire. Bloquea con los brazos para guiar el movimiento, saltando tan lejos como puedas hacia la derecha.\", \"Aterriza mirando en la misma direccion, con los pies separados a la anchura de las caderas, absorbiendo el impacto con la parte inferior del cuerpo.\"]','pliometria','[\"Side_Standing_Long_Jump/0.jpg\", \"Side_Standing_Long_Jump/1.jpg\"]','Salto en largo de pie de lado',669) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Side to Lateral Box Shuffle','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"isquiotibiales\"]','[\"Ponte de pie a un lado de la caja con el pie izquierdo apoyado en el centro de la misma.\", \"Para empezar, salta hacia arriba y al otro lado de la caja, aterrizando con el pie derecho en la parte superior de la caja y el pie izquierdo en el suelo. Balancea los brazos para ayudar al movimiento.\", \"Continua desplazandote hacia atras y hacia adelante a traves de la caja.\"]','pliometria','[\"Side_to_Side_Box_Shuffle/0.jpg\", \"Side_to_Side_Box_Shuffle/1.jpg\"]','Side_to_Side_Box_Shuffle',670) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexiones laterales','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"biceps\", \"antebrazos\", \"espalda_media\", \"hombros\"]','[\"Agarra la barra de dominadas con las palmas hacia delante y con un agarre amplio.\", \"Con ambos brazos extendidos frente a ti sosteniendo la barra con un agarre amplio, lleva el torso hacia atras unos 30 grados mas o menos, creando una curvatura en la parte inferior de la espalda y sacando el pecho. Esta es tu posicion inicial.\", \"Tira de tu torso hacia arriba mientras te inclinas hacia el lado izquierdo hasta que la barra casi toque la parte superior de tu pecho, llevando los hombros y la parte superior de los brazos hacia abajo y hacia atras. Exhala mientras realizas esta parte del movimiento. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa. La parte superior del torso debe permanecer inmovil mientras se mueve en el espacio (sin balancearse) y solo deben moverse los brazos. Los antebrazos no deben hacer ningun otro trabajo que no sea sostener la barra.\", \"Despues de un segundo de contraccion, inhala mientras vuelves la espalda a la posicion inicial.\", \"Ahora, tira del torso hacia arriba mientras te inclinas hacia el lado derecho hasta que la barra casi toque la parte superior del pecho, llevando los hombros y la parte superior de los brazos hacia abajo y hacia atras. Exhala mientras realizas esta parte del movimiento. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa. La parte superior del torso debe permanecer inmovil mientras se mueve por el espacio y solo deben moverse los brazos. Los antebrazos no deben hacer otro trabajo que mantener la barra.\", \"Despues de un segundo de contraccion, inhala mientras vuelves la espalda a la posicion inicial.\", \"Repite los pasos 3-6 hasta que hayas realizado la cantidad prescrita de repeticiones durante cada lado.\"]','fuerza','[\"Side_To_Side_Chins/0.jpg\", \"Side_To_Side_Chins/1.jpg\"]','Flexiones de lado a lado',671) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Traccion lateral de muñeca','estatico','principiante','aislamiento','Ninguno','[\"hombros\"]','[\"antebrazos\", \"dorsales\"]','[\"Este estiramiento funciona mejor de pie. Cruza el brazo izquierdo sobre la linea media de tu cuerpo y manten la muñeca izquierda en tu mano derecha abajo, a la altura de tus caderas. Comienza el estiramiento con el brazo izquierdo doblado.\", \"Endereza lentamente, tira y levantalo arriba a la altura del hombro, como se muestra en la imagen. Siente como este estiramiento se origina en la espalda, no en los hombros, y no tires demasiado fuerte de la articulacion de los hombros. Cambia de lado.\"]','estiramiento','[\"Side_Wrist_Pull/0.jpg\", \"Side_Wrist_Pull/1.jpg\"]','Traccion lateral de la muñeca',672) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral en el suelo','estatico','principiante','Ninguno','Ninguno','[\"dorsales\"]','[]','[\"Primero, acuestate sobre tu lado izquierdo, doblando la rodilla izquierda frente a ti para estabilizar tu torso (usa tambien los musculos abdominales para mantenerte erguido).\", \"Estira la pierna derecha y apoya el pie derecho en el suelo detras del izquierdo. Estira el brazo derecho por encima de la cabeza y tira suavemente de la muñeca derecha para estirar todo el lado derecho del cuerpo. Cambia de lado.\"]','estiramiento','[\"Side-Lying_Floor_Stretch/0.jpg\", \"Side-Lying_Floor_Stretch/1.jpg\"]','Estiramiento lateral en el suelo',673) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion con mancuerna','Ninguno','principiante','aislamiento','mancuerna','[\"hombros\"]','[\"antebrazos\", \"trapecios\"]','[\"Con las piernas abiertas, manten una mancuerna con ambas manos, agarrando la cabeza de la mancuerna en lugar del mango. Tus brazos deben estar extendidos y colgando a la altura de la cintura. Esta sera tu posicion inicial.\", \"Levanta el peso hasta que este por encima del nivel de los hombros, manteniendo los brazos extendidos. Tu torso y caderas deben permanecer inmoviles durante todo el movimiento.\", \"Regresa a la posicion inicial y repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Single_Dumbbell_Raise/0.jpg\", \"Single_Dumbbell_Raise/1.jpg\"]','Elevacion con una sola mancuerna',674) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Puente de gluteos con una sola pierna','empuje','principiante','aislamiento','solo_cuerpo','[\"gluteos\"]','[\"isquiotibiales\"]','[\"Tumbate en el suelo con los pies planos y las rodillas flexionadas.\", \"Levanta una pierna del suelo, llevando la rodilla hacia el pecho. Esta sera tu posicion inicial.\", \"Ejecuta el movimiento impulsandote con el talon, extendiendo la cadera hacia arriba y levantando los gluteos del suelo.\", \"Extiendete lo mas lejos posible, haz una pausa y luego vuelve a la posicion inicial.\"]','fuerza','[\"Puente gluteo con una sola pierna/0.jpg\", \"Puente gluteo con una sola pierna/1.jpg\"]','Puente de gluteos con una sola pierna',676) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje con una sola pierna','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"isquiotibiales\"]','[\"Ponte de pie en el suelo con un pie apoyado en la caja, con el talon cerca del borde.\", \"Empuja con el pie en la parte superior de la caja, tratando de ganar la mayor altura posible extendiendo la cadera y la rodilla.\", \"Aterriza con el mismo pie en la parte superior de la caja, volviendo el otro pie a la posicion inicial.\"]','pliometria','[\"Single_Leg_Push-off/0.jpg\", \"Single_Leg_Push-off/1.jpg\"]','Impulso con una sola pierna',677) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Cruce de un solo brazo en polea','empuje','principiante','aislamiento','polea','[\"pecho\"]','[]','[\"Comienza moviendo las poleas a la posicion alta, selecciona la resistencia que vas a utilizar y coge un mango en cada mano.\", \"Da un paso adelante frente a ambas poleas con los brazos extendidos frente a ti, juntando las manos. Tu cabeza y pecho deben estar arriba mientras te inclinas hacia delante, mientras que tus pies deben estar escalonados. Esta sera tu posicion inicial.\", \"Manten el brazo izquierdo en su sitio y deja que el brazo derecho se extienda hacia un lado, manteniendo una ligera flexion en el codo. El brazo derecho debe estar perpendicular al cuerpo, aproximadamente a la altura de los hombros.\", \"Vuelve el brazo hacia atras a la posicion inicial tirando de la mano hacia atras hasta la linea media del cuerpo.\", \"Manten durante un segundo la posicion inicial y repite el movimiento en el lado opuesto. Continua alternando hacia atras y hacia adelante durante el numero prescrito de repeticiones.\"]','fuerza','[\"Single-Arm_Cable_Crossover/0.jpg\", \"Single-Arm_Cable_Crossover/1.jpg\"]','Cruce con cable con un solo brazo',678) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion con un solo brazo','empuje','intermedio','compuesto','solo_cuerpo','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Comienza acostado boca abajo en el suelo. Ponte en una posicion en la que apoyes tu peso en los dedos de los pies y un brazo. El brazo con el que trabajas debe estar colocado directamente debajo del hombro, completamente extendido. Las piernas deben estar extendidas y, durante este movimiento, es posible que necesites una base mas amplia, colocando los pies mas separados que en una flexion normal.\", \"Manten una buena postura y coloca la mano libre detras de la espalda. Esta sera tu posicion inicial.\", \"Baja permitiendo que el codo se flexione hasta tocar el suelo.\", \"Desciende lentamente y cambia de direccion extendiendo el brazo para volver a la posicion inicial.\"]','fuerza','[\"Single-Arm_Push-Up/0.jpg\", \"Single-Arm_Push-Up/1.jpg\"]','Flexion con un solo brazo',680) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Ejercicio de sprint con un solo cono','empuje','principiante','Ninguno','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Este ejercicio enseña a mover los pies rapidamente. Necesitas un solo cono. Empieza de pie junto al cono con un brazo detras y otro delante.\", \"Da pasos lo mas rapido posible, bloqueando con los brazos. Rodea el cono, manten las rodillas levantadas, con movimientos violentos de los pies.\", \"Descansa despues de tres vueltas alrededor del cono.\"]','pliometria','[\"Single-Cone_Sprint_Drill/0.jpg\", \"Single-Cone_Sprint_Drill/1.jpg\"]','Ejercicio de sprint con un solo cono',681) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con una sola pierna en caja alta','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Coloca una caja en un soporte. Fija una banda o cuerda en su sitio por encima de la caja.\", \"De pie frente a ella, sube a la caja hasta quedar completamente de pie, dejando la otra pierna sin apoyo. Sujetate a la banda para mantener el equilibrio.\", \"Continua subiendo y bajando con la misma pierna antes de cambiar al lado opuesto.\"]','fuerza','[\"Single-Leg_High_Box_Squat/0.jpg\", \"Single-Leg_High_Box_Squat/1.jpg\"]','Sentadilla con una sola pierna en caja alta',682) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Progresion de saltos con una sola pierna','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"isquiotibiales\"]','[\"Coloca una fila de conos frente a ti. Adopta una posicion de pie relajada, equilibrada sobre una pierna. Levanta la rodilla de la pierna opuesta. Esta sera tu posicion inicial.\", \"Salta hacia delante, saltando y aterrizando con la misma pierna sobre el cono.\", \"Utiliza un salto de contramovimiento para saltar de cono en cono.\", \"Al final, gira alrededor y ve de espaldas sobre la otra pierna.\"]','pliometria','[\"Single-Leg_Hop_Progression/0.jpg\", \"Single-Leg_Hop_Progression/1.jpg\"]','Progresion de salto con una sola pierna',683) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto con una sola pierna','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"isquiotibiales\"]','[\"Ponte de pie al lado de una caja con el pie interior encima, cerca del borde.\", \"Empieza balanceando los brazos hacia arriba mientras empujas con la pierna superior, saltando lo mas alto posible. Intenta llevar la rodilla opuesta hacia arriba.\", \"Aterriza en la misma posicion en la que empezaste, utilizando la pierna interior para frenar el impacto.\"]','pliometria','[\"Salto_con_una_pierna/0.jpg\", \"Salto_con_una_pierna/1.jpg\"]','Salto con una sola pierna',686) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadillas','empuje','principiante','Ninguno','Ninguno','[\"cuadriceps\"]','[\"abductores\", \"gluteos\", \"isquiotibiales\"]','[\"Ponte de pie con los pies separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando las rodillas y las caderas, sentandote con las caderas.\", \"Continua hasta que hayas bajado una parte del camino, pero sin llegar a la posicion paralela, y revierte rapidamente el movimiento hasta volver a la posicion inicial. Repite durante 5-10 repeticiones.\"]','estiramiento','[\"Sit_Squats/0.jpg\", \"Sit_Squats/1.jpg\"]','Sentadillas sentadas',687) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominal','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Acuestate en el suelo colocando tus pies debajo de algo que no se mueva o pidiendo a un compañero que los sujete. Tus piernas deben estar dobladas por las rodillas.\", \"Coloca tus manos detras de la cabeza y unelas entrelazando los dedos. Esta es la posicion inicial.\", \"Eleva la parte superior del cuerpo de modo que se forme una V imaginaria con los muslos. Exhala al realizar esta parte del ejercicio.\", \"Una vez que sientas la contraccion durante un segundo, baja la parte superior del cuerpo hacia abajo hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Sit-Up/0.jpg\", \"Sit-Up/1.jpg\"]','Abdominales',688) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Patinaje','Ninguno','intermedio','Ninguno','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"El patinaje sobre ruedas es una actividad divertida que puede ser eficaz para mejorar la capacidad cardiorrespiratoria y la resistencia muscular. Requiere un equilibrio y una coordinacion relativamente buenos. Es necesario aprender los fundamentos del patinaje, incluidos los giros y las paradas, y llevar equipo de proteccion para evitar posibles lesiones.\", \"Puedes patinar a un ritmo comodo durante 30 minutos seguidos. Si quieres un reto cardiovascular, practica el patinaje a intervalos: patina a toda velocidad durante dos minutos de cada cinco, y utiliza los tres minutos restantes para recuperarte. Una persona de 68 kg quemara aproximadamente 175 calorias en 30 minutos patinando a un ritmo comodo, similar al de una caminata rapida.\"]','cardio','[\"Skating/0.jpg\", \"Skating/1.jpg\"]','Patinaje',689) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrastre de trineo - Arnes','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, carga el trineo con el peso deseado y coloca la correa de traccion. Puedes tirar con las asas, utilizar un arnes o colocar la correa de traccion en un cinturon de pesas.\", \"Tanto si tiras hacia delante como hacia atras, inclinate en la direccion del movimiento y avanza extendiendo las caderas y las rodillas.\"]','hombre_fuerte','[\"Arrastre_de_trineo_-_Arnes/0.jpg\", \"Arrastre_de_trineo_-_Arnes/1.jpg\"]','Arrastre de trineo con arnes',690) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Trineo sobre la cabeza Caminata hacia atras','traccion','principiante','compuesto','otro','[\"hombros\"]','[\"pantorrillas\", \"espalda_media\", \"cuadriceps\"]','[\"Fija dos asas a un trineo conectado por una cuerda o cadena. Carga el trineo con un peso ligero.\", \"Colocate frente al trineo, retrocediendo hasta que haya algo de tension en la cuerda. Manten las manos directamente por encima de la cabeza con los codos extendidos. Esta sera tu posicion inicial.\", \"Camina hacia atras, manteniendo los brazos levantados por encima de la cabeza. Evita los movimientos bruscos.\"]','fuerza','[\"Sled_Overhead_Backward_Walk/0.jpg\", \"Sled_Overhead_Backward_Walk/1.jpg\"]','Trineo por encima de la cabeza hacia atras',691) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con trineo sobre la cabeza','empuje','principiante','aislamiento','otro','[\"triceps\"]','[]','[\"Fija dos asas a un trineo con una cadena o una cuerda. Carga el trineo con un peso adecuado.\", \"De espaldas al trineo, alejate hasta que haya tension en la cuerda. Levanta las manos por encima de la cabeza, manteniendolas juntas, con las palmas enfrentadas. Tus codos deben estar apuntando hacia arriba con los codos flexionados. Esta sera tu posicion inicial.\", \"Extiende el codo para enderezar el brazo. Asegurate de que la parte superior del brazo permanezca en posicion para aislar los triceps.\", \"Una vez que hayas completado la extension, da un paso adelante para eliminar la holgura de la cuerda. Puedes mantener los pies escalonados para mayor estabilidad.\"]','fuerza','[\"Sled_Overhead_Triceps_Extension/0.jpg\", \"Sled_Overhead_Triceps_Extension/1.jpg\"]','Extension de triceps con trineo por encima de la cabeza',692) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Empuje con trineo','empuje','principiante','compuesto','otro','[\"cuadriceps\"]','[\"Pantorrillas\", \"Pecho\", \"Gluteos\", \"Isquiotibiales\", \"Triceps\"]','[\"Carga el trineo con el peso deseado.\", \"Adopta una postura atletica, inclinandote hacia el trineo con los brazos completamente extendidos y agarrando las asas. Empuja el trineo lo mas rapido posible, centrandote en extender las caderas y las rodillas para fortalecer la cadena posterior.\"]','hombre_fuerte','[\"Empuje_de_trineo/0.jpg\", \"Empuje_de_trineo/1.jpg\"]','Empuje de trineo',693) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sled Inverso Flye','traccion','principiante','aislamiento','otro','[\"hombros\"]','[]','[\"Fija las asas dobles a un trineo conectado por una cuerda o cadena. Carga el trineo con un peso ligero.\", \"Colocate frente al trineo, retrocediendo hasta que haya algo de tension en la linea. Toma ambos mangos a la longitud de los brazos aproximadamente a la altura de la cintura. Dobla ligeramente las rodillas y manten el pecho y la cabeza erguidos. Esta sera tu posicion inicial.\", \"Sin flexionar los codos, tira de los mangos hacia arriba y hacia afuera, realizando un fly inverso con algo de rotacion externa. Las palmas de las manos deben estar mirando hacia adelante mientras lo haces.\", \"Regresa a la posicion inicial, dando un par de pasos hacia atras para eliminar la holgura de la cuerda.\"]','fuerza','[\"Sled_Reverse_Flye/0.jpg\", \"Sled_Reverse_Flye/1.jpg\"]','Sled_Reverse_Flye',694) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Inclinado Hombro Elevacion','empuje','principiante','aislamiento','barra','[\"hombros\"]','[\"pecho\"]','[\"Coloca un banco inclinado debajo de la maquina Smith. Coloca la barra a una altura que puedas alcanzar cuando estes tumbado y tus brazos esten casi completamente extendidos. Una vez seleccionado el peso que necesitas, tumbate en el banco inclinado y asegurate de que tus hombros esten alineados correctamente debajo de la barra.\", \"Con un agarre pronado (palmas hacia delante) a la anchura de los hombros, levanta la barra del soporte y mantenla recta sobre ti con una ligera flexion en los codos. Esta sera tu posicion inicial.\", \"Mientras exhalas, levanta la barra hasta que tus brazos esten completamente extendidos. Nota: La contraccion debe sentirse alrededor de los hombros.\", \"Despues de una pausa de un segundo, lleva la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite el movimiento durante la cantidad prescrita de repeticiones.\", \"Cuando hayas terminado, coloca la barra en el soporte.\"]','fuerza','[\"Smith_Incline_Shoulder_Raise/0.jpg\", \"Smith_Incline_Shoulder_Raise/1.jpg\"]','Elevacion inclinada de hombros en Smith',697) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Machine Behind the Espalda Shrug','traccion','principiante','aislamiento','maquina','[\"trapecios\"]','[\"hombros\"]','[\"Con la barra a la altura de los muslos, carga un peso adecuado.\", \"Ponte de pie con la barra detras de ti, con las manos separadas a la anchura de los hombros y en posicion pronada, y desengancha el peso. Debes estar de pie con la espalda recta, la cabeza y el pecho erguidos y los brazos extendidos. Esta sera tu posicion inicial.\", \"Inicia el movimiento encogiendo los hombros hacia arriba. No flexiones los brazos ni las muñecas durante el movimiento.\", \"Tras una breve pausa, vuelve a colocar el peso en la posicion inicial.\", \"Repite el movimiento durante el numero deseado de repeticiones antes de enganchar los ganchos para colocar el peso en el soporte.\"]','fuerza','[\"Smith_Machine_Behind_the_Back_Shrug/0.jpg\", \"Smith_Machine_Behind_the_Back_Shrug/1.jpg\"]','Encogimiento de hombros detras de la espalda con maquina Smith',698) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press declinado en maquina Smith','Ninguno','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Coloca un banco declinado en el soporte de modo que la barra quede por encima de tu pecho. Carga un peso adecuado y toma tu lugar en el banco.\", \"Gira la barra para desengancharla del soporte y extiende completamente tus brazos. Tu espalda debe estar ligeramente arqueada y los omoplatos retraidos. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando los brazos, bajando la barra hasta el pecho.\", \"Haz una pausa breve y luego extiende los brazos para empujar el peso hacia atras hasta la posicion inicial.\", \"Despues de completar el numero deseado de repeticiones, gira la barra para colocar el peso en el soporte.\"]','fuerza','[\"Smith_Machine_Decline_Press/0.jpg\", \"Smith_Machine_Decline_Press/1.jpg\"]','Maquina Smith: press declinado',703) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Machine Hang Power Clean','traccion','intermedio','compuesto','maquina','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\", \"cuadriceps\", \"hombros\", \"trapecios\"]','[\"Coloca la barra a la altura de las rodillas y cargala con un peso adecuado.\", \"Agarra la barra con las palmas hacia abajo, a una distancia superior a la anchura de los hombros, y desengancha la barra de la maquina. Tus brazos deben estar completamente extendidos, con la cabeza y el pecho hacia arriba. Tus codos deben estar apuntando hacia fuera, con los hombros hacia atras y hacia abajo. Tus caderas deben estar hacia atras, cargando la tension en los isquiotibiales. Esta sera tu posicion inicial.\", \"Inicia el movimiento extendiendo con fuerza las caderas y las rodillas, acelerando hacia la barra. Asegurate de mantener los brazos rectos durante esta parte del movimiento.\", \"Una vez extendidos por completo, vuelve a doblar las caderas y las rodillas para bajar a la posicion de recepcion.\", \"Deja que los brazos se flexionen en este punto, rotando los codos alrededor de la barra para recibirla en tus hombros.\", \"Extiende las caderas y las rodillas para llegar a una posicion de pie con la barra apoyada en tus hombros y completar el movimiento.\"]','fuerza','[\"Smith_Machine_Hang_Power_Clean/0.jpg\", \"Smith_Machine_Hang_Power_Clean/1.jpg\"]','Maquina Smith: levantamiento de potencia colgado',704) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de cadera en maquina Smith','traccion','principiante','aislamiento','maquina','[\"abdominales\"]','[]','[\"Coloca un banco en el soporte y carga la barra con un peso adecuado. Tumbate boca abajo en el banco, colocando la planta de los pies contra la barra. Desbloquea la barra y extiende las piernas. Es posible que necesites usar las manos para ayudarte. Para mayor estabilidad, agarra los lados de la maquina Smith. Esta sera tu posicion inicial.\", \"Inicia el movimiento girando la pelvis y flexionando la columna para levantar las caderas del banco. Manten una ligera flexion en las rodillas durante todo el movimiento.\", \"Despues de una breve pausa, vuelve a colocar las caderas en el banco.\", \"Repite el numero deseado de repeticiones.\"]','fuerza','[\"Smith_Machine_Hip_Raise/0.jpg\", \"Smith_Machine_Hip_Raise/1.jpg\"]','Smith_Maquina_Elevacion_de_cadera',705) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Machine Inclinado Press de Banca','empuje','principiante','compuesto','maquina','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Coloca un banco inclinado debajo de la maquina Smith. Coloca la barra a una altura que puedas alcanzar cuando estes tumbado boca abajo y tus brazos esten casi completamente extendidos. Una vez seleccionado el peso que necesitas, tumbate boca abajo en el banco inclinado y asegurate de que la parte superior del pecho este alineada con la barra. Con un agarre pronado (las palmas mirando hacia delante) mas ancho que el ancho de los hombros, desbloquea la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. Esta sera tu posicion inicial.\", \"Mientras inspiras, baja lentamente hasta que sientas la barra en la parte superior del pecho.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos del pecho. Bloquea los brazos en la posicion contraida, manten durante un segundo y luego empieza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cuando hayas terminado, coloca la barra de nuevo en el soporte.\"]','fuerza','[\"Smith_Machine_Incline_Bench_Press/0.jpg\", \"Smith_Machine_Incline_Bench_Press/1.jpg\"]','Smith_Maquina_Press de banca inclinado',706) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Prensa de piernas en maquina Smith','empuje','intermedio','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Coloca la barra de la maquina Smith a unos centimetros del suelo. Asegurate de que descansa sobre los soportes de seguridad. Despues de cargar la barra con el peso adecuado, tumbate debajo de ella. Coloca el centro de tus pies sobre la barra, llevando las rodillas hacia el pecho. Esta sera tu posicion inicial.\", \"Comienza el movimiento empujando con los pies para mover la barra hacia arriba, extendiendo las caderas y las rodillas. No bloquees las rodillas.\", \"En la parte superior del movimiento, haz una breve pausa antes de volver a la posicion inicial.\"]','fuerza','[\"Smith_Machine_Leg_Press/0.jpg\", \"Smith_Machine_Leg_Press/1.jpg\"]','Maquina Smith_Prensa de piernas',707) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Machine One-Arm Upright Remo','traccion','principiante','compuesto','maquina','[\"hombros\"]','[\"biceps\", \"trapecios\"]','[\"Con la barra a la altura de los muslos, carga un peso adecuado.\", \"Agarra la barra con las manos separadas y desengancha el peso, retirando la mano libre de la barra. El brazo debe estar extendido mientras te mantienes erguido con la cabeza y el pecho levantados. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando el codo, levantando la parte superior del brazo con el codo apuntando hacia fuera. Continua hasta que el brazo este paralelo al suelo.\", \"Despues de una breve pausa, vuelve a colocar el peso en la posicion inicial.\", \"Repite el numero deseado de repeticiones antes de enganchar los ganchos para colocar el peso en el soporte.\"]','fuerza','[\"Smith_Machine_One-Arm_Upright_Row/0.jpg\", \"Smith_Machine_One-Arm_Upright_Row/1.jpg\"]','Maquina Smith: remo vertical con un brazo',708) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Smith Machine Sobre Cabeza Hombro Press','empuje','principiante','compuesto','maquina','[\"hombros\"]','[\"triceps\"]','[\"Para empezar, coloca un banco plano (o preferiblemente uno con respaldo) debajo de una maquina Smith. Coloca la barra a una altura tal que, cuando te sientes en el banco plano, los brazos esten casi completamente extendidos para alcanzar la barra.\", \"Una vez que tengas la altura correcta, sientate ligeramente detras de la barra, de modo que haya una linea recta imaginaria desde la punta de la nariz hasta la barra. Los pies deben estar fijos. Agarra la barra con las palmas hacia delante, desbloqueala y levantala hasta que tus brazos esten completamente extendidos. Esta es la posicion inicial.\", \"Comienza lentamente a bajar la barra hasta que este a la altura de la barbilla mientras inhalas.\", \"A continuacion, levanta la barra hasta la posicion inicial utilizando los hombros mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Smith_Machine_Overhead_Shoulder_Press/0.jpg\", \"Smith_Machine_Overhead_Shoulder_Press/1.jpg\"]','Maquina Smith: press de hombros por encima de la cabeza',709) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla pistol en maquina Smith','empuje','intermedio','compuesto','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, primero coloca la barra en la posicion que mejor se adapte a tu altura. Colocate debajo de ella y coloca la barra sobre la espalda de tus hombros.\", \"Toma la barra con las manos mirando hacia adelante, desbloqueala y levantala del soporte extendiendo tus piernas. 3\", \"Mueve un pie hacia adelante aproximadamente 12 pulgadas frente a la barra. Extiende la otra pierna frente a ti, manteniendola separada del suelo. Mira hacia adelante en todo momento y manten la columna vertebral en posicion neutra o ligeramente arqueada. Esta sera tu posicion inicial.\", \"Manteniendo una buena postura, baja flexionando la rodilla y la cadera, bajando tanto como te lo permita tu flexibilidad.\", \"Haz una pausa brevemente en la parte inferior y luego vuelve a la posicion inicial impulsandote con el talon del pie, extendiendo la rodilla y la cadera.\"]','fuerza','[\"Smith_Machine_Pistol_Squat/0.jpg\", \"Smith_Machine_Pistol_Squat/1.jpg\"]','Smith_Machine_Sentadilla_Pistola',710) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevaciones inversas de pantorrillas en maquina Smith','empuje','principiante','aislamiento','maquina','[\"pantorrillas\"]','[]','[\"Ajusta la barra en la maquina Smith a tu altura y alinea una plataforma elevada justo debajo de la barra.\", \"Ponte de pie en la plataforma con los talones de los pies apoyados en la parte superior y las puntas de los pies sobresaliendo. Coloca los dedos de los pies mirando hacia adelante con una postura a la anchura de los hombros.\", \"Ahora, coloca tus hombros debajo de la barra mientras mantienes la posicion de los pies descrita y empuja la barra hacia arriba extendiendo tus caderas y rodillas hasta que tu torso este erguido. Las rodillas deben mantenerse ligeramente flexionadas, nunca bloqueadas. Esta sera tu posicion inicial. Consejo: La barra en tu espalda es solo para mantener el equilibrio.\", \"Levanta las puntas de los pies mientras exhalas, extendiendo los dedos de los pies lo mas alto posible y flexionando las pantorrillas. Asegurate de que las rodillas permanezcan fijas en todo momento. No debe haber flexion en ningun momento. Manten la posicion contraida durante un segundo antes de empezar a bajar la espalda.\", \"Baja lentamente la espalda hasta la posicion inicial mientras inhalas bajando las puntas de los pies y los dedos de los pies.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Smith_Machine_Reverse_Calf_Raises/0.jpg\", \"Smith_Machine_Reverse_Calf_Raises/1.jpg\"]','Maquina Smith: elevaciones inversas de pantorrillas',711) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical en maquina Smith','traccion','principiante','compuesto','maquina','[\"trapecios\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Para empezar, coloca la barra en la maquina Smith a una altura que este aproximadamente a la mitad de tus muslos. Una vez elegida la altura correcta y cargada la barra, agarrala con un agarre pronado (palmas hacia delante) a la anchura de los hombros. Es posible que necesites unas muñequeras si utilizas un peso considerable.\", \"Eleva la barra hacia arriba y extiende completamente los brazos con la espalda recta. Debe haber una ligera flexion en los codos. Esta es la posicion inicial.\", \"Usa tus hombros para levantar la barra mientras exhalas. La barra debe estar cerca del cuerpo mientras la mueves hacia arriba. Continua levantandola hasta que casi toque tu barbilla. Consejo: Tus codos deben impulsar el movimiento. A medida que levantas la barra, tus codos deben estar siempre mas altos que tus antebrazos. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja la barra lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Smith_Machine_Upright_Row/0.jpg\", \"Smith_Machine_Upright_Row/1.jpg\"]','Maquina Smith: remo vertical',714) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Equilibrio en arrancada','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"Pantorrillas\", \"Gluteos\", \"Isquiotibiales\", \"Hombros\", \"Triceps\"]','[\"Comience con los pies en posicion de tirando, la barra apoyada sobre la espalda de los hombros y las manos colocadas en un agarre amplio de arranque.\", \"Levante la barra con una flexion brusca de las rodillas y empuje agresivamente por debajo de la barra, pasando los pies a la posicion de recepcion.\", \"Reciba la barra bloqueada sobre la cabeza cerca de la parte inferior de la sentadilla. El torso debe permanecer vertical, bajando las caderas entre las piernas.\", \"Continua descendiendo hasta la profundidad maxima y vuelve a la posicion de pie. Baja el peso con cuidado.\"]','halterofilia_olimpica','[\"Snatch_Balance/0.jpg\", \"Snatch_Balance/1.jpg\"]','Balance de arranque',717) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Snatch Peso Muerto','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"antebrazos\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[\"El peso muerto con arranque fortalece el primer tiron del arranque. Comience con un agarre ancho de arranque con la barra colocada en la plataforma. Los pies deben estar directamente debajo de las caderas, con los pies girados hacia fuera. Agachate hasta la barra, manteniendo la espalda en extension absoluta con la cabeza mirando hacia adelante.\", \"Inicia el movimiento impulsandote con los talones y levantando las caderas. El angulo de la espalda debe permanecer igual hasta que la barra pase las rodillas.\", \"En ese momento, impulsa tus caderas a traves de la barra mientras te recuestas. Devuelve la barra a la plataforma invirtiendo el movimiento.\"]','halterofilia_olimpica','[\"Snatch_Deadlift/0.jpg\", \"Snatch_Deadlift/1.jpg\"]','Arrancada_Peso muerto',718) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrancada','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"pantorrillas\", \"gluteos\", \"espalda_baja\", \"cuadriceps\", \"trapecios\"]','[\"Con una barra en el suelo cerca de las espinillas, toma un agarre ancho para el arranque. Baja las caderas con el peso concentrado en los talones, la espalda recta, la cabeza mirando hacia adelante, el pecho levantado y los hombros justo frente a la barra. Esta sera tu posicion inicial.\", \"Comienza el primer tiron impulsandote con los talones y extendiendo las rodillas. El angulo de la espalda debe permanecer igual y los brazos deben permanecer rectos. Mueve el peso con control mientras continuas por encima de las rodillas.\", \"A continuacion viene el segundo tiron, la principal fuente de aceleracion durante el tiron. A medida que la barra se acerca a la posicion media del muslo, comienza a extender las caderas. En un movimiento de salto, acelera extendiendo las caderas, las rodillas y los tobillos, utilizando la velocidad para mover la barra hacia arriba.\", \"No deberia ser necesario tirar activamente con los brazos para acelerar el peso; al final del segundo tiron, el cuerpo deberia estar completamente extendido, inclinandose ligeramente hacia atras. La extension completa debe ser violenta y abrupta, y asegurate de no prolongar la extension mas tiempo del necesario.\"]','fuerza','[\"Snatch_Pull/0.jpg\", \"Snatch_Pull/1.jpg\"]','Arrancada_Pull',720) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Arrancada con encogimiento de hombros','traccion','intermedio','compuesto','barra','[\"trapecios\"]','[\"antebrazos\", \"hombros\"]','[\"Comience con un agarre amplio, con la barra colgando a la altura de la mitad del muslo. Puede utilizar un agarre en gancho o por encima. La espalda debe estar recta e inclinada ligeramente hacia delante.\", \"Encoja los hombros hacia las orejas. Aunque este ejercicio suele realizarse con mas peso que un arranque, evite sobrecargarlo hasta el punto de que la ejecucion se ralentice.\"]','halterofilia_olimpica','[\"Snatch_Shrug/0.jpg\", \"Snatch_Shrug/1.jpg\"]','Arrancada_Encogimiento',721) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Speed Band Sobre Cabeza Triceps','empuje','principiante','aislamiento','bandas','[\"triceps\"]','[]','[\"Para este ejercicio, fija una banda al suelo. Nosotros utilizamos un banco inclinado y fijamos la banda a la base, colocandonos de pie sobre el banco. Tambien se puede realizar de pie sobre la banda.\", \"Para empezar, tira de la banda por detras de la cabeza, sujetandola con un agarre pronado y los codos hacia arriba. Esta sera tu posicion inicial.\", \"Para realizar el movimiento, extiende el codo para estirar los brazos, asegurandote de mantener la parte superior del brazo en su sitio.\", \"Haz una pausa y luego vuelve a la posicion inicial.\"]','fuerza','[\"Speed_Band_Overhead_Triceps/0.jpg\", \"Speed_Band_Overhead_Triceps/1.jpg\"]','Velocidad_Banda_Por encima de la cabeza_Triceps',722) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Speed Box Sentadilla','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Fija las bandas a la barra que estan bien ancladas cerca del suelo. Es posible que tengas que apretar las bandas para conseguir la tension adecuada.\", \"Utiliza una caja de la altura adecuada durante este ejercicio. Carga la barra con un peso que aun requiera esfuerzo, pero que no sea tan pesado que comprometa la velocidad. Por lo general, sera entre el 50 y el 70 % de tu maximo de una repeticion.\", \"Coloca la barra en la parte superior de la espalda, con los omoplatos retraidos, la espalda arqueada y todo el cuerpo tenso desde la cabeza hasta los pies. Esta sera la posicion inicial.\", \"Saca la barra del soporte y colocate frente a la caja. Sientate con la espalda y las caderas hasta que estes sentado en la caja, asegurandote de que desciendes con control y no te golpees contra la superficie.\", \"Haz una pausa brevemente y explota fuera de la caja, extendiendo las caderas y las rodillas.\"]','levantamiento de pesas','[\"Speed_Box_Squat/0.jpg\", \"Speed_Box_Squat/1.jpg\"]','Velocidad_Box_Sentadilla',723) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Spell Caster','traccion','principiante','compuesto','mancuerna','[\"abdominales\"]','[\"gluteos\", \"hombros\"]','[\"Sosten una mancuerna en cada mano con un agarre pronado. Tus pies deben estar separados a la anchura de tus caderas y tus rodillas extendidas. Esta sera tu posicion inicial.\", \"Comienza el movimiento tirando ambas mancuernas hacia un lado, junto a la cadera, rotando el torso.\", \"Manteniendo los brazos rectos y las mancuernas paralelas al suelo, rota el torso para balancear las pesas hacia el lado opuesto.\", \"Continua alternando, rotando de un lado al otro hasta completar la serie.\"]','fuerza','[\"Spell_Caster/0.jpg\", \"Spell_Caster/1.jpg\"]','Spell_Caster',725) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Spider Crawl','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[\"pecho\", \"hombros\", \"triceps\"]','[\"Comienza en posicion boca abajo en el suelo. Apoya tu peso en tus manos y dedos de los pies, con los pies juntos y el cuerpo recto. Tus brazos deben estar doblados a 90 grados. Esta sera tu posicion inicial.\", \"Inicia el movimiento levantando un pie del suelo. Gira la pierna hacia fuera y lleva la rodilla hacia el codo, lo mas adelante posible.\", \"Vuelve a colocar la pierna en la posicion inicial y repite en el lado opuesto.\"]','fuerza','[\"Spider_Crawl/0.jpg\", \"Spider_Crawl/1.jpg\"]','Spider_Crawl',726) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento espinal','estatico','principiante','aislamiento','Ninguno','[\"espalda_media\"]','[\"dorsales\", \"espalda_baja\", \"cuello\", \"trapecios\"]','[\"Sientate en una silla con la espalda recta y los pies apoyados en el suelo.\", \"Entrelaza los dedos detras de la cabeza, con los codos hacia fuera y la barbilla hacia abajo.\", \"Gira la parte superior del cuerpo hacia un lado aproximadamente 3 veces tan lejos como puedas. Luego inclinate hacia adelante y gira el torso para llevar el codo al suelo en la parte interior de la rodilla.\", \"Vuelve a la posicion erguida y repite con el otro lado.\"]','estiramiento','[\"Spinal_Stretch/0.jpg\", \"Spinal_Stretch/1.jpg\"]','Estiramiento de la columna vertebral',728) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto dividido','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Adopta una posicion de zancada con un pie delante con la rodilla flexionada y la rodilla trasera casi tocando el suelo.\", \"Asegurate de que la rodilla delantera este sobre la linea media del pie.\", \"Extendiendo ambas piernas, salta lo mas alto posible, balanceando los brazos para ganar impulso.\", \"Mientras saltas, junta los pies y muevelos hacia atras a su posicion inicial al aterrizar.\", \"Absorbe el impacto volviendo a la posicion inicial.\"]','pliometria','[\"Split_Jump/0.jpg\", \"Split_Jump/1.jpg\"]','Salto con split',731) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla dividida con mancuernas','empuje','principiante','compuesto','mancuerna','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Colocate en una postura escalonada con el pie trasero elevado y el pie delantero hacia delante.\", \"Sosten una mancuerna en cada mano, dejandolas colgar a los lados. Esta sera tu posicion inicial.\", \"Comienza descendiendo, flexionando la rodilla y la cadera para bajar el cuerpo. Manten una buena postura durante todo el movimiento. Manten la rodilla delantera alineada con el pie mientras realizas el ejercicio.\", \"En la parte inferior del movimiento, empuja con el talon para extender la rodilla y la cadera y volver a la posicion inicial.\"]','fuerza','[\"Split_Squat_with_Dumbbells/0.jpg\", \"Split_Squat_with_Dumbbells/1.jpg\"]','Sentadilla dividida con mancuernas',733) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadillas divididas','empuje','intermedio','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"Pantorrillas\", \"Gluteos\", \"Cuadriceps\"]','[\"En posicion de pie. Salta a una posicion de piernas separadas, con una pierna delante y otra detras, flexionando las rodillas y bajando ligeramente las caderas al hacerlo.\", \"A medida que desciendes, invierte inmediatamente la direccion, poniendote de espaldas y saltando, invirtiendo la posicion de tus piernas. Repite 5-10 veces con cada pierna.\"]','estiramiento','[\"Split_Squats/0.jpg\", \"Split_Squats/1.jpg\"]','Sentadillas con split',734) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadillas - Con bandas','empuje','principiante','compuesto','bandas','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Para empezar, asegurate de que la banda elastica este dividida por igual entre ambos lados izquierdo y derecho del cuerpo. Para ello, utiliza tus manos para agarrar ambos lados de la banda y coloca ambos pies en el centro de la banda. Tus pies deben estar separados a la altura de los hombros.\", \"Al sostener las bandas, deben estar a la misma altura en cada lado. Debes utilizar un agarre pronado (las palmas mirando hacia delante) y tener las asas de las bandas junto a la cara durante este ejercicio. Esta es la posicion inicial.\", \"Empieza a doblar lentamente las rodillas y baja las piernas de modo que tus muslos queden paralelos al suelo mientras exhalas.\", \"Utiliza el talon de tus pies para empujar tu cuerpo hacia arriba hasta la posicion inicial mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Squats_-_With_Bands/0.jpg\", \"Squats_-_With_Bands/1.jpg\"]','Sentadillas con bandas',739) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Stairmaster','Ninguno','intermedio','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, subete a la escaladora y selecciona la opcion deseada en el menu. Puedes elegir un ajuste manual o seleccionar un programa para ejecutar. Por lo general, puedes introducir tu edad y peso para estimar la cantidad de calorias quemadas durante el ejercicio.\", \"Bombea tus piernas arriba y abajo con un ritmo establecido, empujando los pedales hacia abajo, pero sin llegar hasta el suelo. Se recomienda que mantengas el agarre en las asas para no caerte. Las asas se pueden utilizar para controlar tu frecuencia cardiaca y ayudarte a mantener una intensidad adecuada.\", \"Las Stairmasters ofrecen comodidad, beneficios cardiovasculares y suelen tener menos impacto que correr al aire libre. Por lo general, son mucho mas duras que otros equipos de cardio. Una persona de 68 kg quemara normalmente mas de 300 calorias en 30 minutos, en comparacion con las aproximadamente 175 calorias que se queman caminando.\"]','cardio','[\"Stairmaster/0.jpg\", \"Stairmaster/1.jpg\"]','Stairmaster',740) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuerna a un brazo inclinado de pie','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[\"hombros\"]','[\"Con una mancuerna en una mano y la palma mirando hacia tu torso, flexiona ligeramente las rodillas y lleva el torso hacia adelante, doblando la cintura, mientras mantienes la espalda recta hasta que este casi paralela al suelo. Asegurate de mantener la cabeza erguida.\", \"El brazo debe estar cerca del torso y paralelo al suelo, mientras que el antebrazo apunta hacia el suelo y la mano sostiene el peso. Consejo: Debe haber un angulo de 90 grados entre el antebrazo y el brazo. Esta es tu posicion inicial.\", \"Manteniendo los brazos fijos, utiliza los triceps para levantar las pesas mientras exhalas hasta que los antebrazos esten paralelos al suelo y todo el brazo este extendido. Al igual que en muchos otros ejercicios de brazos, solo se mueve el antebrazo.\", \"Despues de una segunda contraccion en la parte superior, baja lentamente la mancuerna hacia la posicion inicial mientras inhalas.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/0.jpg\", \"Standing_Bent-Over_One-Arm_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuerna a un brazo inclinado de pie',744) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuernas a dos brazos inclinado de pie','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Con una mancuerna en cada mano y las palmas mirando hacia tu torso, flexiona ligeramente las rodillas y lleva el torso hacia adelante, doblando la cintura, mientras mantienes la espalda recta hasta que este casi paralela al suelo. Asegurate de mantener la cabeza erguida. Los brazos superiores deben estar cerca del torso y paralelos al suelo, mientras que los antebrazos apuntan hacia el suelo y las manos sostienen las pesas. Consejo: Debe haber un angulo de 90 grados entre los antebrazos y la parte superior del brazo. Esta es tu posicion inicial.\", \"Manteniendo los brazos superiores fijos, utiliza los triceps para levantar las pesas mientras exhalas hasta que los antebrazos esten paralelos al suelo y los brazos completos esten extendidos. Al igual que en muchos otros ejercicios de brazos, solo se mueve el antebrazo.\", \"Despues de una segunda contraccion en la parte superior, baja lentamente las mancuernas hacia su posicion inicial mientras inhalas.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/0.jpg\", \"Standing_Bent-Over_Two-Arm_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuernas a dos brazos de pie inclinado',745) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de biceps de pie en polea','traccion','principiante','aislamiento','polea','[\"biceps\"]','[]','[\"Ponte de pie con el torso erguido mientras sostienes una barra de polea que esta conectada a una polea baja. Agarra la barra de la polea a la altura de los hombros y manten los codos cerca del torso. Las palmas de tus manos deben estar mirando hacia arriba (agarre supinado). Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas el musculo.\", \"Comienza lentamente a llevar la barra de curl hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Biceps_Cable_Curl/0.jpg\", \"Standing_Biceps_Cable_Curl/1.jpg\"]','Curl de biceps con cable de pie',746) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de biceps de pie','estatico','principiante','aislamiento','otro','[\"biceps\"]','[\"pecho\", \"hombros\"]','[\"Clasp tus manos behind tu espalda con your palms together, straighten brazos y luego rotate them so your palms face downward.\", \"Levanta tu brazos arriba y manten hasta you feel a stretch in your biceps.\"]','estiramiento','[\"Standing_Biceps_Stretch/0.jpg\", \"Standing_Biceps_Stretch/1.jpg\"]','Estiramiento de biceps de pie',747) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de Bradford de pie','empuje','principiante','compuesto','barra','[\"hombros\"]','[\"triceps\"]','[\"Coloca una barra cargada al nivel de los hombros en un soporte. Con un agarre pronado a la altura de los hombros, comienza con la barra apoyada en la parte delantera de tus hombros. Esta es tu posicion inicial.\", \"Inicia el levantamiento extendiendo los codos para presionar la barra sobre la cabeza. Evita bloquear los codos al mover el peso detras de la cabeza.\", \"Baja la barra hacia la espalda de la cabeza hasta que los codos formen un angulo recto.\", \"Eleva la barra por encima de la cabeza extendiendo los codos.\", \"Baja la barra a la posicion inicial.\", \"Alterna de esta forma hasta completar la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Bradford_Press/0.jpg\", \"Standing_Bradford_Press/1.jpg\"]','Press Bradford de pie',748) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de pecho con poleas de pie','empuje','principiante','compuesto','polea','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Coloca las poleas dobles a la altura del pecho y selecciona un peso adecuado. Ponte de pie con un pie o dos delante de las poleas, sosteniendo una en cada mano. Puede escalonar su postura para una mayor estabilidad.\", \"Coloque la parte superior del brazo en un angulo de 90 grados con los omoplatos juntos. Esta sera su posicion inicial.\", \"Manteniendo el resto del cuerpo inmovil, extienda los codos para empujar las manijas hacia adelante, juntandolas frente a usted.\", \"Haga una pausa en la parte superior del movimiento y vuelva a la posicion inicial.\"]','fuerza','[\"Standing_Cable_Chest_Press/0.jpg\", \"Standing_Cable_Chest_Press/1.jpg\"]','Press de pecho con cable de pie',749) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de concentracion de pie','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Toma una mancuerna en la mano con la que vas a trabajar e inclinate hacia delante. Deja que el brazo con el que trabajas cuelgue perpendicular al suelo con el codo apuntando hacia fuera. Esta sera tu posicion inicial.\", \"Flexiona el codo para levantar el peso, manteniendo la parte superior del brazo inmovil. En la parte superior de la repeticion, flexiona el biceps y haz una pausa.\", \"Baja la mancuerna de espaldas a la posicion inicial.\", \"Repite el movimiento durante la cantidad prescrita de repeticiones.\"]','fuerza','[\"Standing_Concentration_Curl/0.jpg\", \"Standing_Concentration_Curl/1.jpg\"]','Curl de concentracion de pie',753) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de mancuernas de pie','empuje','principiante','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"De pie con los pies separados a la anchura de los hombros, toma una mancuerna en cada mano. Levanta las mancuernas a la altura de la cabeza, con los codos hacia fuera y aproximadamente a 90 grados. Esta sera tu posicion inicial.\", \"Manteniendo una tecnica estricta, sin impulsar las piernas ni inclinarte hacia atras, extiende los codos para levantar las pesas juntas directamente por encima de la cabeza.\", \"Haz una pausa y vuelve lentamente a la posicion inicial.\"]','fuerza','[\"Standing_Dumbbell_Press/0.jpg\", \"Standing_Dumbbell_Press/1.jpg\"]','Press con mancuernas de pie',755) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl inverso con mancuernas de pie','traccion','intermedio','aislamiento','mancuerna','[\"biceps\"]','[\"antebrazos\"]','[\"Para comenzar, ponte de pie con una mancuerna en cada mano utilizando un agarre pronado (las palmas hacia abajo). Tus brazos deben estar completamente extendidos mientras tus pies estan separados a la anchura de los hombros. Esta es la posicion inicial.\", \"Mientras mantienes los brazos superiores fijos, flexiona los pesos mientras contraes los biceps al exhalar. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y las mancuernas esten al nivel de los hombros. Manten la posicion contraida durante un segundo mientras aprietas el musculo.\", \"Comienza lentamente a llevar las mancuernas de vuelta a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Dumbbell_Reverse_Curl/0.jpg\", \"Standing_Dumbbell_Reverse_Curl/1.jpg\"]','Curl inverso con mancuernas de pie',756) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Standing con Mancuerna Straight-Arm Frontal Delt Elevacion Above Head','empuje','intermedio','aislamiento','mancuerna','[\"hombros\"]','[]','[\"Sosten el mancuernas frente a tus muslos, con las palmas mirando hacia tus muslos.\", \"Manten tus brazos rectos con una ligera flexion en los codos, pero mantenlos bloqueados. Esta sera tu posicion inicial.\", \"Levanta el mancuernas in a semicircular motion to arm\'s length sobre la cabeza as you exhale.\", \"Slowly return to the inicial posicion using the mismo path as you inhale.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/0.jpg\", \"Standing_Dumbbell_Straight-Arm_Front_Delt_Raise_Above_Head/1.jpg\"]','Elevacion frontal de deltoides con mancuernas de pie con brazos rectos por encima de la cabeza',757) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps de pie con mancuernas','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Para empezar, ponte de pie con una mancuerna sujeta con ambas manos. Tus pies deben estar separados aproximadamente a la anchura de los hombros. Lentamente, utiliza ambas manos para agarrar la mancuerna y levantala por encima de tu cabeza hasta que ambos brazos esten completamente extendidos.\", \"La resistencia debe descansar en las palmas de tus manos con los pulgares alrededor de ella. Las palmas de las manos deben estar mirando hacia arriba, hacia el techo. Esta sera tu posicion inicial.\", \"Manten la parte superior de los brazos cerca de la cabeza, con los codos hacia dentro y perpendiculares al suelo, y baja la resistencia con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Consejo: La parte superior de los brazos debe permanecer inmovil y solo deben moverse los antebrazos. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la mancuerna. Exhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Dumbbell_Triceps_Extension/0.jpg\", \"Standing_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuernas de pie',758) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical con mancuernas','traccion','principiante','compuesto','mancuerna','[\"trapecios\"]','[\"biceps\", \"hombros\"]','[\"Agarra una mancuerna en cada mano con un agarre pronado (palmas hacia adelante) que sea ligeramente inferior al ancho de los hombros. Las mancuernas deben descansar sobre la parte superior de los muslos. Tus brazos deben estar extendidos con una ligera flexion en los codos y tu espalda debe estar recta. Esta sera tu posicion inicial.\", \"Usa tus hombros para levantar las mancuernas mientras exhalas. Las mancuernas deben estar cerca del cuerpo mientras las mueves hacia arriba y los codos deben impulsar el movimiento. Continua levantandolas hasta que casi toquen tu barbilla. Consejo: Tus codos deben impulsar el movimiento. A medida que levantas las mancuernas, tus codos deben estar siempre mas altos que tus antebrazos. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja las mancuernas lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Dumbbell_Upright_Row/0.jpg\", \"Standing_Dumbbell_Upright_Row/1.jpg\"]','Remo vertical con mancuernas de pie',759) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de cuadriceps elevado de pie','estatico','principiante','Ninguno','otro','[\"cuadriceps\"]','[]','[\"Comienza de pie con la espalda a unos dos o tres pies de distancia de un banco o escalon.\", \"Levanta una pierna hacia atras y apoya el pie en el escalon, ya sea en el empeine o en la planta del pie, lo que te resulte mas comodo.\", \"Manten la rodilla de apoyo ligeramente flexionada y evita que la rodilla se extienda mas alla de los dedos de los pies. Cambia de lado.\"]','estiramiento','[\"Standing_Elevated_Quad_Stretch/0.jpg\", \"Standing_Elevated_Quad_Stretch/1.jpg\"]','Estiramiento de cuadriceps elevado de pie',760) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Frontal de pie con barra elevada por encima de la cabeza','empuje','intermedio','aislamiento','barra','[\"hombros\"]','[]','[\"Para empezar, ponte de pie recto con una barra en tus manos. Debes agarrar la barra con las palmas hacia abajo y con un agarre mas cercano que el ancho de los hombros entre si.\", \"Tus pies deben estar separados a la anchura de los hombros entre si. Tus codos deben estar ligeramente flexionados. Esta es la posicion inicial.\", \"Eleva la barra hacia arriba hasta que este directamente sobre tu cabeza mientras exhalas. Asegurate de mantener los codos ligeramente flexionados al realizar cada repeticion.\", \"Una vez que sientas la contraccion, comienza a bajar la barra hacia atras hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Front_Barbell_Raise_Over_Head/0.jpg\", \"Standing_Front_Barbell_Raise_Over_Head/1.jpg\"]','Elevacion frontal con barra de pie por encima de la cabeza',761) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de pantorrillas de pie','estatico','principiante','Ninguno','Ninguno','[\"pantorrillas\"]','[\"isquiotibiales\"]','[\"Coloca el talon derecho en un escalon con la rodilla extendida e inclinate hacia delante para agarrar el dedo del pie derecho con la mano derecha. La rodilla izquierda debe estar ligeramente doblada y la espalda recta.\", \"Apoya tu peso en la pierna izquierda y coloca la mano izquierda en el muslo izquierdo.\", \"Tira de los dedos del pie derecho hacia la rodilla hasta que sientas un estiramiento en la pantorrilla.\"]','estiramiento','[\"Standing_Gastrocnemius_Calf_Stretch/0.jpg\", \"Standing_Gastrocnemius_Calf_Stretch/1.jpg\"]','Estiramiento de pantorrillas y gemelos de pie',762) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de isquiotibiales y pantorrillas de pie','estatico','principiante','Ninguno','otro','[\"isquiotibiales\"]','[]','[\"Coloca un cinturon, una banda elastica o una cuerda alrededor de un pie. De pie, coloca ese pie hacia delante.\", \"Dobla la pierna trasera, mientras mantienes la delantera recta. Ahora levanta los dedos del pie delantero del suelo e inclinate hacia delante.\", \"Utilizando el cinturon, tira de la parte superior del pie para aumentar el estiramiento de la pantorrilla. Manten la posicion durante 10-20 segundos y repite con el otro pie.\"]','estiramiento','[\"Standing_Hamstring_and_Calf_Stretch/0.jpg\", \"Standing_Hamstring_and_Calf_Stretch/1.jpg\"]','Estiramiento de isquiotibiales y pantorrillas de pie',763) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Circulos de cadera de pie','traccion','principiante','aislamiento','solo_cuerpo','[\"abductores\"]','[\"aductores\"]','[\"Comienza de pie sobre una pierna, sujetandote a un soporte vertical.\", \"Levanta la rodilla que no esta apoyada hasta formar un angulo de 90 grados. Esta sera tu posicion inicial.\", \"Abre la cadera lo maximo posible, intentando hacer un gran circulo con la rodilla.\", \"Realiza este movimiento lentamente durante varias repeticiones y repite con la otra pierna.\"]','estiramiento','[\"Standing_Hip_Circles/0.jpg\", \"Standing_Hip_Circles/1.jpg\"]','Circulos de cadera de pie',764) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexores de cadera de pie','estatico','principiante','aislamiento','Ninguno','[\"cuadriceps\"]','[]','[\"Ponte de pie recto con la columna vertical, el pie izquierdo ligeramente delante del derecho.\", \"Dobla ambas rodillas y levanta el talon trasero del suelo mientras empujas la cadera derecha hacia delante. Sin embargo, no puedes conseguir un estiramiento completo y profundo en esta posicion, porque es dificil relajar el flexor de la cadera y mantenerte de pie al mismo tiempo. Cambia de lado.\"]','estiramiento','[\"Standing_Hip_Flexors/0.jpg\", \"Standing_Hip_Flexors/1.jpg\"]','Flexores de cadera de pie',765) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral de pie','estatico','principiante','Ninguno','Ninguno','[\"abdominales\"]','[]','[\"Adopta una postura ligeramente mas ancha que la distancia entre las caderas, con las rodillas ligeramente flexionadas.\", \"Coloca la mano derecha en la cadera derecha para apoyar la columna vertebral.\", \"Levanta el brazo izquierdo en linea vertical y coloca la mano izquierda detras de la cabeza. Manten la mano en esa posicion mientras inclinas el torso hacia la derecha.\", \"Manten el peso distribuido uniformemente entre ambas piernas (no te inclines hacia la cadera izquierda). Cambia de lado.\"]','estiramiento','[\"Standing_Lateral_Stretch/0.jpg\", \"Standing_Lateral_Stretch/1.jpg\"]','Estiramiento lateral de pie',767) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto de longitud de pie','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Este ejercicio se realiza mejor en arena u otra superficie blanda. Asegurate de que puedes medir la distancia. Pongase de pie en una postura de sentadilla parcial con los pies separados a la anchura de los hombros.\", \"Utilizando un gran balanceo de brazos y un contramovimiento de las piernas, salte hacia delante tan lejos como pueda.\", \"Intente aterrizar con los pies delante de usted, llegando tan lejos como sea posible con las piernas.\", \"Mida la distancia desde el punto de aterrizaje hasta el punto inicial y registre los resultados.\"]','pliometria','[\"Standing_Long_Jump/0.jpg\", \"Standing_Long_Jump/1.jpg\"]','Salto de longitud desde parada',769) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion de deltoides con polea baja de pie','empuje','principiante','aislamiento','polea','[\"hombros\"]','[\"antebrazos\"]','[\"Comienza de pie al lado derecho de una polea baja. Usa tu mano izquierda para cruzar el cuerpo y agarra una sola manija conectada a la polea baja con un agarre pronado (las palmas hacia abajo). Descansa tu brazo frente a ti. Tu mano derecha debe agarrar la maquina para un mejor apoyo y equilibrio.\", \"Asegurate de que tu espalda este erguida y tus pies separados a la altura de los hombros. Esta es la posicion inicial.\", \"Comienza a utilizar la mano izquierda y cruza tu cuerpo hasta que se eleve a la altura de los hombros mientras exhalas.\", \"Siente la contraccion en la parte superior durante un segundo y comienza a bajar lentamente el mango hacia atras hasta la posicion inicial original mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"Standing_Low-Pulley_Deltoid_Raise/0.jpg\", \"Standing_Low-Pulley_Deltoid_Raise/1.jpg\"]','Elevacion de deltoides con polea baja de pie',770) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con una sola mano de pie con polea baja','empuje','intermedio','aislamiento','polea','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Agarra una sola manija con tu brazo izquierdo junto a la maquina de polea baja. Gira alejandote de la maquina manteniendo la manija al lado de tu cuerpo con el brazo completamente extendido. Ahora usa ambas manos para elevar la manija directamente por encima de la cabeza con la palma hacia adelante. Manten la parte superior del brazo completamente vertical (perpendicular al suelo) y coloca tu mano derecha en tu codo izquierdo para ayudar a mantenerlo estable. Esta es la posicion inicial.\", \"Manten los brazos cerca de la cabeza (codos hacia dentro) y perpendiculares al suelo, baja la resistencia con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Consejo: Los brazos deben permanecer fijos y solo deben moverse los antebrazos. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la manija unica. Exhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazos y repite el ejercicio.\"]','fuerza','[\"Standing_Low-Pulley_One-Arm_Triceps_Extension/0.jpg\", \"Standing_Low-Pulley_One-Arm_Triceps_Extension/1.jpg\"]','Extension de triceps con una mano de pie con polea baja',771) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press militar de pie','empuje','principiante','compuesto','barra','[\"hombros\"]','[\"triceps\"]','[\"Comienza colocando una barra que este aproximadamente a la altura del pecho en un soporte para sentadillas. Una vez que hayas seleccionado los pesos, agarra la barra con un agarre pronado (las palmas mirando hacia adelante). Asegurate de agarrar la barra con una separacion mayor que el ancho de los hombros.\", \"Dobla ligeramente las rodillas y coloca la barra en la clavicula. Eleva la barra manteniendola apoyada en el pecho. Da un paso hacia atras y coloca los pies separados a la anchura de los hombros.\", \"Una vez que hayas cogido la barra con la longitud de agarre correcta, levantala por encima de la cabeza bloqueando los brazos. Mantenla aproximadamente a la altura de los hombros y ligeramente por delante de la cabeza. Esta es tu posicion inicial.\", \"Baja la barra lentamente hasta la clavicula mientras inhalas.\", \"Eleva la barra hacia atras hasta la posicion inicial mientras exhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Military_Press/0.jpg\", \"Standing_Military_Press/1.jpg\"]','Press militar de pie',772) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Apreton de manos con placa olimpica de pie','estatico','principiante','aislamiento','otro','[\"antebrazos\"]','[\"biceps\"]','[\"Para empezar, ponte de pie recto mientras sostienes una placa de peso por el borde a la longitud del brazo en cada mano con un agarre neutro (palmas hacia dentro). Tus pies deben estar separados a la anchura de los hombros. Esta sera tu posicion inicial.\", \"Baja las placas hasta que los dedos esten casi extendidos, pero aun puedas mantener el peso. Inhala mientras bajas las placas.\", \"Ahora levanta las placas hasta la posicion inicial mientras exhalas cerrando las manos.\", \"Repite durante el numero de repeticiones recomendado en tu programa.\"]','fuerza','[\"Standing_Olympic_Plate_Hand_Squeeze/0.jpg\", \"Standing_Olympic_Plate_Hand_Squeeze/1.jpg\"]','Apreton de manos con placa olimpica de pie',773) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de un brazo de pie en polea','traccion','intermedio','aislamiento','polea','[\"biceps\"]','[]','[\"Comienza por agarrar una sola manija junto a la maquina de polea baja. Asegurate de estar lo suficientemente lejos de la maquina para que tu brazo soporte el peso.\", \"Asegurate de que la parte superior de tu brazo este fija, perpendicular al suelo, con los codos hacia adentro y las palmas hacia adelante. El brazo que no esta levantando debe sujetar la cintura. Esto le permitira mantener el equilibrio.\", \"Comience lentamente a flexionar el mango unico hacia arriba mientras mantiene la parte superior del brazo inmovil hasta que el antebrazo toque el biceps mientras exhala. Consejo: Solo debe moverse el antebrazo.\", \"Manten la contraccion mientras aprietas el biceps y luego baja el mango unico hacia atras hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo mientras realizas este ejercicio.\"]','fuerza','[\"Standing_One-Arm_Cable_Curl/0.jpg\", \"Standing_One-Arm_Cable_Curl/1.jpg\"]','Curl de biceps con cable de pie con un brazo',774) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Curl de un brazo de pie con mancuerna sobre banco inclinado','traccion','principiante','aislamiento','mancuerna','[\"biceps\"]','[]','[\"Ponte de pie en el lado de la espalda de un banco inclinado como si fueras a ser el observador de alguien. Toma una mancuerna en una mano y apoyala en el banco inclinado con un agarre supinado (palmas hacia arriba).\", \"Coloca la mano que no esta levantando en la esquina o lado del banco inclinado. El pecho debe estar apoyado contra la parte superior del banco inclinado y los pies deben estar apoyados contra el suelo con una postura amplia. Esta es la posicion inicial.\", \"Mientras mantienes el brazo superior inmovil, flexiona la mancuerna hacia arriba mientras contraes los biceps y exhalas. Solo deben moverse los antebrazos. Continua el movimiento hasta que tus biceps esten completamente contraidos y la mancuerna este al nivel de los hombros. Manten la posicion contraida durante un segundo.\", \"Comienza lentamente a llevar las mancuernas hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo mientras realizas este ejercicio.\"]','fuerza','[\"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/0.jpg\", \"Standing_One-Arm_Dumbbell_Curl_Over_Incline_Bench/1.jpg\"]','Curl de biceps con mancuernas a un brazo de pie sobre banco inclinado',775) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con mancuerna de pie','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Para empezar, ponte de pie con una mancuerna en una mano. Los pies deben estar separados aproximadamente a la anchura de los hombros. Ahora extiende completamente el brazo con la mancuerna por encima de la cabeza. Consejo: el meñique de la mano debe mirar hacia el techo y la palma de la mano debe mirar hacia delante. La mancuerna debe estar por encima de la cabeza.\", \"Esta sera tu posicion inicial.\", \"Manteniendo la parte superior del brazo cerca de la cabeza (codos hacia dentro) y perpendicular al suelo, baja la resistencia con un movimiento semicircular detras de la cabeza hasta que el antebrazo toque el biceps. Consejo: La parte superior del brazo debe permanecer inmovil y solo debe moverse el antebrazo. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la mancuerna. Exhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"Standing_One-Arm_Dumbbell_Triceps_Extension/0.jpg\", \"Standing_One-Arm_Dumbbell_Triceps_Extension/1.jpg\"]','Extension de triceps con mancuerna a un brazo de pie',776) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps de pie con barra sobre la cabeza','empuje','principiante','aislamiento','barra','[\"triceps\"]','[\"hombros\"]','[\"Para empezar, ponte de pie sosteniendo una barra o barra EZ con un agarre pronado (palmas hacia delante) con las manos mas juntas que el ancho de los hombros. Los pies deben estar separados aproximadamente a la anchura de los hombros.\", \"Ahora eleva la barra por encima de la cabeza hasta que los brazos esten completamente extendidos. Manten los codos hacia dentro. Esta sera tu posicion inicial.\", \"Manten los brazos cerca de la cabeza y los codos hacia dentro, perpendiculares al suelo, y baja la resistencia con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Consejo: los brazos deben permanecer fijos y solo deben moverse los antebrazos. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la barra. Exhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Standing_Overhead_Barbell_Triceps_Extension/0.jpg\", \"Standing_Overhead_Barbell_Triceps_Extension/1.jpg\"]','Extension de triceps con barra por encima de la cabeza de pie',777) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de mancuerna con un brazo y palma hacia dentro de pie','empuje','principiante','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Comienza con una mancuerna en una mano con el brazo completamente extendido al lado utilizando un agarre neutro. Utiliza el otro brazo para mantenerte en un banco inclinado y conservar el equilibrio.\", \"Los pies deben estar separados a la anchura de los hombros. Ahora levanta lentamente la mancuerna hasta crear un angulo de 90 grados con el brazo. Nota: El antebrazo debe estar perpendicular al suelo. Continua manteniendo un agarre neutro durante todo el ejercicio.\", \"Levanta lentamente la mancuerna hasta que tu brazo este completamente extendido. Esta es la posicion inicial.\", \"Mientras inhalas, baja el peso hasta que tu brazo vuelva a formar un angulo de 90 grados.\", \"Siente la contraccion durante un segundo y luego levanta el peso hacia atras hacia la posicion inicial mientras exhalas. Recuerda mantenerte en el banco inclinado y mantener los pies en posicion para mantener el equilibrio durante el ejercicio.\", \"Repite durante la cantidad recomendada de repeticiones.\", \"Cambia de brazo y repite el ejercicio.\"]','fuerza','[\"Standing_Palm-In_One-Arm_Dumbbell_Press/0.jpg\", \"Standing_Palm-In_One-Arm_Dumbbell_Press/1.jpg\"]','Press con mancuernas con una mano y palmas hacia dentro de pie',778) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de mancuernas de pie con las palmas hacia dentro','empuje','intermedio','compuesto','mancuerna','[\"hombros\"]','[\"triceps\"]','[\"Comienza con una mancuerna en cada mano con el brazo completamente extendido al lado utilizando un agarre neutro. Tus pies deben estar separados a la anchura de los hombros. Ahora levanta lentamente las mancuernas hasta crear un angulo de 90 grados con tus brazos. Nota: Tus antebrazos deben estar perpendiculares al suelo. Esta es la posicion inicial.\", \"Continua manteniendo un agarre neutro durante todo el ejercicio. Levanta lentamente las mancuernas hasta que tus brazos esten completamente extendidos.\", \"Mientras inhalas, baja las pesas hasta que tu brazo vuelva a formar un angulo de 90 grados.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Press con mancuernas de pie con las palmas hacia dentro/0.jpg\", \"Press con mancuernas de pie con las palmas hacia dentro/1.jpg\"]','Press con mancuernas de pie con las palmas hacia dentro',779) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Inclinacion pelvica de pie','estatico','principiante','aislamiento','Ninguno','[\"espalda_baja\"]','[\"gluteos\"]','[\"Comienza con los pies separados a la distancia de las caderas.\", \"Dobla ligeramente las rodillas para mantenerlas flexibles y elasticas.\", \"Puedes mover la pelvis hacia adelante y hacia atras y hacia atras varias veces antes de sostener el coxis hacia adelante en este estiramiento.\"]','estiramiento','[\"Standing_Pelvic_Tilt/0.jpg\", \"Standing_Pelvic_Tilt/1.jpg\"]','Inclinacion pelvica de pie',781) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Toques de dedos de pie de pie','estatico','principiante','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"pantorrillas\"]','[\"Ponte de pie con algo de espacio delante y detras de ti.\", \"Inclinate por la cintura, manteniendo las piernas rectas, hasta que puedas relajarte y dejar que la parte superior del cuerpo cuelgue hacia delante. Deja que los brazos y las manos cuelguen de forma natural. Manten la postura durante 10 a 20 segundos.\"]','estiramiento','[\"Standing_Toe_Touches/0.jpg\", \"Standing_Toe_Touches/1.jpg\"]','Toques de dedos de los pies de pie',784) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps con toalla de pie','empuje','principiante','aislamiento','solo_cuerpo','[\"triceps\"]','[]','[\"Para empezar, ponte de pie con ambos brazos completamente extendidos por encima de la cabeza sosteniendo un extremo de una toalla con ambas manos. Tus codos deben estar hacia dentro y los brazos perpendiculares al suelo con las palmas enfrentadas entre si, mientras que tus pies deben estar separados a la anchura de los hombros. Esta es la posicion inicial.\", \"Ahora comunicate con tu compañero para que pueda agarrar el otro lado de la toalla y aplicar resistencia. Manten los brazos cerca de la cabeza (codos hacia dentro) y perpendiculares al suelo, baja la resistencia con un movimiento semicircular detras de la cabeza hasta que los antebrazos toquen los biceps. Consejo: Los brazos deben permanecer fijos y solo deben moverse los antebrazos. Inhala mientras realizas este paso.\", \"Vuelve a la posicion inicial utilizando los triceps para levantar la toalla. Exhala mientras realizas este paso.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Standing_Towel_Triceps_Extension/0.jpg\", \"Standing_Towel_Triceps_Extension/1.jpg\"]','Extension de triceps con toalla de pie',785) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento de dos brazos por encima de la cabeza de pie','traccion','principiante','compuesto','balon_medicinal','[\"hombros\"]','[\"pecho\", \"dorsales\"]','[\"Ponte de pie con los pies separados a la anchura de los hombros y sujeta una pelota medicinal con ambas manos. Para empezar, lleva la pelota medicinal detras de la cabeza mientras flexionas ligeramente las rodillas y te inclinas hacia atras.\", \"Lanza la pelota hacia delante con fuerza, flexionando la cadera y utilizando todo el cuerpo para completar el movimiento.\", \"La pelota medicinal se puede lanzar a un compañero o a una pared, y se recoge cuando rebota.\"]','pliometria','[\"Standing_Two-Arm_Overhead_Throw/0.jpg\", \"Standing_Two-Arm_Overhead_Throw/1.jpg\"]','Lanzamiento por encima de la cabeza con los dos brazos de pie',786) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Salto en estrella','empuje','principiante','compuesto','solo_cuerpo','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"hombros\"]','[\"Comienza en una postura relajada con los pies separados a la anchura de los hombros y manten los brazos pegados al cuerpo.\", \"Para iniciar el movimiento, haz una sentadilla hasta la mitad y salta hacia arriba lo mas alto posible. Extiende completamente todo el cuerpo, separando las piernas y los brazos alejandolos del cuerpo.\", \"Al aterrizar, lleva las extremidades hacia atras y absorbe el impacto con las piernas.\"]','pliometria','[\"Star_Jump/0.jpg\", \"Star_Jump/1.jpg\"]','Salto en estrella',787) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Step Mill','Ninguno','intermedio','Ninguno','maquina','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Para empezar, subete a la escaladora y selecciona la opcion deseada en el menu. Puedes elegir un ajuste manual o seleccionar un programa para ejecutar. Por lo general, puedes introducir tu edad y peso para estimar la cantidad de calorias quemadas durante el ejercicio. Ten cuidado de no tropezar al subir las escaleras. Se recomienda que mantenga el agarre en las asas para no caerse.\", \"Las escaleras de step ofrecen comodidad, beneficios cardiovasculares y suelen tener menos impacto que correr al aire libre, al tiempo que ofrecen una tasa similar de calorias quemadas. Por lo general, son mucho mas duras que otros equipos de cardio. Una persona de 68 kg normalmente quemara mas de 300 calorias en 30 minutos, en comparacion con las aproximadamente 175 calorias que se queman al caminar.\"]','cardio','[\"Step_Mill/0.jpg\", \"Step_Mill/1.jpg\"]','Step_Mill',788) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Step-up con elevacion de rodilla','empuje','principiante','compuesto','solo_cuerpo','[\"gluteos\"]','[\"isquiotibiales\", \"cuadriceps\"]','[\"Ponte de pie frente a una caja o banco de una altura adecuada con los pies juntos. Esta sera tu posicion inicial.\", \"Comienza el movimiento subiendo, colocando el pie izquierdo en la parte superior del banco. Extiende la cadera y la rodilla de la pierna delantera para subirte a la caja. Mientras estas de pie en la caja con la pierna izquierda, flexiona la rodilla y la cadera derechas, llevando la rodilla tan alto como puedas.\", \"Invierte este movimiento para bajar de la caja y luego repite la secuencia con la pierna contraria.\"]','fuerza','[\"Step-up_with_Knee_Raise/0.jpg\", \"Step-up_with_Knee_Raise/1.jpg\"]','Step-up con elevacion de rodilla',789) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Stiff-Legged con Barra Peso Muerto','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"gluteos\", \"espalda_baja\"]','[\"Agarra una barra con un agarre por encima (las palmas hacia abajo). Es posible que necesites unas muñequeras si utilizas un peso considerable.\", \"Ponte de pie con el torso recto y las piernas separadas a la anchura de los hombros o menos. Las rodillas deben estar ligeramente flexionadas. Esta es tu posicion inicial.\", \"Manteniendo las rodillas fijas, baja la barra hasta la parte superior de tus pies flexionando las caderas mientras mantienes la espalda recta. Sigue moviendote hacia adelante como si fueras a recoger algo del suelo hasta que sientas un estiramiento en los isquiotibiales. Inhala mientras realizas este movimiento.\", \"Empieza a subir el torso de nuevo extendiendo las caderas hasta que la espalda este en la posicion inicial. Exhala mientras realizas este movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Stiff-Legged_Barbell_Deadlift/0.jpg\", \"Stiff-Legged_Barbell_Deadlift/1.jpg\"]','Peso muerto con barra y piernas rigidas',791) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con barra recta Remo medio','traccion','principiante','compuesto','barra','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca una barra cargada en el extremo de un banco. De pie en el banco detras de la barra, agarra la barra con un agarre medio y pronado. Manten las caderas hacia atras y el pecho hacia arriba, manteniendo la columna vertebral en posicion neutra. Esta sera tu posicion inicial.\", \"Remar la barra hacia el torso retraiendo los omoplatos y flexionando los codos. Realiza un movimiento controlado, sin sacudidas.\", \"Tras una breve pausa, devuelve lentamente la barra a la posicion inicial, asegurandote de bajarla completamente.\"]','fuerza','[\"Straight_Bar_Bench_Mid_Rows/0.jpg\", \"Straight_Bar_Bench_Mid_Rows/1.jpg\"]','Remo medio con barra recta en banco',794) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Elevacion recta en banco inclinado','empuje','principiante','aislamiento','barra','[\"hombros\"]','[\"trapecios\"]','[\"Coloca una barra en el suelo detras de la cabeza de un banco inclinado.\", \"Tumbate en el banco boca abajo. Con un agarre pronado, levanta la barra del suelo, manteniendo los brazos rectos. Deja que la barra cuelgue recta hacia abajo. Esta sera tu posicion inicial.\", \"Para empezar, levanta la barra frente a tu cabeza mientras mantienes los brazos extendidos.\", \"Vuelve a la posicion inicial.\"]','fuerza','[\"Straight_Raises_on_Incline_Bench/0.jpg\", \"Straight_Raises_on_Incline_Bench/1.jpg\"]','Elevaciones rectas en banco inclinado',795) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sumo Peso Muerto','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"aductores\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"espalda_media\", \"cuadriceps\", \"trapecios\"]','[\"Comienza con una barra cargada en el suelo. Acercate a la barra de modo que esta se cruce con el centro de los pies. Los pies deben estar muy separados, cerca de los collares. Dobla las caderas para agarrar la barra. Los brazos deben estar directamente debajo de los hombros, dentro de las piernas, y puedes usar un agarre pronado, un agarre mixto o un agarre en gancho. Relaja los hombros, lo que en efecto alarga tus brazos.\", \"Respira y luego baja tus caderas, mirando hacia adelante con la cabeza y el pecho levantados. Empuja contra el suelo, separando los pies, con tu peso en la mitad posterior de tus pies. Extiende las caderas y las rodillas.\", \"A medida que la barra pasa por las rodillas, inclina la espalda e impulsa las caderas hacia la barra, juntando los omoplatos.\", \"Vuelve a colocar el peso en el suelo flexionando las caderas y controlando el peso en el descenso.\"]','levantamiento de pesas','[\"Sumo_Deadlift/0.jpg\", \"Sumo_Deadlift/1.jpg\"]','Peso muerto sumo',799) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto sumo con bandas','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"aductores\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"espalda_media\", \"cuadriceps\", \"trapecios\"]','[\"Para hacer peso muerto con bandas cortas, simplemente colocalas sobre la barra antes de empezar y pisa sobre ellas para prepararte. Asegurate de que esten debajo de la mitad del pie, justo donde estas empujando contra el suelo.\", \"Empieza con la barra cargada en el suelo. Acercate a la barra de forma que esta se cruce con el centro de los pies. Los pies deben estar muy separados, cerca de los collares. Flexiona las caderas para agarrar la barra. Los brazos deben estar directamente debajo de los hombros, dentro de las piernas, y puedes usar un agarre pronado, un agarre mixto o un agarre en gancho.\", \"Respira y luego baja las caderas, mirando hacia adelante con la cabeza y el pecho hacia arriba. Empuja contra el suelo, separando los pies, con el peso en la mitad posterior de los pies. Extiende las caderas y las rodillas.\", \"A medida que la barra pasa por las rodillas, inclina la espalda e impulsa las caderas hacia la barra, juntando los omoplatos.\", \"Devuelve el peso al suelo flexionando las caderas y controlando el peso en el descenso.\"]','levantamiento de pesas','[\"Sumo_Deadlift_with_Bands/0.jpg\", \"Sumo_Deadlift_with_Bands/1.jpg\"]','Peso muerto sumo con bandas',800) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto sumo con cadenas','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"abductores\", \"aductores\", \"antebrazos\", \"gluteos\", \"espalda_baja\", \"espalda_media\", \"cuadriceps\", \"trapecios\"]','[\"Puedes sujetar las cadenas a las mangas de la barra, o simplemente colocar la parte central sobre la barra para que haya un mayor aumento de peso al levantar. Intenta mantener los extremos de las cadenas alejandote de las placas para no golpearlas al bajar el peso.\", \"Comienza con una barra cargada en el suelo. Acercate a la barra de modo que esta se cruce con el centro de los pies. Los pies deben estar muy separados, cerca de los collares. Dobla las caderas para agarrar la barra. Los brazos deben estar directamente debajo de los hombros, dentro de las piernas, y puedes usar un agarre pronado, un agarre mixto o un agarre en gancho. Relaja los hombros, lo que en efecto alarga tus brazos.\", \"Respira y luego baja las caderas, mirando hacia adelante con la cabeza y el pecho levantados. Empuja contra el suelo, separando los pies, con el peso en la mitad posterior de los pies. Extiende las caderas y las rodillas.\", \"A medida que la barra pasa por las rodillas, inclina la espalda y empuja las caderas hacia la barra, juntando los omoplatos.\", \"Devuelve el peso al suelo flexionando las caderas y controlando el peso en el descenso.\"]','levantamiento de pesas','[\"Sumo_Deadlift_with_Chains/0.jpg\", \"Sumo_Deadlift_with_Chains/1.jpg\"]','Peso muerto sumo con cadenas',801) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Superman','estatico','principiante','compuesto','solo_cuerpo','[\"espalda_baja\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Para empezar, tumbate recto y boca abajo en el suelo o en una colchoneta de ejercicios. Tus brazos deben estar completamente extendidos frente a ti. Esta es la posicion inicial.\", \"Levanta simultaneamente tus brazos, piernas y pecho del suelo y manten esta contraccion durante 2 segundos. Consejo: Aprieta tu espalda baja para obtener los mejores resultados de este ejercicio. Recuerda exhalar durante este movimiento. Nota: Al mantener la posicion contraida, debes parecer Superman cuando esta volando.\", \"Comienza lentamente a bajar los brazos, las piernas y el pecho hacia la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones prescrita en tu programa.\"]','estiramiento','[\"Superman/0.jpg\", \"Superman/1.jpg\"]','Superman',802) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento de pecho en posicion supina','empuje','principiante','compuesto','balon_medicinal','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Este ejercicio es ideal para practicar lanzamientos de pecho cuando no tienes un compañero o una pared con la resistencia suficiente. Tumbate en el suelo boca arriba con las rodillas flexionadas.\", \"Comienza con el balon en el pecho, sujetandolo con ambas manos por la parte inferior.\", \"Explota hacia arriba, extendiendo el codo para lanzar el balon directamente por encima de ti lo mas alto posible.\", \"Atrapa el balon con ambas manos cuando caiga.\"]','pliometria','[\"Supine_Chest_Throw/0.jpg\", \"Supine_Chest_Throw/1.jpg\"]','Lanzamiento supino de pecho',803) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento supino con un brazo por encima de la cabeza','traccion','principiante','compuesto','balon_medicinal','[\"abdominales\"]','[\"pecho\", \"dorsales\", \"hombros\"]','[\"Tumbate en el suelo boca arriba con las rodillas flexionadas. Sujeta la pelota con una mano, extendiendo el brazo completamente detras de la cabeza. Esta sera tu posicion inicial.\", \"Inicia el movimiento desde el hombro, lanzando la pelota directamente delante de ti mientras te incorporas, intentando alcanzar la maxima distancia posible.\", \"La pelota se puede lanzar a un compañero o rebotar contra una pared.\"]','pliometria','[\"Supine_One-Arm_Overhead_Throw/0.jpg\", \"Supine_One-Arm_Overhead_Throw/1.jpg\"]','Lanzamiento supino con un brazo por encima de la cabeza',804) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Lanzamiento supino con dos brazos por encima de la cabeza','traccion','principiante','compuesto','balon_medicinal','[\"abdominales\"]','[\"pecho\", \"dorsales\", \"hombros\"]','[\"Tumbate en el suelo boca arriba con las rodillas flexionadas.\", \"Sujeta la pelota con ambas manos, extendiendo los brazos completamente detras de la cabeza. Esta sera tu posicion inicial.\", \"Inicia el movimiento desde el hombro, lanzando la pelota directamente hacia delante mientras te incorporas, intentando alcanzar la maxima distancia posible.\", \"La pelota se puede lanzar a un compañero o rebotar contra una pared.\"]','pliometria','[\"Supine_Two-Arm_Overhead_Throw/0.jpg\", \"Supine_Two-Arm_Overhead_Throw/1.jpg\"]','Lanzamiento supino con dos brazos por encima de la cabeza',805) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Caida suspendida','traccion','intermedio','aislamiento','otro','[\"abdominales\"]','[\"pecho\", \"espalda_baja\", \"hombros\"]','[\"Ajusta las correas para que las asas esten a una altura adecuada, por debajo del nivel de la cintura.\", \"Comienza de pie y agarra las asas. Inclinate hacia las correas, moviendote a una posicion de flexion inclinada. Esta sera tu posicion inicial.\", \"Manteniendo los brazos rectos, inclinate aun mas hacia las correas de suspension, acercando tu cuerpo al suelo, permitiendo que tus hombros se extiendan, levantando los brazos por encima de tu cabeza.\", \"Manten la columna vertebral en posicion neutra y el resto del cuerpo recto, siendo los hombros las unicas articulaciones que se pueden mover.\", \"Haz una pausa durante la contraccion maxima y luego vuelve a la posicion inicial.\"]','fuerza','[\"Suspended_Fallout/0.jpg\", \"Suspended_Fallout/1.jpg\"]','Caida suspendida',806) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion suspendida','empuje','principiante','compuesto','otro','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Fija las correas de suspension de forma segura a la parte superior de una rejilla u otro objeto.\", \"Inclinandote hacia las correas, toma un asa con cada mano y ponte en posicion de plancha para hacer flexiones. Debes estar lo mas paralelo al suelo que puedas con los brazos completamente extendidos, manteniendo una buena postura.\", \"Manteniendo el torso recto y rigido, desciende lentamente permitiendo que los codos se flexionen.\", \"Continua hasta que tus codos formen un angulo de 90 grados, haciendo una pausa antes de extenderlos para volver a la posicion inicial.\"]','fuerza','[\"Suspended_Push-Up/0.jpg\", \"Suspended_Push-Up/1.jpg\"]','Flexiones suspendidas',807) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales inversos suspendidos','traccion','principiante','aislamiento','otro','[\"abdominales\"]','[]','[\"Asegura un juego de correas de suspension con las asas colgando aproximadamente a un pie del suelo. Colocate en posicion de plancha de flexiones mirando hacia el rack.\", \"Coloca tus pies en las asas. Debes mantener una postura recta, sin permitir que las caderas se hundan. Esta sera tu posicion inicial.\", \"Comienza el movimiento flexionando las rodillas y las caderas, llevando las rodillas hacia el torso. Al hacerlo, inclina la pelvis hacia delante, permitiendo que la columna se flexione.\", \"En la parte superior del movimiento controlado, vuelve a la posicion inicial.\"]','fuerza','[\"Suspended_Reverse_Crunch/0.jpg\", \"Suspended_Reverse_Crunch/1.jpg\"]','Abdominal inverso suspendido',808) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo suspendido','traccion','principiante','compuesto','otro','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Suspende las correas a la altura del pecho. Toma un asa en cada mano e inclinate hacia atras. Manten el cuerpo erguido y la cabeza y el pecho levantados. Los brazos deben estar completamente extendidos. Esta sera tu posicion inicial.\", \"Comienza flexionando el codo para iniciar el movimiento. Al hacerlo, protrae los omoplatos.\", \"Al completar el movimiento, haz una pausa y luego vuelve a la posicion inicial.\"]','fuerza','[\"Suspended_Row/0.jpg\", \"Suspended_Row/1.jpg\"]','Remo suspendido',809) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla dividida suspendida','empuje','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"Suspende las correas de modo que las asas esten a 18-30 pulgadas del suelo.\", \"De espaldas al equipo, coloca el pie trasero en la asa que tienes detras. Manten la cabeza mirando hacia adelante y el pecho erguido, con la rodilla ligeramente flexionada. Esta sera tu posicion inicial.\", \"Desciende flexionando la rodilla y las caderas, bajando hasta el suelo. Manten el peso en el talon del pie y manten la postura durante todo el ejercicio.\", \"En la parte inferior del movimiento, invierte el movimiento, extendiendo la cadera y la rodilla para volver a la posicion inicial.\"]','fuerza','[\"Suspended_Split_Squat/0.jpg\", \"Suspended_Split_Squat/1.jpg\"]','Sentadilla dividida suspendida',810) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con barra en T con asa','traccion','principiante','compuesto','barra','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca una barra en una landmine o en una esquina para evitar que se mueva. Carga un peso adecuado en tu extremo.\", \"Ponte de pie sobre la barra y coloca un mango de remo doble D alrededor de la barra junto al collarin. Utilizando tus caderas y piernas, levantate hasta quedar de pie.\", \"Adopta una postura amplia con las caderas hacia atras y el pecho hacia arriba. Tus brazos deben estar extendidos. Esta sera tu posicion inicial.\", \"Tira del peso hacia la parte superior del abdomen retraiendo los omoplatos y flexionando los codos. No hagas movimientos bruscos con el peso ni hagas trampa durante el movimiento.\", \"Despues de una breve pausa, vuelve a la posicion inicial.\"]','fuerza','[\"T-Bar_Row_with_Handle/0.jpg\", \"T-Bar_Row_with_Handle/1.jpg\"]','Remo con barra en T con asa',812) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('El Straddle','estatico','principiante','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"aductores\", \"pantorrillas\"]','[\"Comienza en posicion sentada y erguida. Empieza por extender las piernas frente a ti en forma de V.\", \"Con las manos en el suelo, inclinate hacia delante lo mas lejos posible. Manten la posicion durante 10 a 20 segundos.\"]','estiramiento','[\"The_Straddle/0.jpg\", \"The_Straddle/1.jpg\"]','El_Straddle',814) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abductor de muslos','empuje','principiante','aislamiento','maquina','[\"abductores\"]','[\"gluteos\"]','[\"Para empezar, sientate en la maquina abductora y selecciona un peso con el que te sientas comodo. Cuando tus piernas esten colocadas correctamente, agarra las asas a cada lado. Toda la parte superior de tu cuerpo (desde la cintura hacia arriba) debe permanecer inmovil. Esta es la posicion inicial.\", \"Presiona lentamente contra la maquina con las piernas para alejarlas una de otra mientras exhalas.\", \"Siente la contraccion durante un segundo y comienza a mover las piernas hacia atras a la posicion inicial mientras inhalas. Nota: Recuerda mantener la parte superior del cuerpo inmovil para evitar lesiones.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Thigh_Abductor/0.jpg\", \"Thigh_Abductor/1.jpg\"]','Abductor de muslo',815) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Adductor de muslo','traccion','principiante','aislamiento','maquina','[\"aductores\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Para empezar, sientate en la maquina de aductores y selecciona un peso con el que te sientas comodo. Cuando tus piernas esten colocadas correctamente en las almohadillas para las piernas de la maquina, agarra las asas a cada lado. Toda la parte superior del cuerpo (desde la cintura hacia arriba) debe permanecer inmovil. Esta es la posicion inicial.\", \"Presiona lentamente contra la maquina con tus piernas para moverlas una hacia la otra mientras exhalas.\", \"Siente la contraccion durante un segundo y comienza a mover tus piernas hacia atras a la posicion inicial mientras inhalas. Nota: Recuerda mantener la parte superior del cuerpo inmovil y evitar movimientos bruscos para prevenir lesiones.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Thigh_Adductor/0.jpg\", \"Thigh_Adductor/1.jpg\"]','Aductor del muslo',816) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Volteo de neumatico','traccion','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"Pantorrillas\", \"Pecho\", \"Antebrazos\", \"Gluteos\", \"Isquiotibiales\", \"Espalda baja\", \"Hombros\", \"Trapecios\", \"Triceps\"]','[\"Comienza agarrando la parte inferior del neumatico por la banda de rodadura y coloca los pies un poco hacia atras. Tu pecho debe empujar hacia el neumatico.\", \"Para levantar el neumatico, extiende las caderas, las rodillas y los tobillos, empujando hacia el neumatico y hacia arriba.\", \"Cuando el neumatico alcance un angulo de 45 grados, da un paso adelante y empuja con la rodilla hacia el neumatico. Mientras lo haces, ajusta tu agarre a la parte superior del neumatico y empuja hacia adelante con toda la fuerza posible para completar el giro. Repite tantas veces como sea necesario.\"]','hombre_fuerte','[\"Tire_Flip/0.jpg\", \"Tire_Flip/1.jpg\"]','Volteo de neumatico',817) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Toe Touchers','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Para empezar, tumbate en el suelo o en una colchoneta de ejercicios con la espalda apoyada contra el suelo. Tus brazos deben estar extendidos a los lados con las palmas hacia abajo.\", \"Tus piernas deben estar juntas. Eleva lentamente las piernas en el aire hasta que esten casi perpendiculares al suelo con una ligera flexion en las rodillas. Tus pies deben estar paralelos al suelo.\", \"Mueve tus brazos de modo que esten completamente extendidos en un angulo de 45 grados con respecto al suelo. Esta es la posicion inicial.\", \"Mientras mantienes la parte inferior de la espalda apoyada contra el suelo, levanta lentamente el torso y utiliza las manos para intentar tocar los dedos de los pies. Recuerda exhalar mientras realizas esta parte del ejercicio.\", \"Comienza lentamente a bajar el torso y los brazos hacia atras hasta la posicion inicial mientras inhalas. Recuerda mantener los brazos rectos apuntando hacia los dedos de los pies.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','estiramiento','[\"Toe_Touchers/0.jpg\", \"Toe_Touchers/1.jpg\"]','Toe_Touchers',818) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rotacion del torso','traccion','principiante','Ninguno','fitball','[\"abdominales\"]','[]','[\"Ponte de pie sosteniendo una pelota de ejercicios con ambas manos. Extiende tus brazos de modo que la pelota quede recta frente a ti. Esta sera tu posicion inicial.\", \"Gira tu torso hacia un lado, manteniendo la vista en la pelota mientras te mueves. Ahora, gira la espalda en la direccion opuesta. Repite durante 10-20 repeticiones.\"]','estiramiento','[\"Rotacion_del_torso/0.jpg\", \"Rotacion_del_torso/1.jpg\"]','Rotacion del torso',819) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto con barra trampa','traccion','principiante','compuesto','otro','[\"cuadriceps\"]','[\"gluteos\", \"isquiotibiales\"]','[\"Para este ejercicio, carga una barra trap, tambien conocida como barra hexagonal, con un peso adecuado y colocala en el suelo. Ponte de pie en el centro del aparato y agarra ambas asas.\", \"Baja las caderas, mira hacia delante con la cabeza y manten el pecho erguido.\", \"Comienza el movimiento impulsandote con los talones y extiende las caderas y las rodillas. Evita arquear la espalda en todo momento.\", \"Al completar el movimiento, baja el peso de espaldas al suelo de forma controlada.\"]','fuerza','[\"Trap_Bar_Deadlift/0.jpg\", \"Trap_Bar_Deadlift/1.jpg\"]','Peso muerto con barra trap',821) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Triceps con mancuernas Kickback','empuje','principiante','aislamiento','mancuerna','[\"triceps\"]','[]','[\"Comienza con una mancuerna en cada mano y las palmas mirando hacia tu torso. Manten la espalda recta con una ligera flexion en las rodillas y inclinate hacia adelante por la cintura. Tu torso debe estar casi paralelo al suelo. Asegurate de mantener la cabeza erguida. Los brazos deben estar cerca del torso y paralelos al suelo. Los antebrazos deben apuntar hacia el suelo mientras sostienes las pesas. Debe formarse un angulo de 90 grados entre el antebrazo y el brazo. Esta es la posicion inicial.\", \"Ahora, mientras mantienes los brazos inmoviles, exhala y utiliza los triceps para levantar las pesas hasta que el brazo este completamente extendido. Concentrate en mover el antebrazo.\", \"Despues de una breve pausa en la contraccion superior, inhala y baja lentamente las mancuernas hacia atras hasta la posicion inicial.\", \"Repite el movimiento durante la cantidad prescrita de repeticiones.\"]','fuerza','[\"Tricep_Dumbbell_Kickback/0.jpg\", \"Tricep_Dumbbell_Kickback/1.jpg\"]','Extension de triceps con mancuernas',822) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento lateral del triceps','estatico','principiante','Ninguno','Ninguno','[\"triceps\"]','[\"hombros\"]','[\"Lleva el brazo derecho por delante del cuerpo y por encima del hombro izquierdo, sujetando el codo con la mano izquierda, hasta que sientas un estiramiento en el triceps. A continuacion, repite con el otro brazo.\"]','estiramiento','[\"Tricep_Side_Stretch/0.jpg\", \"Tricep_Side_Stretch/1.jpg\"]','Estiramiento lateral del triceps',823) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps por encima de la cabeza con cuerda','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Fija una cuerda a una polea baja. Despues de seleccionar un peso adecuado, agarra la cuerda con ambas manos y colocate de espaldas a la polea.\", \"Coloca tus manos detras de la cabeza con los codos apuntando hacia arriba. Los codos deben estar flexionados al principio, y puedes escalonar la postura e inclinarte suavemente alejandote de la maquina para crear mayor estabilidad. Esta sera tu posicion inicial.\", \"Para realizar el movimiento, extiende el codo mientras mantienes el brazo en posicion, levantando las manos por encima de la cabeza.\", \"Aprieta los triceps en la parte superior del movimiento y baja lentamente el peso hacia la posicion inicial.\"]','fuerza','[\"Triceps_Overhead_Extension_with_Rope/0.jpg\", \"Triceps_Overhead_Extension_with_Rope/1.jpg\"]','Extension de triceps por encima de la cabeza con cuerda',824) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Fija una barra recta o angulada a una polea alta y agarrala con un agarre por encima (palmas hacia abajo) a la anchura de los hombros.\", \"De pie con el torso recto y una ligera inclinacion hacia delante, acerca los brazos superiores al cuerpo y perpendiculares al suelo. Los antebrazos deben apuntar hacia arriba, hacia la polea, mientras sostienen la barra. Esta es tu posicion inicial.\", \"Usando los triceps, lleva la barra hacia abajo hasta que toque la parte delantera de tus muslos y los brazos esten completamente extendidos perpendiculares al suelo. Los brazos superiores deben permanecer siempre fijos junto al torso y solo deben moverse los antebrazos. Exhala mientras realizas este movimiento.\", \"Despues de un segundo manten en la posicion contraida, lleva la barra lentamente arriba hasta el punto inicial. Inhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Triceps_Pushdown/0.jpg\", \"Triceps_Pushdown/1.jpg\"]','Extension de triceps con polea',825) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Extension de triceps - Accesorio de barra en V','empuje','principiante','aislamiento','polea','[\"triceps\"]','[]','[\"Conecta una barra en V a una polea alta y agarrala con un agarre por encima (las palmas hacia abajo) a la altura de los hombros.\", \"De pie con el torso recto y una ligera inclinacion hacia delante, acerca los brazos superiores al cuerpo y perpendiculares al suelo. Los antebrazos deben apuntar hacia arriba, hacia la polea, mientras sostienen la barra. Los pulgares deben estar mas altos que los meñiques. Esta es tu posicion inicial.\", \"Utilizando los triceps, lleva la barra hacia abajo hasta que toque la parte delantera de tus muslos y los brazos esten completamente extendidos perpendiculares al suelo. Los brazos superiores deben permanecer siempre fijos junto a tu torso y solo deben moverse los antebrazos. Exhala mientras realizas este movimiento.\", \"Despues de un segundo en la posicion contraida, lleva la barra en V lentamente hacia arriba hasta el punto inicial. Inhala mientras realizas este paso.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Triceps_Pushdown_-_V-Bar_Attachment/0.jpg\", \"Triceps_Pushdown_-_V-Bar_Attachment/1.jpg\"]','Extension de triceps con barra en V',827) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de triceps','estatico','principiante','aislamiento','Ninguno','[\"triceps\"]','[\"dorsales\"]','[\"Lleva la mano detras de la cabeza, agarra el codo y tira suavemente. Manten la posicion durante 10 a 20 segundos y luego cambia de lado.\"]','estiramiento','[\"Estiramiento_de_triceps/0.jpg\", \"Estiramiento_de_triceps/1.jpg\"]','Estiramiento de triceps',828) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales con las piernas flexionadas','traccion','principiante','aislamiento','solo_cuerpo','[\"abdominales\"]','[]','[\"Para empezar, tumbate en el suelo o en una colchoneta de ejercicios con la espalda apoyada contra el suelo. Tus brazos deben estar extendidos a los lados con las palmas hacia abajo.\", \"Tus piernas deben estar cruzadas, rodeando un tobillo con el otro. Eleva lentamente las piernas en el aire hasta que tus muslos esten perpendiculares al suelo, con una ligera flexion en las rodillas. Nota: Tus rodillas y dedos de los pies deben estar paralelos al suelo, al contrario que los muslos.\", \"Mueve tus brazos desde el suelo y cruzalos para que descansen sobre tu pecho. Esta es la posicion inicial.\", \"Mientras mantienes la parte baja de la espalda pegada al suelo, levanta lentamente el torso. Recuerda exhalar mientras realizas esta parte del ejercicio.\", \"Comienza lentamente a bajar el torso hacia la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Tuck_Crunch/0.jpg\", \"Tuck_Crunch/1.jpg\"]','Tuck_Crunch',829) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dos brazos con pesa rusa limpia','traccion','intermedio','compuesto','pesas rusas','[\"hombros\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\", \"trapecios\"]','[\"Coloca dos pesas rusas entre tus pies. Para colocarte en la posicion inicial, empuja el trasero hacia atras y mira recto al frente.\", \"Limpia las pesas rusas hasta tus hombros extendiendo las piernas y las caderas mientras levantas las pesas rusas hacia tus hombros. Gira las muñecas mientras lo haces.\", \"Baja las pesas rusas hacia atras a la posicion inicial y repite.\"]','fuerza','[\"Two-Arm_Kettlebell_Clean/0.jpg\", \"Two-Arm_Kettlebell_Clean/1.jpg\"]','Dos brazos con pesas rusas',831) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo con pesas rusas a dos brazos','traccion','intermedio','compuesto','pesas rusas','[\"espalda_media\"]','[\"biceps\", \"dorsales\"]','[\"Coloca dos pesas rusas frente a tus pies. Dobla ligeramente las rodillas y luego empuja los gluteos hacia atras tanto como sea posible mientras te inclinas para colocarte en la posicion inicial.\", \"Agarra ambas pesas rusas y llevalas hacia el abdomen, retraiendo los omoplatos y flexionando los codos. Manten la espalda recta. Baja y repite.\"]','fuerza','[\"Two-Arm_Kettlebell_Row/0.jpg\", \"Two-Arm_Kettlebell_Row/1.jpg\"]','Remo con pesas rusas a dos brazos',834) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Underhand en Polea Pulldowns','traccion','principiante','compuesto','polea','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Sientate en una maquina de poleas con una barra ancha fijada a la polea superior. Ajusta la almohadilla para las rodillas de la maquina a tu altura. Estas almohadillas evitaran que tu cuerpo se eleve por la resistencia fijada a la barra.\", \"Agarra la barra de poleas con las palmas mirando hacia tu torso (agarre supinado). Asegurate de que las manos esten colocadas mas cerca que el ancho de los hombros.\", \"Con ambos brazos extendidos frente a ti sosteniendo la barra con el ancho de agarre elegido, lleva el torso hacia atras unos 30 grados mas o menos, creando una curvatura en la parte inferior de la espalda y sacando el pecho. Esta es tu posicion inicial.\", \"Mientras exhalas, tira de la barra hacia abajo hasta que toque la parte superior del pecho, llevando los hombros y la parte superior de los brazos hacia abajo y hacia atras. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa y manten los codos cerca del cuerpo. La parte superior del torso debe permanecer inmovil mientras acercas la barra hacia ti y solo deben moverse los brazos. Los antebrazos no deben hacer ningun otro trabajo que no sea sostener la barra.\", \"Despues de un segundo en la posicion contraida, mientras inhalas, lleva lentamente la barra hacia atras a la posicion inicial cuando tus brazos esten completamente extendidos y los dorsales esten completamente estirados.\", \"Repite este movimiento durante la cantidad prescrita de repeticiones.\"]','fuerza','[\"Underhand_Cable_Pulldowns/0.jpg\", \"Underhand_Cable_Pulldowns/1.jpg\"]','Pulldowns con cable a dos brazos',835) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento de la parte superior de la espalda','estatico','principiante','Ninguno','Ninguno','[\"espalda_media\"]','[\"espalda_media\"]','[\"Entrelaza los dedos con los pulgares apuntando hacia abajo y redondea los hombros mientras estiras los brazos hacia delante.\"]','estiramiento','[\"Upper_Back_Stretch/0.jpg\", \"Upper_Back_Stretch/1.jpg\"]','Estiramiento de la parte superior de la espalda',836) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Agarre de la parte superior de la espalda y las piernas','estatico','principiante','Ninguno','Ninguno','[\"isquiotibiales\"]','[\"espalda_baja\", \"espalda_media\"]','[\"Mientras estas sentado, inclinate hacia adelante para abrazar tus muslos por debajo con ambos brazos.\", \"Manten tus rodillas juntas y tus piernas extendidas mientras acercas tu pecho a tus rodillas. Tambien puedes estirar la parte media de la espalda tirando de ella alejandola de tus rodillas mientras las abrazas.\"]','estiramiento','[\"Upper_Back-Leg_Grab/0.jpg\", \"Upper_Back-Leg_Grab/1.jpg\"]','Agarre de espalda y piernas',837) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical con barra','traccion','principiante','compuesto','barra','[\"hombros\"]','[\"trapecios\"]','[\"Agarra una barra con un agarre por encima de la cabeza que sea ligeramente inferior al ancho de los hombros. La barra debe descansar en la parte superior de tus muslos con tus brazos extendidos y una ligera flexion en tus codos. Tu espalda tambien debe estar recta. Esta sera tu posicion inicial.\", \"Ahora exhala y usa los lados de tus hombros para levantar la barra, elevando tus codos hacia arriba y hacia los lados. Manten la barra cerca de tu cuerpo mientras la levantas. Continua levantando la barra hasta que casi toque tu barbilla. Consejo: Tus codos deben impulsar el movimiento y siempre deben estar mas altos que tus antebrazos. Recuerda mantener tu torso inmovil y hacer una pausa de un segundo en la parte superior del movimiento.\", \"Baja la barra lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Upright_Barbell_Row/0.jpg\", \"Upright_Barbell_Row/1.jpg\"]','Remo vertical con barra',838) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical en polea','traccion','intermedio','compuesto','polea','[\"trapecios\"]','[\"hombros\"]','[\"Agarra un recto bar cable attachment que esta attached to a low pulley con un agarre pronado (palmas mirando hacia tus muslos) que es ligeramente menos que el ancho de los hombros. La barra debe estar descansando en la parte superior de tus muslos. Tus brazos deben estar extendidos con una ligera flexion en los codos y tu espalda debe estar recta. Esta sera tu posicion inicial.\", \"Usa tus hombros laterales para levantar la barra de polea mientras exhalas. La barra debe estar cerca del cuerpo mientras la subes. Continua levantandola hasta que casi toque tu barbilla. Consejo: Tus codos deben impulsar el movimiento. Mientras levantas la barra, tus codos deben estar siempre mas altos que tus antebrazos. Ademas, manten tu torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja la barra lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Upright_Cable_Row/0.jpg\", \"Upright_Cable_Row/1.jpg\"]','Remo vertical con cable',839) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Remo vertical con bandas','traccion','principiante','compuesto','bandas','[\"trapecios\"]','[\"hombros\"]','[\"Para comenzar, colocate de pie sobre una banda elastica de modo que la tension comience a la longitud del brazo. Agarra las asas con un agarre pronado (las palmas mirando hacia los muslos) que sea ligeramente inferior al ancho de los hombros. Las asas deben descansar sobre la parte superior de los muslos. Tus brazos deben estar extendidos con una ligera flexion en los codos y tu espalda debe estar recta. Esta sera tu posicion inicial.\", \"Usa tus hombros para levantar las asas mientras exhalas. Las asas deben estar cerca del cuerpo mientras las mueves hacia arriba. Continua levantando las asas hasta que casi toquen tu barbilla. Consejo: Tus codos deben impulsar el movimiento. A medida que levantas las asas, tus codos deben estar siempre mas altos que tus antebrazos. Ademas, manten el torso inmovil y haz una pausa de un segundo en la parte superior del movimiento.\", \"Baja las asas lentamente hasta la posicion inicial. Inhala mientras realizas esta parte del movimiento.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Upright_Row_-_With_Bands/0.jpg\", \"Upright_Row_-_With_Bands/1.jpg\"]','Remo vertical con bandas',840) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Estiramiento hacia arriba','estatico','principiante','Ninguno','Ninguno','[\"hombros\"]','[\"pecho\", \"dorsales\"]','[\"Extiende ambas manos rectas por encima de la cabeza, con las palmas tocandose.\", \"Empuja lentamente las manos hacia arriba y hacia atras, manteniendo la espalda recta.\"]','estiramiento','[\"Upward_Stretch/0.jpg\", \"Upward_Stretch/1.jpg\"]','Estiramiento hacia arriba',841) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Tiron con barra en V','traccion','intermedio','compuesto','polea','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Sientate en una maquina de pull-down con una barra en V acoplada a la polea superior.\", \"Ajusta la almohadilla para las rodillas de la maquina a tu altura. Estas almohadillas evitaran que tu cuerpo se eleve por la resistencia acoplada a la barra.\", \"Agarra la barra en V con las palmas enfrentadas (agarre neutro). Saca el pecho y inclinate ligeramente hacia atras (unos 30 grados) para activar mejor los dorsales. Esta sera tu posicion inicial.\", \"Utilizando los dorsales, tira de la barra hacia abajo mientras aprietas los omoplatos. Continua hasta que tu pecho casi toque la barra en V. Exhala mientras ejecutas este movimiento. Consejo: Manten el torso inmovil durante todo el movimiento.\", \"Despues de un segundo en la posicion contraida, lleva lentamente la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante el numero prescrito de repeticiones.\"]','fuerza','[\"V-Bar_Pulldown/0.jpg\", \"V-Bar_Pulldown/1.jpg\"]','V-Bar_Pulldown',842) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('V-Bar Pullup','traccion','principiante','compuesto','solo_cuerpo','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Comienza colocando el centro de la barra en V en el centro de la barra de dominadas (suponiendo que la estacion de dominadas que estas utilizando no tiene asas de agarre neutro). Las asas de la barra en V estaran orientadas hacia abajo para que puedas colgarte de la barra de dominadas mediante el uso de las asas.\", \"Una vez que hayas colocado la barra en V de forma segura, agarra la barra por cada lado y cuelgate de ella. Saca el pecho y inclinate ligeramente hacia atras para activar mejor los dorsales. Esta sera tu posicion inicial.\", \"Utilizando los dorsales, levanta el torso mientras inclinas ligeramente la cabeza hacia atras para no golpearte con la barra de dominadas. Continua hasta que tu pecho casi toque la barra en V. Exhala mientras ejecutas este movimiento.\", \"Despues de un segundo manten en la posicion contraida, baja lentamente tu cuerpo espalda a la posicion inicial mientras inhalas.\", \"Repite durante el numero prescrito de repeticiones.\"]','fuerza','[\"V-Bar_Pullup/0.jpg\", \"V-Bar_Pullup/1.jpg\"]','Barra en V_Dominadas',843) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Hiperextension con pelota lastrada','traccion','intermedio','compuesto','fitball','[\"espalda_baja\"]','[\"gluteos\", \"isquiotibiales\", \"espalda_media\"]','[\"Para empezar, tumbate boca abajo sobre una pelota de ejercicios con el torso apoyado contra la pelota y paralelo al suelo. Las puntas de los pies deben estar apoyadas contra el suelo para ayudarte a mantener el equilibrio. Coloca una placa con peso debajo de la barbilla o detras del cuello. Esta es la posicion inicial.\", \"Levanta lentamente el torso hacia arriba doblando la cintura y la zona lumbar. Recuerda exhalar durante este movimiento.\", \"Sosten la contraccion en la parte inferior de la espalda durante un segundo y baja el torso hacia abajo hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones prescrita en tu programa.\"]','fuerza','[\"Weighted_Ball_Hyperextension/0.jpg\", \"Weighted_Ball_Hyperextension/1.jpg\"]','Hiperextension con balon lastrado',846) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Flexion con peso en banco','empuje','intermedio','compuesto','otro','[\"triceps\"]','[\"pecho\", \"hombros\"]','[\"Para este ejercicio, tendras que colocar un banco detras de tu espalda y otro frente a ti. Con los bancos perpendiculares a tu cuerpo, mantente en un banco en su borde con las manos cerca de tu cuerpo, separadas a la altura de los hombros. Tus brazos deben estar completamente extendidos.\", \"Las piernas estaran extendidas hacia adelante sobre el otro banco. Tus piernas deben estar paralelas al suelo mientras tu torso debe estar perpendicular al suelo. Pide a tu compañero que coloque la mancuerna en tu regazo. Nota: Este ejercicio se realiza mejor con un compañero, ya que colocar el peso en el regazo puede ser dificil y causar lesiones sin ayuda. Esta sera tu posicion inicial.\", \"Baja lentamente tu cuerpo mientras inhalas doblando los codos hasta que te bajes lo suficiente como para que haya un angulo ligeramente inferior a 90 grados entre la parte superior del brazo y el antebrazo. Consejo: Manten los codos lo mas cerca posible durante todo el movimiento. Los antebrazos deben apuntar siempre hacia abajo.\", \"Utiliza los triceps para volver a subir el torso y levantate hasta la posicion inicial mientras exhalas.\", \"Repite durante el numero recomendado de repeticiones.\"]','fuerza','[\"Weighted_Bench_Dip/0.jpg\", \"Weighted_Bench_Dip/1.jpg\"]','Fondos en banco con peso',848) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales con peso','traccion','principiante','aislamiento','balon_medicinal','[\"abdominales\"]','[]','[\"Acuestate boca arriba con los pies apoyados en el suelo o descansando en un banco con las rodillas dobladas en un angulo de 90 grados.\", \"Sosten un peso contra tu pecho, o puedes mantenerlo extendido por encima de tu torso. Esta sera tu posicion inicial.\", \"Ahora, exhala y comienza lentamente a levantar los hombros del suelo. Tus hombros deben separarse del suelo aproximadamente 4 pulgadas mientras tu espalda baja permanece en el suelo.\", \"En la parte superior del movimiento, flexiona tus abdominales y manten durante una breve pausa.\", \"Luego inhala y baja lentamente tu espalda hasta la posicion inicial.\"]','fuerza','[\"Weighted_Crunches/0.jpg\", \"Weighted_Crunches/1.jpg\"]','Abdominales con peso',849) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con salto y peso','empuje','intermedio','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Coloca una barra con poco peso sobre la espalda, a la altura de los hombros. Tambien puedes utilizar un chaleco con peso, una bolsa de arena u otro tipo de resistencia durante este ejercicio.\", \"El peso debe ser lo suficientemente ligero como para que no te frene de forma significativa. Tus pies deben estar ligeramente mas separados que el ancho de los hombros, con la cabeza y el pecho erguidos. Esta sera tu posicion inicial.\", \"Utilizando un contramovimiento, haz una sentadilla parcial y cambia inmediatamente de direccion para impulsarte desde el suelo, extendiendo las caderas, las rodillas y los tobillos. Manten una buena postura durante todo el salto.\", \"Al volver al suelo, absorbe el impacto con las piernas.\"]','fuerza','[\"Weighted_Jump_Squat/0.jpg\", \"Weighted_Jump_Squat/1.jpg\"]','Sentadilla con salto con peso',850) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominadas con peso','traccion','intermedio','compuesto','otro','[\"dorsales\"]','[\"biceps\", \"espalda_media\"]','[\"Coloca una pesa en un cinturon de dip y fijalo alrededor de tu cintura. Agarra la barra de dominadas con las palmas de las manos mirando hacia delante. Para un agarre medio, tus manos deben estar separadas a la anchura de los hombros. Ambos brazos deben estar extendidos frente a ti sosteniendo la barra con el agarre elegido.\", \"Deberas llevar el torso hacia atras aproximadamente 30 grados mientras creas una curvatura en la parte inferior de la espalda y sacas el pecho. Esta sera tu posicion inicial.\", \"Ahora, exhala y tira de tu torso hacia arriba hasta que tu cabeza este por encima de tus manos. Concentrate en apretar los omoplatos hacia atras y hacia abajo al llegar a la posicion contraida superior.\", \"Despues de un breve momento en la posicion contraida superior, inhala y baja lentamente tu torso hacia atras hasta la posicion inicial con los brazos extendidos y los dorsales completamente estirados.\"]','fuerza','[\"Weighted_Pull_Ups/0.jpg\", \"Weighted_Pull_Ups/1.jpg\"]','Dominadas con peso',851) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sentadilla con peso','empuje','experto','compuesto','barra','[\"cuadriceps\"]','[\"pantorrillas\", \"gluteos\", \"isquiotibiales\"]','[\"De pie, con los pies separados a la anchura de los hombros y los dedos de los pies levantados, utiliza una mano para agarrarte a las barras de una jaula de sentadillas y el brazo opuesto para sujetar una placa en la parte superior del pecho. Esta es tu posicion inicial.\", \"Mientras te sujetas con un brazo, flexiona las rodillas y baja lentamente el torso hacia el suelo llevando la pelvis y las rodillas hacia delante. Inhala mientras bajas y detente cuando tus piernas superiores e inferiores casi formen un angulo de 90 grados. Manten la posicion de estiramiento durante un segundo.\", \"Despues de mantener la posicion durante un segundo, utiliza los musculos de los muslos para llevar el torso hacia arriba hasta la posicion inicial. Exhala mientras te levantas.\", \"Repite durante el numero de veces recomendado.\"]','fuerza','[\"Weighted_Sissy_Squat/0.jpg\", \"Weighted_Sissy_Squat/1.jpg\"]','Sentadilla con peso',852) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Abdominales con peso - Con bandas','traccion','intermedio','aislamiento','otro','[\"abdominales\"]','[]','[\"Comienza atando las bandas alrededor de la base del banco declinado. Coloca las asas hacia el interior del banco declinado para que, cuando te tumbes, puedas alcanzarlas con ambas manos.\", \"Coloca tus piernas en la maquina declinada hasta que esten bien sujetas. Ahora, coge las bandas de ejercicio con ambas manos. Utiliza un agarre pronado (palmas hacia delante) para sujetar las asas. Colocalas cerca de la clavicula y gira la muñeca hasta conseguir un agarre neutro (palmas hacia el torso). Nota: Tus brazos deben permanecer inmoviles durante todo el ejercicio. Esta es la posicion inicial.\", \"Mueve tu torso hacia arriba hasta que la parte superior de tu cuerpo quede perpendicular al suelo mientras exhalas. Manten la contraccion durante un segundo y baja la parte superior del cuerpo hacia atras hasta la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Weighted_Sit-Ups_-_With_Bands/0.jpg\", \"Weighted_Sit-Ups_-_With_Bands/1.jpg\"]','Abdominales con peso y bandas',853) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Peso muerto con piernas rigidas y postura amplia','traccion','intermedio','compuesto','barra','[\"isquiotibiales\"]','[\"aductores\", \"gluteos\", \"espalda_baja\"]','[\"Comienza con una barra cargada en el suelo. Adopta una postura amplia y luego flexiona las caderas para agarrar la barra. Las caderas deben estar lo mas alejadas posible de la espalda y las piernas casi rectas. Manten la espalda recta y la cabeza y el pecho hacia arriba. Esta sera tu posicion inicial.\", \"Comienza el movimiento activando las caderas, impulsandolas hacia adelante mientras dejas que los brazos cuelguen rectos. Continua hasta que estes de pie recto y, a continuacion, vuelve lentamente el peso a la posicion inicial. Para repeticiones sucesivas, no es necesario que el peso toque el suelo.\"]','halterofilia_olimpica','[\"Wide_Stance_Stiff_Legs/0.jpg\", \"Wide_Stance_Stiff_Legs/1.jpg\"]','Sentadilla con piernas rigidas y postura ancha',856) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca con agarre ancho','empuje','intermedio','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestese boca arriba en un banco plano con los pies firmemente apoyados en el suelo. Con un agarre amplio y pronado (palmas hacia delante) que este a unas 3 pulgadas mas alejado que el ancho de los hombros (para cada mano), levante la barra del soporte y mantengala recta sobre usted con los brazos bloqueados. La barra quedara perpendicular al torso y al suelo. Esta sera tu posicion inicial.\", \"Mientras inspiras, baja lentamente hasta que sientas la barra en la parte media del pecho.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos del pecho. Bloquea los brazos y aprieta el pecho en la posicion contraida, manten durante un segundo y luego empieza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Wide-Grip_Barbell_Bench_Press/0.jpg\", \"Wide-Grip_Barbell_Bench_Press/1.jpg\"]','Press de banca con barra con agarre ancho',857) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Press de banca declinado con barra con agarre ancho','empuje','intermedio','compuesto','barra','[\"pecho\"]','[\"hombros\", \"triceps\"]','[\"Acuestate boca arriba en un banco declinado con los pies bien sujetos en la parte delantera del banco. Con un agarre ancho y pronado (palmas hacia delante) que este a unos 7,5 cm mas alejado que el ancho de los hombros (para cada mano), levanta la barra del soporte y mantenla recta sobre ti con los brazos bloqueados. La barra quedara perpendicular al torso y al suelo. Esta sera tu posicion inicial.\", \"Mientras inspiras, baja lentamente hasta que sientas la barra en la parte inferior del pecho.\", \"Despues de una pausa de un segundo, lleva la barra de vuelta a la posicion inicial mientras exhalas y empuja la barra utilizando los musculos del pecho. Bloquea los brazos y aprieta el pecho en la posicion contraida, manten durante un segundo y luego empieza a bajar lentamente de nuevo. Consejo: Debes tardar al menos el doble de tiempo en bajar que en subir.\", \"Repite el movimiento durante el numero de repeticiones prescrito.\"]','fuerza','[\"Wide-Grip_Decline_Barbell_Bench_Press/0.jpg\", \"Wide-Grip_Decline_Barbell_Bench_Press/1.jpg\"]','Press de banca declinado con barra y agarre ancho',858) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Dominada trasera con agarre ancho','traccion','intermedio','compuesto','solo_cuerpo','[\"dorsales\"]','[\"biceps\", \"espalda_media\", \"hombros\"]','[\"Agarra la barra de dominadas con las palmas mirando hacia delante y con un agarre amplio.\", \"Con ambos brazos extendidos frente a ti sosteniendo la barra, lleva el torso hacia delante y la cabeza de modo que haya una linea imaginaria desde la barra de dominadas hasta la espalda de tu cuello. Esta es tu posicion inicial.\", \"Tira de tu torso hacia arriba hasta que la barra este cerca de la espalda de tu cuello. Para ello, lleva los hombros y la parte superior de los brazos hacia abajo y hacia atras, mientras inclinas ligeramente la cabeza hacia delante. Exhala mientras realizas esta parte del movimiento. Consejo: Concentrate en apretar los musculos de la espalda una vez que alcances la posicion de contraccion completa. La parte superior del torso debe permanecer inmovil mientras se mueve en el espacio y solo deben moverse los brazos. Los antebrazos no deben hacer ningun otro trabajo que no sea mantener la barra.\", \"Despues de un segundo en la posicion contraida, comienza a inhalar y baja lentamente el torso hacia la posicion inicial cuando tus brazos esten completamente extendidos y los dorsales esten completamente estirados.\", \"Repite este movimiento durante la cantidad prescrita de repeticiones.\"]','fuerza','[\"Wide-Grip_Rear_Pull-Up/0.jpg\", \"Wide-Grip_Rear_Pull-Up/1.jpg\"]','Dominada con agarre ancho detras del cuello',862) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Wide-Grip de pie con barra curl','traccion','principiante','aislamiento','barra','[\"biceps\"]','[]','[\"Ponte de pie con el torso erguido mientras sostienes una barra por el agarre exterior ancho. Las palmas de tus manos deben estar mirando hacia delante. Los codos deben estar cerca del torso. Esta sera tu posicion inicial.\", \"Mientras mantienes los brazos superiores inmoviles, flexiona los pesos hacia delante mientras contraes los biceps al exhalar. Consejo: Solo deben moverse los antebrazos.\", \"Continua el movimiento hasta que tus biceps esten completamente contraidos y la barra este al nivel de los hombros. Manten la posicion contraida durante un segundo y aprieta los biceps con fuerza.\", \"Comienza lentamente a llevar la barra hacia atras a la posicion inicial mientras inhalas.\", \"Repite durante la cantidad recomendada de repeticiones.\"]','fuerza','[\"Wide-Grip_Standing_Barbell_Curl/0.jpg\", \"Wide-Grip_Standing_Barbell_Curl/1.jpg\"]','Wide-Grip_Standing_Barbell_Curl',863) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Sprints','traccion','principiante','compuesto','solo_cuerpo','[\"abdominales\"]','[]','[\"Cuelgate de una barra de dominadas con un agarre pronado. Los brazos y las piernas deben estar extendidos. Esta sera tu posicion inicial.\", \"Comienza levantando rapidamente una rodilla lo mas alto que puedas. No balancees el cuerpo ni las piernas. 3\", \"Inmediatamente invierte el movimiento, volviendo la pierna a la posicion inicial. Simultaneamente, levanta la rodilla opuesta lo mas alto posible.\", \"Continua alternando entre piernas hasta completar la serie.\"]','fuerza','[\"Wind_Sprints/0.jpg\", \"Wind_Sprints/1.jpg\"]','Wind_Sprints',864) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Molino','traccion','intermedio','Ninguno','Ninguno','[\"abductores\"]','[\"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"Acuestate boca arriba con tus brazos extendidos a los lados y tus piernas rectas. Esta sera tu posicion inicial.\", \"Levanta una pierna y cruza rapidamente sobre tu cuerpo, intentando tocar el suelo cerca de la mano opuesta.\", \"Regresa a la posicion inicial y repite con la pierna opuesta. Continua alternando durante 10-20 repeticiones.\"]','estiramiento','[\"Windmills/0.jpg\", \"Windmills/1.jpg\"]','Molino',865) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rodillo de muñeca','traccion','principiante','aislamiento','otro','[\"antebrazos\"]','[\"hombros\"]','[\"Para empezar, ponte de pie con la espalda recta y agarra un rodillo de muñeca con un agarre pronado (las palmas hacia abajo). Los pies deben estar separados a la anchura de los hombros.\", \"Levanta lentamente ambos brazos hasta que esten completamente extendidos y paralelos al suelo frente a ti. Nota: Asegurate de que la cuerda no se enrolle alrededor del rodillo. Todo el cuerpo debe permanecer inmovil, excepto los antebrazos. Esta es la posicion inicial.\", \"Gire una muñeca a la vez con un movimiento hacia arriba para llevar el peso hacia la barra haciendo rodar la cuerda alrededor del rodillo.\", \"Una vez que el peso haya llegado a la barra, comience a bajarlo lentamente hacia atras girando la muñeca con un movimiento hacia abajo hasta que el peso llegue a la posicion inicial.\", \"Repita durante el numero de repeticiones prescrito en su programa.\"]','fuerza','[\"Wrist_Roller/0.jpg\", \"Wrist_Roller/1.jpg\"]','Rodillo de muñeca',868) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Rotaciones de muñeca con barra recta','traccion','principiante','aislamiento','barra','[\"antebrazos\"]','[]','[\"Sujete una barra con ambas manos y las palmas hacia abajo; las manos separadas aproximadamente a la anchura de los hombros. Esta sera su posicion inicial.\", \"Alternando entre cada una de sus manos, realice el movimiento extendiendo la muñeca como si estuviera enrollando un periodico. Continue alternando hasta el fallo.\", \"Invierta el movimiento flexionando la muñeca, enrollando en la direccion opuesta. Continue el movimiento alternado hasta el fallo.\"]','fuerza','[\"Rotaciones_de_muñeca_con_barra_recta/0.jpg\", \"Rotaciones_de_muñeca_con_barra_recta/1.jpg\"]','Rotaciones de muñeca con barra recta',869) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
INSERT INTO `exercise_catalog` (`name`,`force`,`level`,`mechanic`,`equipment`,`primary_muscles`,`secondary_muscles`,`instructions`,`category`,`images`,`code`,`id`) VALUES ('Caminata con yugo','Ninguno','intermedio','compuesto','otro','[\"cuadriceps\"]','[\"abdominales\", \"abductores\", \"aductores\", \"pantorrillas\", \"gluteos\", \"isquiotibiales\", \"espalda_baja\"]','[\"El yugo se suele hacer con un aparato de yugo, pero a veces se ve con frigorificos u otros objetos pesados.\", \"Comienza colocando el aparato sobre la espalda de los hombros. Con la cabeza mirando hacia adelante y la espalda arqueada, levanta el yugo impulsandote con los talones.\", \"Comienza a caminar lo mas rapido posible dando pasos cortos y rapidos. Puedes sujetar los postes laterales del yugo para estabilizarlo y mantenerlo en su posicion. Continua durante la distancia indicada lo mas rapido posible, normalmente entre 23 y 30 metros.\"]','hombre_fuerte','[\"Yoke_Walk/0.jpg\", \"Yoke_Walk/1.jpg\"]','Caminata con yugo',870) ON DUPLICATE KEY UPDATE name=VALUES(name), `force`=VALUES(`force`), level=VALUES(level), mechanic=VALUES(mechanic), equipment=VALUES(equipment), primary_muscles=VALUES(primary_muscles), secondary_muscles=VALUES(secondary_muscles), instructions=VALUES(instructions), category=VALUES(category), images=VALUES(images), code=VALUES(code);
